CREATE OR REPLACE FUNCTION "app_private"."accept_employee_invitation_for_user"("target_user_id" "uuid", "target_invitation_id" "uuid", "invitation_token_hash" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  invitation public.employee_invitations%rowtype;
  employee_role public.workspace_roles%rowtype;
  normalized_user_email text;
  email_confirmed boolean;
  membership public.workspace_memberships%rowtype;
  accepted_membership_id uuid;
begin
  if target_invitation_id is null and invitation_token_hash is null then
    raise exception 'active invitation not found' using errcode = 'P0002';
  end if;

  select *
  into invitation
  from public.employee_invitations
  where status = 'pending'
    and (
      (target_invitation_id is not null and id = target_invitation_id)
      or (invitation_token_hash is not null and token_hash = invitation_token_hash)
    )
  for update;

  if invitation.id is null or invitation.expires_at <= now() then
    if invitation.id is not null then
      update public.employee_invitations
      set status = 'expired'::public.employee_invitation_status,
          updated_at = now()
      where id = invitation.id;
    end if;
    raise exception 'active invitation not found' using errcode = 'P0002';
  end if;

  select lower(email), email_confirmed_at is not null
  into normalized_user_email, email_confirmed
  from auth.users
  where id = target_user_id;

  if normalized_user_email is null or normalized_user_email <> invitation.email then
    raise exception 'invitation email does not match authenticated account' using errcode = '42501';
  end if;
  if not email_confirmed then
    raise exception 'the account email address is not confirmed' using errcode = '42501', hint = 'authz.not_active';
  end if;

  select *
  into employee_role
  from public.workspace_roles
  where id = invitation.role_id
    and workspace_id = invitation.workspace_id;

  if employee_role.id is null then
    raise exception 'invitation role is unavailable' using errcode = '22023';
  end if;

  select *
  into membership
  from public.workspace_memberships
  where workspace_id = invitation.workspace_id
    and user_id = target_user_id
  for update;

  if membership.id is not null
    and membership.status <> 'suspended'::public.membership_status then
    raise exception 'workspace membership already exists' using errcode = '23505';
  end if;

  update public.employee_profiles
  set user_id = target_user_id,
      revision = revision + 1,
      updated_at = now()
  where id = invitation.employee_id
    and workspace_id = invitation.workspace_id
    and user_id is null
    and archived_at is null;

  if not found then
    raise exception 'invitable employee is unavailable' using errcode = 'P0002';
  end if;

  perform set_config('app.employee_invitation_accept', 'on', true);

  if membership.id is not null then
    update public.workspace_memberships
    set role = employee_role.access_class::public.workspace_role,
        role_id = invitation.role_id,
        status = 'pending_activation'::public.membership_status,
        all_locations = invitation.all_locations,
        updated_at = now()
    where id = membership.id
    returning id into accepted_membership_id;
  else
    insert into public.workspace_memberships (
      workspace_id, user_id, role, role_id, status, all_locations
    ) values (
      invitation.workspace_id,
      target_user_id,
      employee_role.access_class::public.workspace_role,
      invitation.role_id,
      'pending_activation'::public.membership_status,
      invitation.all_locations
    )
    returning id into accepted_membership_id;
  end if;

  perform app_private.reset_employee_onboarding_for_rehire(
    invitation.workspace_id,
    invitation.employee_id,
    accepted_membership_id,
    target_user_id
  );

  update public.employee_invitations
  set status = 'accepted'::public.employee_invitation_status,
      accepted_at = now(),
      updated_at = now()
  where id = invitation.id;

  insert into public.employee_events (
    workspace_id, employee_id, actor_user_id, action, summary
  )
  values (
    invitation.workspace_id,
    invitation.employee_id,
    target_user_id,
    'employee.invitation_accepted',
    'Employee invitation accepted; activation pending'
  );

  perform app_private.initialize_employee_onboarding(target_user_id, invitation.workspace_id);
  return invitation.workspace_id;
end;
$$;


ALTER FUNCTION "app_private"."accept_employee_invitation_for_user"("target_user_id" "uuid", "target_invitation_id" "uuid", "invitation_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."account_phone_e164"("raw_phone" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  trimmed text := btrim(coalesce(raw_phone, ''));
  digits text;
  normalized text;
begin
  if trimmed = '' then
    return null;
  end if;
  digits := regexp_replace(trimmed, '\D', '', 'g');
  normalized := case
    when left(trimmed, 1) = '+' then '+' || digits
    when digits like '1%' and char_length(digits) > 10 then '+' || digits
    else '+1' || ltrim(digits, '0')
  end;
  if normalized !~ '^\+[1-9][0-9]{7,14}$' then
    raise exception 'that phone number cannot be dialled' using errcode = '22023';
  end if;
  return normalized;
end;
$_$;


ALTER FUNCTION "app_private"."account_phone_e164"("raw_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."account_phone_reaches_employee_records"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and new.phone_e164 is not distinct from old.phone_e164 then
    return null;
  end if;

  update public.employee_private_profiles private_record
  set phone = new.phone_e164,
      updated_at = now()
  from public.employee_profiles record
  join public.workspace_memberships membership
    on membership.workspace_id = record.workspace_id
   and membership.user_id = record.user_id
  where private_record.employee_id = record.id
    and private_record.workspace_id = record.workspace_id
    and record.user_id = new.user_id
    and record.archived_at is null
    and membership.status in ('active', 'pending_activation')
    and private_record.phone is distinct from new.phone_e164;

  return null;
end;
$$;


ALTER FUNCTION "app_private"."account_phone_reaches_employee_records"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."activate_employee_onboarding_case"("target_case_id" "uuid", "actor_user_id" "uuid", "event_action" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_case public.employee_onboarding_cases%rowtype;
  next_revision integer;
begin
  select * into target_case
  from public.employee_onboarding_cases
  where id = target_case_id
  for update;

  if target_case.id is null then
    raise exception 'onboarding case unavailable' using errcode = 'P0002';
  end if;
  if exists(select 1 from public.employee_onboarding_requirements r where r.case_id=target_case.id and app_private.document_activation_blocked(r)) then raise exception 'Submit conditional documents or give an initial reason' using errcode='23514'; end if;
  if exists (
    select 1
    from public.employee_onboarding_requirements
    where case_id = target_case.id
      and (kind<>'document' or (publication_paused_at is null and not lifecycle_exempt and lifecycle_closed_at is null and status<>'superseded')) and required
      and blocks_activation
      and status <> 'completed'::public.employee_onboarding_requirement_status
  ) then
    raise exception 'activation-blocking requirements remain' using errcode = '23514';
  end if;

  perform set_config('app.membership_change', target_case.membership_id::text, true);
  update public.workspace_memberships
  set status = 'active', updated_at = now()
  where id = target_case.membership_id and status = 'pending_activation';
  if not found then
    raise exception 'pending membership unavailable' using errcode = '23514';
  end if;

  update public.employee_onboarding_cases
  set status = 'approved'::public.employee_onboarding_case_status,
      approved_by = actor_user_id,
      approved_at = now(),
      revision = revision + 1,
      updated_at = now()
  where id = target_case.id
  returning revision into next_revision;

  insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary)
  values (
    target_case.workspace_id,
    target_case.employee_id,
    actor_user_id,
    event_action,
    'Employee onboarding approved and workspace access activated'
  );

  return next_revision;
end;
$$;


ALTER FUNCTION "app_private"."activate_employee_onboarding_case"("target_case_id" "uuid", "actor_user_id" "uuid", "event_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."actor"("actor" "uuid", "w" "uuid") RETURNS "app_private"."actor_state"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  state app_private.actor_state;
  held_role uuid;
begin
  state.user_id := actor;
  state.workspace_id := w;
  state.works := '{}';
  state.manages := '{}';
  state.permissions := '{}';

  select membership.id, membership.status, role.access_class, role.id
    into state.membership_id, state.status, state.class, held_role
  from public.workspace_memberships membership
  join public.workspace_roles role
    on role.id = membership.role_id and role.workspace_id = membership.workspace_id
  where membership.workspace_id = w and membership.user_id = actor;
  if state.membership_id is null then
    return state;
  end if;

  state.workspace_open := app_private.workspace_open_to_actor(w, actor);
  state.document_blocked := coalesce(app_private.document_actor_blocked(actor, w), false);

  select profile.id into state.employee_id
  from public.employee_profiles profile
  where profile.workspace_id = w and profile.user_id = actor and profile.archived_at is null;

  state.works := coalesce((
    select array_agg(distinct assignment.location_id order by assignment.location_id)
    from public.employee_location_assignments assignment
    join public.locations location on location.id = assignment.location_id
    where assignment.workspace_id = w
      and assignment.employee_id = state.employee_id
      and assignment.ended_at is null
      and app_private.location_is_live(location)
  ), '{}');

  -- A manager manages where they are assigned, and nowhere else (EMP-001).
  state.manages := case
    when state.class in ('owner', 'admin') then coalesce((
      select array_agg(location.id order by location.id)
      from public.locations location
      where location.workspace_id = w and app_private.location_is_live(location)
    ), '{}')
    when state.class = 'manager' then state.works
    else '{}'::uuid[]
  end;

  state.permissions := coalesce((
    select array_agg(grant_row.permission_key order by grant_row.permission_key)
    from public.workspace_role_permissions grant_row
    join public.permissions permission on permission.key = grant_row.permission_key
    where grant_row.workspace_id = w
      and grant_row.role_id = held_role
      and (state.class <> 'employee' or permission.employee_eligible)
  ), '{}');

  return state;
end;
$$;


ALTER FUNCTION "app_private"."actor"("actor" "uuid", "w" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."actor_actions"("state" "app_private"."actor_state") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  some_location uuid;
begin
  select location.id into some_location
  from public.locations location
  where location.workspace_id = state.workspace_id and app_private.location_is_live(location)
  order by location.id
  limit 1;

  return coalesce((
    select array_agg(action.key order by action.key)
    from app_private.authz_actions action
    where case
      when action.scope_class in ('account', 'own', 'org') then
        app_private.authz_check(state, action, null, null, null) is null
      else
        app_private.authz_check(state, action, '{}'::uuid[], null, null) is null
        or (cardinality(state.manages) > 0
            and app_private.authz_check(state, action, state.manages[1:1], null, null) is null)
        or (some_location is not null
            and app_private.authz_check(state, action, array[some_location], null, null) is null)
    end
  ), '{}');
end;
$$;


ALTER FUNCTION "app_private"."actor_actions"("state" "app_private"."actor_state") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."adopt_account_phone"("target_user_id" "uuid", "typed_phone" "text", "fallback_display_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  account_phone text;
  typed_e164 text;
begin
  select profile.phone_e164 into account_phone
  from public.user_profiles profile
  where profile.user_id = target_user_id
  for update;

  if account_phone is not null then
    return account_phone;
  end if;

  typed_e164 := app_private.account_phone_e164(typed_phone);
  if typed_e164 is null then
    return null;
  end if;

  -- The account row may not exist yet: nothing creates one at sign-up.
  insert into public.user_profiles (user_id, display_name, phone_e164)
  select
    target_user_id,
    left(coalesce(
      nullif(btrim(account.raw_user_meta_data ->> 'display_name'), ''),
      nullif(btrim(fallback_display_name), ''),
      split_part(account.email, '@', 1)
    ), 100),
    typed_e164
  from auth.users account
  where account.id = target_user_id
  on conflict (user_id) do update
    set phone_e164 = excluded.phone_e164,
        updated_at = now()
    where public.user_profiles.phone_e164 is null;

  return typed_e164;
end;
$$;


ALTER FUNCTION "app_private"."adopt_account_phone"("target_user_id" "uuid", "typed_phone" "text", "fallback_display_name" "text") OWNER TO "postgres";

