CREATE TABLE IF NOT EXISTS "public"."announcements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "body" "text" NOT NULL,
    "category" "public"."announcement_category" DEFAULT 'general'::"public"."announcement_category" NOT NULL,
    "status" "public"."announcement_status" DEFAULT 'draft'::"public"."announcement_status" NOT NULL,
    "audience_roles" "public"."workspace_role"[] DEFAULT ARRAY['owner'::"public"."workspace_role", 'admin'::"public"."workspace_role", 'manager'::"public"."workspace_role", 'employee'::"public"."workspace_role"] NOT NULL,
    "publish_at" timestamp with time zone,
    "published_at" timestamp with time zone,
    "expires_at" timestamp with time zone,
    "action_url" "text",
    "revision" integer DEFAULT 1 NOT NULL,
    "created_by" "uuid" NOT NULL,
    "updated_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "department_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "job_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "archived_at" timestamp with time zone,
    "content_revision" integer DEFAULT 1 NOT NULL,
    "delivered_to" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "release_failed_at" timestamp with time zone,
    "release_error" "text",
    "acknowledged_before" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    CONSTRAINT "announcements_action_url_check" CHECK ((("action_url" IS NULL) OR (("char_length"("action_url") <= 500) AND ("action_url" ~ '^/app(/|$)'::"text")))),
    CONSTRAINT "announcements_audience_roles_check" CHECK ((("cardinality"("audience_roles") >= 1) AND ("cardinality"("audience_roles") <= 4))),
    CONSTRAINT "announcements_body_check" CHECK ((("char_length"("btrim"("body")) >= 1) AND ("char_length"("btrim"("body")) <= 5000))),
    CONSTRAINT "announcements_check" CHECK ((("expires_at" IS NULL) OR ("publish_at" IS NULL) OR ("expires_at" > "publish_at"))),
    CONSTRAINT "announcements_revision_check" CHECK (("revision" > 0)),
    CONSTRAINT "announcements_title_check" CHECK ((("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 120)))
);


ALTER TABLE "public"."announcements" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."announcement_deliver"("item" "public"."announcements", "recipients" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  event_id uuid := gen_random_uuid();
begin
  if cardinality(recipients) = 0 then
    return;
  end if;
  perform public.enqueue_notification_outbox_service(
    item.workspace_id, event_id, 'communications.announcement.available', 1, item.updated_by,
    'announcement', item.id::text,
    jsonb_build_object(
      'correlation_id', event_id,
      'announcement_id', item.id,
      'announcement_revision', item.revision,
      'content_revision', item.content_revision,
      'location_ids', to_jsonb(app_private.announcement_places(item.id)),
      'recipient_user_ids', to_jsonb(recipients),
      'audience_contract', 'announcement_targeted_members',
      'category', 'announcement',
      'title', item.title,
      'body', left(item.body, 2000),
      'safe_preview', 'A new announcement is available.',
      'action_url', coalesce(item.action_url, '/app/announcements/' || item.id::text),
      'group_key', 'announcement:' || item.id::text,
      'visible_at', coalesce(item.published_at, now())),
    now());
end;
$$;


ALTER FUNCTION "app_private"."announcement_deliver"("item" "public"."announcements", "recipients" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."announcement_out_to"("state" "app_private"."actor_state", "item" "public"."announcements", "places" "uuid"[]) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select item.status = 'published' and item.archived_at is null
     and (item.expires_at is null or item.expires_at > now())
     and app_private.communication_reaches(state, item.workspace_id,
           app_private.live_locations(item.workspace_id, places), cardinality(places) = 0,
           item.audience_roles, item.department_ids, item.job_ids)
$$;


ALTER FUNCTION "app_private"."announcement_out_to"("state" "app_private"."actor_state", "item" "public"."announcements", "places" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."announcement_places"("announcement" "uuid") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(array_agg(target.location_id order by target.location_id), '{}')
  from public.announcement_locations target where target.announcement_id = announcement
$$;


ALTER FUNCTION "app_private"."announcement_places"("announcement" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."announcement_recipients"("item" "public"."announcements") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(array_agg(distinct who order by who), '{}')
  from app_private.communication_audience(item.workspace_id,
    app_private.announcement_places(item.id),
    item.audience_roles, item.department_ids, item.job_ids) who
  where who is distinct from item.created_by
$$;


ALTER FUNCTION "app_private"."announcement_recipients"("item" "public"."announcements") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."announcement_release"("w" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  item public.announcements;
  released integer := 0;
begin
  for item in
    select * from public.announcements announcement
    where (w is null or announcement.workspace_id = w)
      and announcement.status = 'scheduled' and announcement.archived_at is null
      and announcement.publish_at <= now() and announcement.release_failed_at is null
    for update skip locked
  loop
    begin
      if item.expires_at is not null and item.expires_at <= now() then
        -- Its time ran out before it went out: it does not (P25).
        update public.announcements set status = 'unpublished', revision = revision + 1 where id = item.id;
      else
        update public.announcements
        set status = 'published', published_at = item.publish_at, revision = revision + 1,
            delivered_to = app_private.announcement_recipients(item)
        where id = item.id
        returning * into item;
        perform app_private.announcement_deliver(item, item.delivered_to);
        released := released + 1;
      end if;
    exception when others then
      -- One broken row must not hold up every workspace's, nor the read that
      -- called this (O2). The error stays with it (KK-98).
      update public.announcements set release_failed_at = now(), release_error = left(sqlstate || ': ' || sqlerrm, 2000)
      where id = item.id;
    end;
  end loop;

  for item in
    select * from public.announcements announcement
    where (w is null or announcement.workspace_id = w)
      and announcement.status = 'published' and announcement.archived_at is null
      and announcement.expires_at <= now() and cardinality(announcement.delivered_to) > 0
    for update skip locked
  loop
    begin
      perform app_private.communication_withdraw(item.workspace_id, 'communications.announcement.available',
        'announcement', item.id::text, 'cancelled');
      update public.announcements set delivered_to = '{}' where id = item.id;
    exception when others then
      -- The next minute tries again.
      raise warning 'announcement % did not leave the inboxes: %', item.id, sqlerrm;
    end;
  end loop;
  return released;
end;
$$;


ALTER FUNCTION "app_private"."announcement_release"("w" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."announcement_visible"("actor" "uuid", "item" "public"."announcements") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with me as (
    select app_private.actor(actor, item.workspace_id) state, app_private.announcement_places(item.id) places
  )
  select app_private.communication_reason(me.state, item.workspace_id, 'announcement', me.places, item.created_by) is null
      or app_private.announcement_out_to(me.state, item, me.places)
  from me
$$;


ALTER FUNCTION "app_private"."announcement_visible"("actor" "uuid", "item" "public"."announcements") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."apply_lifecycle_definition"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "expected_revision" integer, "expected_preview_token" "text", "apply_reason" "text", "target_kind" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d app_private.lifecycle_definition%rowtype; preview jsonb; item jsonb; r public.employee_onboarding_requirements%rowtype;
 case_id uuid; member public.workspace_memberships%rowtype; deadline timestamptz; applied integer:=0; valid_approved boolean;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'settings.documents.write');
 if nullif(btrim(apply_reason),'') is null or char_length(apply_reason)>500 then raise exception 'application reason required' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text,52001));
 if target_kind='acknowledgement' then perform 1 from public.signature_template_versions where id=target_document_type_id and workspace_id=target_workspace_id for update; else perform 1 from public.document_types where id=target_document_type_id and workspace_id=target_workspace_id for update; end if; select * into d from app_private.lifecycle_definition where id=target_document_type_id and workspace_id=target_workspace_id and kind=target_kind;
 if d.id is null or d.lifecycle_revision is distinct from expected_revision then raise exception 'document type changed; refresh required' using errcode='PT409'; end if;
 -- Lock every scoped input that contributes to this preview before revalidation.
 perform 1 from public.employee_profiles e where e.workspace_id=target_workspace_id and e.archived_at is null order by e.id for update;
 perform 1 from public.employee_onboarding_cases where workspace_id=target_workspace_id order by id for update;
 perform 1 from public.employee_onboarding_requirements where workspace_id=target_workspace_id and source_id=d.id order by id for update;
 preview:=app_private.preview_lifecycle_definition(actor_user_id,target_workspace_id,d.id,target_kind);
 if preview->>'preview_token' is distinct from expected_preview_token then raise exception 'document impact changed; refresh preview' using errcode='PT409'; end if;
 for item in select value from jsonb_array_elements(preview->'employees') where value->>'action' in ('assign','update','reopen','remove') loop
  select m.* into member from public.workspace_memberships m join public.employee_profiles e on e.workspace_id=m.workspace_id and e.user_id=m.user_id
   where e.id=(item->>'employee_id')::uuid and m.workspace_id=target_workspace_id;
  if item->>'action'='assign' then
   insert into public.employee_onboarding_cases(workspace_id,employee_id,membership_id,status,approved_at,approved_by)
   values(target_workspace_id,(item->>'employee_id')::uuid,member.id,
    case when member.status='active' then 'approved'::public.employee_onboarding_case_status else 'in_progress'::public.employee_onboarding_case_status end,
    case when member.status='active' then now() end,case when member.status='active' then actor_user_id end)
   on conflict(employee_id) do nothing;
   select id into case_id from public.employee_onboarding_cases where workspace_id=target_workspace_id and employee_id=(item->>'employee_id')::uuid;
   insert into public.employee_onboarding_requirements(workspace_id,employee_id,case_id,kind,source_id,title,description,required,blocks_activation,requires_review,sort_order,source_snapshot,lifecycle_settings)
   values(target_workspace_id,(item->>'employee_id')::uuid,case_id,target_kind::public.employee_onboarding_requirement_kind,d.id,d.title,d.description,d.lifecycle_settings->>'mode'='required',d.lifecycle_settings->>'mode'='required',d.requires_review,100+d.sort_order,d.snapshot,d.lifecycle_settings)
   returning * into r;
  else
   select * into r from public.employee_onboarding_requirements where id=(item->>'requirement_id')::uuid;
   deadline:=r.deadline_at;
   r.publication_paused_at:=null; r.lifecycle_closed_at:=null; if r.status='superseded' then r.status:='not_started'; end if;
   valid_approved:=app_private.document_obligation_state(r,now())='completed';
   if item->>'deadline_action'='clear' or valid_approved then deadline:=null;
   elsif item->>'deadline_action'='restart' then
    deadline:=case when member.status='active' and d.lifecycle_settings->>'period_days' is not null then now()+(d.lifecycle_settings->>'period_days')::integer*interval '24 hours' end;
   end if;
   update public.employee_onboarding_requirements set
    title=d.title,description=d.description,source_snapshot=d.snapshot,lifecycle_settings=d.lifecycle_settings,
    required=d.lifecycle_settings->>'mode'='required',blocks_activation=d.lifecycle_settings->>'mode'='required',requires_review=d.requires_review,
    lifecycle_assignment_disabled=d.archived_at is not null,lifecycle_closed_at=case when item->>'action'='remove' then now() end,lifecycle_close_reason=case when item->>'action'='remove' then btrim(apply_reason) end,
    status=case when item->>'action'='reopen' and status='superseded' then 'not_started'::public.employee_onboarding_requirement_status else status end,
    publication_paused_at=case when target_kind='document' then null else publication_paused_at end,deadline_at=deadline,paused_remaining_seconds=case when target_kind='document' and item->>'deadline_action'='restart' and not valid_approved and d.lifecycle_settings->>'mode'<>'optional' and exists(select 1 from public.employee_document_submissions s where s.id=r.submitted_document_id and s.state='pending_review') then (d.lifecycle_settings->>'period_days')::numeric*86400 when item->>'deadline_action'='preserve' then paused_remaining_seconds end,
    document_suspended_at=case when target_kind='document' and item->>'deadline_action'='restart' then null when item->>'action'='remove' or d.lifecycle_settings->>'mode'='optional' or not (d.lifecycle_settings->>'suspend_on_overdue')::boolean then null else document_suspended_at end,
    lifecycle_revision=lifecycle_revision+1,updated_at=now() where id=r.id returning * into r;
  end if;
  perform app_private.document_audit(r,actor_user_id,'document.definition_applied',jsonb_build_object('reason',btrim(apply_reason),'definition_revision',d.lifecycle_revision,'action',item->>'action','revision',r.lifecycle_revision,'deadline_action',item->>'deadline_action'));
  if member.status='pending_activation' and r.required and item->>'action' in ('assign','reopen') then update public.employee_onboarding_cases set status='changes_requested',revision=revision+1,updated_at=now() where id=r.case_id and status='submitted'; end if; perform app_private.document_sync_onboarding(r.id,actor_user_id); applied:=applied+1;
 end loop;
 return jsonb_build_object('applied',applied);
end;
$$;


ALTER FUNCTION "app_private"."apply_lifecycle_definition"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid", "expected_revision" integer, "expected_preview_token" "text", "apply_reason" "text", "target_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."apply_owner_onboarding_update"("actor_user_id" "uuid", "target_workspace_id" "uuid", "workspace_name" "text", "next_step" smallint, "mark_complete" boolean DEFAULT false, "expected_revision" integer DEFAULT NULL::integer, "owner_first_name" "text" DEFAULT NULL::"text", "owner_middle_name" "text" DEFAULT NULL::"text", "owner_last_name" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  owner_employee_id uuid;
  current_status public.onboarding_status;
  current_revision integer;
  completed_timestamp timestamptz;
  names_given boolean := coalesce(btrim(owner_first_name), '') <> ''
    or coalesce(btrim(owner_middle_name), '') <> ''
    or coalesce(btrim(owner_last_name), '') <> '';
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;
  if not exists (
    select 1
    from public.workspace_memberships membership
    where membership.workspace_id = target_workspace_id
      and membership.user_id = actor_user_id
      and membership.role = 'owner'
      and membership.status = 'active'
  ) then
    raise exception 'owner access required' using errcode = '42501';
  end if;
  if char_length(btrim(workspace_name)) not between 1 and 120 then
    raise exception 'workspace name must be between 1 and 120 characters' using errcode = '22023';
  end if;
  if next_step not between 1 and 4 then
    raise exception 'invalid onboarding step' using errcode = '22023';
  end if;

  select onboarding.status, onboarding.revision
  into current_status, current_revision
  from public.workspace_onboarding onboarding
  where onboarding.workspace_id = target_workspace_id
  for update;

  if current_status is null then
    raise exception 'workspace onboarding was not found' using errcode = 'P0002';
  end if;

  if current_status = 'complete'::public.onboarding_status then
    if mark_complete then
      return;
    end if;
    raise exception 'completed owner onboarding cannot be changed' using errcode = '22023';
  end if;

  if expected_revision is not null and current_revision <> expected_revision then
    raise exception 'owner onboarding revision conflict' using errcode = 'PT409';
  end if;

  if mark_complete and not exists (
    select 1
    from public.locations location
    where location.workspace_id = target_workspace_id
      and location.archived_at is null
  ) then
    raise exception 'at least one active location is required to complete owner onboarding' using errcode = '23514';
  end if;

  if mark_complete and not exists (
    select 1
    from public.departments department
    where department.workspace_id = target_workspace_id
      and department.archived_at is null
      and department.system_key is null
  ) then
    raise exception 'at least one department of your own is required to complete owner onboarding' using errcode = '23514';
  end if;

  if mark_complete and not exists (
    select 1
    from public.jobs job
    left join public.departments department on department.id = job.department_id
    where job.workspace_id = target_workspace_id
      and job.archived_at is null
      and department.system_key is distinct from 'management'
  ) then
    raise exception 'at least one job outside Management is required to complete owner onboarding' using errcode = '23514';
  end if;

  completed_timestamp := now();

  update public.workspaces
  set name = btrim(workspace_name), updated_at = completed_timestamp
  where id = target_workspace_id;

  update public.workspace_onboarding
  set
    status = case
      when mark_complete then 'complete'::public.onboarding_status
      else 'incomplete'::public.onboarding_status
    end,
    current_step = next_step,
    completed_at = case when mark_complete then completed_timestamp else null end,
    revision = revision + 1,
    updated_by = actor_user_id,
    updated_at = completed_timestamp
  where workspace_id = target_workspace_id;

  -- No names sent and none on file: the first step has not been answered.
  if not names_given and not exists (
    select 1
    from public.employee_profiles employee
    join public.employee_private_profiles private_profile
      on private_profile.employee_id = employee.id
    where employee.workspace_id = target_workspace_id
      and employee.user_id = actor_user_id
      and employee.archived_at is null
  ) then
    raise exception 'the owner''s legal name is required' using errcode = '23514';
  end if;

  -- The owner is a member from the first step, so their record exists from the
  -- first step too. Waiting for completion meant the team list did not contain
  -- the one person who was certainly on the team.
  owner_employee_id := app_private.ensure_owner_employee_profile(
    target_workspace_id,
    actor_user_id,
    owner_first_name,
    owner_middle_name,
    owner_last_name
  );

  if names_given then
    perform app_private.write_owner_legal_name(
      target_workspace_id, owner_employee_id,
      owner_first_name, owner_middle_name, owner_last_name
    );
  end if;

  -- Management, Owner and Manager exist from the first save, so the setup steps
  -- and Settings show them; nothing under Management counts as the owner's own
  -- department and job (K2).
  perform app_private.ensure_management_and_owner(target_workspace_id);

  -- Locations come into existence during setup, so this runs on every save and
  -- picks up whatever was added since the last one.
  perform app_private.open_owner_record_to_everything(
    target_workspace_id,
    owner_employee_id,
    actor_user_id
  );

  if mark_complete then

    insert into public.workspace_entitlements (
      workspace_id,
      status,
      trial_started_at,
      trial_ends_at,
      current_period_started_at,
      current_period_ends_at,
      billing_owner_user_id,
      provider,
      created_at,
      updated_at
    ) values (
      target_workspace_id,
      'trialing'::public.workspace_entitlement_status,
      completed_timestamp,
      completed_timestamp + interval '14 days',
      completed_timestamp,
      completed_timestamp + interval '14 days',
      actor_user_id,
      'internal'::public.workspace_entitlement_provider,
      completed_timestamp,
      completed_timestamp
    )
    on conflict (workspace_id) do nothing;
  end if;

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_workspace_id,
    actor_user_id,
    case when mark_complete then 'workspace.onboarding_completed' else 'workspace.onboarding_saved' end,
    'workspace',
    target_workspace_id::text,
    jsonb_build_object(
      'step', next_step,
      'previous_revision', current_revision,
      'revision', current_revision + 1
    )
  );
end;
$$;


ALTER FUNCTION "app_private"."apply_owner_onboarding_update"("actor_user_id" "uuid", "target_workspace_id" "uuid", "workspace_name" "text", "next_step" smallint, "mark_complete" boolean, "expected_revision" integer, "owner_first_name" "text", "owner_middle_name" "text", "owner_last_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."assert_document_definition_target"("actor" "uuid", "w" "uuid", "target" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare options jsonb; pair text[]; selected jsonb;
begin
 options:=public.document_definition_target_options_service(actor,w);
 if coalesce(target->>'operator','and') not in ('and','or') then raise exception 'valid target operator required' using errcode='22023'; end if;
 foreach pair slice 1 in array array[['location_ids','locations'],['department_ids','departments'],['job_ids','jobs'],['employee_ids','employees']] loop
  if jsonb_typeof(coalesce(target->pair[1],'[]'))<>'array' then raise exception 'valid target selection required' using errcode='22023'; end if;
  for selected in select value from jsonb_array_elements(coalesce(target->pair[1],'[]')) loop
   if not exists(select 1 from jsonb_array_elements(options->pair[2]) o where o->'id'=selected) then raise exception 'document target access denied' using errcode='42501'; end if;
  end loop;
 end loop;
end;
$$;


ALTER FUNCTION "app_private"."assert_document_definition_target"("actor" "uuid", "w" "uuid", "target" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."employee_onboarding_requirements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "case_id" "uuid" NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "kind" "public"."employee_onboarding_requirement_kind" NOT NULL,
    "source_id" "uuid",
    "title" "text" NOT NULL,
    "description" "text" DEFAULT ''::"text" NOT NULL,
    "required" boolean DEFAULT true NOT NULL,
    "blocks_activation" boolean DEFAULT true NOT NULL,
    "requires_review" boolean DEFAULT false NOT NULL,
    "sort_order" integer NOT NULL,
    "status" "public"."employee_onboarding_requirement_status" DEFAULT 'not_started'::"public"."employee_onboarding_requirement_status" NOT NULL,
    "source_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "rejection_reason" "text",
    "completed_at" timestamp with time zone,
    "reviewed_at" timestamp with time zone,
    "reviewed_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lifecycle_revision" integer DEFAULT 1 NOT NULL,
    "lifecycle_settings" "jsonb",
    "lifecycle_user_id" "uuid",
    "deadline_at" timestamp with time zone,
    "paused_remaining_seconds" numeric,
    "document_suspended_at" timestamp with time zone,
    "lifecycle_closed_at" timestamp with time zone,
    "lifecycle_close_reason" "text",
    "lifecycle_exempt" boolean DEFAULT false NOT NULL,
    "conditional_reason" "text",
    "submitted_document_id" "uuid",
    "approved_document_id" "uuid",
    "lifecycle_retired_at" timestamp with time zone,
    "lifecycle_assignment_disabled" boolean DEFAULT false NOT NULL,
    "publication_paused_at" timestamp with time zone,
    "owner_excused" boolean DEFAULT false NOT NULL,
    CONSTRAINT "employee_onboarding_requirements_check" CHECK (((NOT "blocks_activation") OR "required")),
    CONSTRAINT "employee_onboarding_requirements_description_check" CHECK (("char_length"("description") <= 500)),
    CONSTRAINT "employee_onboarding_requirements_lifecycle_revision_check" CHECK (("lifecycle_revision" > 0)),
    CONSTRAINT "employee_onboarding_requirements_paused_remaining_seconds_check" CHECK (("paused_remaining_seconds" >= (0)::numeric)),
    CONSTRAINT "employee_onboarding_requirements_rejection_reason_check" CHECK ((("rejection_reason" IS NULL) OR (("char_length"("rejection_reason") >= 1) AND ("char_length"("rejection_reason") <= 500)))),
    CONSTRAINT "employee_onboarding_requirements_sort_order_check" CHECK (("sort_order" >= 0)),
    CONSTRAINT "employee_onboarding_requirements_title_check" CHECK ((("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 120)))
);


ALTER TABLE "public"."employee_onboarding_requirements" OWNER TO "postgres";


COMMENT ON COLUMN "public"."employee_onboarding_requirements"."owner_excused" IS 'Excused because the record belonged to the owner; taken back when it no longer does.';



CREATE OR REPLACE FUNCTION "app_private"."assert_document_published"("r" "public"."employee_onboarding_requirements") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if r.kind='document' and (r.publication_paused_at is not null or (r.source_id is not null and exists(select 1 from public.document_types d where d.id=r.source_id and d.workspace_id=r.workspace_id and d.publication_status<>'published')))
 then raise exception 'Document is unpublished; changes are paused' using errcode='PT409'; end if;
end;
$$;


ALTER FUNCTION "app_private"."assert_document_published"("r" "public"."employee_onboarding_requirements") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."authorize"("actor" "uuid", "w" "uuid", "action" "text", "target_locations" "uuid"[] DEFAULT NULL::"uuid"[], "target_person" "uuid" DEFAULT NULL::"uuid", "target_user" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reason text := app_private.authz_reason(actor, w, action, target_locations, target_person, target_user);
begin
  if reason is not null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || reason, detail = action;
  end if;
end;
$$;


ALTER FUNCTION "app_private"."authorize"("actor" "uuid", "w" "uuid", "action" "text", "target_locations" "uuid"[], "target_person" "uuid", "target_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."authorize_employee_list"("actor" "uuid", "w" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reason text := app_private.authz_check(app_private.actor(actor, w),
    (select r from app_private.authz_actions r where r.key = 'employee.list'), null, null, null);
begin
  if reason is not null and reason <> 'out_of_scope' then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || reason, detail = 'employee.list';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."authorize_employee_list"("actor" "uuid", "w" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."authorize_role_grant"("actor" "uuid", "w" "uuid", "next_role_id" "uuid", "target_person" "uuid" DEFAULT NULL::"uuid", "target_user" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  next_class public.workspace_role := (
    select role.access_class from public.workspace_roles role where role.id = next_role_id and role.workspace_id = w
  );
begin
  perform app_private.authorize(actor, w,
    case when app_private.authz_rank(next_class) >= app_private.authz_rank('admin')
      then 'employee.make_admin' else 'employee.change_role' end,
    target_person => target_person, target_user => target_user);
  if next_class is null then
    raise exception 'target role not found' using errcode = 'P0002';
  end if;
  if app_private.authz_rank(next_class) >= app_private.authz_rank((app_private.actor(actor, w)).class) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.rank', detail = 'employee.change_role';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."authorize_role_grant"("actor" "uuid", "w" "uuid", "next_role_id" "uuid", "target_person" "uuid", "target_user" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "app_private"."authz_actions" (
    "key" "text" NOT NULL,
    "scope_class" "text" NOT NULL,
    "effect" "text" DEFAULT 'write'::"text" NOT NULL,
    "permission_key" "text",
    "owner_only" boolean DEFAULT false NOT NULL,
    "restricted_ok" boolean DEFAULT false NOT NULL,
    "self_ok" boolean DEFAULT false NOT NULL,
    "no_self" boolean DEFAULT false NOT NULL,
    "rank_below" boolean DEFAULT false NOT NULL,
    "employee_target" boolean DEFAULT false NOT NULL,
    "outranked_no" boolean DEFAULT false NOT NULL,
    CONSTRAINT "authz_actions_check" CHECK ((("effect" <> 'cross'::"text") OR ("scope_class" = 'person'::"text"))),
    CONSTRAINT "authz_actions_effect_check" CHECK (("effect" = ANY (ARRAY['read'::"text", 'write'::"text", 'cross'::"text"]))),
    CONSTRAINT "authz_actions_scope_class_check" CHECK (("scope_class" = ANY (ARRAY['account'::"text", 'own'::"text", 'org'::"text", 'place'::"text", 'set'::"text", 'person'::"text"])))
);


ALTER TABLE "app_private"."authz_actions" OWNER TO "postgres";


COMMENT ON TABLE "app_private"."authz_actions" IS 'Every action app_private.authorize() answers for. The keys are the ones supabase/tests/authorization_coverage.test.sql ties each entry point to.';



COMMENT ON COLUMN "app_private"."authz_actions"."outranked_no" IS 'No when target_user (the record''s author) outranks the actor today (FB-6.7 K2, KK-87).';



CREATE OR REPLACE FUNCTION "app_private"."authz_check"("state" "app_private"."actor_state", "rule_row" "app_private"."authz_actions", "target_locations" "uuid"[], "target_person" "uuid", "target_user" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_workspace uuid;
  person uuid := target_person;
  whose uuid;
  target_access public.workspace_role;
  target_is_self boolean;
  places uuid[];
  reach text;
begin
  if state.user_id is null then
    return 'not_member';
  end if;
  if rule_row.scope_class = 'account' then
    -- An account action is about one's own account.
    if target_user is not null and target_user is distinct from state.user_id then
      return 'out_of_scope';
    end if;
    return null;
  end if;
  if state.membership_id is null then
    return 'not_member';
  end if;
  if not state.workspace_open then
    return 'workspace_closed';
  end if;

  if person is not null then
    select profile.workspace_id, profile.user_id into target_workspace, whose
    from public.employee_profiles profile
    where profile.id = person;
    if target_workspace is distinct from state.workspace_id then
      return 'out_of_scope';
    end if;
  end if;
  if target_user is not null then
    if person is not null and whose is distinct from target_user then
      return 'out_of_scope';
    end if;
    whose := target_user;
    if person is null then
      select profile.id into person
      from public.employee_profiles profile
      where profile.workspace_id = state.workspace_id
        and profile.user_id = target_user
        and profile.archived_at is null;
      if person is null and not exists (
        select 1 from public.workspace_memberships membership
        where membership.workspace_id = state.workspace_id and membership.user_id = target_user
      ) then
        return 'out_of_scope';
      end if;
    end if;
  end if;
  target_is_self := coalesce(whose = state.user_id, false);

  -- Their own row is theirs to read in any state.
  if rule_row.self_ok and target_is_self then
    return null;
  end if;

  if state.status = 'pending_activation' then
    if not rule_row.restricted_ok then
      return 'not_active';
    end if;
  elsif state.status <> 'active' then
    return 'not_active';
  elsif state.document_blocked and not rule_row.restricted_ok then
    return 'document_blocked';
  end if;

  if rule_row.scope_class = 'own' then
    -- One's own availability is an employee's (M13): a manager, an admin or
    -- the owner has no own record of that kind.
    if rule_row.employee_target and state.class <> 'employee' then
      return 'rank';
    end if;
    if (person is null and whose is null) or target_is_self then
      return null;
    end if;
    return 'out_of_scope';
  end if;

  if rule_row.owner_only and state.class <> 'owner' then
    return 'owner_only';
  end if;
  -- The owner holds every permission.
  if state.class <> 'owner'
     and rule_row.permission_key is not null
     and not rule_row.permission_key = any (state.permissions) then
    return 'missing_permission';
  end if;
  if state.class = 'employee' then
    return 'missing_permission';
  end if;

  if rule_row.no_self and target_is_self then
    return 'rank';
  end if;
  -- A manager's own record goes one level up; owners and admins keep theirs
  -- (user decision 2026-09-24, 2A).
  if rule_row.rank_below and target_is_self and state.class not in ('owner', 'admin') then
    return 'rank';
  end if;
  if rule_row.rank_below and (person is not null or whose is not null) and not target_is_self then
    select role.access_class into target_access
    from public.workspace_memberships membership
    join public.workspace_roles role
      on role.id = membership.role_id and role.workspace_id = membership.workspace_id
    where membership.workspace_id = state.workspace_id and membership.user_id = whose;
    -- ponytail: somebody without a membership yet ranks as an employee; use the
    -- invitation's role if a manager ever invites into a higher one.
    if app_private.authz_rank(coalesce(target_access, 'employee')) >= app_private.authz_rank(state.class) then
      return 'rank';
    end if;
  end if;

  -- Some actions are about employees only: never a manager, an admin or the
  -- owner, whoever asks, themselves included (the Manager note, 2026-09-26).
  if rule_row.employee_target and (person is not null or whose is not null)
     and not app_private.ranks_as_employee(state.workspace_id, whose) then
    return 'rank';
  end if;

  -- A record whose author outranks the actor today is not theirs to change;
  -- a peer's is (FB-6.7 K2, KK-87).
  if rule_row.outranked_no and whose is not null and not target_is_self then
    select role.access_class into target_access
    from public.workspace_memberships membership
    join public.workspace_roles role
      on role.id = membership.role_id and role.workspace_id = membership.workspace_id
    where membership.workspace_id = state.workspace_id and membership.user_id = whose;
    if app_private.authz_rank(coalesce(target_access, 'employee')) > app_private.authz_rank(state.class) then
      return 'rank';
    end if;
  end if;

  if state.class in ('owner', 'admin') then
    reach := 'org';
  else
    select rule.manager_rule into reach
    from app_private.authz_scope_rules rule
    join app_private.authz_settings setting on setting.scope_model = rule.model
    where rule.scope_class = rule_row.scope_class and rule.effect = rule_row.effect;
    reach := coalesce(reach, 'none');
  end if;

  if rule_row.scope_class = 'org' then
    if reach = 'none' then
      return 'out_of_scope';
    end if;
    return null;
  end if;

  if target_locations is not null then
    places := target_locations;
    if array_position(places, null) is not null then
      return 'out_of_scope';
    end if;
    if rule_row.scope_class = 'place' and cardinality(places) <> 1 then
      return 'out_of_scope';
    end if;
    if exists (
      select 1 from unnest(places) place
      where not exists (
        select 1 from public.locations location
        where location.id = place and location.workspace_id = state.workspace_id and app_private.location_is_live(location)
      )
    ) then
      return 'out_of_scope';
    end if;
  elsif rule_row.scope_class = 'person' and (person is not null or whose is not null) then
    -- Where the person is assigned; somebody with no employee record works nowhere.
    places := coalesce((
      select array_agg(distinct assignment.location_id)
      from public.employee_location_assignments assignment
      join public.locations location on location.id = assignment.location_id
      where assignment.employee_id = person and assignment.ended_at is null
        and app_private.location_is_live(location)
    ), '{}');
  else
    return 'out_of_scope';
  end if;

  if reach = 'org' then
    return null;
  end if;
  if reach = 'none' or cardinality(places) = 0 then
    return 'out_of_scope';
  end if;
  if reach = 'any' and places && state.manages then
    return null;
  end if;
  if reach = 'all' and places <@ state.manages then
    return null;
  end if;
  return 'out_of_scope';
end;
$$;


ALTER FUNCTION "app_private"."authz_check"("state" "app_private"."actor_state", "rule_row" "app_private"."authz_actions", "target_locations" "uuid"[], "target_person" "uuid", "target_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."authz_rank"("access" "public"."workspace_role") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case access when 'owner' then 4 when 'admin' then 3 when 'manager' then 2 when 'employee' then 1 else 0 end
$$;


ALTER FUNCTION "app_private"."authz_rank"("access" "public"."workspace_role") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."authz_reason"("actor" "uuid", "w" "uuid", "action" "text", "target_locations" "uuid"[] DEFAULT NULL::"uuid"[], "target_person" "uuid" DEFAULT NULL::"uuid", "target_user" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  rule_row app_private.authz_actions;
begin
  select * into rule_row from app_private.authz_actions a where a.key = action;
  if not found then
    raise exception 'Unknown action %', action using errcode = '22023';
  end if;
  return app_private.authz_check(app_private.actor(actor, w), rule_row, target_locations, target_person, target_user);
end;
$$;


ALTER FUNCTION "app_private"."authz_reason"("actor" "uuid", "w" "uuid", "action" "text", "target_locations" "uuid"[], "target_person" "uuid", "target_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."availability_follows_role"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare employee uuid; is_employee boolean := app_private.ranks_as_employee(new.workspace_id, new.user_id);
begin
  select e.id into employee from public.employee_profiles e where e.workspace_id = new.workspace_id and e.user_id = new.user_id;
  if employee is null then return null; end if;
  if not is_employee then
    delete from public.manager_weekly_reminders where workspace_id = new.workspace_id and employee_id = employee;
    delete from public.employee_weekly_preferences where workspace_id = new.workspace_id and employee_id = employee;
    delete from public.weekly_preference_events
    where workspace_id = new.workspace_id and employee_id = employee and source = 'employee';
    delete from public.weekly_preference_commands
    where workspace_id = new.workspace_id and command ->> 'employee_id' = employee::text and command ->> 'source' = 'employee';
  end if;

  -- An open onboarding gains or loses the Availability step with the role.
  with open_cases as (
    select c.id from public.employee_onboarding_cases c
    where c.workspace_id = new.workspace_id and c.employee_id = employee
      and c.status in ('in_progress', 'submitted', 'changes_requested')
    order by c.id for update),
  dropped as (
    delete from public.employee_onboarding_requirements r using open_cases c
    where not is_employee and r.case_id = c.id and r.kind = 'availability' and r.lifecycle_retired_at is null
    returning r.case_id),
  added as (
    insert into public.employee_onboarding_requirements (workspace_id, case_id, employee_id, kind, title, description,
      required, blocks_activation, requires_review, sort_order, source_snapshot)
    select new.workspace_id, c.id, employee, 'availability', 'Availability', 'Confirmed recurring weekly availability.',
      false, false, false, 500, '{}'::jsonb
    from open_cases c
    where is_employee and not exists (select 1 from public.employee_onboarding_requirements r
      where r.case_id = c.id and r.kind = 'availability' and r.lifecycle_retired_at is null)
    returning case_id)
  update public.employee_onboarding_cases set revision = revision + 1, updated_at = now()
  where id in (select case_id from dropped union select case_id from added);
  return null;
end;
$$;


ALTER FUNCTION "app_private"."availability_follows_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."can_access_location"("target_workspace_id" "uuid", "target_location_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select not app_private.document_actor_blocked((select auth.uid()), target_workspace_id) and exists (
    select 1
    from public.workspace_memberships membership
    where membership.workspace_id = target_workspace_id
      and membership.user_id = (select auth.uid())
      and membership.status = 'active'
      and app_private.workspace_open_to_actor(target_workspace_id, (select auth.uid()))
      and (
        membership.all_locations
        or exists (
          select 1
          from public.membership_location_scopes scope
          where scope.membership_id = membership.id
            and scope.workspace_id = target_workspace_id
            and scope.location_id = target_location_id
        )
      )
  );
$$;


ALTER FUNCTION "app_private"."can_access_location"("target_workspace_id" "uuid", "target_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."can_edit_role"("actor" "uuid", "w" "uuid", "rid" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select exists(select 1 from public.workspace_memberships m join public.workspace_roles ar on ar.id=m.role_id
 left join public.workspace_roles target on target.id=rid and target.workspace_id=w
 where m.user_id=actor and m.workspace_id=w and m.status='active' and m.role_id is distinct from rid
 and public.service_actor_has_permission(actor,w,'roles.manage')
 and (rid is null or (target.id is not null and target.access_class<>'owner'))
 and (ar.access_class='owner' or (ar.access_class='admin' and (rid is null or target.access_class in ('manager','employee')))));
$$;


ALTER FUNCTION "app_private"."can_edit_role"("actor" "uuid", "w" "uuid", "rid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."can_invite_with_role"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_role_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((
    select app_private.authz_rank(role.access_class) < app_private.authz_rank(state.class)
      and app_private.authz_reason(actor_user_id, target_workspace_id, 'employee.create', state.manages) is null
    from app_private.actor(actor_user_id, target_workspace_id) state
    join public.workspace_roles role on role.workspace_id = state.workspace_id
    where role.id = target_role_id
  ), false)
$$;


ALTER FUNCTION "app_private"."can_invite_with_role"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_role_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."can_manage_workspace"("target_workspace_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select app_private.workspace_has_permission(target_workspace_id, 'workspace.manage');
$$;


ALTER FUNCTION "app_private"."can_manage_workspace"("target_workspace_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."schedule_edit_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "week_start" "date" NOT NULL,
    "source_kind" "public"."schedule_edit_source" NOT NULL,
    "source_draft_id" "uuid",
    "source_revision" integer DEFAULT 0 NOT NULL,
    "holder_user_id" "uuid" NOT NULL,
    "revision" integer DEFAULT 1 NOT NULL,
    "dirty" boolean DEFAULT false NOT NULL,
    "status" "public"."schedule_edit_session_status" DEFAULT 'active'::"public"."schedule_edit_session_status" NOT NULL,
    "last_heartbeat" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '00:04:00'::interval) NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    "recovered_draft_id" "uuid",
    "location_ids" "uuid"[] NOT NULL,
    "base_publication_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    CONSTRAINT "schedule_edit_sessions_check" CHECK (((("source_kind" = 'draft'::"public"."schedule_edit_source") AND ("source_draft_id" IS NOT NULL) AND ("source_revision" > 0)) OR (("source_kind" <> 'draft'::"public"."schedule_edit_source") AND ("source_draft_id" IS NULL)))),
    CONSTRAINT "schedule_edit_sessions_location_ids_check" CHECK (("cardinality"("location_ids") > 0)),
    CONSTRAINT "schedule_edit_sessions_revision_check" CHECK (("revision" > 0)),
    CONSTRAINT "schedule_edit_sessions_source_revision_check" CHECK (("source_revision" >= 0))
);


ALTER TABLE "public"."schedule_edit_sessions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."close_schedule_edit_session"("edit" "public"."schedule_edit_sessions") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare recovery_draft_id uuid; base_name text; draft_name text; copy integer := 1;
begin
  -- Unsaved work becomes a recovery draft; nothing of it is deleted.
  if edit.dirty then
    -- KK-162: "Auto-save · Ayşe Yılmaz · Oct 5, 9:14 PM", in the edit's
    -- location's time and the workspace's 12/24-hour clock.
    base_name := 'Auto-save · ' || left(coalesce(nullif(btrim((select profile.display_name from public.user_profiles profile
        where profile.user_id = edit.holder_user_id)), ''), 'Manager'), 40)
      || ' · ' || to_char(now() at time zone coalesce((select location.timezone from public.locations location
          where location.id = any(edit.location_ids) order by location.name, location.id limit 1), 'UTC'),
        case when (select settings.time_format from public.workspace_scheduling_settings settings
          where settings.workspace_id = edit.workspace_id) = '24h' then 'Mon FMDD, HH24:MI' else 'Mon FMDD, FMHH12:MI AM' end);
    draft_name := base_name;
    -- ponytail: names are unique in a week; count up until one is free.
    while exists (select 1 from public.schedule_drafts draft
      where draft.workspace_id = edit.workspace_id and draft.week_start = edit.week_start
        and draft.archived_at is null and lower(btrim(draft.name)) = lower(btrim(draft_name))) loop
      copy := copy + 1;
      draft_name := base_name || ' (' || copy || ')';
    end loop;
    insert into public.schedule_drafts (
      workspace_id, week_start, name, created_by, updated_by, location_ids, base_publication_ids
    ) values (
      edit.workspace_id, edit.week_start, draft_name,
      edit.holder_user_id, edit.holder_user_id, edit.location_ids, edit.base_publication_ids
    ) returning id into recovery_draft_id;
    insert into public.schedule_draft_shifts (id, workspace_id, draft_id, location_id, employee_id, job_id, shift_type_id, scheduled_date, start_time, end_time, time_basis, time_snapshot, time_timezone, unpaid_break_minutes, hide_time_on_badge, note, revision, label_ids, label_names)
    select id, workspace_id, recovery_draft_id, location_id, employee_id, job_id, shift_type_id, scheduled_date, start_time, end_time, time_basis, time_snapshot, time_timezone, unpaid_break_minutes, hide_time_on_badge, note, revision, label_ids, label_names
    from public.schedule_edit_session_shifts
    -- A shift the person took off stays off, as when they save.
    where session_id = edit.id and pending_op_type is distinct from 'delete';
  end if;
  update public.schedule_edit_sessions
  set status = case when recovery_draft_id is null then 'expired'::public.schedule_edit_session_status
                    else 'recovered'::public.schedule_edit_session_status end,
      recovered_draft_id = recovery_draft_id,
      closed_at = now()
  where id = edit.id;
  return recovery_draft_id;
end;
$$;


ALTER FUNCTION "app_private"."close_schedule_edit_session"("edit" "public"."schedule_edit_sessions") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."closure_days"("w" "uuid", "kind" "public"."important_date_type", "starts" "date", "ends" "date", "recurrence" "public"."important_date_recurrence", "location_ids" "uuid"[]) RETURNS TABLE("location_id" "uuid", "closed_date" "date")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select location.id, day::date
  from public.locations location
  cross join lateral generate_series(0, case when recurrence = 'annual'
    then greatest(extract(year from current_date)::integer + 2 - extract(year from starts)::integer, 0) else 0 end) as years(n)
  cross join lateral generate_series(starts + make_interval(years => years.n), ends + make_interval(years => years.n),
    interval '1 day') as days(day)
  where kind = 'closed_day' and location.workspace_id = w and location.archived_at is null
    and (cardinality(location_ids) = 0 or location.id = any (location_ids))
$$;


ALTER FUNCTION "app_private"."closure_days"("w" "uuid", "kind" "public"."important_date_type", "starts" "date", "ends" "date", "recurrence" "public"."important_date_recurrence", "location_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."communication_audience"("w" "uuid", "stored" "uuid"[], "roles" "public"."workspace_role"[], "department_ids" "uuid"[], "job_ids" "uuid"[]) RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with live as (
    select app_private.live_locations(w, stored) ids, cardinality(stored) = 0 everywhere
  )
  select membership.user_id
  from public.workspace_memberships membership, live
  where membership.workspace_id = w and membership.status = 'active'
    and app_private.communication_reaches(app_private.actor(membership.user_id, w), w, live.ids, live.everywhere,
          roles, department_ids, job_ids)
$$;


ALTER FUNCTION "app_private"."communication_audience"("w" "uuid", "stored" "uuid"[], "roles" "public"."workspace_role"[], "department_ids" "uuid"[], "job_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."communication_authorize"("actor" "uuid", "w" "uuid", "kind" "text", "stored" "uuid"[], "author" "uuid", "kept" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  reason text := app_private.communication_reason(app_private.actor(actor, w), w, kind, stored, author);
begin
  if reason is null and exists (
    select 1 from unnest(stored) id
    where not id = any (app_private.live_locations(w, stored)) and not id = any (kept)
  ) then
    reason := 'out_of_scope';
  end if;
  if reason is not null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || reason, detail = kind || '.write';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."communication_authorize"("actor" "uuid", "w" "uuid", "kind" "text", "stored" "uuid"[], "author" "uuid", "kept" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."communication_reaches"("state" "app_private"."actor_state", "w" "uuid", "live" "uuid"[], "everywhere" boolean, "roles" "public"."workspace_role"[], "department_ids" "uuid"[], "job_ids" "uuid"[]) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  -- coalesce: somebody who is not a member (no status) gets a plain no.
  select coalesce(state.status = 'active', false) and coalesce(
    state.manages && live
    or (everywhere and cardinality(state.manages) > 0)
    or ((roles is null or state.class = any (roles))
        and (everywhere or state.works && live)
        and (cardinality(coalesce(department_ids, '{}')) = 0 or exists (
          select 1 from public.employee_job_assignments assignment
          join public.jobs job on job.id = assignment.job_id and job.workspace_id = w
          where assignment.workspace_id = w and assignment.employee_id = state.employee_id
            and assignment.ended_at is null and job.archived_at is null and job.department_id = any (department_ids)))
        and (cardinality(coalesce(job_ids, '{}')) = 0 or exists (
          select 1 from public.employee_job_assignments assignment
          join public.jobs job on job.id = assignment.job_id and job.workspace_id = w
          where assignment.workspace_id = w and assignment.employee_id = state.employee_id
            and assignment.ended_at is null and job.archived_at is null and job.id = any (job_ids)))), false)
$$;


ALTER FUNCTION "app_private"."communication_reaches"("state" "app_private"."actor_state", "w" "uuid", "live" "uuid"[], "everywhere" boolean, "roles" "public"."workspace_role"[], "department_ids" "uuid"[], "job_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."communication_reason"("state" "app_private"."actor_state", "w" "uuid", "kind" "text", "stored" "uuid"[], "author" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  live uuid[] := app_private.live_locations(w, stored);
  writer uuid := (
    select membership.user_id from public.workspace_memberships membership
    where membership.workspace_id = w and membership.user_id = author and membership.status = 'active'
  );
  -- The role the author last had here, whether they are still here or not.
  last_role public.workspace_role := (
    select role.access_class from public.workspace_memberships membership
    join public.workspace_roles role on role.id = membership.role_id and role.workspace_id = membership.workspace_id
    where membership.workspace_id = w and membership.user_id = author
  );
  narrow app_private.authz_actions;
  wide app_private.authz_actions;
  reason text;
begin
  select * into strict narrow from app_private.authz_actions a where a.key = kind || '.write';
  select * into strict wide from app_private.authz_actions a where a.key = kind || '.write_wide';
  -- An admin or owner who has left protects the record harder, not softer:
  -- only an admin or the owner changes it (Mert, 2026-10-02, O1; fail
  -- closed). So does a record that no longer says who wrote it (a deleted
  -- account). A manager who has left ranks as the manager they were ("En
  -- nihayetinde o da müdürdü.", Mert, 2026-10-02): the K3 rule goes on.
  if writer is null and (last_role is null or last_role in ('owner', 'admin')) then
    reason := app_private.authz_check(state, wide, null, null, null);
    return case when reason = 'out_of_scope' then 'rank' else reason end;
  end if;
  writer := author;
  if cardinality(stored) > 0 and cardinality(live) = 1 then
    return app_private.authz_check(state, narrow, live, null, writer);
  end if;
  return app_private.authz_check(state, wide, null, null, writer);
end;
$$;


ALTER FUNCTION "app_private"."communication_reason"("state" "app_private"."actor_state", "w" "uuid", "kind" "text", "stored" "uuid"[], "author" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."communication_withdraw"("w" "uuid", "type_key" "text", "subject_type" "text", "subject_id" "text", "visibility" "text", "people" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  outbox_row public.notification_outbox%rowtype;
  legacy_ids uuid[];
begin
  for outbox_row in
    select * from public.notification_outbox outbox
    where outbox.workspace_id = w and outbox.type_key = communication_withdraw.type_key
      and outbox.subject_type = communication_withdraw.subject_type
      and outbox.subject_id = communication_withdraw.subject_id
    for update
  loop
    if people is not null then
      update public.notification_outbox outbox
      set payload = jsonb_set(outbox.payload, '{recipient_user_ids}', coalesce((
            select jsonb_agg(who) from jsonb_array_elements_text(outbox.payload -> 'recipient_user_ids') who
            where not who::uuid = any (people)), '[]'::jsonb))
      where outbox.id = outbox_row.id and outbox.status in ('pending', 'retry');

      select coalesce(array_agg(item.legacy_notification_id), '{}') into legacy_ids
      from public.notification_inbox_items item
      join public.notification_recipients recipient on recipient.id = item.recipient_projection_id
      where recipient.workspace_id = w and recipient.event_id = outbox_row.event_id
        and recipient.recipient_user_id = any (people) and item.legacy_notification_id is not null;

      update public.notification_inbox_items item
      set visibility_state = visibility, legacy_notification_id = null
      from public.notification_recipients recipient
      where recipient.id = item.recipient_projection_id
        and recipient.workspace_id = w and recipient.event_id = outbox_row.event_id
        and recipient.recipient_user_id = any (people) and item.visibility_state = 'visible';

      delete from public.notifications notification
      where notification.id = any (legacy_ids) and notification.workspace_id = w;
      continue;
    end if;

    perform public.project_notification_event_service(outbox_row.id);
    update public.notification_events event
    set cancelled_at = coalesce(event.cancelled_at, now())
    where event.id = outbox_row.event_id and event.workspace_id = w;

    select coalesce(array_agg(item.legacy_notification_id), '{}') into legacy_ids
    from public.notification_inbox_items item
    join public.notification_recipients recipient on recipient.id = item.recipient_projection_id
    where recipient.workspace_id = w and recipient.event_id = outbox_row.event_id
      and item.legacy_notification_id is not null;

    update public.notification_inbox_items item
    set visibility_state = visibility, legacy_notification_id = null
    from public.notification_recipients recipient
    where recipient.id = item.recipient_projection_id
      and recipient.workspace_id = w and recipient.event_id = outbox_row.event_id
      and item.visibility_state = 'visible';

    delete from public.notifications notification
    where notification.id = any (legacy_ids) and notification.workspace_id = w;

    update public.notification_outbox outbox
    set status = 'processed', lease_owner = null, lease_expires_at = null,
        last_error = 'withdrawn: ' || visibility,
        payload = outbox.payload || jsonb_build_object('cancelled_at', now(), 'visibility_state', visibility)
    where outbox.id = outbox_row.id and outbox.status in ('pending', 'retry', 'leased');
  end loop;
end;
$$;


ALTER FUNCTION "app_private"."communication_withdraw"("w" "uuid", "type_key" "text", "subject_type" "text", "subject_id" "text", "visibility" "text", "people" "uuid"[]) OWNER TO "postgres";


