CREATE TABLE IF NOT EXISTS "public"."document_types" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text" DEFAULT ''::"text" NOT NULL,
    "required_at_onboarding" boolean DEFAULT false NOT NULL,
    "requires_review" boolean DEFAULT true NOT NULL,
    "accepted_formats" "text"[] DEFAULT ARRAY['pdf'::"text", 'jpeg'::"text", 'png'::"text", 'webp'::"text"] NOT NULL,
    "tracks_expiry" boolean DEFAULT false NOT NULL,
    "expiry_warning_days" integer DEFAULT 30 NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "archived_at" timestamp with time zone,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expiry_schedule_impact" "public"."document_expiry_schedule_impact" DEFAULT 'track_only'::"public"."document_expiry_schedule_impact" NOT NULL,
    "expiry_policy_version" integer DEFAULT 1 NOT NULL,
    "lifecycle_revision" integer DEFAULT 1 NOT NULL,
    "lifecycle_settings" "jsonb" DEFAULT '{"mode": "optional", "target": {"job_ids": [], "employee_ids": [], "location_ids": [], "department_ids": []}, "period_days": null, "extra_fields": [], "assignment_scope": "future_onboarding", "suspend_on_overdue": false}'::"jsonb" NOT NULL,
    "publication_status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "publication_revision" integer DEFAULT 1 NOT NULL,
    "published_at" timestamp with time zone,
    CONSTRAINT "document_types_accepted_formats_check" CHECK ((("cardinality"("accepted_formats") > 0) AND ("accepted_formats" <@ ARRAY['pdf'::"text", 'jpeg'::"text", 'png'::"text", 'webp'::"text"]))),
    CONSTRAINT "document_types_description_check" CHECK (("char_length"("description") <= 240)),
    CONSTRAINT "document_types_expiry_block_requires_required" CHECK ((("expiry_schedule_impact" <> 'block'::"public"."document_expiry_schedule_impact") OR "required_at_onboarding")),
    CONSTRAINT "document_types_expiry_policy_version_check" CHECK (("expiry_policy_version" > 0)),
    CONSTRAINT "document_types_expiry_warning_days_check" CHECK ((("expiry_warning_days" >= 1) AND ("expiry_warning_days" <= 365))),
    CONSTRAINT "document_types_lifecycle_revision_check" CHECK (("lifecycle_revision" > 0)),
    CONSTRAINT "document_types_publication_revision_check" CHECK (("publication_revision" > 0)),
    CONSTRAINT "document_types_publication_status_check" CHECK (("publication_status" = ANY (ARRAY['draft'::"text", 'published'::"text"]))),
    CONSTRAINT "document_types_sort_order_check" CHECK (("sort_order" >= 0)),
    CONSTRAINT "document_types_title_check" CHECK ((("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 80)))
);


