CREATE OR REPLACE FUNCTION "app_private"."enqueue_document_notification"("w" "uuid", "e" "uuid", "u" "uuid", "k" "text", "kind" "text", "title" "text", "body" "text", "requirement" "uuid" DEFAULT NULL::"uuid", "actor" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare event uuid; recipients uuid[]; route text; requirement_kind text; submission uuid;
begin
 if kind='missing' then body:='You have outstanding document requests. Open Documents for details.'; end if; if u is null or not app_private.workspace_allows_interactive_access(w)
  or not exists(select 1 from public.employee_profiles p join public.workspace_memberships m on m.workspace_id=p.workspace_id and m.user_id=p.user_id where p.id=e and p.workspace_id=w and p.user_id=u and p.archived_at is null and m.status in ('active','pending_activation')) then return false; end if;
 if requirement is not null and kind in ('expiry','review','assigned') and exists(select 1 from public.employee_onboarding_requirements r where r.id=requirement and r.publication_paused_at is not null) then return false; end if; if requirement is not null then
  select r.kind::text,case when enqueue_document_notification.kind='expiry' then r.approved_document_id else r.submitted_document_id end into requirement_kind,submission from public.employee_onboarding_requirements r where r.id=requirement and r.workspace_id=w and r.employee_id=e and r.lifecycle_user_id=u and r.lifecycle_retired_at is null and r.lifecycle_closed_at is null and not r.lifecycle_exempt;
  if requirement_kind is null then return false; end if;
 end if;
 if kind='review' then
  select coalesce(array_agg(m.user_id),'{}'::uuid[]) into recipients from public.workspace_memberships m where m.workspace_id=w and m.status='active'
   and app_private.authz_reason(m.user_id,w,'documents.review',null,e) is null;
  route:='/app/employees/documents?requirement='||requirement::text;
 else recipients:=array[u]; route:='/app/account/documents?workspace='||w::text||case when requirement is null then '' else '&requirement='||requirement::text||'&kind='||requirement_kind end; end if;
 insert into app_private.document_notification_dedup(workspace_id,employee_id,user_id,notification_key) values(w,e,u,k) on conflict do nothing returning event_id into event;
 if event is null then return false; end if;
 perform public.enqueue_notification_outbox_service(w,event,'people.documents.'||kind,1,actor,'employee_documents',e::text,
  jsonb_build_object('correlation_id',event,'employee_id',e,'requirement_id',requirement,'submission_id',submission,'document_publication_revision',(select d.publication_revision from public.employee_onboarding_requirements r join public.document_types d on d.id=r.source_id and d.workspace_id=r.workspace_id where r.id=requirement and r.kind='document'),'recipient_user_ids',to_jsonb(recipients),'audience_contract',case when kind='review' then 'document_reviewers' else 'document_employee' end,
   'title',title,'body',body,'safe_preview','A document update is available.','action_url',route,'group_key','documents:'||e::text),now());
 return true;
end;
$$;


ALTER FUNCTION "app_private"."enqueue_document_notification"("w" "uuid", "e" "uuid", "u" "uuid", "k" "text", "kind" "text", "title" "text", "body" "text", "requirement" "uuid", "actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."enqueue_workspace_retention_purge_job"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  completed_closure_request_id uuid;
begin
  if new.lifecycle_status <> 'deleted' then
    return new;
  end if;

  select request.id into completed_closure_request_id
  from public.workspace_closure_requests request
  where request.workspace_id = new.id
    and request.status = 'completed'
  order by request.completed_at desc, request.created_at desc
  limit 1;

  insert into public.workspace_retention_purge_jobs (
    workspace_id,
    closure_request_id,
    due_at,
    metadata
  )
  values (
    new.id,
    completed_closure_request_id,
    coalesce(new.closed_at, now()),
    jsonb_build_object('source', 'workspace_deleted')
  )
  on conflict (workspace_id) do update
    set closure_request_id = coalesce(public.workspace_retention_purge_jobs.closure_request_id, excluded.closure_request_id),
        due_at = least(public.workspace_retention_purge_jobs.due_at, excluded.due_at),
        updated_at = now()
    where public.workspace_retention_purge_jobs.status = 'pending';

  return new;
end;
$$;


ALTER FUNCTION "app_private"."enqueue_workspace_retention_purge_job"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."ensure_management_and_owner"("target_workspace_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  made_management uuid;
begin
  insert into public.departments (workspace_id, name, system_key)
  values (target_workspace_id, 'Management', 'management')
  on conflict (workspace_id, system_key) where system_key is not null do nothing
  returning id into made_management;
  -- Manager is made with Management and never again: it is an ordinary job, so
  -- an owner who deletes it does not get it back on the next setup save. A job
  -- of that name already there is left alone.
  if made_management is not null then
    insert into public.jobs (workspace_id, name, department_id)
    values (target_workspace_id, 'Manager', made_management)
    on conflict (workspace_id, lower(name)) where archived_at is null do nothing;
  end if;
  insert into public.jobs (workspace_id, name, department_id, system_key)
  select target_workspace_id, 'Owner', department.id, 'owner'
  from public.departments department
  where department.workspace_id = target_workspace_id and department.system_key = 'management'
  on conflict (workspace_id, system_key) where system_key is not null do nothing;
end;
$$;


ALTER FUNCTION "app_private"."ensure_management_and_owner"("target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."ensure_owner_employee_profile"("target_workspace_id" "uuid", "owner_user_id" "uuid", "owner_first_name" "text" DEFAULT NULL::"text", "owner_middle_name" "text" DEFAULT NULL::"text", "owner_last_name" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  existing_employee_id uuid;
  next_code bigint;
  owner_email text;
  given_name text := btrim(coalesce(owner_first_name, ''));
  family_name text := btrim(coalesce(owner_last_name, ''));
begin
  if not exists (
    select 1
    from public.workspace_memberships membership
    where membership.workspace_id = target_workspace_id
      and membership.user_id = owner_user_id
      and membership.role = 'owner'::public.workspace_role
      and membership.status = 'active'::public.membership_status
  ) then
    raise exception 'active owner membership required' using errcode = '42501';
  end if;

  select employee.id
  into existing_employee_id
  from public.employee_profiles employee
  where employee.workspace_id = target_workspace_id
    and employee.user_id = owner_user_id
    and employee.archived_at is null
  order by employee.created_at
  limit 1
  for update;

  -- Whatever the employees tab says is what the workspace decided to call this
  -- person. Setup finishing again is not a reason to argue with it, and the
  -- owner hides from the schedule there like anyone else.
  if existing_employee_id is not null then
    return existing_employee_id;
  end if;

  if given_name = '' or family_name = '' then
    raise exception 'a legal name needs a first and a last name' using errcode = '22023';
  end if;

  select lower(auth_user.email) into owner_email
  from auth.users auth_user
  where auth_user.id = owner_user_id;

  select coalesce(max(substring(employee.employee_code from 3)::bigint), 0) + 1
  into next_code
  from public.employee_profiles employee
  where employee.workspace_id = target_workspace_id
    and employee.employee_code ~ '^E-[0-9]+$';

  insert into public.workspace_employee_counters (workspace_id, next_value)
  values (target_workspace_id, next_code + 1)
  on conflict (workspace_id) do update
  set next_value = greatest(
    public.workspace_employee_counters.next_value + 1,
    excluded.next_value
  )
  returning next_value - 1 into next_code;

  insert into public.employee_profiles (
    workspace_id, user_id, employee_code, first_name, middle_name, last_name,
    preferred_name, invitation_email, internal_note, is_remote,
    is_excluded_from_schedule, created_by
  ) values (
    target_workspace_id,
    owner_user_id,
    'E-' || lpad(next_code::text, 4, '0'),
    -- Too long is refused with the legal name's own words right after this.
    left(given_name, 80),
    left(btrim(coalesce(owner_middle_name, '')), 80),
    left(family_name, 80),
    '',
    owner_email,
    -- An internal note is a manager's sentence about a person. Nothing the
    -- system has to say belongs in it.
    '',
    false,
    -- On the schedule like everyone else. Exclude is a choice made in the row.
    false,
    owner_user_id
  )
  returning id into existing_employee_id;

  insert into public.employee_events (
    workspace_id, employee_id, actor_user_id, action, summary
  ) values (
    target_workspace_id,
    existing_employee_id,
    owner_user_id,
    'employee.owner_record_created',
    'Owner employee record created when setup began'
  );

  return existing_employee_id;
end;
$_$;


ALTER FUNCTION "app_private"."ensure_owner_employee_profile"("target_workspace_id" "uuid", "owner_user_id" "uuid", "owner_first_name" "text", "owner_middle_name" "text", "owner_last_name" "text") OWNER TO "postgres";


