CREATE OR REPLACE FUNCTION "app_private"."guard_assignment_deleted_job"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare deleted timestamptz;
begin
  if new.ended_at is null then
    -- The lock serializes this check with deletion, including employee-save commands
    -- that validated the job before they waited for deletion to finish.
    select j.deleted_at into deleted from public.jobs j where j.id=new.job_id for key share;
    if deleted is not null then raise exception 'This job was deleted. Reload jobs before assigning it.' using errcode='PT409'; end if;
  end if;
  return new;
end; $$;


ALTER FUNCTION "app_private"."guard_assignment_deleted_job"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."guard_catalog_deletion_state"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op='UPDATE' and old.deleted_at is not null then
    raise exception 'This item was deleted. Reload the catalog.' using errcode='PT409';
  end if;
  if new.deleted_at is not null and current_user not in ('postgres','service_role') then
    raise exception 'Use the authorized catalog deletion command.' using errcode='42501';
  end if;
  if new.deleted_at is not null and new.archived_at is null then
    raise exception 'Deleted items must remain archived' using errcode='23514';
  end if;
  return new;
end; $$;


ALTER FUNCTION "app_private"."guard_catalog_deletion_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."guard_deleted_department_job"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
