CREATE OR REPLACE FUNCTION "app_private"."is_workspace_member"("target_workspace_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select not app_private.document_actor_blocked((select auth.uid()), target_workspace_id) and exists (
    select 1
    from public.workspace_memberships membership
    where membership.workspace_id = target_workspace_id
      and membership.user_id = (select auth.uid())
      and membership.status = 'active'
      and app_private.workspace_open_to_actor(target_workspace_id, (select auth.uid()))
  );
$$;


ALTER FUNCTION "app_private"."is_workspace_member"("target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."job_assignment_candidates"("actor" "uuid", "target_workspace_id" "uuid", "target_job_id" "uuid") RETURNS TABLE("employee_id" "uuid", "display_name" "text", "employee_code" "text", "location_name" "text", "location_ids" "uuid"[], "display_status" "text", "assigned" boolean, "is_primary" boolean, "revision" integer, "can_manage" boolean, "disabled_reason" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with me as (select app_private.actor(actor, target_workspace_id) as state),
  read_rule as (select r from app_private.authz_actions r where r.key = 'employee.list'),
  save_rule as (select r from app_private.authz_actions r where r.key = 'employee.save'),
  reached as (
    select e.*, app_private.authz_check((select state from me), (select r from save_rule), null, e.id, null) is null as may_save
    from public.employee_profiles e
    where e.workspace_id = target_workspace_id and e.archived_at is null
      and app_private.authz_check((select state from me), (select r from read_rule), null, e.id, null) is null
  )
  select e.id, concat_ws(' ', coalesce(nullif(e.preferred_name, ''), e.first_name), e.last_name), e.employee_code,
    loc.name, coalesce(locs.ids, '{}'::uuid[]),
    case when m.status = 'active' then 'active'
      when oc.status in ('submitted', 'changes_requested') then 'needs_attention'
      when m.status = 'pending_activation' then 'onboarding'
      when invitation.status = 'pending' and invitation.expires_at > now() then 'invited'
      else 'not_invited' end,
    a.id is not null, coalesce(a.is_primary, false), e.revision,
    e.may_save,
    case when e.may_save then null else 'Your role cannot change this employee''s assignments.' end
  from reached e
  left join public.employee_job_assignments a on a.workspace_id = e.workspace_id
    and a.employee_id = e.id and a.job_id = target_job_id and a.ended_at is null
  left join public.employee_location_assignments pl on pl.employee_id = e.id and pl.ended_at is null and pl.is_primary
  left join public.locations loc on loc.id = pl.location_id
  left join lateral (select array_agg(la.location_id) ids from public.employee_location_assignments la
    where la.employee_id = e.id and la.ended_at is null) locs on true
  left join public.workspace_memberships m on m.workspace_id = e.workspace_id and m.user_id = e.user_id
  left join public.employee_onboarding_cases oc on oc.employee_id = e.id and oc.workspace_id = e.workspace_id
  left join lateral (select i.status, i.expires_at from public.employee_invitations i
    where i.employee_id = e.id order by i.created_at desc, i.id limit 1) invitation on true;
$$;


ALTER FUNCTION "app_private"."job_assignment_candidates"("actor" "uuid", "target_workspace_id" "uuid", "target_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."keep_job_assignment_rules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.ended_at is not null then
    -- The owner keeps the Owner job (S1 a); a change of ownership moves the
    -- membership first, so the old owner's assignment ends as anyone's.
    if tg_op = 'UPDATE' and old.ended_at is null
       and exists (select 1 from public.jobs job where job.id = new.job_id and job.system_key = 'owner')
       and app_private.employee_record_is_workspace_owner(new.workspace_id, new.employee_id) then
      raise exception 'The owner keeps the Owner job'
        using errcode = '23514', hint = 'employee.owner_job';
    end if;
    return new;
  end if;
  if exists (select 1 from public.jobs job where job.id = new.job_id and job.system_key = 'owner')
     and not app_private.employee_record_is_workspace_owner(new.workspace_id, new.employee_id) then
    raise exception 'Only the workspace owner works the Owner job'
      using errcode = '42501', hint = 'authz.owner_only';
  end if;
  -- Every job can be somebody's primary job but Owner (EMP-001 S2).
  if new.is_primary
     and exists (select 1 from public.jobs job where job.id = new.job_id and job.system_key = 'owner') then
    raise exception 'The Owner job is never marked primary'
      using errcode = '23514', hint = 'employee.management_primary';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."keep_job_assignment_rules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."keep_manager_at_a_location"("w" "uuid", "target_employee" "uuid", "becoming" "public"."workspace_role" DEFAULT NULL::"public"."workspace_role") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  record public.employee_profiles%rowtype;
  holder app_private.actor_state;
begin
  select * into record
  from public.employee_profiles employee
  where employee.id = target_employee and employee.workspace_id = w;
  if record.id is null or record.archived_at is not null or record.is_remote then
    return;
  end if;

  if becoming is null then
    if record.user_id is null then
      return;
    end if;
    holder := app_private.actor(record.user_id, w);
    if holder.class is distinct from 'manager' or holder.status not in ('active', 'pending_activation') then
      return;
    end if;
  elsif becoming <> 'manager' then
    return;
  end if;

  if not exists (
    select 1 from public.employee_location_assignments assignment
    where assignment.employee_id = record.id and assignment.ended_at is null
  ) then
    raise exception 'a manager needs a location to manage'
      using errcode = '22023', hint = 'employee.manager_location_required';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."keep_manager_at_a_location"("w" "uuid", "target_employee" "uuid", "becoming" "public"."workspace_role") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."keep_owner_at_every_location"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if old.ended_at is null and new.ended_at is not null
     and app_private.employee_record_is_workspace_owner(new.workspace_id, new.employee_id)
     and exists (select 1 from public.locations location
                 where location.id = new.location_id and location.archived_at is null) then
    raise exception 'The owner works at every location'
      using errcode = '23514', hint = 'employee.owner_locations';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."keep_owner_at_every_location"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."keep_session_shift_in_session_locations"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if not exists (
    select 1 from public.schedule_edit_sessions session
    where session.id = new.session_id and new.location_id = any(session.location_ids)
  ) then
    raise exception 'shift location is outside this edit' using errcode = '42501', detail = 'schedule.edit', hint = 'authz.out_of_scope';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."keep_session_shift_in_session_locations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."keep_system_catalog_records"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.system_key is not null and current_user not in ('postgres', 'service_role') then
      raise exception 'Management and Owner are made by setup'
        using errcode = '23514', hint = 'catalog.system_record';
    end if;
    return new;
  end if;
  if new.system_key is distinct from old.system_key then
    raise exception 'A catalog record cannot become or stop being Management or Owner'
      using errcode = '23514', hint = 'catalog.system_record';
  end if;
  if old.system_key is not null
     and (new.archived_at is not null or new.deleted_at is not null) then
    raise exception 'Management and Owner are kept; rename them instead'
      using errcode = '23514', hint = 'catalog.system_record';
  end if;
  -- The Owner job stays under Management (S2 a): elsewhere it could be marked
  -- primary and leave the Management group.
  if tg_table_name = 'jobs' then
    if old.system_key = 'owner' and new.department_id is distinct from old.department_id then
      raise exception 'The Owner job stays under Management'
        using errcode = '23514', hint = 'catalog.system_record';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."keep_system_catalog_records"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."live_draft_locations"("w" "uuid", "locs" "uuid"[]) RETURNS "uuid"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  -- KARARLAR Q-B, Q-C: an archived or deleted location no longer counts for
  -- the draft; live is what the core calls live.
  select array(select place from unnest(locs) place
    where exists (select 1 from public.locations location
      where location.id = place and location.workspace_id = w and app_private.location_is_live(location)))
$$;


