CREATE TABLE IF NOT EXISTS "public"."signature_template_versions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "template_id" "uuid" NOT NULL,
    "version_number" integer NOT NULL,
    "title" "text" NOT NULL,
    "summary" "text" DEFAULT ''::"text" NOT NULL,
    "execution_class" "public"."signature_execution_class" DEFAULT 'acknowledgement'::"public"."signature_execution_class" NOT NULL,
    "content_text" "text" NOT NULL,
    "content_digest" "text" NOT NULL,
    "intent_statement" "text" NOT NULL,
    "locale" "text" DEFAULT 'en-US'::"text" NOT NULL,
    "effective_date" "date" NOT NULL,
    "required_at_onboarding" boolean DEFAULT true NOT NULL,
    "blocks_activation" boolean DEFAULT true NOT NULL,
    "retention_policy_id" "uuid" NOT NULL,
    "status" "public"."signature_version_status" DEFAULT 'draft'::"public"."signature_version_status" NOT NULL,
    "published_by" "uuid",
    "published_at" timestamp with time zone,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lifecycle_settings" "jsonb",
    "lifecycle_revision" integer DEFAULT 1 NOT NULL,
    CONSTRAINT "signature_template_versions_check" CHECK (((("status" = 'draft'::"public"."signature_version_status") AND ("published_by" IS NULL) AND ("published_at" IS NULL)) OR (("status" = 'published'::"public"."signature_version_status") AND ("published_by" IS NOT NULL) AND ("published_at" IS NOT NULL)))),
    CONSTRAINT "signature_template_versions_check1" CHECK (((NOT "blocks_activation") OR "required_at_onboarding")),
    CONSTRAINT "signature_template_versions_content_digest_check" CHECK (("content_digest" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "signature_template_versions_content_text_check" CHECK ((("char_length"("content_text") >= 1) AND ("char_length"("content_text") <= 50000))),
    CONSTRAINT "signature_template_versions_intent_statement_check" CHECK ((("char_length"("btrim"("intent_statement")) >= 1) AND ("char_length"("btrim"("intent_statement")) <= 500))),
    CONSTRAINT "signature_template_versions_locale_check" CHECK (("locale" ~ '^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$'::"text")),
    CONSTRAINT "signature_template_versions_summary_check" CHECK (("char_length"("summary") <= 240)),
    CONSTRAINT "signature_template_versions_title_check" CHECK ((("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 80))),
    CONSTRAINT "signature_template_versions_version_number_check" CHECK (("version_number" > 0))
);


ALTER TABLE "public"."signature_template_versions" OWNER TO "postgres";


