CREATE OR REPLACE FUNCTION "app_private"."record_schedule_edit_undo_step"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  edit uuid := coalesce(new.session_id, old.session_id);
  call_at timestamptz := statement_timestamp();
  call_xact xid8 := pg_current_xact_id();
begin
  -- A closed edit keeps no history, nor does one being deleted.
  if not exists (select 1 from public.schedule_edit_sessions session where session.id = edit and session.status = 'active') then
    return null;
  end if;
  -- A new step: only the 24 before it are kept.
  if not exists (select 1 from app_private.schedule_edit_undo_steps step
      where step.session_id = edit and step.step_at = call_at and step.step_xact = call_xact) then
    delete from app_private.schedule_edit_undo_steps step
    where step.session_id = edit and (step.step_at, step.step_xact) <= (
      select kept.step_at, kept.step_xact
      from (select distinct older.step_at, older.step_xact from app_private.schedule_edit_undo_steps older
            where older.session_id = edit) kept
      order by kept.step_at desc, kept.step_xact desc offset 24 limit 1);
  end if;
  insert into app_private.schedule_edit_undo_steps (workspace_id, session_id, step_at, step_xact, shift_id, before)
  values (coalesce(new.workspace_id, old.workspace_id), edit, call_at, call_xact, coalesce(new.id, old.id),
    case when tg_op = 'INSERT' then null else to_jsonb(old) end)
  -- The first change in a step is how the row was before it.
  on conflict (session_id, shift_id, step_at, step_xact) do nothing;
  return null;
end;
$$;


ALTER FUNCTION "app_private"."record_schedule_edit_undo_step"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."record_security_audit_event_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "event_type" "text", "surface" "text", "resource_type" "text" DEFAULT NULL::"text", "raw_resource_id" "text" DEFAULT NULL::"text", "metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  event_id uuid;
begin
  if btrim(coalesce(event_type, '')) = '' then
    raise exception 'security audit event type required' using errcode = '23514';
  end if;
  if btrim(coalesce(surface, '')) = '' then
    raise exception 'security audit surface required' using errcode = '23514';
  end if;
  if metadata is null or jsonb_typeof(metadata) <> 'object' then
    raise exception 'security audit metadata object required' using errcode = '23514';
  end if;

  insert into app_private.security_audit_events (
    actor_user_id,
    workspace_id,
    event_type,
    surface,
    resource_type,
    resource_id_hash,
    metadata
  ) values (
    actor_user_id,
    target_workspace_id,
    btrim(event_type),
    btrim(surface),
    nullif(btrim(coalesce(resource_type, '')), ''),
    case
      when raw_resource_id is null or btrim(raw_resource_id) = '' then null
      else encode(extensions.digest(btrim(raw_resource_id), 'sha256'), 'hex')
    end,
    metadata
  )
  returning id into event_id;

  return event_id;
end;
$$;


ALTER FUNCTION "app_private"."record_security_audit_event_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "event_type" "text", "surface" "text", "resource_type" "text", "raw_resource_id" "text", "metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."reset_employee_onboarding_for_rehire"("target_workspace_id" "uuid", "target_employee_id" "uuid", "target_membership_id" "uuid", "actor_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.employee_onboarding_cases%rowtype;
begin
 select * into c from public.employee_onboarding_cases where workspace_id=target_workspace_id and employee_id=target_employee_id for update;
 if c.id is null then return; end if;
 update public.employee_onboarding_requirements set lifecycle_retired_at=now(),lifecycle_closed_at=now(),lifecycle_close_reason='New account onboarding',
  status='superseded',required=false,blocks_activation=false,deadline_at=null,paused_remaining_seconds=null,document_suspended_at=null,lifecycle_revision=lifecycle_revision+1,updated_at=now()
 where case_id=c.id and lifecycle_retired_at is null;
 delete from public.employee_sensitive_identifiers where workspace_id=target_workspace_id and employee_id=target_employee_id;
 delete from public.employee_private_profiles where workspace_id=target_workspace_id and employee_id=target_employee_id;
 update public.employee_onboarding_cases set membership_id=target_membership_id,status='in_progress',submitted_at=null,approved_at=null,approved_by=null,
  final_approval_required=public.employee_onboarding_final_approval_required(target_workspace_id),revision=revision+1,updated_at=now() where id=c.id;
 insert into public.onboarding_events(workspace_id,employee_id,case_id,actor_user_id,action,target_type,target_id)
 values(target_workspace_id,target_employee_id,c.id,actor_user_id,'onboarding.rehire_started','onboarding_case',c.id::text);
end;
$$;


