CREATE OR REPLACE FUNCTION "app_private"."schedule_publication_changes_since_start"("preview" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case when jsonb_typeof(preview -> 'locations') is distinct from 'array' then preview
  else jsonb_set(preview, '{locations}', coalesce((
    select jsonb_agg(item || jsonb_build_object('changed_since_start', (
      select case
        when current_publication.id is not null then jsonb_build_object(
          'kind', 'published',
          'by_name', coalesce(publisher.display_name, 'Another manager'),
          'at', current_publication.published_at)
        else jsonb_build_object(
          'kind', 'unpublished',
          'by_name', coalesce(unpublisher.display_name, 'Another manager'),
          'at', latest.unpublished_at)
      end
      from public.schedule_drafts draft
      left join public.schedule_location_publications current_publication
        on current_publication.id = nullif(item ->> 'active_publication_id', '')::uuid
      left join public.user_profiles publisher on publisher.user_id = current_publication.published_by
      left join lateral (
        select publication.* from public.schedule_location_publications publication
        where publication.location_id = (item ->> 'location_id')::uuid
          and publication.week_start = draft.week_start
        order by publication.version_number desc
        limit 1
      ) latest on true
      left join public.user_profiles unpublisher on unpublisher.user_id = latest.unpublished_by
      where draft.id = (preview ->> 'draft_id')::uuid
        and current_publication.id is distinct from (
          select publication.id from public.schedule_location_publications publication
          where publication.id = any(draft.base_publication_ids)
            and publication.location_id = (item ->> 'location_id')::uuid
        )
    )) order by position)
    from jsonb_array_elements(preview -> 'locations') with ordinality entry(item, position)
  ), '[]'::jsonb)) end;
$$;


ALTER FUNCTION "app_private"."schedule_publication_changes_since_start"("preview" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_referenced_catalog"("target_workspace_id" "uuid", "job_ids" "uuid"[], "shift_type_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'referenced_jobs', coalesce((
      select jsonb_agg(jsonb_build_object('id', job.id, 'name', job.name) order by lower(job.name), job.id)
      from public.jobs job
      where job.workspace_id = target_workspace_id and job.id = any (job_ids)
        and job.archived_at is not null and job.deleted_at is null
    ), '[]'::jsonb),
    'referenced_shift_types', coalesce((
      select jsonb_agg(jsonb_build_object('id', shift_type.id, 'name', shift_type.name)
        order by lower(shift_type.name), shift_type.id)
      from public.shift_types shift_type
      where shift_type.workspace_id = target_workspace_id and shift_type.id = any (shift_type_ids)
        and shift_type.archived_at is not null and shift_type.deleted_at is null
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION "app_private"."schedule_referenced_catalog"("target_workspace_id" "uuid", "job_ids" "uuid"[], "shift_type_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_template_department_ids"("w" "uuid", "department_keys" "text"[]) RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  ids uuid[];
begin
  if department_keys is null then
    return '{}'::uuid[];
  end if;
  if cardinality(department_keys) = 0 then
    raise exception 'select at least one department' using errcode = '22023';
  end if;
  if exists (
    select 1 from unnest(department_keys) as key(value)
    where key.value <> '__no_department__'
      and key.value !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) then
    raise exception 'invalid department key' using errcode = '22023';
  end if;
  ids := array(select key.value::uuid from unnest(department_keys) as key(value) where key.value <> '__no_department__');
  if exists (
    select 1 from unnest(ids) as selected(id)
    left join public.departments department
      on department.id = selected.id and department.workspace_id = w and department.archived_at is null
    where department.id is null
  ) then
    raise exception 'schedule template department not found' using errcode = 'P0002';
  end if;
  return ids;
end;
$_$;


ALTER FUNCTION "app_private"."schedule_template_department_ids"("w" "uuid", "department_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_template_replace_targets"("w" "uuid", "edit_session" "uuid", "template" "uuid", "department_keys" "text"[]) RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with template_shift as (
    select template_shift.location_id, job.department_id
    from public.schedule_template_shifts template_shift
    join public.jobs job on job.id = template_shift.job_id and job.workspace_id = template_shift.workspace_id
    where template_shift.template_id = template and template_shift.workspace_id = w
      and template_shift.location_id = any (public.live_location_ids(w, array(
        select distinct s.location_id from public.schedule_template_shifts s where s.template_id = template)))
  ), picked as (
    select app_private.schedule_template_department_ids(w, department_keys) as ids
  )
  select edit_shift.id
  from public.schedule_edit_session_shifts edit_shift
  join public.jobs job on job.id = edit_shift.job_id and job.workspace_id = edit_shift.workspace_id
  join public.locations location on location.id = edit_shift.location_id and location.workspace_id = edit_shift.workspace_id
  cross join picked
  where edit_shift.session_id = edit_session and edit_shift.workspace_id = w
    and edit_shift.pending_op_type is distinct from 'delete'
    and exists (
      select 1 from template_shift t
      where t.location_id = edit_shift.location_id and t.department_id is not distinct from job.department_id)
    and (department_keys is null
      or job.department_id = any (picked.ids)
      or (job.department_id is null and '__no_department__' = any (department_keys)))
    -- A shift that has started stays (P09); an unknown time counts as not started.
    and coalesce(lower(app_private.shift_time_range(edit_shift.scheduled_date, edit_shift.start_time,
          edit_shift.end_time, coalesce(edit_shift.time_timezone, location.timezone))) > now(), true)
$$;


ALTER FUNCTION "app_private"."schedule_template_replace_targets"("w" "uuid", "edit_session" "uuid", "template" "uuid", "department_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."schedule_week_availability"("target_workspace_id" "uuid", "target_week_start" "date", "target_employee_ids" "uuid"[], "target_location_ids" "uuid"[], "with_reminders" boolean DEFAULT true) RETURNS TABLE("employee_id" "uuid", "location_id" "uuid", "unavailable" "tstzmultirange", "leave" "tstzmultirange", "projection" "jsonb")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
with location_zone as (
  select l.id, l.name, l.timezone, app_private.timezone_name_valid(l.timezone) as zone_ok
  from public.locations l
  where l.workspace_id = target_workspace_id and l.id = any(target_location_ids)
), zone as (
  select distinct z.timezone as zone_name from location_zone z where z.zone_ok
), piece as (
  -- Two four-day pieces, as the offset helper is bounded to eight physical
  -- days and a fall-back week is eight days and an hour.
  select z.zone_name,
    tstzrange((target_week_start + o.offset_days)::timestamp at time zone z.zone_name,
              (target_week_start + o.offset_days + 4)::timestamp at time zone z.zone_name, '[)') as span
  from zone z cross join (values (0), (4)) o(offset_days)
), segment as (
  select p.zone_name, s.utc_span, s.offset_seconds
  from piece p cross join lateral public.availability_offset_segments(p.span, p.zone_name) s
), mark as (
  select e.employee_id, false as reminder, e.preference, public.weekly_preference_valid(e.preference) as valid
  from public.employee_weekly_preferences e
  where e.workspace_id = target_workspace_id and e.employee_id = any(target_employee_ids)
  union all
  select m.employee_id, true, m.preference, public.weekly_preference_valid(m.preference)
  from public.manager_weekly_reminders m
  where with_reminders and m.workspace_id = target_workspace_id and m.employee_id = any(target_employee_ids) and m.enabled
), mark_day as (
  select m.employee_id, m.reminder, m.valid, m.preference ->> 'input_mode' as input_mode, d.value as rule
  from mark m cross join lateral jsonb_array_elements(case when m.valid then m.preference -> 'days' else '[]'::jsonb end) d
), clock as (
  select md.employee_id, md.reminder, (md.rule ->> 'day')::integer as dow,
    time '00:00' as start_clock, time '24:00' as end_clock, true as ok
  from mark_day md
  where coalesce((md.rule ->> 'all_day')::boolean, false)
  union all
  select md.employee_id, md.reminder, (md.rule ->> 'day')::integer,
    (r.value ->> 'start')::time, (r.value ->> 'end')::time, true
  from mark_day md
  cross join lateral jsonb_array_elements(md.rule -> 'ranges') r
  where not coalesce((md.rule ->> 'all_day')::boolean, false) and md.input_mode = 'time_range'
  union all
  select md.employee_id, md.reminder, (md.rule ->> 'day')::integer, hours.start_clock, hours.end_clock,
    hours.start_clock is not null and hours.end_clock is not null and hours.start_clock <> hours.end_clock
  from mark_day md
  cross join lateral jsonb_array_elements_text(md.rule -> 'shift_type_ids') selected(type_id)
  cross join lateral (
    select case when t.id is not null and t.archived_at is null and t.deleted_at is null then t.default_start_time else d.start_time end as start_clock,
           case when t.id is not null and t.archived_at is null and t.deleted_at is null then t.default_end_time else d.end_time end as end_clock
    from (select selected.type_id::uuid as id) chosen
    left join public.shift_types t on t.workspace_id = target_workspace_id and t.id = chosen.id
    left join public.weekly_preference_type_defaults d on d.workspace_id = target_workspace_id and d.shift_type_id = chosen.id
  ) hours
  where not coalesce((md.rule ->> 'all_day')::boolean, false) and md.input_mode = 'shift_type'
), broken as (
  -- A mark that cannot be read (invalid, or a shift type without hours) makes
  -- the employee's week unknown rather than partly drawn.
  select m.employee_id from mark m where not m.valid
  union
  select c.employee_id from clock c where not c.ok
), local_day as (
  select s.zone_name, s.utc_span, s.offset_seconds, day::date as local_date
  from segment s
  cross join lateral generate_series(
    (((lower(s.utc_span) at time zone 'UTC') + make_interval(secs => s.offset_seconds))::date - 1)::timestamp,
    (((upper(s.utc_span) at time zone 'UTC') + make_interval(secs => s.offset_seconds))::date)::timestamp,
    interval '1 day') day
), unavailable_piece as (
  select c.employee_id, c.reminder, ld.zone_name,
    tstzrange(((ld.local_date + c.start_clock) at time zone 'UTC') - make_interval(secs => ld.offset_seconds),
              ((ld.local_date + c.end_clock + case when c.end_clock < c.start_clock then interval '1 day' else interval '0' end) at time zone 'UTC')
                - make_interval(secs => ld.offset_seconds), '[)') * ld.utc_span as span
  from local_day ld
  join clock c on c.dow = extract(dow from ld.local_date)::integer and c.ok
), unavailable as (
  -- Unavailable is the employee's own marks; a manager's note is kept apart,
  -- only a reminder (M12).
  select u.employee_id, u.zone_name, range_agg(u.span) filter (where not u.reminder) as spans,
    range_agg(u.span) filter (where u.reminder) as note_spans
  from unavailable_piece u
  where not isempty(u.span)
  group by u.employee_id, u.zone_name
), leave_target as (
  select z.zone_name,
    tstzrange(target_week_start::timestamp at time zone z.zone_name, (target_week_start + 8)::timestamp at time zone z.zone_name, '[)') as span
  from zone z
), leave as (
  select req.employee_id, lt.zone_name, range_agg(piece.span * lt.span) as spans
  from leave_target lt
  join public.schedule_time_off_requests req
    on req.workspace_id = target_workspace_id and req.employee_id = any(target_employee_ids)
   and req.request_type = 'time_off' and req.status = 'approved'
  join public.schedule_time_off_segments seg
    on seg.request_id = req.id and seg.workspace_id = req.workspace_id and seg.status = 'approved'
   and seg.segment_date between target_week_start - 4 and target_week_start + 12
  cross join lateral unnest(public.time_off_effective_ranges(seg.id)) piece(span)
  where piece.span && lt.span
  group by req.employee_id, lt.zone_name
), clock_segments as (
  select s.zone_name,
    jsonb_agg(jsonb_build_object('start_at', lower(s.utc_span), 'end_at', upper(s.utc_span), 'offset_seconds', s.offset_seconds)
      order by lower(s.utc_span)) as segments
  from segment s
  group by s.zone_name
), day_span as (
  select z.zone_name, target_week_start + i as work_date,
    tstzrange((target_week_start + i)::timestamp at time zone z.zone_name, (target_week_start + i + 1)::timestamp at time zone z.zone_name, '[)') as span
  from zone z cross join generate_series(0, 6) i
), employee_zone as (
  -- Everything but the location's own name is the same for every location in
  -- a time zone, so it is built once per employee and zone.
  select e.employee_id, z.zone_name,
    coalesce(u.spans, '{}'::tstzmultirange) as unavailable,
    coalesce(lv.spans, '{}'::tstzmultirange) as leave,
    jsonb_build_object(
      'status', 'ready',
      'unavailable_intervals', public.availability_ranges_json(coalesce(u.spans, '{}'::tstzmultirange)),
      'employee_intervals', public.availability_ranges_json(coalesce(u.spans, '{}'::tstzmultirange)),
      -- The note's hours, for the card shown while writing; the caller keeps
      -- them only for whoever may read the note.
      'note_intervals', public.availability_ranges_json(coalesce(u.note_spans, '{}'::tstzmultirange)),
      'leave_intervals', public.availability_ranges_json(coalesce(lv.spans, '{}'::tstzmultirange)),
      'clock_segments', cs.segments,
      'days', (select jsonb_agg(jsonb_build_object(
                 'date', ds.work_date,
                 'has_unavailable', coalesce(u.spans, '{}'::tstzmultirange) && ds.span,
                 'all_day', coalesce(u.spans, '{}'::tstzmultirange) @> ds.span) order by ds.work_date)
               from day_span ds where ds.zone_name = z.zone_name)) as body
  from unnest(target_employee_ids) e(employee_id)
  cross join zone z
  left join unavailable u on u.employee_id = e.employee_id and u.zone_name = z.zone_name
  left join leave lv on lv.employee_id = e.employee_id and lv.zone_name = z.zone_name
  left join clock_segments cs on cs.zone_name = z.zone_name
  where not exists (select 1 from broken b where b.employee_id = e.employee_id)
)
select e.employee_id, lz.id, ez.unavailable, ez.leave,
  jsonb_build_object('location_id', lz.id, 'location_name', lz.name, 'timezone', lz.timezone, 'week_start', target_week_start)
  || coalesce(ez.body, jsonb_build_object('status', 'unknown', 'unavailable_intervals', '[]'::jsonb, 'employee_intervals', '[]'::jsonb, 'note_intervals', '[]'::jsonb, 'leave_intervals', '[]'::jsonb,
       'clock_segments', '[]'::jsonb, 'days', '[]'::jsonb))
from unnest(target_employee_ids) e(employee_id)
cross join location_zone lz
left join employee_zone ez on ez.employee_id = e.employee_id and ez.zone_name = lz.timezone and lz.zone_ok;
$$;


ALTER FUNCTION "app_private"."schedule_week_availability"("target_workspace_id" "uuid", "target_week_start" "date", "target_employee_ids" "uuid"[], "target_location_ids" "uuid"[], "with_reminders" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."scope_set"("actor" "uuid", "w" "uuid", "action" "text") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  rule_row app_private.authz_actions;
  state app_private.actor_state;
begin
  select * into rule_row from app_private.authz_actions a where a.key = action;
  if not found then
    raise exception 'Unknown action %', action using errcode = '22023';
  end if;
  state := app_private.actor(actor, w);
  return coalesce((
    select array_agg(location.id order by location.id)
    from public.locations location
    where location.workspace_id = w
      and app_private.location_is_live(location)
      and app_private.authz_check(state, rule_row, array[location.id], null, null) is null
  ), '{}');
end;
$$;


ALTER FUNCTION "app_private"."scope_set"("actor" "uuid", "w" "uuid", "action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."set_document_exemption"("r" "public"."employee_onboarding_requirements", "actor_user_id" "uuid", "make_exempt" boolean, "exemption_reason" "text", "expected_revision" integer) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare next_deadline timestamptz; matching boolean; valid_approved boolean; asked public.employee_onboarding_requirements; next_revision integer;
begin
 if not make_exempt and app_private.employee_record_is_workspace_owner(r.workspace_id,r.employee_id) then
  raise exception 'an owner is not asked for the documents they ask of everyone else' using errcode='42501';
 end if;
 if not make_exempt then perform app_private.assert_document_published(r); end if;
 if expected_revision is null or r.lifecycle_revision<>expected_revision then raise exception 'document changed; refresh required' using errcode='PT409'; end if;
 if make_exempt is null or nullif(btrim(exemption_reason),'') is null or char_length(exemption_reason)>500 then raise exception 'exemption reason required' using errcode='22023'; end if;
 if r.lifecycle_exempt=make_exempt then return r.lifecycle_revision; end if;
 asked:=app_private.document_requirement_asked(r);
 matching:=app_private.document_target_matches(r.workspace_id,r.employee_id,r.lifecycle_settings->'target');
 -- Ignore exemption/closure while checking a retained approved version.
 r.lifecycle_exempt:=false; r.lifecycle_closed_at:=null;
 if r.status='superseded' then r.status:='not_started'; end if;
 valid_approved:=app_private.document_obligation_state(r,now())='completed';
 if not make_exempt and matching and not valid_approved and r.lifecycle_settings->>'mode'<>'optional' and r.lifecycle_settings->>'period_days' is not null then
  next_deadline:=now()+(r.lifecycle_settings->>'period_days')::integer*interval '24 hours';
 end if;
 update public.employee_onboarding_requirements set lifecycle_exempt=make_exempt,
  lifecycle_closed_at=case when make_exempt or matching then null else coalesce(lifecycle_closed_at,now()) end,
  lifecycle_close_reason=btrim(exemption_reason),deadline_at=next_deadline,paused_remaining_seconds=null,document_suspended_at=null,
  required=case when make_exempt then required else asked.required end,
  blocks_activation=case when make_exempt then blocks_activation else asked.blocks_activation end,
  owner_excused=false,
  lifecycle_revision=lifecycle_revision+1,updated_at=now() where id=r.id returning lifecycle_revision into next_revision;
 perform app_private.document_audit(r,actor_user_id,case when make_exempt then 'document.exempted' else 'document.exemption_removed' end,
  jsonb_build_object('reason',btrim(exemption_reason),'revision',next_revision,'old_deadline',r.deadline_at,'new_deadline',next_deadline,'matching',matching,'valid_approved',valid_approved));
 return next_revision;
end;
$$;


ALTER FUNCTION "app_private"."set_document_exemption"("r" "public"."employee_onboarding_requirements", "actor_user_id" "uuid", "make_exempt" boolean, "exemption_reason" "text", "expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."settings_locations"("w" "uuid", "ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(to_jsonb(l) order by l.sort_order, l.name, l.id), '[]'::jsonb)
  from (
    select location.id, location.workspace_id, location.name, location.short_name, location.phone,
      location.street_address, location.city, location.region, location.postal_code,
      location.country_code, location.timezone, location.sort_order, location.archived_at
    from public.locations location
    where location.workspace_id = w and location.deleted_at is null and location.id = any (ids)
  ) l;
$$;


ALTER FUNCTION "app_private"."settings_locations"("w" "uuid", "ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."shift_time_range"("d" "date", "s" time without time zone, "e" time without time zone, "tz" "text") RETURNS "tstzrange"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select tstzrange((d+s) at time zone tz,((d+case when e<=s then 1 else 0 end)+e) at time zone tz,'[)');
$$;


ALTER FUNCTION "app_private"."shift_time_range"("d" "date", "s" time without time zone, "e" time without time zone, "tz" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."shorten_time_off"("actor" "uuid", "w" "uuid", "emp" "uuid", "cut" "tstzmultirange", "note" "text", "source" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare parent public.schedule_time_off_requests%rowtype; seg record; rid uuid; sid uuid; zone_name text;
 given tstzmultirange; remaining tstzmultirange; next_status public.time_off_request_status; said text; result jsonb:='[]';
begin
 perform public.availability_lock_workspace(w);
 if cut is null or isempty(cut) then return result; end if;
 if exists(select 1 from unnest(cut) x where lower(x)<=now() or not isfinite(lower(x)) or not isfinite(upper(x))) then
  raise exception 'Only future approved hours can be given back' using errcode='22023'; end if;
 said:=left(btrim(coalesce(note,'')),1000);
 for parent in select r.* from public.schedule_time_off_requests r
  where r.workspace_id=w and r.employee_id=emp and r.request_type='time_off' and r.status = 'approved'
   and exists(select 1 from public.schedule_time_off_segments s where s.request_id=r.id and s.workspace_id=w and public.time_off_effective_ranges(s.id) && cut)
  order by r.created_at, r.id for update loop
  rid:=gen_random_uuid(); given:='{}';
  insert into public.schedule_time_off_requests(id,workspace_id,employee_id,request_type,reason,created_by)
   values(rid,w,emp,'time_off_cancellation',said,actor);
  insert into public.time_off_cancellation_links values(rid,w,parent.id,parent.revision);
  for seg in select s.id,s.time_timezone,p.piece from public.schedule_time_off_segments s
   cross join lateral unnest(public.time_off_effective_ranges(s.id)*cut) p(piece)
   where s.request_id=parent.id and s.workspace_id=w order by lower(p.piece) loop
   zone_name:=seg.time_timezone; sid:=gen_random_uuid();
   insert into public.schedule_time_off_segments(id,workspace_id,request_id,segment_date,start_time,end_time,time_timezone,starts_at,ends_at,ends_next_day)
    values(sid,w,rid,(lower(seg.piece) at time zone zone_name)::date,(lower(seg.piece) at time zone zone_name)::time,(upper(seg.piece) at time zone zone_name)::time,
     zone_name,lower(seg.piece),upper(seg.piece),(upper(seg.piece) at time zone zone_name)::date>(lower(seg.piece) at time zone zone_name)::date);
   insert into public.time_off_cancellation_periods values(sid,w,rid,seg.id,parent.id);
   given:=given+tstzmultirange(seg.piece);
  end loop;
  insert into public.schedule_time_off_events(workspace_id,request_id,action,actor_user_id,note,metadata)
   values(w,rid,'submitted',actor,said,jsonb_build_object('parent_request_id',parent.id,'parent_revision',parent.revision,'shortened',true,'source',source));
  -- The hours given back are settled at once (a request with no location has no zone for the old decision path).
  update public.schedule_time_off_segments set status='approved' where request_id=rid and workspace_id=w;
  update public.schedule_time_off_requests set status='approved',revision=revision+1,updated_at=now() where id=rid;
  insert into public.schedule_time_off_events(workspace_id,request_id,action,actor_user_id,note,metadata)
   values(w,rid,'approved',actor,said,jsonb_build_object('revision',2,'shortened',true,'source',source));
  select coalesce(range_agg(p.span),'{}') into remaining from public.schedule_time_off_segments s
   cross join lateral unnest(public.time_off_effective_ranges(s.id)) p(span) where s.request_id=parent.id and s.workspace_id=w;
  next_status:=case when isempty(remaining) then 'revoked'::public.time_off_request_status else parent.status end;
  update public.schedule_time_off_requests set status=next_status,revision=revision+1,updated_at=now() where id=parent.id returning * into parent;
  -- Nothing of the time off is left: a cancellation waiting on it closes (as a revoke does).
  if next_status = 'revoked' then
   update public.schedule_time_off_requests cr set status='revoked',revision=cr.revision+1,updated_at=now()
   from public.time_off_cancellation_links cl
   where cl.request_id=cr.id and cl.parent_request_id=parent.id and cl.workspace_id=w and cr.status='pending' and cr.id<>rid;
   insert into public.schedule_time_off_events(workspace_id,request_id,action,actor_user_id,note,metadata)
   select w,cr.id,'revoked',actor,'Closed because the time off was given back in full.',jsonb_build_object('parent_request_id',parent.id)
   from public.time_off_cancellation_links cl join public.schedule_time_off_requests cr on cr.id=cl.request_id
   where cl.parent_request_id=parent.id and cl.workspace_id=w and cr.id<>rid and cr.status='revoked'
    and not exists(select 1 from public.schedule_time_off_events e where e.request_id=cr.id and e.action='revoked');
  end if;
  insert into public.schedule_time_off_events(workspace_id,request_id,action,actor_user_id,note,metadata)
   values(w,parent.id,next_status::text,actor,said,jsonb_build_object('revision',parent.revision,'cancellation_request_id',rid,
    'cancelled_intervals',public.availability_ranges_json(given),'shortened',true,'source',source));
  perform public.notify_time_off_shortened(actor,w,parent.id,given,zone_name,source);
  result:=result||jsonb_build_array(jsonb_build_object('request_id',parent.id,'revision',parent.revision,'status',parent.status,
   'cancellation_request_id',rid,'intervals',public.availability_ranges_json(given)));
 end loop;
 return result;
end;
$$;


ALTER FUNCTION "app_private"."shorten_time_off"("actor" "uuid", "w" "uuid", "emp" "uuid", "cut" "tstzmultirange", "note" "text", "source" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."snapshot_document_lifecycle_requirement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare membership_state public.membership_status;
begin
 if new.kind not in ('document','acknowledgement') then return new; end if;
 select e.user_id,m.status into new.lifecycle_user_id,membership_state from public.employee_profiles e
 join public.employee_onboarding_cases c on c.id=new.case_id and c.workspace_id=new.workspace_id
 join public.workspace_memberships m on m.id=c.membership_id and m.user_id=e.user_id
 where e.id=new.employee_id and e.workspace_id=new.workspace_id;
 if new.lifecycle_settings is null and new.kind='document' then
  select lifecycle_settings into new.lifecycle_settings from public.document_types where id=new.source_id and workspace_id=new.workspace_id;
 end if;
 if new.lifecycle_settings is null and new.kind='acknowledgement' then select app_private.policy_lifecycle_settings(v) into new.lifecycle_settings from public.signature_template_versions v where v.id=new.source_id and v.workspace_id=new.workspace_id; end if; if new.lifecycle_settings is null then
  new.lifecycle_settings:=jsonb_build_object('mode',case when new.required then 'required' else 'optional' end,
   'target',jsonb_build_object('operator','and','location_ids','[]'::jsonb,'department_ids','[]'::jsonb,'job_ids','[]'::jsonb,'employee_ids','[]'::jsonb),
   'assignment_scope','future_onboarding','period_days',null,'suspend_on_overdue',false,'extra_fields','[]'::jsonb);
 end if;
 new := app_private.document_requirement_asked(new);
 if membership_state='active' and new.lifecycle_settings->>'mode'<>'optional' and new.lifecycle_settings->>'period_days' is not null then
  new.deadline_at:=now()+(new.lifecycle_settings->>'period_days')::integer*interval '24 hours';
 end if;
 return new;
end;
$$;


ALTER FUNCTION "app_private"."snapshot_document_lifecycle_requirement"() OWNER TO "postgres";


