CREATE OR REPLACE FUNCTION "app_private"."time_off_notice"("w" "uuid", "rid" "uuid", "type_key" "text", "recipients" "uuid"[], "audience" "text", "title" "text", "body" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if cardinality(recipients) = 0 then
    return;
  end if;
  perform public.enqueue_notification_outbox_service(w, gen_random_uuid(), type_key, 1, null,
    'schedule_time_off_requests', rid::text,
    jsonb_build_object('request_id', rid, 'recipient_user_ids', to_jsonb(recipients), 'audience_contract', audience,
      'category', 'request', 'title', title, 'body', body, 'safe_preview', 'A time-off request needs a decision.',
      'action_url', '/app/schedule/requests?tab=time-off&request=' || rid::text,
      'group_key', 'schedule_time_off_requests:' || rid::text),
    now());
end;
$$;


ALTER FUNCTION "app_private"."time_off_notice"("w" "uuid", "rid" "uuid", "type_key" "text", "recipients" "uuid"[], "audience" "text", "title" "text", "body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_notify_shifts_opened"("actor" "uuid", "w" "uuid", "rid" "uuid", "decision" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare fmt text; person_name text; g record;
begin
 fmt := case when (select s.time_format from public.workspace_scheduling_settings s where s.workspace_id = w) = '24h'
  then 'HH24:MI' else 'FMHH12:MI AM' end;
 select coalesce(nullif(e.preferred_name, ''), e.first_name) into person_name
  from public.schedule_time_off_requests r join public.employee_profiles e on e.id = r.employee_id and e.workspace_id = r.workspace_id
  where r.id = rid and r.workspace_id = w;
 for g in
  with opened as (
   select p.location_id, l.name location_name, p.scheduled_date, p.start_time, p.end_time
   from public.time_off_assignment_releases rel
   join public.schedule_published_shifts p on p.id = rel.published_shift_id and p.workspace_id = w
   join public.locations l on l.id = p.location_id and l.workspace_id = w
   where rel.workspace_id = w and rel.request_id = rid and rel.decision_revision = decision
  ), managers as (
   select m.user_id from public.workspace_memberships m
   where m.workspace_id = w and m.status = 'active' and m.user_id is distinct from actor
    -- A manager: deciding alone is not theirs anywhere (the core, no role reading).
    and app_private.authz_reason(m.user_id, w, 'time_off.decide_alone') is not null
  ), told as (
   select mg.user_id, o.* from managers mg join opened o
    on app_private.authz_reason(mg.user_id, w, 'schedule.edit', array[o.location_id]) is null
  ), per_person as (
   select t.user_id, count(*)::integer n, min(t.scheduled_date) first_day,
    array_agg(to_char(t.scheduled_date, 'Dy, Mon FMDD') || ', ' || to_char(t.start_time, fmt) || '–' || to_char(t.end_time, fmt)
     || ' (' || t.location_name || ')' order by t.scheduled_date, t.start_time, t.location_name) shift_lines
   from told t group by t.user_id
  ), worded as (
   select p.*, array_to_string(p.shift_lines[1:3], '; ')
     || case when cardinality(p.shift_lines) > 3 then '; +' || (cardinality(p.shift_lines) - 3) || ' more' else '' end lines
   from per_person p
  )
  select n, first_day, lines, array_agg(user_id order by user_id) recipients
  from worded group by n, first_day, lines
 loop
  perform public.enqueue_notification_outbox_service(w, gen_random_uuid(), 'schedule.time_off.shifts_opened', 1, actor,
   'schedule_time_off_requests', rid::text,
   jsonb_build_object('request_id', rid, 'recipient_user_ids', to_jsonb(g.recipients),
    'audience_contract', 'time_off_location_managers', 'category', 'schedule',
    'title', left(coalesce(person_name, 'A teammate') || ' is off — ' || g.n || case when g.n = 1 then ' shift is open' else ' shifts are open' end, 160),
    'body', g.lines,
    'safe_preview', 'Approved time off left shifts open.',
    'action_url', '/app/schedule?date=' || g.first_day::text,
    'group_key', 'schedule_time_off_requests:' || rid::text),
   now());
 end loop;
end;
$$;


ALTER FUNCTION "app_private"."time_off_notify_shifts_opened"("actor" "uuid", "w" "uuid", "rid" "uuid", "decision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_progress"("actor" "uuid", "w" "uuid", "rid" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r public.schedule_time_off_requests%rowtype;
  st jsonb;
  alone boolean;
  mine uuid[] := '{}';
  open_places uuid[];
  my_vote text;
begin
  select * into r from public.schedule_time_off_requests where id = rid and workspace_id = w;
  st := app_private.time_off_state(w, rid);
  alone := r.status = 'pending' and app_private.time_off_reason(actor, w, 'time_off.decide_alone', r.employee_id) is null;
  if r.status = 'pending' and not alone then
    select coalesce(array_agg((x ->> 'id')::uuid), '{}') into mine
    from jsonb_array_elements(st -> 'locations') x
    where app_private.time_off_reason(actor, w, 'time_off.decide', r.employee_id, (x ->> 'id')::uuid) is null;
  end if;
  select coalesce(array_agg((x ->> 'id')::uuid), '{}') into open_places
  from jsonb_array_elements(st -> 'locations') x where x -> 'approved_by' = 'null'::jsonb;
  select v ->> 'verdict' into my_vote from jsonb_array_elements(st -> 'votes') v
  where (v ->> 'voter')::uuid = actor and not (v ->> 'stale')::boolean;
  return jsonb_build_object(
    'remaining', st -> 'remaining',
    'fallback', st -> 'fallback',
    'decide_by', r.decide_by,
    'can_vote', cardinality(mine) > 0,
    'can_decide_alone', alone,
    'my_vote', my_vote,
    'my_approval_finalizes', alone or (cardinality(mine) > 0 and cardinality(open_places) > 0 and open_places <@ mine),
    'locations', coalesce((select jsonb_agg(x || jsonb_build_object('name', l.name,
        'approved_by_name', (select coalesce(nullif(up.display_name, ''), 'Team member') from public.user_profiles up where up.user_id = (x ->> 'approved_by')::uuid))
      order by l.name)
      from jsonb_array_elements(st -> 'locations') x join public.locations l on l.id = (x ->> 'id')::uuid), '[]'),
    'impact', case when alone or cardinality(mine) > 0 then app_private.time_off_impact_seen(actor, w, rid) end);
end;
$$;


ALTER FUNCTION "app_private"."time_off_progress"("actor" "uuid", "w" "uuid", "rid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_reason"("actor" "uuid", "w" "uuid", "action" "text", "person" "uuid" DEFAULT NULL::"uuid", "place" "uuid" DEFAULT NULL::"uuid", "documents_aside" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  state app_private.actor_state := app_private.actor(actor, w);
  rule_row app_private.authz_actions;
begin
  select * into rule_row from app_private.authz_actions a where a.key = action;
  if not found then
    raise exception 'Unknown action %', action using errcode = '22023';
  end if;
  -- documents_aside: whether somebody could act once a missing document is in (a passing restriction).
  if state.class = 'owner' or documents_aside then
    state.document_blocked := false;
  end if;
  return app_private.authz_check(state, rule_row, case when place is null then null else array[place] end, person, null);
end;
$$;


ALTER FUNCTION "app_private"."time_off_reason"("actor" "uuid", "w" "uuid", "action" "text", "person" "uuid", "place" "uuid", "documents_aside" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_release_shifts"("w" "uuid", "rid" "uuid", "actor" "uuid", "decision" integer, "recorded_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  person uuid := (select r.employee_id from public.schedule_time_off_requests r where r.id = rid and r.workspace_id = w);
  -- The records need a person; the job (no actor) names an approval that counts.
  who uuid := coalesce(actor, recorded_by);
  s jsonb;
  changes jsonb := '[]';
  other record;
begin
  for s in select x from jsonb_array_elements(app_private.time_off_impact(w, rid) -> 'shifts') x loop
    insert into public.time_off_assignment_releases(workspace_id, request_id, decision_revision, published_shift_id, before_assignment, actor_user_id)
    values (w, rid, decision, (s ->> 'id')::uuid, s, who);
    update public.schedule_published_shifts set employee_id = null where workspace_id = w and id = (s ->> 'id')::uuid and employee_id = person;
    if not found then raise exception 'A published shift changed before it could be opened; try again' using errcode = 'PT409'; end if;
    changes := changes || jsonb_build_array(s || jsonb_build_object('new_employee_id', null));
  end loop;
  if jsonb_array_length(changes) > 0 then
    perform public.shift_exchange_reconcile_batch(who, w, changes);
    for other in select c.id from public.shift_exchange_cases c where c.workspace_id = w and c.status = 'open'
     and exists (select 1 from jsonb_array_elements(changes) x where (x ->> 'source_id')::uuid in (c.offered_source_id, c.requested_source_id)) loop
      update public.shift_exchange_cases set status = 'invalidated', revision = revision + 1, updated_at = now() where id = other.id;
      update public.shift_exchange_applications set status = 'invalidated', updated_at = now() where case_id = other.id and status in ('invited', 'pending_manager');
      perform public.shift_exchange_emit(who, w, other.id, null, 'invalidated', 'An involved assignment was released with approved time off. Review the current schedule.');
    end loop;
    perform realtime.send(jsonb_build_object('workspace_id', w, 'request_id', rid), 'changed', 'shift-exchanges:' || w::text, true);
    perform app_private.time_off_notify_shifts_opened(actor, w, rid, decision);
  end if;
  return changes;
end;
$$;


ALTER FUNCTION "app_private"."time_off_release_shifts"("w" "uuid", "rid" "uuid", "actor" "uuid", "decision" integer, "recorded_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_shifts_fingerprint"("shifts" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select md5(coalesce(string_agg(line, ',' order by line), ''))
  from (select concat_ws('|', x ->> 'location_id', x ->> 'job_id', x ->> 'scheduled_date', x ->> 'start_time', x ->> 'end_time') line
        from jsonb_array_elements(coalesce(shifts, '[]')) x) lines;
$$;


ALTER FUNCTION "app_private"."time_off_shifts_fingerprint"("shifts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_state"("w" "uuid", "rid" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r public.schedule_time_off_requests%rowtype;
  pictured jsonb;
  live uuid[];
  empty_print text := app_private.time_off_shifts_fingerprint('[]');
  votes jsonb;
  places jsonb;
begin
  select * into r from public.schedule_time_off_requests where id = rid and workspace_id = w;
  if r.id is null then
    return null;
  end if;
  pictured := app_private.time_off_impact(w, rid);
  live := app_private.time_off_live_locations(w, rid);

  select coalesce(jsonb_agg(jsonb_build_object(
      'voter', v.voter_user_id, 'verdict', v.verdict, 'note', v.note, 'at', v.updated_at,
      'stale', exists (select 1 from jsonb_each_text(v.impact) seen
                       where seen.value is distinct from coalesce(pictured -> 'locations' -> seen.key ->> 'fingerprint', empty_print)),
      'locations', (select coalesce(jsonb_agg(seen.key order by seen.key), '[]') from jsonb_each_text(v.impact) seen))
    order by v.updated_at, v.voter_user_id), '[]')
  into votes
  from public.time_off_votes v
  where v.request_id = rid and v.workspace_id = w;

  -- A vote that still counts, at each fixed location.
  select coalesce(jsonb_agg(jsonb_build_object('id', place, 'approved_by', counted.voter, 'approved_at', counted.voted_at) order by place), '[]')
  into places
  from unnest(live) place
  left join lateral (
    select (v ->> 'voter')::uuid voter, v ->> 'at' voted_at
    from jsonb_array_elements(votes) v
    where v ->> 'verdict' = 'approve' and not (v ->> 'stale')::boolean
      and v -> 'locations' ? place::text
      and (v ->> 'voter')::uuid = any (app_private.time_off_location_voters(w, r.employee_id, place))
    order by v ->> 'at' limit 1
  ) counted on true;

  return jsonb_build_object(
    'status', r.status,
    'fallback', cardinality(live) = 0,
    'locations', places,
    'remaining', (select count(*)::integer from jsonb_array_elements(places) p where p -> 'approved_by' = 'null'::jsonb),
    -- Fixed locations still to approve where nobody can vote now (a passing restriction).
    'unattended', (select count(*)::integer from jsonb_array_elements(places) p where p -> 'approved_by' = 'null'::jsonb
      and cardinality(app_private.time_off_location_voters(w, r.employee_id, (p ->> 'id')::uuid)) = 0),
    'votes', votes,
    'decide_by', r.decide_by,
    'fingerprint', pictured ->> 'fingerprint');
end;
$$;


ALTER FUNCTION "app_private"."time_off_state"("w" "uuid", "rid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_sweep"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r record;
  st jsonb;
  v jsonb;
  waiting uuid[];
  alone uuid[];
  fallback_due boolean;
  reminder_due boolean;
  done integer := 0;
begin
  -- Not decided in time: the system declines it.
  for r in select q.id, q.workspace_id from public.schedule_time_off_requests q
    where q.status = 'pending' and q.decide_by is not null and q.decide_by <= now()
    order by q.decide_by, q.id limit 500 loop
    -- Each request on its own: one that fails is rolled back alone and named,
    -- the rest of the pass and every other workspace go on.
    begin
      perform public.availability_lock_workspace(r.workspace_id);
      -- Read again under the lock: a withdrawal or a last vote may have closed it.
      if exists (select 1 from public.schedule_time_off_requests q where q.id = r.id and q.status = 'pending' and q.decide_by <= now()) then
        perform app_private.time_off_finalize(r.workspace_id, r.id, 'deny', null, 'Not decided in time', false, true);
        done := done + 1;
      end if;
    exception when others then
      raise warning 'time-off-deadlines: request % of workspace % failed: % %', r.id, r.workspace_id, sqlstate, sqlerrm;
    end;
  end loop;

  for r in select q.* from public.schedule_time_off_requests q
    where q.status = 'pending' and q.decide_by > now()
    order by q.decide_by, q.id limit 500 loop
    begin
    perform public.availability_lock_workspace(r.workspace_id);
    -- Read again under the lock: a withdrawal or a last vote may have closed it.
    select q.* into r from public.schedule_time_off_requests q where q.id = r.id;
    if r.status <> 'pending' or r.decide_by <= now() then
      continue;
    end if;
    st := app_private.time_off_state(r.workspace_id, r.id);

    -- A vote on shifts that changed is let go; its manager looks again.
    for v in select x from jsonb_array_elements(st -> 'votes') x where (x ->> 'stale')::boolean loop
      delete from public.time_off_votes where request_id = r.id and voter_user_id = (v ->> 'voter')::uuid;
      perform app_private.time_off_notice(r.workspace_id, r.id, 'requests.time_off.review_again', array[(v ->> 'voter')::uuid], 'time_off_voter',
        'Look at this time off again', 'The shifts it affects changed, so your approval no longer counts.');
      done := done + 1;
    end loop;

    -- Every location still deciding has approved (another dropped out, KARARLAR
    -- "İzin" 2026-09-30): the request is settled, by the system.
    if (st ->> 'remaining')::integer = 0 and not (st ->> 'fallback')::boolean then
      perform app_private.time_off_finalize(r.workspace_id, r.id, 'approve', null, 'All deciding locations approved', false);
      done := done + 1;
      continue;
    end if;

    fallback_due := ((st ->> 'fallback')::boolean or (st ->> 'unattended')::integer > 0) and r.fallback_notified_at is null
      and exists (select 1 from public.time_off_required_locations x where x.request_id = r.id);
    -- Twelve hours before the deadline, once; not for one sent inside them.
    reminder_due := r.reminded_at is null and r.decide_by - interval '12 hours' <= now()
      and r.created_at < r.decide_by - interval '12 hours';
    alone := app_private.time_off_alone_deciders(r.workspace_id, r.employee_id);

    -- Only an admin or the owner can decide it now: tell them once. When the
    -- reminder is due in the same pass, this one line carries it for them.
    if fallback_due then
      perform app_private.time_off_notice(r.workspace_id, r.id, 'requests.time_off.reminder',
        alone, 'time_off_fallback_deciders', 'Time off waits for an admin',
        case when reminder_due then 'No manager can decide this now. Decide before the deadline or it is declined.'
             else 'No manager can decide this now.' end);
      update public.schedule_time_off_requests set fallback_notified_at = now() where id = r.id;
      done := done + 1;
    end if;

    if reminder_due then
      st := app_private.time_off_state(r.workspace_id, r.id);
      if (st ->> 'fallback')::boolean then
        waiting := alone;
      else
        select coalesce(array_agg(distinct u order by u), '{}') into waiting
        from jsonb_array_elements(st -> 'locations') x,
             unnest(app_private.time_off_location_voters(r.workspace_id, r.employee_id, (x ->> 'id')::uuid)) u
        where x -> 'approved_by' = 'null'::jsonb;
        -- A location nobody can vote at now: an admin and the owner, who can decide it.
        if (st ->> 'unattended')::integer > 0 then
          waiting := array(select distinct u from unnest(waiting || alone) u order by u);
        end if;
      end if;
      -- An admin and the owner already have it in the line above.
      if fallback_due then
        waiting := array(select u from unnest(waiting) u where u <> all (alone) order by u);
      end if;
      perform app_private.time_off_notice(r.workspace_id, r.id, 'requests.time_off.reminder', waiting, 'time_off_deciders',
        'Time off waits for your decision', 'Decide before the deadline or it is declined.');
      update public.schedule_time_off_requests set reminded_at = now() where id = r.id;
      done := done + 1;
    end if;
    exception when others then
      raise warning 'time-off-deadlines: request % of workspace % failed: % %', r.id, r.workspace_id, sqlstate, sqlerrm;
    end;
  end loop;
  return done;
end;
$$;


ALTER FUNCTION "app_private"."time_off_sweep"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."time_off_timezone"("w" "uuid", "person" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select l.timezone
  from public.employee_location_assignments a
  join public.locations l on l.id = a.location_id and l.workspace_id = a.workspace_id
  where a.workspace_id = w and a.employee_id = person and a.ended_at is null and app_private.location_is_live(l)
  order by a.is_primary desc, a.assigned_at limit 1;
$$;


ALTER FUNCTION "app_private"."time_off_timezone"("w" "uuid", "person" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."timezone_name_valid"("zone" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  if zone is null then return false; end if;
  if exists (select 1 from app_private.timezone_names where name = zone) then return true; end if;
  -- ponytail: the snapshot is as old as this migration; a zone a later tzdata adds
  -- still passes through the catalog scan below (slow, never wrong). Refresh the
  -- table if that ever shows up in timings.
  return exists (select 1 from pg_catalog.pg_timezone_names where name = zone);
end;
$$;


ALTER FUNCTION "app_private"."timezone_name_valid"("zone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."user_has_active_organization_access"("actor_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.workspace_memberships membership
    join public.workspaces workspace on workspace.id = membership.workspace_id
    where membership.user_id = actor_user_id
      and membership.status = 'active'
      and (
        workspace.lifecycle_status = 'active'
        or (
          workspace.lifecycle_status = 'closure_scheduled'
          and workspace.closure_effective_at > now()
        )
      )
  );
$$;


