CREATE OR REPLACE FUNCTION "app_private"."weekly_preference_may_write"("actor" "uuid", "w" "uuid", "source" "text", "model" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if source is null or source not in ('employee','manager') then raise exception 'Choose whose week to save' using errcode='22023'; end if;
 if not coalesce((model->>case when source='employee' then 'can_edit_employee' else 'can_manage' end)::boolean,false) then
  -- The core says why.
  perform app_private.authorize(actor,w,case when source='employee' then 'availability.own' else 'availability.team_write' end,
   target_person=>(model->>'employee_id')::uuid);
  raise exception 'Not allowed' using errcode='42501',hint='authz.out_of_scope',detail='availability';
 end if;
end;
$$;


ALTER FUNCTION "app_private"."weekly_preference_may_write"("actor" "uuid", "w" "uuid", "source" "text", "model" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."weekly_preference_whole_days"("w" "uuid", "preference" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 with selectable as (
  select t.id::text as id from public.shift_types t
  where t.workspace_id = w and t.archived_at is null and t.deleted_at is null
   and t.default_start_time is not null and t.default_end_time is not null and t.default_start_time <> t.default_end_time
 )
 select case when preference->>'input_mode' <> 'shift_type' or not exists (select 1 from selectable) then preference
  else jsonb_set(preference, '{days}', (
   select jsonb_agg(case when not (d->>'all_day')::boolean
      and not exists (select 1 from selectable s where not (d->'shift_type_ids') ? s.id)
     then d || jsonb_build_object('all_day', true, 'shift_type_ids', '[]'::jsonb) else d end
     order by (d->>'day')::integer)
   from jsonb_array_elements(preference->'days') d)) end
$$;


ALTER FUNCTION "app_private"."weekly_preference_whole_days"("w" "uuid", "preference" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."workspace_allows_interactive_access"("target_workspace_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.workspaces workspace
    where workspace.id = target_workspace_id
      and (
        workspace.lifecycle_status = 'active'
        or (
          workspace.lifecycle_status = 'closure_scheduled'
          and workspace.closure_effective_at > now()
        )
        or (
          workspace.lifecycle_status = 'draft'
          and current_setting('app.allow_incomplete_workspace_context', true) = 'on'
        )
      )
  );
$$;


ALTER FUNCTION "app_private"."workspace_allows_interactive_access"("target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."workspace_has_permission"("target_workspace_id" "uuid", "target_permission" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select public.service_actor_has_permission(auth.uid(),target_workspace_id,target_permission);
$$;


ALTER FUNCTION "app_private"."workspace_has_permission"("target_workspace_id" "uuid", "target_permission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."workspace_open_to_actor"("target_workspace_id" "uuid", "actor_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select app_private.workspace_allows_interactive_access(target_workspace_id)
    or exists (
      select 1
      from public.workspaces workspace
      join public.workspace_memberships membership
        on membership.workspace_id = workspace.id
      where workspace.id = target_workspace_id
        and workspace.lifecycle_status = 'draft'
        and membership.user_id = actor_user_id
        and membership.status = 'active'
        and membership.role = 'owner'
    );
$$;


ALTER FUNCTION "app_private"."workspace_open_to_actor"("target_workspace_id" "uuid", "actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "app_private"."workspace_role_for"("target_workspace_id" "uuid") RETURNS "public"."workspace_role"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select membership.role
  from public.workspace_memberships membership
  where membership.workspace_id = target_workspace_id
    and membership.user_id = (select auth.uid())
    and membership.status = 'active'
    and not app_private.document_actor_blocked((select auth.uid()), target_workspace_id)
    and app_private.workspace_open_to_actor(target_workspace_id, (select auth.uid()))
  limit 1;
$$;


ALTER FUNCTION "app_private"."workspace_role_for"("target_workspace_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."workspace_todos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "title" "text" NOT NULL,
    "body" "text" DEFAULT ''::"text" NOT NULL,
    "severity" "public"."workspace_todo_severity" DEFAULT 'info'::"public"."workspace_todo_severity" NOT NULL,
    "status" "public"."workspace_todo_status" DEFAULT 'open'::"public"."workspace_todo_status" NOT NULL,
    "system_generated" boolean DEFAULT true NOT NULL,
    "source_type" "text" NOT NULL,
    "source_id" "uuid" NOT NULL,
    "source_key" "text" NOT NULL,
    "employee_id" "uuid",
    "due_at" timestamp with time zone,
    "action_url" "text",
    "resolved_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "workspace_todos_action_url_check" CHECK ((("action_url" IS NULL) OR (("char_length"("action_url") <= 500) AND ("action_url" ~ '^/app(/|$)'::"text")))),
    CONSTRAINT "workspace_todos_body_check" CHECK (("char_length"("body") <= 1000)),
    CONSTRAINT "workspace_todos_check" CHECK ((("status" = 'resolved'::"public"."workspace_todo_status") = ("resolved_at" IS NOT NULL))),
    CONSTRAINT "workspace_todos_source_key_check" CHECK ((("char_length"("btrim"("source_key")) >= 1) AND ("char_length"("btrim"("source_key")) <= 160))),
    CONSTRAINT "workspace_todos_source_type_check" CHECK ((("char_length"("btrim"("source_type")) >= 1) AND ("char_length"("btrim"("source_type")) <= 80))),
    CONSTRAINT "workspace_todos_title_check" CHECK ((("char_length"("btrim"("title")) >= 1) AND ("char_length"("btrim"("title")) <= 160)))
);


