CREATE OR REPLACE FUNCTION "public"."acknowledge_announcement_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_announcement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  item public.announcements;
  acknowledged timestamptz;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'announcement.acknowledge');
  perform app_private.announcement_release(target_workspace_id);
  select * into item from public.announcements where id = target_announcement_id and workspace_id = target_workspace_id;
  if item.id is null or item.status <> 'published' or item.archived_at is not null
     or not app_private.announcement_visible(actor_user_id, item) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'announcement.acknowledge';
  end if;
  insert into public.announcement_acknowledgements (workspace_id, announcement_id, user_id)
  values (target_workspace_id, target_announcement_id, actor_user_id)
  on conflict (announcement_id, user_id) do nothing;
  select a.acknowledged_at into acknowledged from public.announcement_acknowledgements a
  where a.announcement_id = target_announcement_id and a.user_id = actor_user_id;
  return jsonb_build_object('status', 'saved', 'acknowledged_at', acknowledged);
end;
$$;


ALTER FUNCTION "public"."acknowledge_announcement_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_announcement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acknowledge_document_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "signer_name" "text", "expected_content_digest" "text", "authenticated_timestamp" timestamp with time zone, "request_idempotency_key" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype; c public.employee_onboarding_cases%rowtype; evidence public.employee_acknowledgement_envelopes%rowtype; employee_name text;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'documents.self',target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id and q.workspace_id=target_workspace_id));
 select c0.* into c from public.employee_onboarding_cases c0 join public.employee_onboarding_requirements q on q.case_id=c0.id
 where q.id=target_requirement_id and q.workspace_id=target_workspace_id and q.lifecycle_user_id=actor_user_id for update of c0;
 select * into r from public.employee_onboarding_requirements where id=target_requirement_id and workspace_id=target_workspace_id for update;
 if c.id is null or r.kind<>'acknowledgement' or r.lifecycle_user_id is distinct from actor_user_id
  or not app_private.document_actor_can_read(actor_user_id,r.workspace_id,r.employee_id,r.lifecycle_user_id)
 then raise exception 'policy unavailable' using errcode='P0002'; end if;
 select * into evidence from public.employee_acknowledgement_envelopes where workspace_id=target_workspace_id and idempotency_key=request_idempotency_key;
 if evidence.id is not null then if evidence.withdrawn_at is not null then raise exception 'acknowledgement was withdrawn; use a new request' using errcode='PT409'; end if;
  if evidence.requirement_id<>r.id or evidence.user_id<>actor_user_id or evidence.content_digest is distinct from expected_content_digest or evidence.typed_name is distinct from btrim(signer_name)
  then raise exception 'acknowledgement request changed' using errcode='PT409'; end if;
  return r.lifecycle_revision;
 end if;
 if r.lifecycle_revision<>expected_revision then raise exception 'policy changed; refresh required' using errcode='PT409'; end if;
 if r.lifecycle_closed_at is not null or r.lifecycle_exempt or r.status='superseded' then raise exception 'policy request is closed' using errcode='22023'; end if;
 select concat_ws(' ',first_name,last_name) into employee_name from public.employee_profiles where id=r.employee_id and workspace_id=r.workspace_id;
 if expected_content_digest is null or r.source_snapshot->>'content_digest' is distinct from expected_content_digest
  or signer_name is null or lower(regexp_replace(btrim(signer_name),'\s+',' ','g'))<>lower(regexp_replace(btrim(employee_name),'\s+',' ','g'))
  or request_idempotency_key is null or authenticated_timestamp is null or authenticated_timestamp<now()-interval '30 minutes' or authenticated_timestamp>now()+interval '1 minute'
 then raise exception 'current content, matching full name and recent sign-in required' using errcode='22023'; end if;
 if exists(select 1 from public.employee_acknowledgement_envelopes where requirement_id=r.id and withdrawn_at is null) then raise exception 'policy already acknowledged; refresh required' using errcode='PT409'; end if;
 insert into public.employee_acknowledgement_envelopes(workspace_id,employee_id,case_id,requirement_id,template_version_id,content_digest,intent_statement,typed_name,user_id,membership_id,authenticated_at,idempotency_key)
 values(r.workspace_id,r.employee_id,r.case_id,r.id,r.source_id,expected_content_digest,r.source_snapshot->>'intent_statement',btrim(signer_name),actor_user_id,c.membership_id,authenticated_timestamp,request_idempotency_key);
 update public.employee_onboarding_requirements set status='completed',completed_at=now(),deadline_at=null,paused_remaining_seconds=null,document_suspended_at=null,
  rejection_reason=null,lifecycle_revision=lifecycle_revision+1,updated_at=now() where id=r.id returning lifecycle_revision into expected_revision;
 perform app_private.document_audit(r,actor_user_id,'document.policy_acknowledged',jsonb_build_object('content_digest',expected_content_digest,'evidence_schema_version','acknowledgement:v1','revision',expected_revision));
 perform app_private.document_sync_onboarding(r.id,actor_user_id);
 return expected_revision;
end;
$$;


ALTER FUNCTION "public"."acknowledge_document_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "signer_name" "text", "expected_content_digest" "text", "authenticated_timestamp" timestamp with time zone, "request_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."acquire_schedule_edit_session_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date", "requested_source" "public"."schedule_edit_source", "requested_draft_id" "uuid" DEFAULT NULL::"uuid", "target_location_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  current_week_start date;
  manageable uuid[];
  effective uuid[];
  adding uuid[];
  own_session public.schedule_edit_sessions%rowtype;
  holder public.schedule_edit_sessions%rowtype;
  set_aside public.schedule_edit_sessions%rowtype;
  set_aside_draft_id uuid;
  source_draft public.schedule_drafts%rowtype;
  edit_session_id uuid;
  session_source public.schedule_edit_source;
  session_draft_id uuid;
  recovery_draft_id uuid;
begin
  current_week_start := public.schedule_current_week_start_service(target_workspace_id);
  if current_week_start is not null and target_week_start < current_week_start then
    raise exception '%', jsonb_build_object(
      'status', 'past_edit_blocked',
      'past_edits', jsonb_build_array(jsonb_build_object(
        'op_type', 'update',
        'shift_id', null,
        'scheduled_date', to_char(target_week_start, 'YYYY-MM-DD'),
        'location_name', 'Schedule week',
        'employee_name', null,
        'reason', 'past_week',
        'severity', 'blocked'
      )),
      'past_edit_messages', jsonb_build_array(
        'Past schedule weeks are read-only.'
      ),
      'current_week_start', current_week_start
    )::text using errcode = 'P0001';
  end if;

  perform public.availability_lock_workspace(target_workspace_id);

  -- Where this person may edit: the live locations the core gives.
  manageable := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.edit');
  select coalesce(array_agg(location.id order by location.id), '{}') into manageable
  from public.locations location
  where location.workspace_id = target_workspace_id
    and location.archived_at is null
    and location.id = any(manageable);
  select coalesce(array_agg(distinct requested order by requested), '{}') into effective
  from unnest(coalesce(target_location_ids, manageable)) requested
  where requested = any(manageable);
  if cardinality(effective) = 0 then
    -- Nothing here to edit: asked of no place, the core answers with the
    -- person's reason (no permission, blocked) or out_of_scope.
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit', target_locations => array[null]::uuid[]);
  end if;

  select * into own_session
  from public.schedule_edit_sessions session
  where session.workspace_id = target_workspace_id
    and session.week_start = target_week_start
    and session.holder_user_id = actor_user_id
    and session.status = 'active'
  for update;
  -- The person's own edit reaching a location they no longer edit closes;
  -- they start again where they may (B-3).
  -- Asking for another draft or source of the week puts the open edit aside
  -- the same way (D-O9): it is never resumed in place of what was asked for.
  -- It closes below, once nobody else's edit of the asked draft says no.
  if own_session.id is not null
    and (app_private.authz_reason(actor_user_id, target_workspace_id, 'schedule.edit', own_session.location_ids) is not null
      or own_session.source_kind is distinct from requested_source
      or own_session.source_draft_id is distinct from case when requested_source = 'draft' then requested_draft_id end) then
    set_aside := own_session;
    own_session := null;
  end if;
  adding := array(
    select location_id from unnest(effective) location_id
    where own_session.id is null or not location_id = any(own_session.location_ids)
  );

  if own_session.id is null and requested_source = 'draft' then
    select * into source_draft
    from public.schedule_drafts draft
    where draft.id = requested_draft_id
      and draft.workspace_id = target_workspace_id
      and draft.week_start = target_week_start
      and draft.archived_at is null
      and draft.location_ids && manageable;
    -- A draft touching none of the person's locations is not there for them.
    if source_draft.id is null then
      raise exception 'Not allowed' using errcode = '42501', detail = 'schedule.edit', hint = 'authz.out_of_scope';
    end if;

    -- One person edits a draft at a time: say who, take nothing.
    select * into holder
    from public.schedule_edit_sessions session
    where session.source_draft_id = source_draft.id
      and session.status = 'active'
    for update;
    -- An edit whose holder may no longer edit all of it holds nothing (B-3).
    if holder.id is not null and holder.expires_at > now()
      and app_private.authz_reason(holder.holder_user_id, target_workspace_id, 'schedule.edit', holder.location_ids) is null then
      return jsonb_build_object(
        'status', 'conflict',
        'session_id', holder.id,
        'holder_name', coalesce((
          select profile.display_name from public.user_profiles profile
          where profile.user_id = holder.holder_user_id
        ), 'Another manager'),
        'last_heartbeat', holder.last_heartbeat,
        'expires_at', holder.expires_at
      );
    end if;

    -- An expired edit of the draft closes; unsaved work becomes a recovery draft.
    -- ponytail: if the person's own edit is put aside too, the answer names only this one.
    if holder.id is not null then
      recovery_draft_id := app_private.close_schedule_edit_session(holder);
    end if;
  end if;

  if set_aside.id is not null and set_aside.id is distinct from holder.id then
    -- Closed always; the answer names the other editor's draft first.
    set_aside_draft_id := app_private.close_schedule_edit_session(set_aside);
    recovery_draft_id := coalesce(recovery_draft_id, set_aside_draft_id);
  end if;

  if own_session.id is not null then
    -- BL-069: the same person picks their edit back up, widened to the new locations.
    update public.schedule_edit_sessions
    set last_heartbeat = now(),
        expires_at = now() + interval '4 minutes',
        location_ids = array(
          select distinct location_id from unnest(own_session.location_ids || adding) location_id
          order by location_id
        ),
        base_publication_ids = own_session.base_publication_ids || app_private.schedule_edit_starting_point(
          target_workspace_id, target_week_start, adding, own_session.source_draft_id
        )
    where id = own_session.id;
    edit_session_id := own_session.id;
    session_source := own_session.source_kind;
    session_draft_id := own_session.source_draft_id;
  else
    insert into public.schedule_edit_sessions (
      workspace_id, week_start, source_kind, source_draft_id, source_revision,
      holder_user_id, location_ids, base_publication_ids
    ) values (
      target_workspace_id, target_week_start, requested_source,
      case when requested_source = 'draft' then source_draft.id end,
      case when requested_source = 'draft' then source_draft.revision else 0 end,
      actor_user_id, effective,
      app_private.schedule_edit_starting_point(target_workspace_id, target_week_start, effective, source_draft.id)
    ) returning id into edit_session_id;
    session_source := requested_source;
    session_draft_id := source_draft.id;
  end if;

  if session_source = 'published' then
    insert into public.schedule_edit_session_shifts (id, workspace_id, session_id, location_id, employee_id, job_id, shift_type_id, scheduled_date, start_time, end_time, time_basis, time_snapshot, time_timezone, unpaid_break_minutes, hide_time_on_badge, note, label_ids, label_names)
    select shift.source_shift_id, shift.workspace_id, edit_session_id, shift.location_id, shift.employee_id, shift.job_id, shift.shift_type_id, shift.scheduled_date, shift.start_time, shift.end_time, shift.time_basis, shift.time_snapshot, shift.time_timezone, shift.unpaid_break_minutes, shift.hide_time_on_badge, shift.note, shift.label_ids, shift.label_names
    from public.schedule_published_shifts shift
    join public.schedule_location_publications publication on publication.id = shift.publication_id
    where shift.workspace_id = target_workspace_id
      and publication.week_start = target_week_start
      and publication.status = 'current'
      and shift.location_id = any(adding);
  elsif session_source = 'draft' then
    insert into public.schedule_edit_session_shifts (id, workspace_id, session_id, location_id, employee_id, job_id, shift_type_id, scheduled_date, start_time, end_time, time_basis, time_snapshot, time_timezone, unpaid_break_minutes, hide_time_on_badge, note, revision, label_ids, label_names)
    select shift.id, shift.workspace_id, edit_session_id, shift.location_id, shift.employee_id, shift.job_id, shift.shift_type_id, shift.scheduled_date, shift.start_time, shift.end_time, shift.time_basis, shift.time_snapshot, shift.time_timezone, shift.unpaid_break_minutes, shift.hide_time_on_badge, shift.note, shift.revision, shift.label_ids, shift.label_names
    from public.schedule_draft_shifts shift
    where shift.draft_id = session_draft_id
      and shift.location_id = any(adding);
  end if;

  -- DB-1c: the shifts the edit is opened or widened with are not a step of it.
  delete from app_private.schedule_edit_undo_steps step
  where step.session_id = edit_session_id and step.step_at = statement_timestamp()
    and step.step_xact = pg_current_xact_id();

  return jsonb_build_object(
    'status', case
      when own_session.id is not null then 'resumed'
      when recovery_draft_id is not null then 'acquired_after_recovery'
      else 'acquired'
    end,
    'session', public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, edit_session_id),
    'recovered_draft_id', recovery_draft_id,
    'recovered_draft_name', (select draft.name from public.schedule_drafts draft where draft.id = recovery_draft_id)
  );
end;
$$;


ALTER FUNCTION "public"."acquire_schedule_edit_session_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date", "requested_source" "public"."schedule_edit_source", "requested_draft_id" "uuid", "target_location_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."act_on_notification_inbox_item_v2_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_item_id" "uuid", "target_action" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; affected integer;
begin
 if target_workspace_id is not null then
  return app_private.document_account_inbox_action_base(actor_user_id,target_workspace_id,target_item_id,target_action);
 end if;
 if target_action not in ('read_all','seen','read','unread','dismiss') then raise exception 'unsupported notification action' using errcode='22023'; end if;
 if target_action='read_all' or app_private.document_account_inbox_allowed(target_item_id,actor_user_id) then
  update public.notification_inbox_items i set
   seen_at=coalesce(i.seen_at,now()),
   read_at=case when target_action in ('read','read_all') then coalesce(i.read_at,now()) when target_action='unread' then null else i.read_at end,
   dismissed_at=case when target_action='dismiss' then now() else i.dismissed_at end
  where (target_action='read_all' or i.id=target_item_id) and app_private.document_account_inbox_allowed(i.id,actor_user_id);
  get diagnostics affected=row_count;
  if target_action='read_all' then
   result:=app_private.document_account_inbox_action_base(actor_user_id,null,null,target_action);
   affected:=affected+(result->>'affected')::integer;
  elsif affected=0 then raise exception 'notification inbox item not found' using errcode='P0002';
  end if;
  return jsonb_build_object('status','saved','affected',affected);
 end if;
 return app_private.document_account_inbox_action_base(actor_user_id,null,target_item_id,target_action);
end;
$$;


ALTER FUNCTION "public"."act_on_notification_inbox_item_v2_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_item_id" "uuid", "target_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."act_on_notification_inbox_workspace_base"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_item_id" "uuid", "target_action" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  affected integer;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'notifications.read_own');

  if target_action = 'read_all' then
    update public.notification_inbox_items item
    set seen_at = coalesce(item.seen_at, now()),
        read_at = coalesce(item.read_at, now())
    from public.notification_recipients recipient
    where item.workspace_id = target_workspace_id
      and recipient.id = item.recipient_projection_id
      and recipient.workspace_id = item.workspace_id
      and recipient.recipient_user_id = actor_user_id
      and item.dismissed_at is null
      and item.visibility_state = 'visible';
  elsif target_item_id is null then
    raise exception 'notification inbox item required' using errcode = '22023';
  elsif target_action = 'seen' then
    update public.notification_inbox_items item
    set seen_at = coalesce(item.seen_at, now())
    from public.notification_recipients recipient
    where item.id = target_item_id
      and item.workspace_id = target_workspace_id
      and recipient.id = item.recipient_projection_id
      and recipient.workspace_id = item.workspace_id
      and recipient.recipient_user_id = actor_user_id
      and item.dismissed_at is null;
  elsif target_action = 'read' then
    update public.notification_inbox_items item
    set seen_at = coalesce(item.seen_at, now()),
        read_at = coalesce(item.read_at, now())
    from public.notification_recipients recipient
    where item.id = target_item_id
      and item.workspace_id = target_workspace_id
      and recipient.id = item.recipient_projection_id
      and recipient.workspace_id = item.workspace_id
      and recipient.recipient_user_id = actor_user_id
      and item.dismissed_at is null;
  elsif target_action = 'unread' then
    update public.notification_inbox_items item
    set seen_at = coalesce(item.seen_at, now()),
        read_at = null
    from public.notification_recipients recipient
    where item.id = target_item_id
      and item.workspace_id = target_workspace_id
      and recipient.id = item.recipient_projection_id
      and recipient.workspace_id = item.workspace_id
      and recipient.recipient_user_id = actor_user_id
      and item.dismissed_at is null;
  elsif target_action = 'dismiss' then
    update public.notification_inbox_items item
    set seen_at = coalesce(item.seen_at, now()),
        dismissed_at = now()
    from public.notification_recipients recipient
    where item.id = target_item_id
      and item.workspace_id = target_workspace_id
      and recipient.id = item.recipient_projection_id
      and recipient.workspace_id = item.workspace_id
      and recipient.recipient_user_id = actor_user_id
      and item.dismissed_at is null;
  else
    raise exception 'unsupported notification action' using errcode = '22023';
  end if;

  get diagnostics affected = row_count;
  if target_action <> 'read_all' and affected = 0 then
    raise exception 'notification inbox item not found' using errcode = 'P0002';
  end if;
  return jsonb_build_object('status', 'saved', 'affected', affected);
end;
$$;


ALTER FUNCTION "public"."act_on_notification_inbox_workspace_base"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_item_id" "uuid", "target_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_schedule_pending_op_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "target_op_type" "text", "target_shift_id" "uuid" DEFAULT NULL::"uuid", "target_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_session public.schedule_edit_sessions%rowtype;
  existing_shift public.schedule_edit_session_shifts%rowtype;
  created_id uuid := gen_random_uuid();
  next_location_id uuid;
  next_employee_id uuid;
  next_job_id uuid;
  next_shift_type_id uuid;
  next_scheduled_date date;
  next_start_time time;
  next_end_time time;
  next_unpaid_break_minutes integer;
  next_note text;
begin
 perform public.availability_lock_workspace(target_workspace_id);
  if target_op_type not in ('create', 'update', 'delete') then
    raise exception 'invalid pending op type' using errcode='22023';
  end if;

  select * into target_session
    from public.schedule_edit_sessions session
   where session.id = target_session_id
     and session.workspace_id = target_workspace_id
   for update;

  if target_session.id is null or target_session.holder_user_id <> actor_user_id then
    raise exception 'edit session not found' using errcode='P0002';
  end if;
  if target_session.status <> 'active' then
    raise exception 'edit session closed' using errcode = 'PT409', hint = 'schedule.edit_session_closed';
  elsif target_session.expires_at <= now() then
    raise exception 'edit lease expired' using errcode = 'PT409', hint = 'schedule.edit_lease_expired';
  end if;
  -- The edit's locations are still the person's to edit (B-3).
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit', target_locations => target_session.location_ids);

  if target_op_type in ('update', 'delete') then
    select * into existing_shift
      from public.schedule_edit_session_shifts shift
     where shift.session_id = target_session_id
       and shift.id = target_shift_id
     for update;
    if existing_shift.id is null then
      raise exception 'shift not found' using errcode='P0002';
    end if;
  end if;

  next_location_id := coalesce(
    nullif(target_payload->>'location_id', '')::uuid,
    existing_shift.location_id
  );
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit',
    target_locations => case when next_location_id is not null then array(
      select distinct place from unnest(array[existing_shift.location_id, next_location_id]) place where place is not null
    ) end);

  if target_op_type in ('create','update') then
    target_payload:=public.normalize_schedule_time_source(target_workspace_id,case when target_payload ? 'time_basis' then coalesce(to_jsonb(existing_shift),'{}'::jsonb)||target_payload else (coalesce(to_jsonb(existing_shift),'{}'::jsonb)||target_payload)-'time_basis' end,case when existing_shift.id is not null then to_jsonb(existing_shift) else null end);
  end if;
  if target_op_type = 'create' then
    insert into public.schedule_edit_session_shifts(id, workspace_id, session_id, location_id, employee_id, job_id, shift_type_id, scheduled_date, start_time, end_time, time_basis, time_snapshot, time_timezone, unpaid_break_minutes, note, pending_op_type, locked, hide_time_on_badge)
    values (created_id, target_workspace_id, target_session_id, next_location_id, nullif(target_payload->>'employee_id', '')::uuid, nullif(target_payload->>'job_id', '')::uuid, nullif(target_payload->>'shift_type_id', '')::uuid, (target_payload->>'scheduled_date')::date, nullif(target_payload->>'start_time','')::time, nullif(target_payload->>'end_time','')::time, target_payload->>'time_basis', target_payload->'time_snapshot', target_payload->>'time_timezone', coalesce((target_payload->>'unpaid_break_minutes')::integer, 0), coalesce(target_payload->>'note', ''), 'create', false, coalesce((target_payload->>'hide_time_on_badge')::boolean,false));
  else
    if target_op_type = 'delete' then
      update public.schedule_edit_session_shifts
         set pending_op_type = 'delete',
             locked = true,
             revision = revision + 1,
             updated_at = now()
       where session_id = target_session_id
         and id = existing_shift.id;
    else
      next_employee_id := coalesce(nullif(target_payload->>'employee_id', '')::uuid, existing_shift.employee_id);
      next_job_id := coalesce(nullif(target_payload->>'job_id', '')::uuid, existing_shift.job_id);
      next_shift_type_id := coalesce(nullif(target_payload->>'shift_type_id', '')::uuid, existing_shift.shift_type_id);
      next_scheduled_date := coalesce((target_payload->>'scheduled_date')::date, existing_shift.scheduled_date);
      next_start_time := nullif(target_payload->>'start_time','')::time;
      next_end_time := nullif(target_payload->>'end_time','')::time;
      next_unpaid_break_minutes := coalesce((target_payload->>'unpaid_break_minutes')::integer, existing_shift.unpaid_break_minutes, 0);
      next_note := coalesce(target_payload->>'note', existing_shift.note, '');

      update public.schedule_edit_session_shifts
         set location_id = next_location_id,
             employee_id = next_employee_id,
             job_id = next_job_id,
             shift_type_id = next_shift_type_id,
             scheduled_date = next_scheduled_date,
             start_time = next_start_time,
             end_time = next_end_time, time_basis=target_payload->>'time_basis', time_snapshot=target_payload->'time_snapshot', time_timezone=target_payload->>'time_timezone', hide_time_on_badge=coalesce((target_payload->>'hide_time_on_badge')::boolean,false),
             unpaid_break_minutes = next_unpaid_break_minutes,
             note = next_note,
             pending_op_type = 'update',
             locked = false,
             revision = revision + 1,
             updated_at = now()
       where session_id = target_session_id
         and id = existing_shift.id;
    end if;
    created_id := existing_shift.id;
  end if;

  update public.schedule_edit_sessions
     set revision = revision + 1,
         dirty = true,
         last_heartbeat = now(),
         expires_at = now() + interval '4 minutes'
   where id = target_session_id;

  return jsonb_build_object('status', 'ok', 'op_id', created_id);
end;
$$;


ALTER FUNCTION "public"."add_schedule_pending_op_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "target_op_type" "text", "target_shift_id" "uuid", "target_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_policy_definition_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_version_id" "uuid", "expected_revision" integer, "expected_preview_token" "text", "apply_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.documents.write');
  return app_private.apply_lifecycle_definition(actor_user_id, target_workspace_id, target_version_id, expected_revision,
    expected_preview_token, apply_reason, 'acknowledgement');
end;
$$;


ALTER FUNCTION "public"."apply_policy_definition_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_version_id" "uuid", "expected_revision" integer, "expected_preview_token" "text", "apply_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_schedule_auto_fill_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "expected_session_revision" integer, "expected_fingerprint" "text", "assignments" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare target_session public.schedule_edit_sessions%rowtype; preview jsonb; assignment jsonb; proposal jsonb;
  applied jsonb:='[]'::jsonb; rejected jsonb:='[]'::jsonb; shift_row public.schedule_edit_session_shifts%rowtype; employee uuid;
begin
 perform public.availability_lock_workspace(target_workspace_id);
  if jsonb_typeof(assignments)<>'array' then raise exception 'auto-fill assignments must be an array' using errcode='22023'; end if;
  select * into target_session from public.schedule_edit_sessions s where s.id=target_session_id and s.workspace_id=target_workspace_id for update;
  if target_session.id is null or target_session.holder_user_id<>actor_user_id then raise exception 'edit session not found' using errcode='P0002'; end if;
  if target_session.revision<>expected_session_revision then raise exception 'stale auto-fill preview' using errcode = 'PT409'; end if;
  preview:=public.preview_schedule_auto_fill_service(actor_user_id,target_workspace_id,target_session_id);
  if preview->>'fingerprint'<>expected_fingerprint then raise exception 'stale auto-fill preview' using errcode = 'PT409'; end if;
  for assignment in select value from jsonb_array_elements(assignments) loop
    select value into proposal from jsonb_array_elements(preview->'proposals') where value->>'shift_id'=assignment->>'shift_id';
    employee:=(assignment->>'employee_id')::uuid;
    select * into shift_row from public.schedule_edit_session_shifts where session_id=target_session.id and id=(assignment->>'shift_id')::uuid and employee_id is null;
    if proposal is null or shift_row.id is null or not exists(select 1 from jsonb_array_elements(proposal->'candidates') c where c->>'employee_id'=assignment->>'employee_id')
      or exists(select 1 from public.schedule_edit_session_shifts x where x.session_id=target_session.id and x.employee_id=employee
        and tsrange(x.scheduled_date+x.start_time,x.scheduled_date+x.end_time+case when x.end_time<=x.start_time then interval '1 day' else interval '0' end,'[)')
          && tsrange(shift_row.scheduled_date+shift_row.start_time,shift_row.scheduled_date+shift_row.end_time+case when shift_row.end_time<=shift_row.start_time then interval '1 day' else interval '0' end,'[)')) then
      rejected:=rejected||jsonb_build_array(jsonb_build_object('shift_id',assignment->>'shift_id','reason','Assignment is no longer eligible'));
    else
      update public.schedule_edit_session_shifts set employee_id=employee,revision=revision+1,updated_at=now() where session_id=target_session.id and id=shift_row.id;
      applied:=applied||jsonb_build_array(jsonb_build_object('shift_id',shift_row.id,'employee_id',employee));
    end if;
  end loop;
  if jsonb_array_length(applied)>0 then update public.schedule_edit_sessions set revision=revision+1,dirty=true,last_heartbeat=now(),expires_at=now()+interval '4 minutes' where id=target_session.id; end if;
  return jsonb_build_object('status','applied','applied',applied,'rejected',rejected,'session',public.get_schedule_edit_session_service(actor_user_id,target_workspace_id,target_session.id));
end; $$;


ALTER FUNCTION "public"."apply_schedule_auto_fill_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "expected_session_revision" integer, "expected_fingerprint" "text", "assignments" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_schedule_default_hours_service"("actor" "uuid", "w" "uuid", "sid" "uuid", "command" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare review jsonb; row_value jsonb; result jsonb; prior public.schedule_default_hours_reviews%rowtype; rev integer; key uuid:=(command->>'idempotency_key')::uuid;
begin
 if key is null then raise exception 'A retry key is required' using errcode='22023'; end if;
 perform public.availability_lock_workspace(w);
 perform public.get_schedule_edit_session_service(actor,w,sid);
 select * into prior from public.schedule_default_hours_reviews where workspace_id=w and actor_id=actor and operation_id=key;
 if found then
  if prior.session_id<>sid or prior.command<>command then raise exception 'Retry key was already used for a different review' using errcode = 'PT409'; end if;
  return public.get_schedule_edit_session_service(actor,w,sid);
 end if;
 -- Settings uses atomic row updates. Hold these source rows while reviewing and
 -- applying so a changed default cannot slip between the two operations.
 perform 1 from public.shift_types t where t.workspace_id=w and t.id in(select s.shift_type_id from public.schedule_edit_session_shifts s where s.workspace_id=w and s.session_id=sid and s.id in(select value::uuid from jsonb_array_elements_text(command->'shift_ids'))) order by t.id for share;
 review:=public.preview_schedule_default_hours_service(actor,w,sid,command);
 if review->>'fingerprint' is distinct from command->>'fingerprint' then raise exception 'Defaults, shifts or conflicts changed; review again' using errcode = 'PT409'; end if;
 if (review->>'blocked_count')::integer>0 or (review->>'changed_count')::integer=0 then raise exception 'Resolve blocked shifts or choose changed defaults before applying' using errcode='23514'; end if;
 if exists(select 1 from jsonb_array_elements(review->'shifts') x where (x->>'can_apply')::boolean
  and x->'after_assessment'->>'operation'='warning_requires_override'
  and x->'after_assessment'->>'warning_policy'='confirm'
  and not coalesce((x->'after_assessment'->>'override_recorded')::boolean,false))
  and not coalesce((command->>'confirm_availability')::boolean,false) then
  raise exception 'Confirm the current availability conflicts before applying defaults' using errcode='22023'; end if;
  rev:=(review->>'session_revision')::integer;
 for row_value in select value from jsonb_array_elements(review->'shifts') where (value->>'can_apply')::boolean loop
  result:=public.mutate_schedule_edit_shift_service(actor,w,sid,rev,'update',(row_value->>'shift_id')::uuid,(row_value->>'shift_revision')::integer,row_value->'after',null);
  rev:=(result->>'revision')::integer;
 end loop;
 insert into public.schedule_default_hours_reviews(workspace_id,actor_id,operation_id,session_id,command,review,result) values(w,actor,key,sid,command,review,result);
 insert into public.audit_events(workspace_id,actor_user_id,action,target_type,target_id,metadata) values(w,actor,'schedule.default_hours_applied','schedule_edit_session',sid::text,
  jsonb_build_object('review_operation_id',key,'fingerprint',review->>'fingerprint','changed_count',review->'changed_count','starts_on',review->'starts_on','ends_on',review->'ends_on'));
 return result;
end $$;


ALTER FUNCTION "public"."apply_schedule_default_hours_service"("actor" "uuid", "w" "uuid", "sid" "uuid", "command" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_schedule_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "expected_session_revision" integer, "target_template_id" "uuid", "apply_mode" "text", "department_keys" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_session public.schedule_edit_sessions%rowtype;
  template_row public.schedule_templates%rowtype;
  source record;
  applied_count integer := 0;
  converted_count integer := 0;
  chosen_employee uuid;
  target_date date;
  target_end_date date;
  selected_department_ids uuid[] := '{}'::uuid[];
  include_no_department boolean := false;
  template_scope uuid[];
  live_locations uuid[];
  kept_ids uuid[];
  kept_names text[];
  left_off text[] := '{}'::text[];
  skipped jsonb;
  replaced uuid[] := '{}'::uuid[];
begin
 perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.templates',
   target_locations => app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.templates'));
 template_scope := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.templates');
 perform public.availability_lock_workspace(target_workspace_id);
  if apply_mode not in ('merge', 'overwrite') then
    raise exception 'invalid template apply mode' using errcode = '22023';
  end if;

  -- No department list: the whole template. Checked the same way as the preview.
  selected_department_ids := app_private.schedule_template_department_ids(target_workspace_id, department_keys);
  include_no_department := coalesce('__no_department__' = any (department_keys), false);

  select *
    into target_session
  from public.schedule_edit_sessions session
  where session.id = target_session_id
    and session.workspace_id = target_workspace_id
  for update;

  if target_session.id is null or target_session.holder_user_id <> actor_user_id then
    raise exception 'edit session not found' using errcode = 'P0002';
  end if;

  if target_session.status <> 'active' then
    raise exception 'edit session closed' using errcode = 'PT409', hint = 'schedule.edit_session_closed';
  elsif target_session.expires_at <= now() then
    raise exception 'edit lease expired' using errcode = 'PT409', hint = 'schedule.edit_lease_expired';
  end if;

  if target_session.revision <> expected_session_revision then
    raise exception 'session revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
  end if;

  select *
    into template_row
  from public.schedule_templates template
  where template.id = target_template_id
    and template.workspace_id = target_workspace_id;

  if template_row.id is null then
    raise exception 'schedule template not found' using errcode = 'P0002';
  end if;
  -- Shifts at a deleted location are neither checked nor written (Q-C).
  live_locations := public.live_location_ids(target_workspace_id, array(
    select distinct s.location_id from public.schedule_template_shifts s where s.template_id = template_row.id));

  if exists (
    select 1
    from public.schedule_template_shifts template_shift
    left join public.locations location
      on location.id = template_shift.location_id
     and location.workspace_id = template_shift.workspace_id
     and location.archived_at is null
    left join public.jobs job
      on job.id = template_shift.job_id
     and job.workspace_id = template_shift.workspace_id
     and job.archived_at is null
    left join public.shift_types shift_type
      on shift_type.id = template_shift.shift_type_id
     and shift_type.workspace_id = template_shift.workspace_id
     and shift_type.archived_at is null
    where template_shift.template_id = template_row.id
      and template_shift.location_id = any (live_locations)
      and (
        location.id is null
        or job.id is null
        or (template_shift.shift_type_id is not null and shift_type.id is null)
        or not template_shift.location_id = any (template_scope)
      )
  ) then
    raise exception 'schedule template references unavailable schedule definitions' using errcode = '23503';
  end if;

  -- S3 (Mert 2026-10-05): Replace clears only the template's own locations and
  -- departments, never a shift that has started; a published shift is staged
  -- for removal like Delete stages it, a draft-only shift goes.
  if apply_mode = 'overwrite' then
    replaced := array(select app_private.schedule_template_replace_targets(
      target_workspace_id, target_session.id, template_row.id, department_keys));
    update public.schedule_availability_overrides set revoked_at = now()
    where workspace_id = target_workspace_id and shift_id = any (replaced) and revoked_at is null;
    delete from public.schedule_edit_session_shifts session_shift
    where session_shift.session_id = target_session.id
      and session_shift.id = any (replaced)
      and session_shift.source_published_shift_id is null
      and not session_shift.locked;
    update public.schedule_edit_session_shifts session_shift
    set pending_op_type = 'delete', locked = true, revision = session_shift.revision + 1, updated_at = now()
    where session_shift.session_id = target_session.id
      and session_shift.id = any (replaced)
      and (session_shift.source_published_shift_id is not null or session_shift.locked);
  end if;

  for source in
    select template_shift.*
    from public.schedule_template_shifts template_shift
    join public.jobs job
      on job.id = template_shift.job_id
     and job.workspace_id = template_shift.workspace_id
    where template_shift.template_id = template_row.id
      and template_shift.workspace_id = target_workspace_id
      and template_shift.location_id = any (live_locations)
      and (
        department_keys is null
        or job.department_id = any(selected_department_ids)
        or (job.department_id is null and include_no_department)
      )
    order by template_shift.day_offset, template_shift.start_time, template_shift.id
  loop
    target_date := target_session.week_start + source.day_offset;
    target_end_date := target_date + case when source.end_time <= source.start_time then 1 else 0 end;
    chosen_employee := source.employee_id;

    if chosen_employee is not null and (
      not exists (
        select 1
        from public.employee_profiles employee
        join public.employee_location_assignments location_assignment
          on location_assignment.employee_id = employee.id
         and location_assignment.workspace_id = employee.workspace_id
         and location_assignment.location_id = source.location_id
         and location_assignment.ended_at is null
        join public.employee_job_assignments job_assignment
          on job_assignment.employee_id = employee.id
         and job_assignment.workspace_id = employee.workspace_id
         and job_assignment.job_id = source.job_id
         and job_assignment.ended_at is null
        where employee.id = chosen_employee
          and employee.workspace_id = target_workspace_id
          and employee.archived_at is null
          -- Excluded from Schedule: the template's shift comes in open (BL-218).
          and not employee.is_excluded_from_schedule
      )
      or exists (
        select 1
        from public.schedule_edit_session_shifts existing_shift
        where existing_shift.session_id = target_session.id
          and existing_shift.employee_id = chosen_employee
          and existing_shift.pending_op_type is distinct from 'delete'
          and tsrange(
            existing_shift.scheduled_date + existing_shift.start_time,
            existing_shift.scheduled_date + existing_shift.end_time + case
              when existing_shift.end_time <= existing_shift.start_time then interval '1 day'
              else interval '0'
            end,
            '[)'
          ) && tsrange(target_date + source.start_time, target_end_date + source.end_time, '[)')
      )
    ) then
      chosen_employee := null;
      converted_count := converted_count + 1;
    end if;

    -- Only labels still active in Settings > Shift labels, named as there
    -- (BL-164); the rest are left off and counted (BL-197).
    select coalesce(array_agg(label.id order by tag.ord), '{}'::uuid[]), coalesce(array_agg(label.name order by tag.ord), '{}'::text[])
      into kept_ids, kept_names
    from unnest(coalesce(source.label_ids, '{}'::uuid[])) with ordinality as tag(id, ord)
    join public.shift_labels label
      on label.id = tag.id and label.workspace_id = target_workspace_id and label.archived_at is null;
    left_off := left_off || array(
      select coalesce(nullif(tag.name, ''), 'Unnamed label')
      from unnest(coalesce(source.label_ids, '{}'::uuid[]), coalesce(source.label_names, '{}'::text[])) as tag(id, name)
      where tag.id is not null and not tag.id = any (kept_ids));

    insert into public.schedule_edit_session_shifts(id, workspace_id, session_id, location_id, employee_id, job_id, shift_type_id, scheduled_date, start_time, end_time, time_basis, time_snapshot, time_timezone, hide_time_on_badge, label_ids, label_names, note, unpaid_break_minutes)
    values(gen_random_uuid(), target_workspace_id, target_session.id, source.location_id, chosen_employee, source.job_id, source.shift_type_id, target_date, source.start_time, source.end_time, source.time_basis, source.time_snapshot, source.time_timezone, source.hide_time_on_badge, kept_ids, kept_names, source.note, source.unpaid_break_minutes);
    applied_count := applied_count + 1;
  end loop;

  -- What was not applied, one entry per kind and name; BL-197 fills archived labels.
  select coalesce(jsonb_agg(jsonb_build_object('kind', 'archived_label', 'name', x.name, 'shift_count', x.n) order by x.name), '[]'::jsonb)
    into skipped
  from (select name, count(*)::integer n from unnest(left_off) name group by name) x;

  update public.schedule_edit_sessions
     set revision = revision + 1,
         dirty = true,
         last_heartbeat = now(),
         expires_at = now() + interval '4 minutes'
   where id = target_session.id;

  insert into public.schedule_template_events(
    workspace_id,
    template_id,
    template_name,
    action,
    actor_user_id,
    session_id,
    detail
  )
  values(
    target_workspace_id,
    template_row.id,
    template_row.name,
    'applied',
    actor_user_id,
    target_session.id,
    jsonb_build_object(
      'mode', apply_mode,
      'department_keys', to_jsonb(department_keys),
      'applied_shift_count', applied_count,
      'converted_open_count', converted_count,
      'skipped', skipped
    )
  );

  return jsonb_build_object(
    'status', 'applied',
    'mode', apply_mode,
    'applied_shift_count', applied_count,
    'converted_open_count', converted_count,
    'removed_shift_count', cardinality(replaced),
    'skipped', skipped,
    'session', public.get_schedule_edit_session_service(
      actor_user_id,
      target_workspace_id,
      target_session.id
    )
  );
end;
$$;


ALTER FUNCTION "public"."apply_schedule_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "expected_session_revision" integer, "target_template_id" "uuid", "apply_mode" "text", "department_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_signature_retention_policy_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_policy_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := actor_user_id;
  target_name text;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.documents.write');

  update public.signature_retention_policies
  set status = 'approved', approved_by = actor_id, approved_at = now(), updated_at = now()
  where id = target_policy_id and workspace_id = target_workspace_id
    and status = 'draft' and archived_at is null
  returning name into target_name;
  if target_name is null then
    raise exception 'approvable retention policy not found' using errcode = 'P0002';
  end if;

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_workspace_id, actor_id, 'signature_retention_policy.approved',
    'signature_retention_policy', target_policy_id::text,
    jsonb_build_object('name', target_name)
  );
end;
$$;


ALTER FUNCTION "public"."approve_signature_retention_policy_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_policy_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assess_schedule_shift_service"("actor" "uuid", "w" "uuid", "shift" "jsonb", "target_shift_id" "uuid" DEFAULT NULL::"uuid", "target_session_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select public.assess_weekly_schedule_assignment_service(actor,w,shift,target_shift_id,target_session_id);
$$;


ALTER FUNCTION "public"."assess_schedule_shift_service"("actor" "uuid", "w" "uuid", "shift" "jsonb", "target_shift_id" "uuid", "target_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assess_weekly_schedule_assignment_service"("actor" "uuid", "w" "uuid", "shift" "jsonb", "target_shift_id" "uuid" DEFAULT NULL::"uuid", "target_session_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare previous jsonb; normalized jsonb; identified jsonb; a jsonb; current_a jsonb; loc uuid:=(shift->>'location_id')::uuid;
begin
 perform app_private.authorize(actor, w, 'schedule.edit', target_locations => array[loc]);
 if target_session_id is not null then
  if not exists(select 1 from public.schedule_edit_sessions where workspace_id=w and id=target_session_id and holder_user_id=actor and status='active' and expires_at>now()) then
   raise exception 'Edit session not found or expired' using errcode='42501'; end if;
  select to_jsonb(s) into previous from public.schedule_edit_session_shifts s where workspace_id=w and session_id=target_session_id and id=target_shift_id;
  if target_shift_id is not null and previous is null then raise exception 'Shift no longer exists in this edit session' using errcode='P0002'; end if;
 end if;
 if nullif(shift->>'employee_id','') is not null and not exists(select 1 from public.employee_location_assignments where workspace_id=w and employee_id=(shift->>'employee_id')::uuid and location_id=loc and ended_at is null) then
  raise exception 'Employee is not assigned to this location' using errcode='42501'; end if;
 normalized:=(public.normalize_schedule_time_source(w,shift,previous)-'id'-'source_shift_id')
   ||jsonb_build_object('session_id',target_session_id,'_exclude_shift_id',target_shift_id);
 a:=public.assess_weekly_shift_availability(w,(shift->>'employee_id')::uuid,normalized);
 identified:=normalized||jsonb_build_object('id',target_shift_id);
 if target_shift_id is not null and a->>'conflict_severity'<>'block' and public.schedule_availability_prior_publication(w,identified) is not null then
  a:=a||jsonb_build_object('operation','allowed','responsibility_retained',true,
   'reasons',(select coalesce(jsonb_agg(r),'[]') from jsonb_array_elements(a->'reasons') r where r->>'code'='availability'));
 elsif previous is not null and a->>'operation'='warning_requires_override' then
  current_a:=public.assess_weekly_shift_availability(w,(shift->>'employee_id')::uuid,identified);
  if public.schedule_availability_override(w,identified,current_a) is not null then
   a:=a||jsonb_build_object('override_recorded',true);
  end if;
 end if;
 -- The note's hours reach only whoever the core lets read the note (M12).
 if coalesce(jsonb_array_length(a->'manager_intervals'),0)>0
  and app_private.authz_reason(actor,w,'availability.note_read',target_person=>(shift->>'employee_id')::uuid) is not null then
  a:=a||jsonb_build_object('manager_intervals','[]'::jsonb,
   'reasons',(select coalesce(jsonb_agg(r),'[]') from jsonb_array_elements(a->'reasons') r where r->>'code'<>'note'));
 end if;
 return a||jsonb_build_object('can_override',true);
end; $$;


ALTER FUNCTION "public"."assess_weekly_schedule_assignment_service"("actor" "uuid", "w" "uuid", "shift" "jsonb", "target_shift_id" "uuid", "target_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assess_weekly_shift_availability"("w" "uuid", "emp" "uuid", "shift" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare loc uuid:=(shift->>'location_id')::uuid; day date:=coalesce(shift->>'scheduled_date',shift->>'date')::date;
 zone_name text; preference_zone text; basis text:=coalesce(shift->>'time_basis','explicit'); start_clock time; end_clock time;
 local_start timestamp; local_end timestamp; start_at timestamptz; end_at timestamptz; span tstzrange; day_span tstzrange;
 capacity jsonb; remaining tstzmultirange; unavailable tstzmultirange:='{}'; leave_ranges tstzmultirange:='{}';
 leave_evidence jsonb:='[]'; reasons jsonb:='[]'; settings public.workspace_scheduling_settings%rowtype;
 leave_row record; leave_span tstzrange; coverage text; operation text; fingerprint_payload jsonb;
 conflict_severity text; rule_severity text; rule jsonb; annotated jsonb:='[]'; availability_fingerprint text;
 neighbor record; neighbor_span tstzrange; gap_minutes numeric; schedule_week date; schedule_locations uuid[];
 edit_id uuid:=nullif(shift->>'session_id','')::uuid; context_draft_id uuid:=nullif(shift->>'draft_id','')::uuid;
 exclude_id uuid:=coalesce(nullif(shift->>'_exclude_shift_id',''),shift->>'source_shift_id',shift->>'id')::uuid;
 -- BL-092: shifts this person gives up in the same operation (the other side
 -- of a swap) are not theirs any more when this one becomes theirs.
 given_up uuid[]:=array(select value::uuid from jsonb_array_elements_text(
  case when jsonb_typeof(shift->'_exclude_shift_ids')='array' then shift->'_exclude_shift_ids' else '[]'::jsonb end)
  where value is not null);
 missing_time boolean; invalid_clock boolean:=false; ambiguous_clock boolean:=false;
begin
 select l.timezone,coalesce(nullif(shift->>'time_timezone',''),nullif(shift->'time_snapshot'->>'timezone',''),l.timezone)
  into preference_zone,zone_name from public.locations l where l.workspace_id=w and l.id=loc;
 if day is null or not isfinite(day) or zone_name is null or preference_zone is null
  or not app_private.timezone_name_valid(zone_name)
  or not app_private.timezone_name_valid(preference_zone) then
  raise exception 'A valid location, date and timezone are required for availability assessment' using errcode='22023'; end if;
 select * into settings from public.workspace_scheduling_settings where workspace_id=w;
 if settings.workspace_id is null then raise exception 'Scheduling settings unavailable' using errcode='P0002'; end if;
 if basis not in ('explicit','type_default') then
  raise exception 'Unknown shift time source' using errcode='22023'; end if;
 if basis='type_default' then
  start_clock:=nullif(shift->'time_snapshot'->>'start_time','')::time;
  end_clock:=nullif(shift->'time_snapshot'->>'end_time','')::time;
  if (start_clock,end_clock) is distinct from (nullif(shift->>'start_time','')::time,nullif(shift->>'end_time','')::time) then
   raise exception 'Saved reference hours and their snapshot must agree' using errcode='22023'; end if;
 elsif basis='explicit' then
  start_clock:=nullif(shift->>'start_time','')::time; end_clock:=nullif(shift->>'end_time','')::time;
 end if;
 invalid_clock:=start_clock is not null and start_clock=end_clock;
 missing_time:=start_clock is null or end_clock is null or start_clock=end_clock;
 day_span:=tstzrange(day::timestamp at time zone zone_name,(day+1)::timestamp at time zone zone_name,'[)');
 if not missing_time then
  local_start:=day+start_clock;
  local_end:=day+end_clock+case when end_clock<start_clock then interval '1 day' else interval '0' end;
  start_at:=local_start at time zone zone_name; end_at:=local_end at time zone zone_name;
  invalid_clock:=(start_at at time zone zone_name)<>local_start or (end_at at time zone zone_name)<>local_end or end_at<=start_at;
  if not invalid_clock then
   span:=tstzrange(start_at,end_at,'[)');
   ambiguous_clock:=exists(select 1 from (values(start_at,local_start),(end_at,local_end)) endpoint(instant,wall)
    cross join (values(interval '-1 day'),(interval '1 day')) probe(delta)
    cross join lateral (select (endpoint.wall at time zone 'UTC')-make_interval(secs=>public.availability_utc_offset(endpoint.instant+probe.delta,zone_name)) alternate) alt
    where alt.alternate<>endpoint.instant and (alt.alternate at time zone zone_name)=endpoint.wall);
  end if;
 end if;
 -- Assignment snapshots locate the actual instants; recurring rules are always
 -- interpreted in the target location's current local timezone.
 capacity:=case when emp is null then jsonb_build_object('unavailable_intervals','[]'::jsonb,'employee_intervals','[]'::jsonb,'manager_intervals','[]'::jsonb)
  else public.weekly_preference_capacity(w,emp,coalesce(span,day_span),preference_zone) end;
 -- Only the employee's own marks are unavailable hours; the note is not (M12).
 select coalesce(range_agg(tstzrange((x->>'start_at')::timestamptz,(x->>'end_at')::timestamptz,'[)')),'{}') into unavailable
  from jsonb_array_elements(capacity->'employee_intervals') x;
 for leave_row in select seg.id,seg.request_id,req.revision,approved_piece.span
  from public.schedule_time_off_segments seg
  join public.schedule_time_off_requests req on req.id=seg.request_id and req.workspace_id=seg.workspace_id
  cross join lateral unnest(public.time_off_effective_ranges(seg.id)) approved_piece(span)
  where req.workspace_id=w and req.employee_id=emp and req.request_type='time_off'
   and req.status = 'approved' and seg.status='approved'
   and seg.segment_date between day-3 and day+3 order by seg.id,lower(approved_piece.span) loop
  leave_span:=leave_row.span*coalesce(span,day_span);
  if not isempty(leave_span) then
   leave_ranges:=leave_ranges+tstzmultirange(leave_span);
   leave_evidence:=leave_evidence||jsonb_build_array(jsonb_build_object('segment_id',leave_row.id,'request_id',leave_row.request_id,
    'request_revision',leave_row.revision,'intervals',public.availability_ranges_json(tstzmultirange(leave_span))));
  end if;
 end loop;
 remaining:=tstzmultirange(coalesce(span,day_span))-(unavailable+leave_ranges);
 coverage:=case when span is null then 'unknown' when isempty(remaining) then 'none' when remaining @> span then 'full' else 'partial' end;
 if not isempty(leave_ranges) then reasons:=reasons||jsonb_build_array(jsonb_build_object('code','approved_time_off',
  'message','Approved time off overlaps this assignment. Resolve the leave or assignment before assigning.',
  'intervals',public.availability_ranges_json(leave_ranges),'definite',span is not null or leave_ranges @> day_span)); end if;
 -- The employee's own mark is always only a warning (M8); a manager's note is
 -- a reminder shown while writing, nothing more (M12).
 if span is not null and jsonb_array_length(capacity->'employee_intervals')>0 then reasons:=reasons||jsonb_build_array(jsonb_build_object('code','availability',
  'message','The assignment overlaps unavailable hours.','intervals',capacity->'employee_intervals','definite',true)); end if;
 if span is not null and jsonb_array_length(capacity->'manager_intervals')>0 then reasons:=reasons||jsonb_build_array(jsonb_build_object('code','note',
  'message','The assignment overlaps hours a manager noted for this person.','intervals',capacity->'manager_intervals','definite',true)); end if;
 if missing_time then reasons:=reasons||jsonb_build_array(jsonb_build_object('code','time_source_unresolved',
  'message','Confirm shift hours before assigning or publishing.','definite',false)); end if;
 if invalid_clock then reasons:=reasons||jsonb_build_array(jsonb_build_object('code','invalid_local_time',
  'message','These hours do not exist on this date in the selected timezone. Choose valid hours.','definite',true)); end if;
 -- Required schedule references are hard constraints. Availability-only callers
 -- without a job descriptor retain their existing contract.
 if shift ? 'job_id' then
  if not exists(select 1 from public.locations where workspace_id=w and id=loc and archived_at is null)
   or not exists(select 1 from public.jobs where workspace_id=w and id=(shift->>'job_id')::uuid and archived_at is null)
   or (nullif(shift->>'shift_type_id','') is not null and not exists(select 1 from public.shift_types where workspace_id=w and id=(shift->>'shift_type_id')::uuid and archived_at is null)) then
   reasons:=reasons||jsonb_build_array(jsonb_build_object('code','invalid_reference','message','A location, job or shift type is no longer available.','definite',true));
  end if;
  if emp is not null then
   -- Excluded from Schedule keeps a person out of new shifts only (BL-218): a
   -- shift already published with them stays theirs through edits and republishing.
   if not exists(select 1 from public.employee_profiles where workspace_id=w and id=emp and archived_at is null and (start_date is null or start_date<=day)
     and (not is_excluded_from_schedule or exists(select 1 from public.schedule_published_shifts published
       where published.workspace_id=w and published.employee_id=emp
         and published.source_shift_id=coalesce(nullif(shift->>'source_shift_id',''),shift->>'id')::uuid))) then
    reasons:=reasons||jsonb_build_array(jsonb_build_object('code','employee_inactive','message','Employee is not active in Schedule.','definite',true));
   end if;
   if not exists(select 1 from public.employee_location_assignments where workspace_id=w and employee_id=emp and location_id=loc and ended_at is null)
    or not exists(select 1 from public.employee_job_assignments where workspace_id=w and employee_id=emp and job_id=(shift->>'job_id')::uuid and ended_at is null) then
    reasons:=reasons||jsonb_build_array(jsonb_build_object('code','assignment_missing','message','Employee needs an active location and job assignment.','definite',true));
   end if;
  end if;
  if exists(select 1 from public.schedule_closures c where c.workspace_id=w and c.location_id=loc
   and day between c.closed_date and coalesce(c.end_date,c.closed_date)
   and (c.is_all_day or (shift->>'shift_type_id')::uuid=any(c.shift_type_ids))) then
   reasons:=reasons||jsonb_build_array(jsonb_build_object('code','closed_location','message','Location or shift type is closed on this date.','definite',true));
  end if;
 end if;
 -- The edit session replaces its week; a saved draft replaces its week. Other
 -- current publications remain relevant across locations and week boundaries.
 select week_start,location_ids into schedule_week,schedule_locations from public.schedule_edit_sessions where workspace_id=w and id=edit_id;
 if schedule_week is null then select week_start,location_ids into schedule_week,schedule_locations from public.schedule_drafts where workspace_id=w and id=context_draft_id; end if;
 if span is not null and emp is not null and shift ? 'job_id' then
  for neighbor in
   select s.id,s.location_id,s.scheduled_date,s.start_time,s.end_time,s.time_basis,coalesce(s.time_timezone,l.timezone) zone
    from public.schedule_edit_session_shifts s join public.locations l on l.id=s.location_id and l.workspace_id=w
    where s.workspace_id=w and s.session_id=edit_id and s.employee_id=emp and s.pending_op_type is distinct from 'delete'
     and s.id is distinct from exclude_id and not s.id=any(given_up) and s.scheduled_date between day-2 and day+2
     and (not (shift ? '_publish_locations') or (s.location_id in (select value::uuid from jsonb_array_elements_text(shift->'_publish_locations'))
      and public.schedule_shift_in_department_scope_service(s.job_id,
       case when jsonb_typeof(shift->'_publish_departments')='array' then array(select value::uuid from jsonb_array_elements_text(shift->'_publish_departments')) end,
       coalesce((shift->>'_publish_no_department')::boolean,true))))
   union all
   select s.id,s.location_id,s.scheduled_date,s.start_time,s.end_time,s.time_basis,coalesce(s.time_timezone,l.timezone)
    from public.schedule_draft_shifts s join public.locations l on l.id=s.location_id and l.workspace_id=w
    where edit_id is null and s.workspace_id=w and s.draft_id=context_draft_id and s.employee_id=emp
     and s.id is distinct from exclude_id and not s.id=any(given_up) and s.scheduled_date between day-2 and day+2
     and (not (shift ? '_publish_locations') or (s.location_id in (select value::uuid from jsonb_array_elements_text(shift->'_publish_locations'))
      and public.schedule_shift_in_department_scope_service(s.job_id,
       case when jsonb_typeof(shift->'_publish_departments')='array' then array(select value::uuid from jsonb_array_elements_text(shift->'_publish_departments')) end,
       coalesce((shift->>'_publish_no_department')::boolean,true))))
   union all
   select s.id,s.location_id,s.scheduled_date,s.start_time,s.end_time,s.time_basis,coalesce(s.time_timezone,l.timezone)
    from public.schedule_published_shifts s join public.schedule_location_publications p on p.id=s.publication_id and p.status='current'
    join public.locations l on l.id=s.location_id and l.workspace_id=w
    where s.workspace_id=w and s.employee_id=emp and (shift ? '_publish_locations' or (s.id is distinct from exclude_id and s.source_shift_id is distinct from exclude_id
     and not s.id=any(given_up) and not coalesce(s.source_shift_id,s.id)=any(given_up)))
     and s.scheduled_date between day-2 and day+2
     and (schedule_week is null or s.scheduled_date not between schedule_week and schedule_week+6
      or not s.location_id = any(coalesce(schedule_locations, '{}'))
      or (shift ? '_publish_locations' and not (s.location_id in (select value::uuid from jsonb_array_elements_text(shift->'_publish_locations'))
       and public.schedule_shift_in_department_scope_service(s.job_id,
        case when jsonb_typeof(shift->'_publish_departments')='array' then array(select value::uuid from jsonb_array_elements_text(shift->'_publish_departments')) end,
        coalesce((shift->>'_publish_no_department')::boolean,true)))))
   order by 1
  loop
   neighbor_span:=app_private.shift_time_range(neighbor.scheduled_date,neighbor.start_time,neighbor.end_time,neighbor.zone);
   if span && neighbor_span then
    reasons:=reasons||jsonb_build_array(jsonb_build_object('code','time_overlap','message','Employee already has an overlapping shift.','definite',true,
     'intervals',public.availability_ranges_json(tstzmultirange(span*neighbor_span))));
   else
    gap_minutes:=extract(epoch from greatest(lower(span)-upper(neighbor_span),lower(neighbor_span)-upper(span)))/60;
    if neighbor.location_id<>loc and gap_minutes<settings.minimum_travel_minutes then
     reasons:=reasons||jsonb_build_array(jsonb_build_object('code','minimum_travel','message','There is not enough travel time between locations.','definite',true));
    end if;
    if gap_minutes<settings.minimum_rest_minutes then
     reasons:=reasons||jsonb_build_array(jsonb_build_object('code','minimum_rest','message','There is not enough rest time between shifts.','definite',true));
    end if;
   end if;
  end loop;
 end if;
 reasons:=reasons||app_private.document_shift_reasons(w,emp,day,coalesce(start_at,lower(day_span))); conflict_severity:='allow';
 for rule in select value from jsonb_array_elements(reasons) loop
  rule_severity:=case rule->>'code'
   when 'availability' then 'warn'
   when 'note' then 'warn'
   when 'approved_time_off' then settings.conflict_rules->>'approved_time_off'
   -- K17: "confirm once" asks like "confirm"; its answer holds for the editing session.
   when 'closed_location' then case settings.conflict_rules->>'closed_location' when 'confirm_once' then 'confirm' else settings.conflict_rules->>'closed_location' end
   when 'minimum_travel' then settings.conflict_rules->>'minimum_travel'
   when 'minimum_rest' then settings.conflict_rules->>'minimum_rest' when 'document_required' then settings.conflict_rules->>'document_required' when 'document_conditional_grace' then settings.conflict_rules->>'document_conditional_grace' when 'document_conditional_overdue' then settings.conflict_rules->>'document_conditional_overdue'
   when 'time_source_unresolved' then 'confirm'
   else 'block' end;
  if rule->>'code' not in ('availability','note') and array_position(array['allow','warn','confirm','block'],rule_severity)>array_position(array['allow','warn','confirm','block'],conflict_severity) then conflict_severity:=rule_severity; end if;
  if rule_severity<>'allow' then annotated:=annotated||jsonb_build_array(rule||jsonb_build_object('severity',rule_severity)
   ||case when rule->>'code'='closed_location' and settings.conflict_rules->>'closed_location'='confirm_once'
    then jsonb_build_object('confirm_scope','edit_session') else '{}'::jsonb end); end if;
 end loop;
 reasons:=annotated;
 operation:=case conflict_severity when 'block' then 'blocked' when 'allow' then 'allowed' else 'warning_requires_override' end;
 -- Revision counters, manager notes and unrelated weekdays/settings are not
 -- conflict identity. The adapters use warning_policy to decide warn/confirm.
 -- Availability is not a conflict: it has its own fingerprint below, which
 -- changes with the person, the shift, its hours or the overlapping marks.
 if span is not null and not isempty(unavailable) then
  availability_fingerprint:=encode(extensions.digest(convert_to(jsonb_build_object('workspace_id',w,'employee_id',emp,
   'assignment',coalesce(shift->>'source_shift_id',shift->>'id'),'location_id',loc,'date',day,
   'intervals',public.availability_ranges_json(tstzmultirange(span)),
   'employee_intervals',capacity->'employee_intervals')::text,'UTF8'),'sha256'),'hex');
 end if;
 fingerprint_payload:=jsonb_build_object('workspace_id',w,'employee_id',emp,
  'assignment',jsonb_build_object('id',coalesce(shift->>'source_shift_id',shift->>'id'),'location_id',loc,'date',day),
  'intervals',public.availability_ranges_json(case when span is null then '{}'::tstzmultirange else tstzmultirange(span) end),
  'leave',public.availability_ranges_json(leave_ranges),
  'warning_policy',case when conflict_severity='confirm' then 'confirm' else 'warn' end,'operation',operation,
  'conflict_rules',settings.conflict_rules,'minimum_travel_minutes',settings.minimum_travel_minutes,'minimum_rest_minutes',settings.minimum_rest_minutes,
  'reasons',(select coalesce(jsonb_agg(r),'[]') from jsonb_array_elements(reasons) r where r->>'code' not in ('availability','note')));
 return jsonb_build_object('coverage',coverage,'operation',operation,'time_basis',basis,'timezone',zone_name,'preference_timezone',preference_zone,
  'assessment_scope',case when span is null then 'calendar_day' else 'shift_interval' end,
  'intervals',public.availability_ranges_json(case when span is null then '{}'::tstzmultirange else tstzmultirange(span) end),
  'available_intervals',case when span is null then '[]'::jsonb else public.availability_ranges_json(remaining) end,
  'unavailable_intervals',public.availability_ranges_json(unavailable+leave_ranges),
  'unknown_intervals',case when span is null then public.availability_ranges_json(tstzmultirange(day_span)) else '[]'::jsonb end,
  'employee_intervals',capacity->'employee_intervals','manager_intervals',capacity->'manager_intervals',
  'has_availability_conflict',span is not null and not isempty(unavailable),'availability_fingerprint',availability_fingerprint,'conflict_severity',conflict_severity,
  'warning_policy',case when conflict_severity='confirm' then 'confirm' else 'warn' end,
  'leave',leave_evidence,'reasons',reasons,
  'policy_revision',settings.availability_preferences_revision,
  'fold_resolution',case when ambiguous_clock then 'post_transition_offset' else null end,
  'assessment_minutes',case when span is null then null else extract(epoch from upper(span)-lower(span))/60 end,
  'fingerprint',encode(extensions.digest(convert_to(fingerprint_payload::text,'UTF8'),'sha256'),'hex'));
end; $$;


ALTER FUNCTION "public"."assess_weekly_shift_availability"("w" "uuid", "emp" "uuid", "shift" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_organization_setting_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  row_id uuid := case when tg_op = 'DELETE' then old.id else new.id end;
  tenant_id uuid := case when tg_op = 'DELETE' then old.workspace_id else new.workspace_id end;
  archived boolean := case
    when tg_table_name = 'workspaces' then false
    else (case when tg_op = 'DELETE' then old.archived_at else new.archived_at end) is not null
  end;
  action_name text;
begin
  if actor_id is null then return case when tg_op = 'DELETE' then old else new end; end if;

  action_name := case
    when tg_table_name = 'workspaces' then 'workspace.identity_updated'
    when tg_op = 'INSERT' then left(tg_table_name, -1) || '.created'
    when archived then left(tg_table_name, -1) || '.archived'
    else left(tg_table_name, -1) || '.updated'
  end;

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id
  ) values (
    tenant_id, actor_id, action_name, left(tg_table_name, -1), row_id::text
  );

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."audit_organization_setting_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_workspace_identity_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if old.name is distinct from new.name and (select auth.uid()) is not null then
    insert into public.audit_events (
      workspace_id, actor_user_id, action, target_type, target_id
    ) values (
      new.id, (select auth.uid()), 'workspace.identity_updated', 'workspace', new.id::text
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."audit_workspace_identity_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."autosave_schedule_edit_session_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  edit public.schedule_edit_sessions%rowtype;
  saved_draft_id uuid;
begin
  -- "Keep editing?" ran out (KARARLAR Schedule "Hareketsizlik"): the unsaved
  -- work goes to an Auto-save draft and the lock is let go.
  perform public.availability_lock_workspace(target_workspace_id);
  select * into edit from public.schedule_edit_sessions session
  where session.id = target_session_id and session.workspace_id = target_workspace_id
    and session.holder_user_id = actor_user_id and session.status = 'active'
  for update;
  if edit.id is null then
    raise exception 'edit session not found' using errcode = 'P0002';
  end if;
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit', target_locations => edit.location_ids);
  saved_draft_id := app_private.close_schedule_edit_session(edit);
  return jsonb_build_object(
    'status', case when saved_draft_id is null then 'nothing_to_save' else 'saved' end,
    'draft_id', saved_draft_id,
    'draft_name', (select draft.name from public.schedule_drafts draft where draft.id = saved_draft_id));
end;
$$;


ALTER FUNCTION "public"."autosave_schedule_edit_session_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."availability_calendar_mask"("target_span" "tstzrange", "zone_name" "text", "starts" "date", "ends" "date") RETURNS "tstzmultirange"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
 select coalesce(range_agg(s.utc_span*r.calendar_span),'{}'::tstzmultirange)
 from public.availability_offset_segments(target_span,zone_name) s cross join lateral (
  select tstzrange((starts::timestamp at time zone 'UTC')-make_interval(secs=>s.offset_seconds),
   case when ends is null then null else ((ends+1)::timestamp at time zone 'UTC')-make_interval(secs=>s.offset_seconds) end,'[)') calendar_span
 ) r where s.utc_span && r.calendar_span;
$$;


ALTER FUNCTION "public"."availability_calendar_mask"("target_span" "tstzrange", "zone_name" "text", "starts" "date", "ends" "date") OWNER TO "postgres";


