CREATE OR REPLACE FUNCTION "public"."block_closure_when_ownership_transfer_pending"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  blocking_transfer uuid;
begin
  if new.status in ('scheduled', 'completed') then
    select transfer.id into blocking_transfer
    from public.workspace_ownership_transfers transfer
    where transfer.workspace_id = new.workspace_id
      and transfer.status = 'pending'
    order by transfer.created_at
    limit 1;

    if blocking_transfer is not null then
      -- The screen can offer to cancel that one rather than describe where to
      -- find it.
      raise exception 'pending ownership transfer must be resolved before workspace closure'
        using errcode = '23514',
              hint = 'workspace.closure.transfer_pending',
              detail = blocking_transfer::text;
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."block_closure_when_ownership_transfer_pending"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."block_entitlement_billing_owner_when_ownership_transfer_pending"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if current_setting('app.owner_transfer', true) = 'on' then
    return new;
  end if;

  if exists (
    select 1
    from public.workspace_ownership_transfers transfer
    where transfer.workspace_id = new.workspace_id
      and transfer.status = 'pending'
  ) then
    raise exception 'pending ownership transfer must be resolved before billing owner changes'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."block_entitlement_billing_owner_when_ownership_transfer_pending"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."block_membership_change_when_ownership_transfer_pending"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  protected_membership_id uuid := case when tg_op = 'DELETE' then old.id else new.id end;
  protected_workspace_id uuid := case when tg_op = 'DELETE' then old.workspace_id else new.workspace_id end;
begin
  if coalesce(current_setting('app.owner_transfer', true), '') = 'on' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if exists (
    select 1
    from public.workspace_ownership_transfers transfer
    where transfer.workspace_id = protected_workspace_id
      and transfer.status = 'pending'
      and protected_membership_id in (
        transfer.previous_owner_membership_id,
        transfer.target_membership_id
      )
  ) then
    raise exception 'pending ownership transfer must be resolved before membership changes'
      using errcode = '23514';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."block_membership_change_when_ownership_transfer_pending"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_delete_schedule_edit_shifts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_shift_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_session public.schedule_edit_sessions%rowtype;
  requested_count integer;
  matched_count integer;
  changed_count integer;
  edit_scope uuid[] := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.edit');
begin
 perform public.availability_lock_workspace(target_workspace_id);
  select count(distinct id) into requested_count
  from unnest(coalesce(target_shift_ids, array[]::uuid[])) as input(id);
  if requested_count < 1 or requested_count > 100 then
    raise exception 'valid shift ids required' using errcode = '22023';
  end if;

  select session.* into target_session
  from public.schedule_edit_sessions session
  where session.workspace_id = target_workspace_id
    and session.holder_user_id = actor_user_id
    and session.status = 'active'
    and session.expires_at > now()
    and exists (
      select 1
      from public.schedule_edit_session_shifts shift
      where shift.session_id = session.id
        and shift.id = any(target_shift_ids)
    )
  order by session.last_heartbeat desc
  limit 1
  for update;

  if target_session.id is null then
    raise exception 'edit session not found' using errcode = 'P0002';
  end if;

  select count(distinct shift.id) into matched_count
  from public.schedule_edit_session_shifts shift
  where shift.session_id = target_session.id
    and shift.id = any(target_shift_ids)
    and shift.location_id = any (edit_scope);

  if matched_count <> requested_count then
    raise exception 'shift revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
  end if;

  update public.schedule_availability_overrides set revoked_at=now() where workspace_id=target_workspace_id and shift_id=any(target_shift_ids) and revoked_at is null;
   with draft_deletes as (
    delete from public.schedule_edit_session_shifts shift
    where shift.session_id = target_session.id
      and shift.id = any(target_shift_ids)
      and shift.source_published_shift_id is null
      and not shift.locked
    returning shift.id
  ), live_marks as (
    update public.schedule_edit_session_shifts shift
    set pending_op_type = 'delete',
        locked = true,
        revision = revision + 1,
        updated_at = now()
    where shift.session_id = target_session.id
      and shift.id = any(target_shift_ids)
      and (shift.source_published_shift_id is not null or shift.locked)
      and shift.pending_op_type is distinct from 'delete'
    returning shift.id
  )
  select count(*) into changed_count
  from (
    select id from draft_deletes
    union all
    select id from live_marks
  ) changed;

  update public.schedule_edit_sessions
  set revision = revision + 1,
      dirty = true,
      last_heartbeat = now(),
      expires_at = now() + interval '4 minutes'
  where id = target_session.id;

  return jsonb_build_object(
    'deleted_count', changed_count,
    'session', public.get_schedule_edit_session_service(
      actor_user_id,
      target_workspace_id,
      target_session.id
    )
  );
end;
$$;


ALTER FUNCTION "public"."bulk_delete_schedule_edit_shifts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_shift_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bump_document_type_expiry_policy_version"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if row(
    new.title,
    new.required_at_onboarding,
    new.tracks_expiry,
    new.expiry_warning_days,
    new.expiry_schedule_impact,
    new.archived_at
  ) is distinct from row(
    old.title,
    old.required_at_onboarding,
    old.tracks_expiry,
    old.expiry_warning_days,
    old.expiry_schedule_impact,
    old.archived_at
  ) then
    new.expiry_policy_version := old.expiry_policy_version + 1;
  end if;

  return new;
end;
$$;


