CREATE OR REPLACE FUNCTION "public"."cancel_account_email_change_service"("actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  pending_email text;
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;

  select nullif(email_change,'') into pending_email from auth.users where id=actor_user_id for update;
  if not found then raise exception 'account not found' using errcode='P0002'; end if;
  if pending_email is null then return jsonb_build_object('status','cancelled'); end if;

  update auth.users auth_user
  set email_change = '',
      email_change_token_current = '',
      email_change_token_new = '',
      email_change_sent_at = null,
      email_change_confirm_status = 0,
      updated_at = now()
  where auth_user.id = actor_user_id
;

  if not found then
    raise exception 'account not found' using errcode = 'P0002';
  end if;

  delete from auth.one_time_tokens token
  where token.user_id = actor_user_id
    and token.token_type in (
      'email_change_token_current'::auth.one_time_token_type,
      'email_change_token_new'::auth.one_time_token_type
    );

  perform app_private.record_security_audit_event_service(
    actor_user_id, null, 'account.email_change_cancelled', 'account.security',
    'auth_user', actor_user_id::text, '{}'::jsonb
  );

  return jsonb_build_object('status', 'cancelled');
end;
$$;


ALTER FUNCTION "public"."cancel_account_email_change_service"("actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_workspace_closure_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  workspace_row public.workspaces%rowtype;
  actor_role public.workspace_role;
  request_id uuid;
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501', hint = 'actor.required';
  end if;
  perform set_config('request.jwt.claim.sub', actor_user_id::text, true);

  select * into workspace_row
  from public.workspaces
  where id = target_workspace_id
  for update;

  if workspace_row.id is null or workspace_row.lifecycle_status = 'deleted' then
    raise exception 'workspace not found' using errcode = '02000', hint = 'workspace.not_found';
  end if;

  select coalesce(role.access_class, membership.role) into actor_role
  from public.workspace_memberships membership
  left join public.workspace_roles role
    on role.id = membership.role_id
   and role.workspace_id = membership.workspace_id
  where membership.workspace_id = target_workspace_id
    and membership.user_id = actor_user_id
    and membership.status = 'active'
  limit 1;

  if actor_role is distinct from 'owner'::public.workspace_role then
    raise exception 'workspace owner access required' using errcode = '42501', hint = 'workspace.owner_required';
  end if;

  if workspace_row.lifecycle_status <> 'closure_scheduled' then
    raise exception 'workspace closure is not scheduled' using errcode = '23514', hint = 'workspace.closure.not_scheduled';
  end if;

  update public.workspace_closure_requests
  set status = 'cancelled',
      cancelled_at = now(),
      cancelled_by = actor_user_id,
      updated_at = now()
  where workspace_id = target_workspace_id
    and status = 'scheduled'
  returning id into request_id;

  update public.workspaces
  set lifecycle_status = 'active',
      closure_scheduled_at = null,
      closure_effective_at = null,
      closed_at = null,
      closed_by = null,
      updated_at = now()
  where id = target_workspace_id;

  insert into public.audit_events (
    workspace_id,
    actor_user_id,
    action,
    target_type,
    target_id,
    metadata
  )
  values (
    target_workspace_id,
    actor_user_id,
    'workspace.closure.cancelled',
    'workspace',
    target_workspace_id::text,
    jsonb_build_object('closure_request_id', request_id)
  );

  return jsonb_build_object(
    'status', 'cancelled',
    'workspace_id', target_workspace_id,
    'closure_request_id', request_id
  );
end;
$$;


ALTER FUNCTION "public"."cancel_workspace_closure_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_workspace_entitlement_on_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.lifecycle_status = 'deleted'::public.workspace_lifecycle_status
     and old.lifecycle_status is distinct from new.lifecycle_status then
    update public.workspace_entitlements
    set status = 'cancelled'::public.workspace_entitlement_status,
        cancelled_at = coalesce(cancelled_at, now()),
        cancellation_reason = coalesce(cancellation_reason, 'workspace_closed_immediate'),
        updated_at = now()
    where workspace_id = new.id
      and status <> 'cancelled'::public.workspace_entitlement_status;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."cancel_workspace_entitlement_on_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_workspace_ownership_transfer_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "transfer_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare transfer_row public.workspace_ownership_transfers%rowtype;
begin
  -- Same workspace -> transfer lock order as initiate/accept, to serialize races.
  perform 1 from public.workspaces where id = target_workspace_id for update;
  if actor_user_id is null or not exists (
    select 1 from public.workspace_memberships m
    left join public.workspace_roles r on r.id = m.role_id and r.workspace_id = m.workspace_id
    where m.workspace_id = target_workspace_id and m.user_id = actor_user_id
      and m.status = 'active' and coalesce(r.access_class, m.role) = 'owner'
  ) then raise exception 'workspace owner access required' using errcode = '42501', hint = 'workspace.owner_required'; end if;
  select * into transfer_row from public.workspace_ownership_transfers t
    where t.id = transfer_id and t.workspace_id = target_workspace_id for update;
  if transfer_row.id is null or transfer_row.status <> 'pending' then
    raise exception 'pending ownership transfer not found' using errcode = '02000', hint = 'transfer.not_found';
  end if;
  if transfer_row.initiated_by <> actor_user_id then
    raise exception 'ownership transfer initiator access required' using errcode = '42501', hint = 'transfer.initiator_required';
  end if;
  update public.workspace_ownership_transfers set status = 'cancelled', cancelled_at = now(),
    cancelled_by = actor_user_id, updated_at = now() where id = transfer_row.id;
  insert into public.audit_events(workspace_id, actor_user_id, action, target_type, target_id)
    values(target_workspace_id, actor_user_id, 'workspace.ownership_transfer.cancelled', 'workspace_ownership_transfer', transfer_row.id::text);
  return jsonb_build_object('status', 'cancelled', 'transfer_id', transfer_row.id, 'workspace_id', target_workspace_id);
end; $$;


ALTER FUNCTION "public"."cancel_workspace_ownership_transfer_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_weekly_preference_type_defaults"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare row_value public.shift_types%rowtype;
begin
 if tg_op='DELETE' then
  if old.archived_at is not null or old.deleted_at is not null then return old; end if;
  row_value:=old;
 elsif new.archived_at is null and new.deleted_at is null then row_value:=new;
 elsif tg_op='UPDATE' and old.archived_at is null and old.deleted_at is null then row_value:=old;
 else return new; end if;
 if row_value.default_start_time is not null and row_value.default_end_time is not null and row_value.default_start_time<>row_value.default_end_time then
  insert into public.weekly_preference_type_defaults(workspace_id,shift_type_id,name,start_time,end_time)
   values(row_value.workspace_id,row_value.id,row_value.name,row_value.default_start_time,row_value.default_end_time)
   on conflict(workspace_id,shift_type_id) do update set name=excluded.name,start_time=excluded.start_time,end_time=excluded.end_time;
 end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end; $$;


ALTER FUNCTION "public"."capture_weekly_preference_type_defaults"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_schedule_time_source"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare normalized jsonb;
begin
  new.time_basis:=coalesce(new.time_basis,'explicit');
  normalized:=public.normalize_schedule_time_source(new.workspace_id,to_jsonb(new),case when tg_op='UPDATE' then to_jsonb(old) else null end,true);
  if (new.start_time,new.end_time) is distinct from
    (nullif(normalized->>'start_time','')::time,nullif(normalized->>'end_time','')::time) then
    raise exception 'The shift interval does not match its saved time source' using errcode='23514';
  end if;
  new.time_snapshot:=normalized->'time_snapshot'; new.time_timezone:=normalized->>'time_timezone';
  return new;
end; $$;


ALTER FUNCTION "public"."check_schedule_time_source"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_account_deletion_work_service"("target_batch_size" integer DEFAULT 20) RETURNS TABLE("request_id" "uuid", "user_id" "uuid", "email" "text", "restore_until" timestamp with time zone, "action" "text", "lease_id" "uuid")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with candidates as (
    select request.id,
      case when request.restore_until <= now() then 'finalize'
        when request.restore_until <= now() + interval '24 hours' and request.reminder_24h_sent_at is null then 'last_24h'
        else 'day_7' end as action
    from public.account_deletion_requests request
    where request.status = 'pending'
      and (request.work_lease_until is null or request.work_lease_until <= now())
      and (request.restore_until <= now()
        or (request.restore_until <= now() + interval '24 hours' and request.reminder_24h_sent_at is null)
        or (request.restore_until > now() + interval '24 hours'
          and request.requested_at <= now() - interval '7 days' and request.reminder_7d_sent_at is null))
    order by request.restore_until, request.id
    limit greatest(1, least(coalesce(target_batch_size, 20), 100))
    for update skip locked
  ), claimed as (
    update public.account_deletion_requests request
    set work_lease_id = gen_random_uuid(), work_lease_until = now() + interval '10 minutes'
    from candidates where request.id = candidates.id
    returning request.*, candidates.action
  )
  select claimed.id, claimed.user_id, lower(btrim(auth_user.email)), claimed.restore_until,
    claimed.action, claimed.work_lease_id
  from claimed join auth.users auth_user on auth_user.id = claimed.user_id;
$$;


ALTER FUNCTION "public"."claim_account_deletion_work_service"("target_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_account_recovery_resend_service"("address_digest" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
begin
  if address_digest !~ '^[a-f0-9]{64}$' then
    raise exception 'valid digest required' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('recovery_resend:' || address_digest, 0));
  delete from app_private.account_throttle_events e where e.at < now() - interval '1 day';
  if (select count(*) from app_private.account_throttle_events e
      where e.kind = 'recovery_resend_address' and e.key_digest = address_digest
        and e.at > now() - interval '1 hour') >= 10 then
    return false;
  end if;
  insert into app_private.account_throttle_events (kind, key_digest)
  values ('recovery_resend_address', address_digest);
  return true;
end;
$_$;


ALTER FUNCTION "public"."claim_account_recovery_resend_service"("address_digest" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_password_reset_send_service"("email_digest" "text", "address_digest" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
begin
  if email_digest !~ '^[a-f0-9]{64}$' or address_digest !~ '^[a-f0-9]{64}$' then
    raise exception 'valid digests required' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('password_reset:' || email_digest, 0));
  delete from app_private.account_throttle_events e where e.at < now() - interval '1 day';

  if (select count(*) from app_private.account_throttle_events e
      where e.kind = 'password_reset_address' and e.key_digest = address_digest
        and e.at > now() - interval '1 hour') >= 10 then
    return 'address_limited';
  end if;
  insert into app_private.account_throttle_events (kind, key_digest)
  values ('password_reset_address', address_digest);

  if exists (select 1 from app_private.account_throttle_events e
      where e.kind = 'password_reset_email' and e.key_digest = email_digest
        and e.at > now() - interval '15 minutes') then
    return 'quiet';
  end if;
  insert into app_private.account_throttle_events (kind, key_digest)
  values ('password_reset_email', email_digest);
  return 'send';
end;
$_$;


ALTER FUNCTION "public"."claim_password_reset_send_service"("email_digest" "text", "address_digest" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_account_deletion_work_service"("target_request_id" "uuid", "target_lease_id" "uuid", "delivery_kind" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform 1 from public.account_deletion_requests where id = target_request_id
    and work_lease_id = target_lease_id and work_lease_until > now() for update;
  if not found then raise exception 'account deletion lease unavailable'; end if;
  if delivery_kind != 'finalize' then
    perform public.mark_account_deletion_email_sent_service(target_request_id, delivery_kind);
  end if;
  update public.account_deletion_requests set work_lease_id = null, work_lease_until = null
  where id = target_request_id and work_lease_id = target_lease_id;
end;
$$;


ALTER FUNCTION "public"."complete_account_deletion_work_service"("target_request_id" "uuid", "target_lease_id" "uuid", "delivery_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."count_account_attention_service"("actor_user_id" "uuid") RETURNS TABLE("documents" integer, "workspaces" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    (
      -- Every document still theirs to act on. The states left out are the ones
      -- where acting is not possible: finished, with a reviewer, or closed.
      select count(*)
      from public.employee_onboarding_requirements requirement
      join public.employee_profiles employee
        on employee.id = requirement.employee_id
      join public.workspaces workspace
        on workspace.id = requirement.workspace_id
      where employee.user_id = actor_user_id
        and employee.archived_at is null
        and requirement.kind in ('document', 'acknowledgement')
        and requirement.lifecycle_retired_at is null
        and workspace.lifecycle_status <> 'deleted'
        and app_private.document_obligation_state(requirement, now()) not in (
          'completed', 'pending_review', 'exempt', 'removed', 'paused'
        )
    )::integer,
    (
      -- Somebody asked and is waiting: an invitation addressed to this account,
      -- or an ownership transfer sent to it.
      (
        select count(*)
        from public.employee_invitations invitation
        join auth.users account on account.id = actor_user_id
        where invitation.status = 'pending'
          and invitation.expires_at > now()
          and lower(invitation.email) = lower(account.email)
          and account.email_confirmed_at is not null
      )
      + (
        select count(*)
        from public.workspace_ownership_transfers transfer
        where transfer.status = 'pending'
          and transfer.expires_at > now()
          and transfer.target_user_id = actor_user_id
      )
    )::integer;
$$;


ALTER FUNCTION "public"."count_account_attention_service"("actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_department_jobs_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_department_id" "uuid", "jobs_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare dep public.departments; item jsonb; job public.jobs; result jsonb:='[]';
begin
  if actor_user_id is null then raise exception 'valid actor required' using errcode='42501'; end if;
  perform set_config('request.jwt.claim.sub',actor_user_id::text,true);
  if not public.workspace_has_permission(target_workspace_id, 'settings.jobs.manage') then
    raise exception 'workspace management access required' using errcode='42501'; end if;
  if jsonb_typeof(jobs_input) is distinct from 'array' then
    raise exception 'Jobs must be an array' using errcode='22023'; end if;
  if jsonb_array_length(jobs_input) not between 1 and 500 then
    raise exception 'Provide between 1 and 500 jobs' using errcode='22023'; end if;
  perform 1 from public.workspaces where id=target_workspace_id for update;
  select * into dep from public.departments where id=target_department_id and workspace_id=target_workspace_id for update;
  if not found then raise exception 'Department not found' using errcode='P0002'; end if;
  if dep.archived_at is not null then raise exception 'Restore the department before adding jobs' using errcode='22023'; end if;
  for item in select value from jsonb_array_elements(jobs_input) loop
    if jsonb_typeof(item) is distinct from 'object'
      or jsonb_typeof(item->'name') is distinct from 'string'
      or jsonb_typeof(item->'color') is distinct from 'string' then
      raise exception 'Valid job name and color required' using errcode='22023'; end if;
    insert into public.jobs(workspace_id,department_id,name,color)
      values(target_workspace_id,dep.id,btrim(item->>'name'),item->>'color') returning * into job;
    result:=result||jsonb_build_array(to_jsonb(job));
  end loop;
  return result;
exception when unique_violation then
  raise exception 'A job with that name already exists. Names must be unique in this organization.' using errcode='23505';
end; $$;


ALTER FUNCTION "public"."create_department_jobs_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_department_id" "uuid", "jobs_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_department_with_jobs_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "department_input" "jsonb", "jobs_input" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare dep public.departments; item jsonb; result_jobs jsonb;
begin
  if actor_user_id is null then raise exception 'valid actor required' using errcode='42501'; end if;
  perform set_config('request.jwt.claim.sub', actor_user_id::text, true);
  if not public.workspace_has_permission(target_workspace_id, 'settings.jobs.manage') then
    raise exception 'workspace management access required' using errcode='42501';
  end if;
  if jsonb_typeof(department_input) is distinct from 'object'
    or jsonb_typeof(department_input->'name') is distinct from 'string'
    or jsonb_typeof(department_input->'color') is distinct from 'string'
    or jsonb_typeof(jobs_input) is distinct from 'array' then
    raise exception 'Valid department and jobs required' using errcode='22023';
  end if;
  if jsonb_array_length(jobs_input)>500 then raise exception 'Too many jobs' using errcode='22023'; end if;
  -- Serialize organization creation order without modifying existing definitions.
  perform 1 from public.workspaces where id=target_workspace_id for update;
  insert into public.departments(workspace_id,name,color)
  values(target_workspace_id,btrim(department_input->>'name'),department_input->>'color')
  returning * into dep;
  for item in select value from jsonb_array_elements(jobs_input) loop
    if jsonb_typeof(item) is distinct from 'object'
      or jsonb_typeof(item->'name') is distinct from 'string'
      or jsonb_typeof(item->'color') is distinct from 'string' then
      raise exception 'Valid job name and color required' using errcode='22023';
    end if;
    insert into public.jobs(workspace_id,department_id,name,color)
    values(target_workspace_id,dep.id,btrim(item->>'name'),item->>'color');
  end loop;
  select coalesce(jsonb_agg(to_jsonb(j) order by lower(j.name),j.id),'[]') into result_jobs
  from public.jobs j where j.workspace_id=target_workspace_id and j.department_id=dep.id;
  return jsonb_build_object('department',to_jsonb(dep),'jobs',result_jobs);
exception when unique_violation then
  raise exception 'A department or job with that name already exists. Names must be unique in this organization.' using errcode='23505';
end; $$;


ALTER FUNCTION "public"."create_department_with_jobs_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "department_input" "jsonb", "jobs_input" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_employee_command_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "command_id" "uuid", "employee_input" "jsonb", "invite_role_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  stored public.employee_create_commands%rowtype;
  invite public.employee_invitations%rowtype;
  fingerprint text;
  saved_id uuid;
  prepared_id uuid;
  secret_token text;
begin
  -- Asked where the record will work, retries included: a manager only where
  -- they manage, never nowhere.
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.create',
    array(select jsonb_array_elements_text(coalesce(employee_input -> 'location_ids', '[]'::jsonb)))::uuid[]);
  if command_id is null then
    raise exception 'command id required' using errcode = '22023';
  end if;
  fingerprint := encode(extensions.digest(jsonb_build_object('employee', employee_input, 'role', invite_role_id)::text, 'sha256'), 'hex');
  -- Serializes retries before creating anything, including concurrent requests.
  perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text || actor_user_id::text || command_id::text, 0));
  select * into stored from public.employee_create_commands c
    where c.workspace_id = target_workspace_id and c.actor_user_id = create_employee_command_service.actor_user_id
      and c.command_id = create_employee_command_service.command_id;
  if found then
    if stored.input_hash <> fingerprint then
      raise exception 'idempotency key belongs to different employee details' using errcode = 'PT409';
    end if;
    -- A retry hands the token out again: only while the role is still theirs to give.
    if invite_role_id is not null
      and not app_private.can_invite_with_role(actor_user_id, target_workspace_id, invite_role_id) then
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.rank', detail = 'employee.invite';
    end if;
  else
    if coalesce(employee_input->>'invitation_email', '') <> ''
      and (employee_input->>'invitation_email') !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
      raise exception 'valid invitation email required' using errcode = '22023';
    end if;
    saved_id := public.save_employee_service(
      actor_user_id, target_workspace_id, null,
      employee_input->>'first_name',
      coalesce(employee_input->>'middle_name', ''),
      employee_input->>'last_name', '',
      employee_input->>'invitation_email', nullif(employee_input->>'start_date', '')::date,
      employee_input->>'internal_note',
      array(select jsonb_array_elements_text(employee_input->'location_ids'))::uuid[],
      (employee_input->>'primary_location_id')::uuid,
      array(select jsonb_array_elements_text(employee_input->'job_ids'))::uuid[],
      (employee_input->>'primary_job_id')::uuid,
      coalesce((employee_input->>'is_remote')::boolean, false),
      coalesce((employee_input->>'is_excluded_from_schedule')::boolean, false), null
    );
    if invite_role_id is not null then
      secret_token := encode(extensions.gen_random_bytes(32), 'hex');
      prepared_id := public.prepare_employee_invitation_service(
        actor_user_id, target_workspace_id, saved_id, lower(btrim(employee_input->>'invitation_email')),
        invite_role_id, encode(extensions.digest(secret_token, 'sha256'), 'hex'), now() + interval '7 days'
      );
    end if;
    insert into public.employee_create_commands
      (workspace_id, actor_user_id, command_id, input_hash, employee_id, invitation_id, invitation_token)
      values (target_workspace_id, actor_user_id, command_id, fingerprint, saved_id, prepared_id, secret_token)
      returning * into stored;
  end if;
  if stored.invitation_id is not null then
    select * into invite from public.employee_invitations where id = stored.invitation_id;
  end if;
  return jsonb_build_object(
    'id', stored.employee_id, 'invitation_id', stored.invitation_id,
    'token', case when invite.status = 'pending' and invite.expires_at > now() then stored.invitation_token else null end,
    'delivery_status', invite.delivery_status
  );
end;
$_$;


ALTER FUNCTION "public"."create_employee_command_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "command_id" "uuid", "employee_input" "jsonb", "invite_role_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_job_with_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "job_input" "jsonb", "assignment_changes" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  target public.jobs;
  department public.departments;
  selected_department_id uuid;
  result jsonb := '{"changed_count":0,"unchanged_count":0}'::jsonb;
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;
  perform set_config('request.jwt.claim.sub', actor_user_id::text, true);
  if not public.workspace_has_permission(target_workspace_id, 'settings.jobs.manage') then
    raise exception 'workspace management access required' using errcode = '42501';
  end if;
  if jsonb_typeof(job_input) is distinct from 'object'
    or jsonb_typeof(job_input->'name') is distinct from 'string'
    or char_length(btrim(job_input->>'name')) not between 1 and 100
    or jsonb_typeof(job_input->'color') is distinct from 'string'
    or (job_input->>'color') !~ '^#[0-9a-fA-F]{6}$'
    or not (job_input ? 'department_id')
    or jsonb_typeof(job_input->'department_id') not in ('string', 'null') then
    raise exception 'Valid job name, color and department required' using errcode = '22023';
  end if;
  if jsonb_typeof(assignment_changes) is distinct from 'array'
    or jsonb_array_length(assignment_changes) > 10000 then
    raise exception 'Choose at most 10000 employees' using errcode = '22023';
  end if;

  selected_department_id := (job_input->>'department_id')::uuid;
  if selected_department_id is not null then
    select * into department from public.departments d
      where d.id = selected_department_id and d.workspace_id = target_workspace_id for share;
    if department.id is null or department.archived_at is not null or department.deleted_at is not null then
      raise exception 'Choose an active department in this workspace' using errcode = '22023';
    end if;
  end if;

  perform 1 from public.workspaces where id = target_workspace_id for update;

  begin
    insert into public.jobs(workspace_id, department_id, name, color)
    values(
      target_workspace_id,
      selected_department_id,
      btrim(job_input->>'name'),
      job_input->>'color'
    )
    returning * into target;
  exception when unique_violation then
    raise exception 'This job name already exists. Choose a unique name.' using errcode = '23505';
  end;

  if jsonb_array_length(assignment_changes) > 0 then
    result := public.update_job_assignments_service(
      actor_user_id, target_workspace_id, target.id, assignment_changes
    );
  end if;

  return result || jsonb_build_object('job', to_jsonb(target));
end;
$_$;


ALTER FUNCTION "public"."create_job_with_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "job_input" "jsonb", "assignment_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_owner_workspace"("workspace_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := (select auth.uid());
  existing_workspace_id uuid;
  created_workspace_id uuid;
begin
  if actor_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  if char_length(btrim(workspace_name)) not between 1 and 120 then
    raise exception 'workspace name must be between 1 and 120 characters' using errcode = '22023';
  end if;

  select workspace.id
  into existing_workspace_id
  from public.workspaces workspace
  join public.workspace_memberships membership
    on membership.workspace_id = workspace.id
   and membership.user_id = actor_id
   and membership.role = 'owner'::public.workspace_role
   and membership.status = 'active'::public.membership_status
  join public.workspace_onboarding onboarding
    on onboarding.workspace_id = workspace.id
   and onboarding.status = 'incomplete'::public.onboarding_status
  order by workspace.created_at desc
  limit 1;

  if existing_workspace_id is not null then
    update public.workspaces
    set name = btrim(workspace_name), updated_at = now()
    where id = existing_workspace_id;

    insert into public.audit_events (
      workspace_id, actor_user_id, action, target_type, target_id
    ) values (
      existing_workspace_id, actor_id, 'workspace.draft_resumed', 'workspace', existing_workspace_id::text
    );

    return existing_workspace_id;
  end if;

  insert into public.workspaces (name, created_by)
  values (btrim(workspace_name), actor_id)
  returning id into created_workspace_id;

  insert into public.workspace_memberships (workspace_id, user_id, role)
  values (created_workspace_id, actor_id, 'owner');

  insert into public.workspace_onboarding (workspace_id, updated_by)
  values (created_workspace_id, actor_id);

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id
  ) values (
    created_workspace_id, actor_id, 'workspace.created', 'workspace', created_workspace_id::text
  );

  return created_workspace_id;
end;
$$;


ALTER FUNCTION "public"."create_owner_workspace"("workspace_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_owner_workspace_service"("actor_user_id" "uuid", "workspace_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;
  -- Serialize create attempts for one account, preserving incomplete-draft reuse.
  perform 1 from auth.users where id = actor_user_id for update;
  if not found then raise exception 'authentication required' using errcode = '42501'; end if;
  -- Same email match and expiry filter as list_pending_employee_invitations_for_account_service.
  if not exists (
    select 1 from public.workspace_memberships m
    left join public.workspace_roles r on r.id = m.role_id and r.workspace_id = m.workspace_id
    where m.user_id = actor_user_id and m.status = 'active'
      and coalesce(r.access_class, m.role) = 'owner'
  ) and exists (
    select 1
    from public.employee_invitations invitation
    join auth.users user_row on user_row.id = actor_user_id
    where invitation.email = lower(user_row.email)
      and invitation.status = 'pending'
      and invitation.expires_at > now()
      and not exists (
        select 1 from public.workspace_memberships membership
        where membership.workspace_id = invitation.workspace_id
          and membership.user_id = actor_user_id
      )
  ) then
    raise exception 'pending invitation must be resolved first' using errcode = '42501';
  end if;
  if exists (
    select 1 from public.workspace_memberships m
    where m.user_id = actor_user_id and m.status = 'active'
      and app_private.workspace_allows_interactive_access(m.workspace_id)
  ) and not exists (
    select 1 from public.workspace_memberships m
    left join public.workspace_roles r on r.id = m.role_id and r.workspace_id = m.workspace_id
    where m.user_id = actor_user_id and m.status = 'active'
      and coalesce(r.access_class, m.role) = 'owner'
      and app_private.workspace_allows_interactive_access(m.workspace_id)
  ) then
    raise exception 'workspace owner access required' using errcode = '42501';
  end if;
  perform set_config('request.jwt.claim.sub', actor_user_id::text, true);
  return public.create_owner_workspace(workspace_name);
end; $$;


ALTER FUNCTION "public"."create_owner_workspace_service"("actor_user_id" "uuid", "workspace_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_schedule_export_preset_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_name" "text", "target_settings" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p public.schedule_export_presets%rowtype;
begin
 perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.export',
   target_locations => app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.export'));
 insert into public.schedule_export_presets(workspace_id,name,settings,created_by,updated_by) values(target_workspace_id,btrim(target_name),target_settings,actor_user_id,actor_user_id) returning * into p;
 return jsonb_build_object('id',p.id,'workspace_id',p.workspace_id,'name',p.name,'settings',p.settings,'created_by',p.created_by,'updated_at',p.updated_at);
exception when unique_violation then raise exception 'schedule export preset name conflict' using errcode='23505'; end; $$;


