CREATE OR REPLACE FUNCTION "public"."create_schedule_export_schedule_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  created public.scheduled_schedule_exports%rowtype;
  preset_name text;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.export', target_locations => array(
    select jsonb_array_elements_text(target_payload->'location_ids')::uuid
  ));

  if not exists (
    select 1
      from public.schedule_export_presets p
     where p.id = (target_payload->>'preset_id')::uuid
       and p.workspace_id = target_workspace_id
       and p.created_by = actor_user_id
  ) then
    raise exception 'schedule export preset not found' using errcode='P0002';
  end if;

  insert into public.scheduled_schedule_exports(
    workspace_id,
    preset_id,
    name,
    recipients,
    location_ids,
    day_of_week,
    send_hour,
    timezone,
    created_by,
    updated_by
  )
  values (
    target_workspace_id,
    (target_payload->>'preset_id')::uuid,
    btrim(target_payload->>'name'),
    target_payload->'recipients',
    array(
      select jsonb_array_elements_text(target_payload->'location_ids')::uuid
    ),
    (target_payload->>'day_of_week')::smallint,
    (target_payload->>'send_hour')::smallint,
    btrim(target_payload->>'timezone'),
    actor_user_id,
    actor_user_id
  )
  returning * into created;

  select p.name into preset_name
    from public.schedule_export_presets p
   where p.id = created.preset_id;

  return public.schedule_export_schedule_json(created, preset_name);
exception
  when unique_violation then
    raise exception 'scheduled export name conflict' using errcode='23505';
end;
$$;


ALTER FUNCTION "public"."create_schedule_export_schedule_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_schedule_shifts_batch_service"("actor" "uuid", "w" "uuid", "sid" "uuid", "expected_revision" integer, "shifts" "jsonb", "request_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare session public.schedule_edit_sessions%rowtype; receipt public.schedule_shift_batch_commands%rowtype;
 item jsonb; result jsonb; next_revision integer;
begin
 if jsonb_typeof(shifts) is distinct from 'array' then
  raise exception 'Choose 1 to 200 shifts' using errcode='22023'; end if;
 if jsonb_array_length(shifts) not between 1 and 200 or request_key is null or expected_revision is null
  or exists(select 1 from jsonb_array_elements(shifts) v where jsonb_typeof(v) is distinct from 'object') then
  raise exception 'Valid shifts, revision and request key required' using errcode='22023'; end if;
 perform public.availability_lock_workspace(w);
 select * into session from public.schedule_edit_sessions where workspace_id=w and id=sid for update;
 if session.id is null or session.holder_user_id is distinct from actor then
  raise exception 'Not allowed' using errcode = '42501', detail = 'schedule.edit', hint = 'authz.out_of_scope'; end if;
 -- The edit's locations are still the person's to edit (B-3).
 perform app_private.authorize(actor, w, 'schedule.edit', target_locations => session.location_ids);
 perform app_private.authorize(actor, w, 'schedule.edit', target_locations => array(
  select distinct nullif(v->>'location_id','')::uuid from jsonb_array_elements(shifts) v));
 if session.status <> 'active' then
  raise exception 'Schedule editing closed; reopen the schedule' using errcode = 'PT409', hint = 'schedule.edit_session_closed';
 elsif session.expires_at <= now() then
  raise exception 'Schedule editing expired; reopen the schedule' using errcode = 'PT409', hint = 'schedule.edit_lease_expired'; end if;
 select * into receipt from public.schedule_shift_batch_commands c
  where c.workspace_id=w and c.actor_user_id=actor and c.idempotency_key=request_key;
 if found then
  if receipt.session_id is distinct from sid or receipt.expected_revision is distinct from expected_revision or receipt.shifts is distinct from shifts then
   raise exception 'Request key already used for a different batch' using errcode = 'PT409'; end if;
  return public.get_schedule_edit_session_service(actor,w,sid);
 end if;
 if session.revision is distinct from expected_revision then
  raise exception 'Schedule editing changed; reload before pasting' using errcode = 'PT409', hint = 'schedule.edit_session_stale'; end if;
 next_revision:=session.revision;
 for item in select value from jsonb_array_elements(shifts) loop
  result:=public.mutate_schedule_edit_shift_service(actor,w,sid,next_revision,'create',gen_random_uuid(),null,item,gen_random_uuid());
  next_revision:=(result->>'revision')::integer;
 end loop;
 insert into public.schedule_shift_batch_commands(workspace_id,actor_user_id,idempotency_key,session_id,expected_revision,shifts)
  values(w,actor,request_key,sid,expected_revision,shifts);
 return result;
end; $$;


ALTER FUNCTION "public"."create_schedule_shifts_batch_service"("actor" "uuid", "w" "uuid", "sid" "uuid", "expected_revision" integer, "shifts" "jsonb", "request_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_schedule_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_draft_id" "uuid", "target_name" "text", "strip_assignments" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d public.schedule_drafts%rowtype; new_template public.schedule_templates%rowtype;
begin
 perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.templates',
   target_locations => app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.templates'));
 select * into d from public.schedule_drafts where id=target_draft_id and workspace_id=target_workspace_id and archived_at is null;
 if d.id is null then raise exception 'schedule draft not found' using errcode='P0002'; end if;
 if not exists(select 1 from public.schedule_draft_shifts where draft_id=d.id) then raise exception 'schedule template source is empty' using errcode='22023'; end if;
 perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.templates',
   target_locations => array(select distinct s.location_id from public.schedule_draft_shifts s where s.draft_id=d.id));
 insert into public.schedule_templates(workspace_id,name,created_by,updated_by) values(target_workspace_id,btrim(target_name),actor_user_id,actor_user_id) returning * into new_template;
 insert into public.schedule_template_shifts(workspace_id, template_id, location_id, employee_id, job_id, shift_type_id, day_offset, start_time, end_time, time_basis, time_snapshot, time_timezone, hide_time_on_badge, note, label_ids, label_names, unpaid_break_minutes)
 select s.workspace_id, new_template.id, s.location_id, case when strip_assignments then null else s.employee_id end, s.job_id, s.shift_type_id, (s.scheduled_date-d.week_start), s.start_time, s.end_time, s.time_basis, s.time_snapshot, s.time_timezone, s.hide_time_on_badge, s.note,
   coalesce(s.label_ids, '{}'::uuid[]), coalesce(s.label_names, '{}'::text[]), s.unpaid_break_minutes
 from public.schedule_draft_shifts s where s.draft_id=d.id;
 insert into public.schedule_template_events(workspace_id,template_id,template_name,action,actor_user_id,detail)
 values(target_workspace_id,new_template.id,new_template.name,'created',actor_user_id,jsonb_build_object('source_draft_id',d.id,'strip_assignments',strip_assignments));
 return public.get_schedule_template_service(actor_user_id,target_workspace_id,new_template.id);
exception when unique_violation then raise exception 'schedule template name conflict' using errcode='23505'; end;
$$;


ALTER FUNCTION "public"."create_schedule_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_draft_id" "uuid", "target_name" "text", "strip_assignments" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_workspace_todo_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "todo_title" "text", "todo_body" "text" DEFAULT ''::"text", "target_employee_id" "uuid" DEFAULT NULL::"uuid", "target_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  inserted public.workspace_todos%rowtype;
  source_uuid uuid := gen_random_uuid();
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'workspace.todos');
  if target_employee_id is not null then
    perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.read', target_person => target_employee_id);
  end if;
  if nullif(btrim(coalesce(todo_title, '')), '') is null then
    raise exception 'todo title required' using errcode = '22023';
  end if;

  insert into public.workspace_todos (
    workspace_id, title, body, severity, status, system_generated,
    source_type, source_id, source_key, employee_id, due_at, action_url
  )
  values (
    target_workspace_id,
    left(btrim(todo_title), 160),
    left(btrim(coalesce(todo_body, '')), 1000),
    'info', 'open', false, 'manual', source_uuid,
    'manual:' || source_uuid::text,
    target_employee_id, target_due_at, null
  )
  returning * into inserted;

  return app_private.workspace_todo_json(inserted);
end;
$$;


ALTER FUNCTION "public"."create_workspace_todo_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "todo_title" "text", "todo_body" "text", "target_employee_id" "uuid", "target_due_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decide_employee_preferred_name_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_request_id" "uuid", "approve" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  request_row public.employee_preferred_name_requests%rowtype;
  asker uuid;
  person uuid;
begin
  select request.employee_id into asker
  from public.employee_preferred_name_requests request
  where request.id = target_request_id
    and request.workspace_id = target_workspace_id;
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.decide_preferred_name', target_person => asker);

  select * into request_row
  from public.employee_preferred_name_requests
  where id = target_request_id
    and workspace_id = target_workspace_id
    and status = 'pending'
  for update;

  if request_row.id is null then
    raise exception 'that request is no longer waiting for an answer'
      using errcode = 'P0002', hint = 'employee.preferred_name.not_pending';
  end if;

  update public.employee_preferred_name_requests
  set status = case when approve then 'approved' else 'rejected' end,
      decided_by = actor_user_id,
      decided_at = now()
  where id = request_row.id;

  if approve then
    update public.employee_profiles
    set preferred_name = request_row.requested_name, updated_at = now()
    where id = request_row.employee_id
      and workspace_id = target_workspace_id
    returning user_id into person;

    if person is not null and person <> actor_user_id then
      perform public.enqueue_notification_outbox_service(
        target_workspace_id,
        gen_random_uuid(),
        'people.preferred_name.approved',
        1,
        actor_user_id,
        'employee',
        request_row.employee_id::text,
        jsonb_build_object(
          'employee_id', request_row.employee_id,
          'request_id', request_row.id,
          'recipient_user_ids', jsonb_build_array(person),
          'audience_contract', 'preferred_name_requester',
          'category', 'people',
          'title', 'Preferred name approved',
          'body', 'You now go by "' || request_row.requested_name || '".',
          'safe_preview', 'Your preferred name was approved.',
          'action_url', '/app',
          'group_key', 'employee:' || request_row.employee_id::text
        ),
        now()
      );
    end if;
  end if;
end;
$$;


ALTER FUNCTION "public"."decide_employee_preferred_name_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_request_id" "uuid", "approve" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decide_time_off_service"("actor" "uuid", "w" "uuid", "rid" "uuid", "verdict" "text", "note" "text", "expected_impact" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r public.schedule_time_off_requests%rowtype;
  alone_why text;
  mine uuid[];
  pictured jsonb;
  state jsonb;
  settled public.schedule_time_off_requests%rowtype;
begin
  perform public.availability_lock_workspace(w);
  select * into r from public.schedule_time_off_requests where id = rid and workspace_id = w for update;
  if r.id is null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'time_off.decide';
  end if;
  alone_why := app_private.time_off_reason(actor, w, 'time_off.decide_alone', r.employee_id);
  if alone_why is not null then
    if alone_why not in ('rank', 'out_of_scope') then
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || alone_why, detail = 'time_off.decide';
    end if;
    select coalesce(array_agg(place order by place), '{}') into mine
    from unnest(app_private.time_off_live_locations(w, rid)) place
    where app_private.time_off_reason(actor, w, 'time_off.decide', r.employee_id, place) is null;
    if cardinality(mine) = 0 then
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || alone_why, detail = 'time_off.decide';
    end if;
  end if;
  if verdict is null or verdict not in ('approve', 'deny') then raise exception 'Choose approve or deny' using errcode = '22023'; end if;
  if char_length(btrim(coalesce(note, ''))) > 1000 then raise exception 'The note can be at most 1000 characters' using errcode = '22023'; end if;
  if r.status <> 'pending' then raise exception 'This request is already closed' using errcode = 'PT409'; end if;
  if r.decide_by is not null and r.decide_by <= now() then raise exception 'This request was not decided in time' using errcode = 'PT409'; end if;
  pictured := app_private.time_off_impact(w, rid);
  if expected_impact is distinct from pictured ->> 'fingerprint' then
    raise exception 'The shifts this time off affects have changed. Review them again' using errcode = 'PT409';
  end if;

  if alone_why is null then
    settled := app_private.time_off_finalize(w, rid, verdict, actor, btrim(coalesce(note, '')), true);
    return jsonb_build_object('status', settled.status, 'final', true, 'alone', true, 'remaining', 0,
      'revision', settled.revision, 'request_id', rid);
  end if;

  insert into public.time_off_votes(request_id, workspace_id, voter_user_id, verdict, note, impact)
  values (rid, w, actor, verdict, btrim(coalesce(note, '')),
    (select jsonb_object_agg(place, coalesce(pictured -> 'locations' -> place::text ->> 'fingerprint', app_private.time_off_shifts_fingerprint('[]')))
     from unnest(mine) place))
  on conflict (request_id, voter_user_id) do update
  set verdict = excluded.verdict, note = excluded.note, impact = excluded.impact, updated_at = now();

  if verdict = 'deny' then
    settled := app_private.time_off_finalize(w, rid, 'deny', actor, btrim(coalesce(note, '')), false);
    return jsonb_build_object('status', settled.status, 'final', true, 'alone', false, 'remaining', 0,
      'revision', settled.revision, 'request_id', rid);
  end if;
  state := app_private.time_off_state(w, rid);
  if (state ->> 'remaining')::integer = 0 and not (state ->> 'fallback')::boolean then
    settled := app_private.time_off_finalize(w, rid, 'approve', actor, btrim(coalesce(note, '')), false);
    return jsonb_build_object('status', settled.status, 'final', true, 'alone', false, 'remaining', 0,
      'revision', settled.revision, 'request_id', rid);
  end if;
  update public.schedule_time_off_requests set revision = revision + 1, updated_at = now() where id = rid returning * into r;
  return jsonb_build_object('status', r.status, 'final', false, 'alone', false, 'remaining', (state ->> 'remaining')::integer,
    'revision', r.revision, 'request_id', rid);
end;
$$;


ALTER FUNCTION "public"."decide_time_off_service"("actor" "uuid", "w" "uuid", "rid" "uuid", "verdict" "text", "note" "text", "expected_impact" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decline_employee_invitation_service"("target_user_id" "uuid", "target_invitation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  invitation public.employee_invitations%rowtype;
  normalized_user_email text;
  email_confirmed boolean;
begin
  select * into invitation from public.employee_invitations
  where id = target_invitation_id and status = 'pending'
  for update;
  if invitation.id is null or invitation.expires_at <= now() then
    if invitation.id is not null then
      update public.employee_invitations
      set status = 'expired', updated_at = now()
      where id = invitation.id;
    end if;
    raise exception 'active invitation not found' using errcode = 'P0002';
  end if;

  select lower(email), email_confirmed_at is not null into normalized_user_email, email_confirmed
  from auth.users where id = target_user_id;
  if normalized_user_email is null or normalized_user_email <> invitation.email then
    raise exception 'invitation email does not match authenticated account' using errcode = '42501';
  end if;
  if not email_confirmed then
    raise exception 'the account email address is not confirmed' using errcode = '42501', hint = 'authz.not_active';
  end if;

  update public.employee_invitations
  set status = 'declined', declined_at = now(), updated_at = now()
  where id = invitation.id;

  insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary)
  values (invitation.workspace_id, invitation.employee_id, target_user_id, 'employee.invitation_declined', 'Employee invitation declined by invitee');
end;
$$;


ALTER FUNCTION "public"."decline_employee_invitation_service"("target_user_id" "uuid", "target_invitation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."defer_initial_employee_document_service"("actor_user_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "deferral_reason" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype;
begin
 perform app_private.authorize(actor_user_id,(select q.workspace_id from public.employee_onboarding_requirements q where q.id=target_requirement_id),'documents.self',target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id));
 perform 1 from public.employee_onboarding_cases c join public.employee_onboarding_requirements q on q.case_id=c.id
 where q.id=target_requirement_id and q.lifecycle_user_id=actor_user_id for update of c;
 select * into r from public.employee_onboarding_requirements where id=target_requirement_id for update;
 if r.id is null or r.lifecycle_user_id is distinct from actor_user_id or not app_private.document_actor_can_read(actor_user_id,r.workspace_id,r.employee_id,r.lifecycle_user_id)
 then raise exception 'document unavailable' using errcode='P0002'; end if;
 perform app_private.assert_document_published(r);
 if r.lifecycle_revision<>expected_revision then raise exception 'document changed; refresh required' using errcode='PT409'; end if;
 if r.kind<>'document' or r.lifecycle_settings->>'mode'<>'conditional' or r.lifecycle_closed_at is not null or r.lifecycle_exempt
  or r.submitted_document_id is not null or exists(select 1 from public.employee_document_submissions s where s.requirement_id=r.id and s.state<>'draft')
  or not exists(select 1 from public.employee_onboarding_cases c join public.workspace_memberships m on m.id=c.membership_id where c.id=r.case_id and m.status='pending_activation')
 then raise exception 'only an initial conditional document can be deferred' using errcode='22023'; end if;
 if nullif(btrim(deferral_reason),'') is null or char_length(deferral_reason)>500 then raise exception 'a short reason is required' using errcode='22023'; end if;
 update public.employee_onboarding_requirements set conditional_reason=btrim(deferral_reason),lifecycle_revision=lifecycle_revision+1,updated_at=now()
 where id=r.id returning lifecycle_revision into expected_revision;
 perform app_private.document_audit(r,actor_user_id,'document.initial_deferred',jsonb_build_object('reason',btrim(deferral_reason),'revision',expected_revision));
 perform app_private.document_sync_onboarding(r.id,actor_user_id);
 return expected_revision;
end;
$$;


ALTER FUNCTION "public"."defer_initial_employee_document_service"("actor_user_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "deferral_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_catalog_entity_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "entity_kind" "text", "target_entity_id" "uuid", "department_jobs" "text" DEFAULT 'keep'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare tbl text; target record; assignment public.employee_location_assignments;
  job record; replacement uuid; affected integer:=0; rule_row app_private.authz_actions; reason text;
begin
  tbl:=case entity_kind when 'locations' then 'locations' when 'departments' then 'departments'
    when 'shift-types' then 'shift_types' when 'shift-labels' then 'shift_labels' end;
  if tbl is null or department_jobs not in ('keep','delete') or department_jobs is null then
    raise exception 'Valid catalog deletion required' using errcode='22023'; end if;
  -- Locations are the organization's (settings.locations.write); departments
  -- and the shift catalog belong to Settings > Jobs (settings.jobs.write), the
  -- shift catalog under its own permission.
  -- ponytail: the shift catalog borrows settings.jobs.write's rule with its own
  -- permission; a settings.shift_catalog.write action comes with FB-6.8.
  select * into rule_row from app_private.authz_actions r
  where r.key = case entity_kind when 'locations' then 'settings.locations.write' else 'settings.jobs.write' end;
  if entity_kind in ('shift-types','shift-labels') then rule_row.permission_key := 'settings.shift_catalog.manage'; end if;
  reason := app_private.authz_check(app_private.actor(actor_user_id, target_workspace_id), rule_row, null, null, null);
  if reason is not null then
    raise exception 'Not allowed' using errcode='42501', hint='authz.' || reason, detail=rule_row.key; end if;
  -- Shares creation's catalog lock; relation triggers serialize stale writes too.
  perform 1 from public.workspaces where id=target_workspace_id for update;
  execute format('select id,name,deleted_at from public.%I where id=$1 and workspace_id=$2 for update',tbl)
    into target using target_entity_id,target_workspace_id;
  if target.id is null then raise exception 'Catalog item not found' using errcode='P0002'; end if;
  if target.deleted_at is not null then return jsonb_build_object('removed_count',0); end if;
  if entity_kind='departments' and exists(select 1 from public.departments
    where id=target_entity_id and system_key is not null) then
    raise exception 'Management and Owner are kept; rename them instead' using errcode='23514', hint='catalog.system_record'; end if;
  if entity_kind='departments' then
    for job in select id from public.jobs where workspace_id=target_workspace_id and department_id=target_entity_id
      and deleted_at is null order by id for update loop
      if department_jobs='delete' then
        perform public.delete_job_with_assignments_service(actor_user_id,target_workspace_id,job.id);
      else
        update public.jobs set department_id=null,updated_at=now() where id=job.id;
      end if;
      affected:=affected+1;
    end loop;
  elsif entity_kind='locations' then
    -- Whoever may delete a location ends everyone's assignment there with it,
    -- their own included (BL-187).
    perform 1 from public.employee_profiles employee
    where employee.workspace_id=target_workspace_id and exists(select 1 from public.employee_location_assignments a
      where a.employee_id=employee.id and a.location_id=target_entity_id and a.ended_at is null)
    order by employee.id for update;
    -- Archived first: the owner is kept at every live location, and this one is
    -- going (BL-218).
    update public.locations set archived_at=coalesce(archived_at,now()) where id=target_entity_id;
    for assignment in select * from public.employee_location_assignments
      where workspace_id=target_workspace_id and location_id=target_entity_id and ended_at is null order by employee_id loop
      update public.employee_location_assignments set ended_at=now() where id=assignment.id;
      if assignment.is_primary then
        select a.id into replacement from public.employee_location_assignments a join public.locations l on l.id=a.location_id
          where a.employee_id=assignment.employee_id and a.ended_at is null
          order by (l.archived_at is not null),l.sort_order,lower(l.name),l.id limit 1;
        if replacement is not null then update public.employee_location_assignments set is_primary=true where id=replacement; end if;
      end if;
      update public.employee_profiles set revision=revision+1,updated_at=now() where id=assignment.employee_id;
      insert into public.employee_events(workspace_id,employee_id,actor_user_id,action,summary)
        values(target_workspace_id,assignment.employee_id,actor_user_id,'location.unassigned','Removed from deleted location '||target.name);
      affected:=affected+1;
    end loop;
  end if;
  execute format('update public.%I set deleted_at=now(),archived_at=coalesce(archived_at,now()),updated_at=now() where id=$1',tbl)
    using target_entity_id;
  return jsonb_build_object('removed_count',affected);
end; $_$;


ALTER FUNCTION "public"."delete_catalog_entity_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "entity_kind" "text", "target_entity_id" "uuid", "department_jobs" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_employee_invitation_delivery_secret"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if old.status = 'pending' and new.status <> 'pending' then
    delete from public.employee_invitation_delivery_secrets
    where invitation_id = new.id;
  end if;
  return new;
end;
$$;


