CREATE OR REPLACE FUNCTION "public"."employee_personal_tasks_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "task_action" "text" DEFAULT 'list'::"text", "target_task_id" "uuid" DEFAULT NULL::"uuid", "task_title" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare owner_profile public.employee_profiles%rowtype;
begin
  owner_profile := public.employee_hub_actor_service(actor_user_id, target_workspace_id);
  -- Serialize per-person writes, including the task limit and retry-safe creation.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(target_workspace_id::text || actor_user_id::text, 0));
  if task_action = 'create' then
    if target_task_id is null or task_title is null or length(btrim(task_title)) not between 1 and 160 then
      raise exception 'Valid personal task required';
    end if;
    if exists(select 1 from public.employee_personal_tasks where id = target_task_id
      and (workspace_id <> target_workspace_id or user_id <> actor_user_id)) then
      raise exception 'Task not found';
    end if;
    if not exists(select 1 from public.employee_personal_tasks where id = target_task_id) then
      if (select count(*) from public.employee_personal_tasks where workspace_id = target_workspace_id and user_id = actor_user_id) >= 100 then
        raise exception 'Your list is full. Remove a completed reminder to add another.';
      end if;
      insert into public.employee_personal_tasks(id, workspace_id, user_id, title)
      values(target_task_id, target_workspace_id, actor_user_id, btrim(task_title));
    end if;
  elsif task_action in ('complete', 'reopen') then
    update public.employee_personal_tasks set completed = (task_action = 'complete')
      where id = target_task_id and workspace_id = target_workspace_id and user_id = actor_user_id;
    if not found then raise exception 'Task not found'; end if;
  elsif task_action = 'delete' then
    delete from public.employee_personal_tasks
      where id = target_task_id and workspace_id = target_workspace_id and user_id = actor_user_id;
  elsif task_action <> 'list' then
    raise exception 'Invalid personal task action';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
    'id', id, 'title', title, 'completed', completed, 'created_at', created_at
  ) order by completed, created_at desc, id) from public.employee_personal_tasks
    where workspace_id = target_workspace_id and user_id = actor_user_id), '[]'::jsonb);
end; $$;


ALTER FUNCTION "public"."employee_personal_tasks_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "task_action" "text", "target_task_id" "uuid", "task_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employee_request_action_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_request_id" "uuid", "target_kind" "text", "target_action" "text", "target_expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare employee public.employee_profiles%rowtype; time_request public.schedule_time_off_requests%rowtype;
begin
  perform public.availability_lock_workspace(target_workspace_id);
employee:=public.employee_hub_actor_service(actor_user_id,target_workspace_id);
  if target_kind='time_off' and target_action='cancel' then
    select * into time_request from public.schedule_time_off_requests where id=target_request_id and workspace_id=target_workspace_id and employee_id=employee.id for update;
    if time_request.id is null then raise exception 'time off request not found' using errcode='P0002'; end if;
    if time_request.revision<>target_expected_revision or time_request.status<>'pending' then raise exception 'stale time off request' using errcode = 'PT409'; end if;
    update public.schedule_time_off_requests set status='revoked',revision=revision+1,updated_at=now() where id=time_request.id returning * into time_request;
    insert into public.schedule_time_off_events(workspace_id,request_id,action,actor_user_id,note) values(target_workspace_id,time_request.id,'revoked',actor_user_id,'Cancelled by employee');
    return jsonb_build_object('status','cancelled','request_id',time_request.id,'revision',time_request.revision);
  end if;
  raise exception 'unsupported employee request action' using errcode='22023';
end; $$;


ALTER FUNCTION "public"."employee_request_action_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_request_id" "uuid", "target_kind" "text", "target_action" "text", "target_expected_revision" integer) OWNER TO "postgres";


