 select jsonb_build_object('input_mode',mode,'days',jsonb_agg(jsonb_build_object('day',day,'all_day',false,'shift_type_ids','[]'::jsonb,'ranges','[]'::jsonb) order by day))
 from generate_series(0,6) day;
$$;


ALTER FUNCTION "public"."empty_weekly_preference"("mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_active_workspace_preference_membership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.workspace_memberships membership
    join public.workspaces workspace
      on workspace.id = membership.workspace_id
    left join public.workspace_onboarding onboarding
      on onboarding.workspace_id = workspace.id
    where membership.user_id = new.user_id
      and membership.workspace_id = new.active_workspace_id
      and membership.status = 'active'::public.membership_status
      and workspace.lifecycle_status = 'active'::public.workspace_lifecycle_status
      and coalesce(onboarding.status, 'complete'::public.onboarding_status) = 'complete'::public.onboarding_status
  ) then
    raise exception 'active workspace preference requires active completed membership'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_active_workspace_preference_membership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_membership_role_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  old_class public.workspace_role;
  new_class public.workspace_role;
begin
  -- The database owner working directly (migrations, seed, test fixtures:
  -- signed in as postgres, with no role set or set back to it) is not an
  -- application caller: every API and browser call signs in as another user
  -- and runs as service_role or authenticated.
  -- ponytail: the console could disable this trigger anyway.
  if session_user = 'postgres' and current_setting('role') in ('none', 'postgres') then
    return new;
  end if;
  new_class := (select role.access_class from public.workspace_roles role where role.id = new.role_id);
  if tg_op = 'UPDATE' then
    old_class := (select role.access_class from public.workspace_roles role where role.id = old.role_id);
  end if;

  -- Taking access away grants nothing; neither does a change that leaves the
  -- role, the account and the status as they were.
  if tg_op = 'UPDATE'
     and new.workspace_id = old.workspace_id
     and new.user_id is not distinct from old.user_id
     and new.role_id = old.role_id
     and (new.status = old.status or new.status = 'suspended'::public.membership_status) then
    return new;
  end if;

  -- A service that asked the core for this row.
  if current_setting('app.membership_change', true) = new.id::text then
    return new;
  end if;

  -- Joining by invitation, checked by the accept flow: a new pending account,
  -- or a suspended one reopened pending, never the owner's (nf-guvenlik O1).
  if coalesce(current_setting('app.employee_invitation_accept', true), '') = 'on'
     and app_private.authz_rank(new_class) < app_private.authz_rank('owner')
     and new.status = 'pending_activation'::public.membership_status
     and (tg_op = 'INSERT'
          or (old.workspace_id = new.workspace_id and old.user_id = new.user_id
              and old.status = 'suspended'::public.membership_status)) then
    return new;
  end if;

  -- The accepted ownership transfer's two rows, validated and locked by the
  -- transfer service: the target admin becomes owner and the owner admin, both
  -- staying active, for the account the transfer names (nf-guvenlik O1).
  if tg_op = 'UPDATE' and coalesce(current_setting('app.owner_transfer', true), '') = 'on'
     and new.workspace_id = old.workspace_id and new.user_id = old.user_id
     and new.status = 'active'::public.membership_status and old.status = 'active'::public.membership_status
     and exists (
       select 1 from public.workspace_ownership_transfers transfer
       join public.workspace_memberships target
         on target.id = transfer.target_membership_id and target.workspace_id = transfer.workspace_id
       where transfer.workspace_id = new.workspace_id and transfer.status = 'pending'
         and transfer.expires_at > now()
         and target.user_id = transfer.target_user_id
         and ((transfer.target_membership_id = new.id and old_class = 'admin' and new_class = 'owner')
           or (transfer.previous_owner_membership_id = new.id and old_class = 'owner' and new_class = 'admin'))
     ) then
    return new;
  end if;

  -- The first membership of a workspace, its creator's.
  if tg_op = 'INSERT' and exists (
    select 1 from public.workspaces workspace
    where workspace.id = new.workspace_id and workspace.created_by = new.user_id
      and not exists (select 1 from public.workspace_memberships existing where existing.workspace_id = new.workspace_id)
  ) then
    return new;
  end if;

  raise exception 'membership change is not permitted' using errcode = '42501', hint = 'authz.missing_permission';
end;
$$;


ALTER FUNCTION "public"."enforce_membership_role_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_role_permission_dependencies"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare rid uuid := coalesce(new.role_id,old.role_id);
begin
 if exists(select 1 from public.workspace_role_permissions g join app_private.role_permission_dependencies d on d.permission_key=g.permission_key where g.role_id=rid and not exists(select 1 from public.workspace_role_permissions r where r.role_id=rid and r.permission_key=d.required_key)) then
  raise exception 'permission set requires dependent read access' using errcode='23514';
 end if;
 return null;
end; $$;


ALTER FUNCTION "public"."enforce_role_permission_dependencies"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_notification_outbox_service"("target_workspace_id" "uuid", "target_event_id" "uuid", "target_type_key" "text", "target_schema_version" integer, "target_actor_user_id" "uuid", "target_subject_type" "text", "target_subject_id" "text", "target_payload" "jsonb", "target_occurred_at" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  outbox_id uuid;
begin
  if jsonb_typeof(target_payload) <> 'object' then
    raise exception 'notification payload must be an object' using errcode = '22023';
  end if;

  insert into public.notification_outbox (
    workspace_id, event_id, type_key, schema_version, actor_user_id,
    subject_type, subject_id, payload, occurred_at
  ) values (
    target_workspace_id, target_event_id, target_type_key, target_schema_version,
    target_actor_user_id, target_subject_type, target_subject_id, target_payload,
    target_occurred_at
  )
  on conflict (workspace_id, event_id) do update
    set event_id = excluded.event_id
  returning id into outbox_id;

  return outbox_id;
end;
$$;


ALTER FUNCTION "public"."enqueue_notification_outbox_service"("target_workspace_id" "uuid", "target_event_id" "uuid", "target_type_key" "text", "target_schema_version" integer, "target_actor_user_id" "uuid", "target_subject_type" "text", "target_subject_id" "text", "target_payload" "jsonb", "target_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extend_employee_document_deadline_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "additional_days" integer, "extension_reason" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype; revised_deadline timestamptz;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'documents.review',target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id and q.workspace_id=target_workspace_id));
 perform 1 from public.employee_onboarding_cases c join public.employee_onboarding_requirements q on q.case_id=c.id where q.id=target_requirement_id and q.workspace_id=target_workspace_id for update of c;
 select * into r from public.employee_onboarding_requirements where id=target_requirement_id and workspace_id=target_workspace_id and kind in ('document','acknowledgement') for update;
 if r.id is null then raise exception 'document unavailable' using errcode='P0002'; end if;
 perform app_private.assert_document_published(r);
 if r.lifecycle_revision<>expected_revision then raise exception 'document changed; refresh required' using errcode='PT409'; end if;
 if additional_days is null or additional_days not between 1 and 3650 or nullif(btrim(extension_reason),'') is null or char_length(extension_reason)>500 then raise exception 'extension days and reason required' using errcode='22023'; end if;
 if r.deadline_at is null or r.deadline_at<=now() or r.lifecycle_exempt or r.lifecycle_closed_at is not null or r.lifecycle_retired_at is not null
  or r.lifecycle_settings->>'mode'='optional' or r.document_suspended_at is not null or app_private.document_actor_blocked(r.lifecycle_user_id,r.workspace_id)
  or app_private.document_obligation_state(r,now())='completed'
  or exists(select 1 from public.employee_document_submissions where id=r.submitted_document_id and state='pending_review')
 then raise exception 'only an active deadline before suspension can be extended' using errcode='22023'; end if;
 revised_deadline:=r.deadline_at+additional_days*interval '24 hours';
 update public.employee_onboarding_requirements set deadline_at=revised_deadline,lifecycle_revision=lifecycle_revision+1,updated_at=now() where id=r.id returning lifecycle_revision into expected_revision;
 perform app_private.document_audit(r,actor_user_id,'document.deadline_extended',jsonb_build_object('reason',btrim(extension_reason),'previous_deadline',r.deadline_at,'new_deadline',revised_deadline,'additional_days',additional_days,'revision',expected_revision));
 return expected_revision;
end;
$$;


ALTER FUNCTION "public"."extend_employee_document_deadline_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "additional_days" integer, "extension_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_notification_outbox_service"("target_worker_id" "text", "target_outbox_id" "uuid", "target_error" "text", "target_max_attempts" integer DEFAULT 5, "target_base_delay_seconds" integer DEFAULT 15) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  outbox public.notification_outbox%rowtype;
  next_status text;
  retry_delay_seconds integer;
begin
  if target_max_attempts not between 1 and 20 then
    raise exception 'notification max attempts must be between 1 and 20' using errcode = '22023';
  end if;
  if target_base_delay_seconds not between 1 and 3600 then
    raise exception 'notification retry delay must be between 1 and 3600' using errcode = '22023';
  end if;

  select * into outbox
  from public.notification_outbox item
  where item.id = target_outbox_id
  for update;
  if outbox.id is null then
    raise exception 'notification outbox item not found' using errcode = 'P0002';
  end if;
  if outbox.status <> 'leased' or outbox.lease_owner <> btrim(target_worker_id) then
    raise exception 'owned notification lease required' using errcode = '42501';
  end if;

  next_status := case when outbox.attempt_count >= target_max_attempts then 'dead_letter' else 'retry' end;
  retry_delay_seconds := least(
    86400,
    target_base_delay_seconds * power(2, greatest(outbox.attempt_count - 1, 0))::integer
  );

  update public.notification_outbox
  set status = next_status,
      available_at = case
        when next_status = 'retry' then clock_timestamp() + make_interval(secs => retry_delay_seconds)
        else available_at
      end,
      lease_owner = null,
      lease_expires_at = null,
      last_error = left(coalesce(nullif(btrim(target_error), ''), 'notification processing failed'), 2000)
  where id = outbox.id;

  return jsonb_build_object(
    'status', next_status,
    'outbox_id', outbox.id,
    'attempt_count', outbox.attempt_count,
    'retry_delay_seconds', case when next_status = 'retry' then retry_delay_seconds else null end
  );
end;
$$;


ALTER FUNCTION "public"."fail_notification_outbox_service"("target_worker_id" "text", "target_outbox_id" "uuid", "target_error" "text", "target_max_attempts" integer, "target_base_delay_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_account_deletion_service"("target_request_id" "uuid", "target_now" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_request public.account_deletion_requests%rowtype;
begin
  select * into target_request
  from public.account_deletion_requests request
  where request.id = target_request_id
    and request.status = 'pending'
  for update;
  if target_request.id is null then
    return jsonb_build_object('status', 'completed', 'idempotent', true);
  end if;
  if target_request.restore_until > target_now then
    raise exception 'account deletion restore window remains open' using errcode = '23514';
  end if;

  update public.account_deletion_requests
  set finalization_started_at = coalesce(finalization_started_at, now()),
      updated_at = now()
  where id = target_request.id;

  delete from public.account_deletion_deliveries where request_id = target_request.id;
  delete from public.user_workspace_preferences where user_id = target_request.user_id;
  delete from public.user_preferences where user_id = target_request.user_id;
  delete from public.user_profiles where user_id = target_request.user_id;

  update public.account_deletion_requests
  set status = 'completed',
      typed_email = '<deleted>',
      recovery_token_digest = null,
      completed_at = now(),
      anonymized_at = now(),
      updated_at = now()
  where id = target_request.id;

  perform app_private.record_security_audit_event_service(
    target_request.user_id, null, 'account.deletion_finalized', 'account.security',
    'account_deletion_request', target_request.id::text, '{}'::jsonb
  );

  return jsonb_build_object('status', 'completed', 'idempotent', false);
end;
$$;


ALTER FUNCTION "public"."finalize_account_deletion_service"("target_request_id" "uuid", "target_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_claimed_account_deletion_service"("target_request_id" "uuid", "target_lease_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.renew_account_deletion_work_service(target_request_id, target_lease_id);
  return public.finalize_account_deletion_service(target_request_id, now());
end;
$$;


ALTER FUNCTION "public"."finalize_claimed_account_deletion_service"("target_request_id" "uuid", "target_lease_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flush_shift_exchange_notifications_service"("target_workspace_id" "uuid", "target_case_id" "uuid", "target_batch_size" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    SET "lock_timeout" TO '100ms'
    AS $$
declare
 item public.notification_outbox%rowtype;
 worker text:='exchange-immediate-'||gen_random_uuid()::text;
 result jsonb; failure jsonb;
 processed integer:=0; skipped integer:=0; retried integer:=0; dead integer:=0; leased integer:=0; deferred integer:=0;
 started timestamptz:=clock_timestamp();
begin
 if target_workspace_id is null or target_case_id is null or target_batch_size is null or target_batch_size not between 1 and 100 then
  raise exception 'A workspace, case and bounded batch are required' using errcode='22023';
 end if;
 if not exists(select 1 from public.shift_exchange_cases where id=target_case_id and workspace_id=target_workspace_id) then
  raise exception 'Shift exchange not found' using errcode='P0002';
 end if;
 -- Same case lock as projection/commands. Never delay a manager command waiting
 -- for this opportunistic path: a busy case remains available to the cron worker.
 if not pg_try_advisory_xact_lock(hashtextextended(target_workspace_id::text||':'||target_case_id::text,925)) then
  return jsonb_build_object('busy',true,'leased',0,'processed',0,'skipped',0,'retried',0,'dead_lettered',0,'invalidation_deferred',0);
 end if;
 for item in
  select o.* from public.notification_outbox o
  where o.workspace_id=target_workspace_id and o.subject_type='shift_exchange_cases' and o.subject_id=target_case_id::text
   and ((o.status in('pending','retry') and o.available_at<=clock_timestamp())
     or (o.status='leased' and o.lease_expires_at<=clock_timestamp()))
  order by o.available_at,o.created_at,o.id
  for update skip locked limit target_batch_size
 loop
  exit when clock_timestamp()-started>=interval '1 second';
  update public.notification_outbox set status='leased',lease_owner=worker,lease_expires_at=clock_timestamp()+interval '60 seconds',
   attempt_count=attempt_count+1,last_error=null where id=item.id;
  leased:=leased+1;
  begin
   result:=public.process_notification_outbox_service(worker,item.id);
   if result->>'status'='skipped' then skipped:=skipped+1; else processed:=processed+1; end if;
   if coalesce((result->>'invalidation_deferred')::boolean,false) then deferred:=deferred+1; end if;
  exception when others then
   failure:=public.fail_notification_outbox_service(worker,item.id,left(SQLERRM,500),5,15);
   if failure->>'status'='dead_letter' then dead:=dead+1; else retried:=retried+1; end if;
  end;
 end loop;
 return jsonb_build_object('busy',false,'leased',leased,'processed',processed,'skipped',skipped,'retried',retried,'dead_lettered',dead,'invalidation_deferred',deferred,
  'remaining',exists(select 1 from public.notification_outbox o where o.workspace_id=target_workspace_id and o.subject_type='shift_exchange_cases' and o.subject_id=target_case_id::text
    and ((o.status in('pending','retry') and o.available_at<=clock_timestamp()) or (o.status='leased' and o.lease_expires_at<=clock_timestamp()))));
end; $$;


ALTER FUNCTION "public"."flush_shift_exchange_notifications_service"("target_workspace_id" "uuid", "target_case_id" "uuid", "target_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_account_deletion_blockers_service"("actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with blocker_rows as (
    select
      'active_membership'::text as kind,
      membership.workspace_id,
      workspace.name as workspace_name,
      role.name as role_name,
      (role.system_key = 'owner') as is_owner,
      null::uuid as transfer_id,
      null::text as transfer_direction
    from public.workspace_memberships membership
    join public.workspaces workspace on workspace.id = membership.workspace_id
    join public.workspace_roles role on role.id = membership.role_id
    where membership.user_id = actor_user_id
      and membership.status = 'active'
      and (
        workspace.lifecycle_status = 'active'
        or (
          workspace.lifecycle_status = 'closure_scheduled'
          and workspace.closure_effective_at > now()
        )
      )

    union all

    select
      'pending_ownership_transfer'::text,
      transfer.workspace_id,
      workspace.name,
      null::text,
      false,
      transfer.id,
      case
        when transfer.initiated_by = actor_user_id then 'outgoing'
        else 'incoming'
      end
    from public.workspace_ownership_transfers transfer
    join public.workspaces workspace on workspace.id = transfer.workspace_id
    where transfer.status = 'pending'
      and (
        transfer.initiated_by = actor_user_id
        or transfer.target_user_id = actor_user_id
      )
  )
  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object(
        'kind', kind,
        'workspace_id', workspace_id,
        'workspace_name', workspace_name,
        'role_name', role_name,
        'is_owner', is_owner,
        'transfer_id', transfer_id,
        'transfer_direction', transfer_direction
      ))
      order by workspace_name, kind, transfer_id
    ),
    '[]'::jsonb
  )
  from blocker_rows;
$$;


ALTER FUNCTION "public"."get_account_deletion_blockers_service"("actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_announcements_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  writable uuid[];
  wide boolean;
  reader app_private.actor_state;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'announcement.read');
  perform app_private.announcement_release(target_workspace_id);
  reader := app_private.actor(actor_user_id, target_workspace_id);
  writable := app_private.scope_set(actor_user_id, target_workspace_id, 'announcement.write');
  wide := app_private.authz_reason(actor_user_id, target_workspace_id, 'announcement.write_wide') is null;
  return jsonb_build_object(
    'workspace_id', target_workspace_id,
    'can_manage', wide or cardinality(writable) > 0,
    'can_target_workspace', wide,
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object('id', location.id, 'name', location.name) order by location.sort_order, location.name)
      from public.locations location
      where location.workspace_id = target_workspace_id and app_private.location_is_live(location)
        and location.id = any (writable)), '[]'::jsonb),
    'departments', case when wide or cardinality(writable) > 0 then coalesce((
      select jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name) order by lower(d.name), d.id)
      from public.departments d where d.workspace_id = target_workspace_id and d.archived_at is null), '[]'::jsonb)
      else '[]'::jsonb end,
    'jobs', case when wide or cardinality(writable) > 0 then coalesce((
      select jsonb_agg(jsonb_build_object('id', j.id, 'name', j.name, 'department_id', j.department_id) order by lower(j.name), j.id)
      from public.jobs j where j.workspace_id = target_workspace_id and j.archived_at is null), '[]'::jsonb)
      else '[]'::jsonb end,
    'announcements', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', item.id, 'workspace_id', item.workspace_id, 'title', item.title, 'body', item.body,
        'category', item.category, 'status', item.status, 'audience_roles', item.audience_roles,
        -- What the list shows: run out (K12), or could not go out (KK-98).
        'display_status', case when item.status = 'published' and item.expires_at <= now() then 'expired'
          when item.status = 'scheduled' and item.release_failed_at is not null then 'publish_failed'
          else item.status::text end,
        'publish_error_code', case when item.release_failed_at is null then null
          when item.release_error like '42501%' then 'not_allowed' else 'failed' end,
        -- Every location it is kept at, archived ones too, so an edit keeps them;
        -- live_location_ids are where it reaches (KK-86).
        'location_ids', coalesce(targets.ids, '{}'::uuid[]), 'location_names', coalesce(targets.names, '{}'::text[]),
        'live_location_ids', app_private.live_locations(target_workspace_id, coalesce(targets.ids, '{}'::uuid[])),
        'department_ids', item.department_ids, 'job_ids', item.job_ids, 'archived_at', item.archived_at,
        'department_names', coalesce((select jsonb_agg(d.name order by lower(d.name), d.id) from public.departments d
          where d.workspace_id = target_workspace_id and d.id = any (item.department_ids)), '[]'::jsonb),
        'job_names', coalesce((select jsonb_agg(j.name order by lower(j.name), j.id) from public.jobs j
          where j.workspace_id = target_workspace_id and j.id = any (item.job_ids)), '[]'::jsonb),
        'publish_at', item.publish_at, 'published_at', item.published_at, 'expires_at', item.expires_at,
        'action_url', item.action_url, 'author_name', coalesce(author.display_name, 'Workspace member'),
        'author_user_id', item.created_by,
        'revision', item.revision, 'content_revision', item.content_revision,
        'created_at', item.created_at, 'updated_at', item.updated_at,
        'read_at', null,
        'acknowledged_at', acknowledgement.acknowledged_at,
        'acknowledged_count', (select count(*) from public.announcement_acknowledgements a where a.announcement_id = item.id),
        -- Everybody it is out to now ("18 of 24 acknowledged"), for whoever may
        -- change it; none once it is not out.
        'recipient_count', case when control.allowed and item.status = 'published' and item.archived_at is null
          and (item.expires_at is null or item.expires_at > now()) then cardinality(item.delivered_to) end,
        'publish_failed_at', item.release_failed_at,
        -- The reader acknowledged an earlier content and not this one (K4).
        'content_changed_since_acknowledged', acknowledgement.acknowledged_at is null
          and actor_user_id = any (item.acknowledged_before),
        'can_edit', control.allowed and item.archived_at is null,
        'can_publish', control.allowed and item.archived_at is null and item.status in ('draft', 'scheduled', 'unpublished'),
        'can_unpublish', control.allowed and item.archived_at is null and item.status in ('scheduled', 'published'),
        'can_archive', control.allowed and item.archived_at is null,
        'can_restore', control.allowed and item.archived_at is not null
      ) order by coalesce(item.publish_at, item.created_at) desc, item.id)
      from public.announcements item
      left join public.user_profiles author on author.user_id = item.created_by
      left join lateral (
        select array_agg(location.id order by location.sort_order, location.name) ids,
               array_agg(location.name order by location.sort_order, location.name) names
        from public.announcement_locations target
        join public.locations location on location.id = target.location_id
        where target.announcement_id = item.id) targets on true
      left join public.announcement_acknowledgements acknowledgement
        on acknowledgement.announcement_id = item.id and acknowledgement.user_id = actor_user_id
      cross join lateral (select app_private.announcement_places(item.id) places) kept
      cross join lateral (
        select app_private.communication_reason(reader, target_workspace_id, 'announcement',
          kept.places, item.created_by) is null allowed) control
      -- announcement_visible, with the reader's state read once for the list.
      where item.workspace_id = target_workspace_id
        and (control.allowed or app_private.announcement_out_to(reader, item, kept.places)
          -- K12: one that ran out stays in the list of whoever manages where it was.
          or (item.status = 'published' and item.archived_at is null and item.expires_at <= now()
              and coalesce(reader.status = 'active', false)
              and (reader.manages && app_private.live_locations(target_workspace_id, kept.places)
                   or (cardinality(kept.places) = 0 and cardinality(reader.manages) > 0))))), '[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_announcements_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_avatar_path_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  avatar_path text;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.read', target_person => target_employee_id);

  select private_profile.avatar_object_path into avatar_path
  from public.employee_private_profiles private_profile
  where private_profile.workspace_id = target_workspace_id
    and private_profile.employee_id = target_employee_id;

  return avatar_path;
end;
$$;


ALTER FUNCTION "public"."get_employee_avatar_path_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_detail_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me app_private.actor_state;
  reads_private boolean;
  reads_access boolean;
  removal app_private.authz_actions;
  answer jsonb;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.read', target_person => target_employee_id);
  me := app_private.actor(actor_user_id, target_workspace_id);
  -- The owner holds every permission.
  reads_private := me.class = 'owner' or 'employees.private.read' = any (me.permissions);
  reads_access := me.class = 'owner' or 'employee_access.read' = any (me.permissions);
  select * into removal from app_private.authz_actions action where action.key = 'employee.remove_from_location';
  if not found then
    raise exception 'core action employee.remove_from_location is missing' using errcode = '22023';
  end if;

  select jsonb_build_object(
    'id', employee.id,
    'workspace_id', employee.workspace_id,
    'employee_code', employee.employee_code,
    'first_name', employee.first_name,
    'last_name', employee.last_name,
    'preferred_name', employee.preferred_name,
    'display_name', concat_ws(' ', employee.first_name, employee.last_name),
    'invitation_email', employee.invitation_email,
    'account_email', account_user.email,
    'start_date', employee.start_date,
    'primary_location_id', primary_location.location_id,
    'primary_location_name', location.name,
    'location_count', (
      select count(*)
      from public.employee_location_assignments assignment
      where assignment.employee_id = employee.id and assignment.ended_at is null
    ),
    'primary_job_id', primary_job.job_id,
    'primary_job_name', job.name,
    'job_count', (
      select count(*)
      from public.employee_job_assignments assignment
      where assignment.employee_id = employee.id and assignment.ended_at is null
    ),
    'role_id', role.id,
    'role_name', role.name,
    'display_status', case
      when employee.archived_at is not null then 'archived'
      when membership.status = 'active' then 'active'
      when membership.status = 'pending_activation' then 'onboarding'
      when invitation.status = 'pending' and invitation.expires_at > now() then 'invited'
      else 'not_invited'
    end,
    'archived_at', employee.archived_at,
    'revision', employee.revision,
    'user_id', employee.user_id,
    'internal_note', employee.internal_note,
    'is_remote', employee.is_remote,
    'is_excluded_from_schedule', employee.is_excluded_from_schedule,
    -- Whether this is the workspace owner's record: the drawer asks here, not
    -- the role's name (BL-421).
    'is_workspace_owner', app_private.employee_record_is_workspace_owner(employee.workspace_id, employee.id),
    -- null only when the reader may not read it. Somebody with nothing on file
    -- yet reads as an empty profile: no names, nothing given, the defaults the
    -- shared employeeDetailSchema needs (7b QA finding 1, shape agreed with
    -- nf-backend).
    'private_contact', case
      when not reads_private then null
      else jsonb_strip_nulls(jsonb_build_object(
        'legal_first_name', private_profile.legal_first_name,
        'legal_last_name', private_profile.legal_last_name,
        'preferred_name', private_profile.preferred_name
      )) || jsonb_build_object(
        'phone', private_profile.phone,
        'street_address', private_profile.street_address,
        'city', private_profile.city,
        'region', private_profile.region,
        'postal_code', private_profile.postal_code,
        'country_code', private_profile.country_code,
        'date_of_birth', private_profile.date_of_birth,
        'emergency_contact_name', private_profile.emergency_contact_name,
        'emergency_contact_relationship', private_profile.emergency_contact_relationship,
        'emergency_contact_phone', private_profile.emergency_contact_phone,
        'emergency_contact_email', coalesce(private_profile.emergency_contact_email, ''),
        'share_phone_with_teammates', coalesce(private_profile.share_phone_with_teammates, false),
        'share_email_with_teammates', coalesce(private_profile.share_email_with_teammates, false)
      )
    end,
    'locations', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', assignment.location_id,
          'name', assigned_location.name,
          'primary', assignment.is_primary,
          'archived', assigned_location.archived_at is not null,
          -- May the reader take them off this location.
          'removable', app_private.authz_check(me, removal, array[assignment.location_id], employee.id, null) is null
        )
        order by assignment.is_primary desc, assigned_location.name
      )
      from public.employee_location_assignments assignment
      join public.locations assigned_location on assigned_location.id = assignment.location_id
      where assignment.employee_id = employee.id and assignment.ended_at is null
    ), '[]'::jsonb),
    'jobs', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', assignment.job_id,
          'name', assigned_job.name,
          'primary', assignment.is_primary,
          'archived', assigned_job.archived_at is not null
        )
        order by assignment.is_primary desc, lower(assigned_job.name), assigned_job.id
      )
      from public.employee_job_assignments assignment
      join public.jobs assigned_job on assigned_job.id = assignment.job_id
      where assignment.employee_id = employee.id and assignment.ended_at is null
    ), '[]'::jsonb),
    'invitation', case
      when invitation.id is null or not reads_access then null
      else jsonb_build_object(
        'id', invitation.id,
        'email', invitation.email,
        'role_id', invitation.role_id,
        'status', invitation.status,
        'expires_at', invitation.expires_at,
        'sent_at', invitation.sent_at,
        'delivery_status', invitation.delivery_status,
        'delivery_attempted_at', invitation.delivery_attempted_at,
        'delivery_failed_at', invitation.delivery_failed_at,
        'delivery_error', invitation.delivery_error,
        'role_name', invitation_role.name,
        'invited_by_name', coalesce(
          nullif(btrim(inviter_profile.display_name), ''),
          inviter_user.email
        )
      )
    end,
    'onboarding', jsonb_build_object(
      'status', case
        when membership.status = 'pending_activation' then 'in_progress'
        when invitation.status = 'pending' then 'invited'
        else 'not_requested'
      end,
      'required_documents', (
        select count(*)
        from public.document_types document_type
        where document_type.workspace_id = employee.workspace_id
          and document_type.required_at_onboarding
          and document_type.archived_at is null
      ),
      'completed_documents', 0
    ),
    'events', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', event.id,
          'action', event.action,
          'occurred_at', event.occurred_at,
          'actor_user_id', event.actor_user_id,
          'summary', event.summary
        )
        order by event.occurred_at desc
      )
      from (
        select *
        from public.employee_events
        where employee_id = employee.id
        order by occurred_at desc
        limit 50
      ) event
    ), '[]'::jsonb),
    -- What the reader may do to this record, by the same rules the actions ask.
    'allowed', (
      select jsonb_object_agg(replace(replace(action.key, 'employee.', ''), '.', '_'),
        app_private.authz_check(me, action, null, employee.id, null) is null
        -- Only a live record with no account on it is invitable, as
        -- prepare_employee_invitation_service says (7b QA finding 2).
        and (action.key <> 'employee.invite'
          or (employee.user_id is null and employee.archived_at is null)))
      from app_private.authz_actions action
      where action.key in ('employee.save', 'employee.terminate', 'employee.archive',
        'employee.remove_access', 'employee.change_role', 'employee.make_admin',
        'employee.invite', 'onboarding.review')
    )
  ) into answer
  from public.employee_profiles employee
  left join public.employee_private_profiles private_profile
    on private_profile.employee_id = employee.id
  left join auth.users account_user
    on account_user.id = employee.user_id
  left join public.employee_location_assignments primary_location
    on primary_location.employee_id = employee.id
    and primary_location.ended_at is null
    and primary_location.is_primary
  left join public.locations location on location.id = primary_location.location_id
  left join public.employee_job_assignments primary_job
    on primary_job.employee_id = employee.id
    and primary_job.ended_at is null
    and primary_job.is_primary
  left join public.jobs job on job.id = primary_job.job_id
  left join public.workspace_memberships membership
    on membership.workspace_id = employee.workspace_id
    and membership.user_id = employee.user_id
  left join public.workspace_roles role on role.id = membership.role_id
  left join lateral (
    select *
    from public.employee_invitations candidate
    where candidate.employee_id = employee.id
    order by candidate.created_at desc
    limit 1
  ) invitation on true
  left join public.workspace_roles invitation_role
    on invitation_role.id = invitation.role_id
  left join public.user_profiles inviter_profile
    on inviter_profile.user_id = invitation.created_by
  left join auth.users inviter_user
    on inviter_user.id = invitation.created_by
  where employee.id = target_employee_id
    and employee.workspace_id = target_workspace_id;

  return answer;
end;
$$;


ALTER FUNCTION "public"."get_employee_detail_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_document_access_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'documents.self');
 return jsonb_build_object('restricted',app_private.document_actor_blocked(actor_user_id,target_workspace_id));
end;
$$;


ALTER FUNCTION "public"."get_employee_document_access_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_document_lifecycle_path_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "target_submission_id" "uuid", "target_file_id" "uuid", "self_only" boolean) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare detail jsonb; path text;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,case when self_only then 'documents.self' else 'documents.read' end,target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id and q.workspace_id=target_workspace_id and q.kind in ('document','acknowledgement')));
 detail:=public.get_employee_document_lifecycle_service(actor_user_id,target_workspace_id,target_requirement_id,self_only);
 select f.object_path into path from public.employee_document_submission_files sf
 join public.employee_document_submissions s on s.id=sf.submission_id join public.employee_documents f on f.id=sf.file_id
 where sf.requirement_id=target_requirement_id and sf.workspace_id=target_workspace_id and sf.submission_id=target_submission_id and sf.file_id=target_file_id and sf.decision='keep'
 and (self_only or app_private.document_submission_visible(actor_user_id,
  (select q from public.employee_onboarding_requirements q where q.id=target_requirement_id),s.state));
 if path is null then raise exception 'document file unavailable' using errcode='P0002'; end if;
 return path;
end;
$$;


ALTER FUNCTION "public"."get_employee_document_lifecycle_path_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "target_submission_id" "uuid", "target_file_id" "uuid", "self_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_document_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "self_only" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype; submissions jsonb; history jsonb;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,case when self_only then 'documents.self' else 'documents.read' end,target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id and q.workspace_id=target_workspace_id and q.kind in ('document','acknowledgement')));
 select * into r from public.employee_onboarding_requirements where id=target_requirement_id and workspace_id=target_workspace_id and kind in ('document','acknowledgement');
 if r.id is null or self_only is null or (self_only and r.lifecycle_user_id is distinct from actor_user_id)
 then raise exception 'document unavailable' using errcode='P0002'; end if;
 -- A document waiting for review is its decider's and its owner's (S2).
 if not self_only and not app_private.document_row_readable(actor_user_id, r) then
  raise exception 'Not allowed' using errcode='42501', hint='authz.out_of_scope', detail='documents.read';
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'version',s.version,'state',s.state,'submitted_at',s.submitted_at,
  'reviewed_at',s.reviewed_at,'expiry_date',s.expiry_date,'metadata',s.metadata,'rejection_reason',s.rejection_reason,
  'files',coalesce((select jsonb_agg(jsonb_build_object('id',f.id,'filename',f.original_filename,'media_type',f.media_type,'size_bytes',f.size_bytes,'decision',sf.decision,'note',sf.note) order by f.created_at,f.id)
   from public.employee_document_submission_files sf join public.employee_documents f on f.id=sf.file_id where sf.submission_id=s.id),'[]')) order by s.version desc),'[]')
 into submissions from public.employee_document_submissions s where s.requirement_id=r.id
  and (self_only or app_private.document_submission_visible(actor_user_id,r,s.state));
 select coalesce(jsonb_agg(jsonb_build_object('id',ev.id,'action',ev.action,'occurred_at',ev.occurred_at,'metadata',ev.metadata) order by ev.occurred_at desc),'[]') into history
 from public.onboarding_events ev where ev.workspace_id=r.workspace_id and ev.employee_id=r.employee_id and ev.target_id=r.id::text
  and (self_only or not exists(select 1 from public.employee_document_submissions s
   where s.id::text=ev.metadata->>'submission_id'
    and not app_private.document_submission_visible(get_employee_document_lifecycle_service.actor_user_id,r,s.state)));
 return jsonb_build_object('obligation',app_private.document_obligation_json(app_private.document_view(actor_user_id,r)),'submissions',submissions,'history',history,'policy',case when r.kind='acknowledgement' then jsonb_build_object('content_text',r.source_snapshot->>'content_text','content_digest',r.source_snapshot->>'content_digest','intent_statement',r.source_snapshot->>'intent_statement','can_withdraw',self_only and exists(select 1 from public.employee_onboarding_cases c join public.workspace_memberships m on m.id=c.membership_id where c.id=r.case_id and c.submitted_at is null and c.status='in_progress' and m.status='pending_activation' and r.lifecycle_retired_at is null),'history',coalesce((select jsonb_agg(jsonb_build_object('typed_name',a.typed_name,'executed_at',a.executed_at,'withdrawn_at',a.withdrawn_at,'content_digest',a.content_digest) order by a.executed_at,a.id) from public.employee_acknowledgement_envelopes a where a.requirement_id=r.id and (not self_only or a.user_id=actor_user_id)),'[]'::jsonb),'evidence',(select jsonb_build_object('typed_name',a.typed_name,'executed_at',a.executed_at,'content_digest',a.content_digest,'intent_statement',a.intent_statement) from public.employee_acknowledgement_envelopes a where a.requirement_id=r.id and a.withdrawn_at is null and (not self_only or a.user_id=actor_user_id))) end,'initial_deferral',jsonb_build_object('reason',r.conditional_reason,'allowed',self_only and r.kind='document' and r.lifecycle_settings->>'mode'='conditional' and r.submitted_document_id is null and not r.lifecycle_exempt and r.lifecycle_closed_at is null and not exists(select 1 from public.employee_document_submissions s where s.requirement_id=r.id and s.state<>'draft') and exists(select 1 from public.employee_onboarding_cases c join public.workspace_memberships m on m.id=c.membership_id where c.id=r.case_id and m.status='pending_activation')),'timezone_settings',(select jsonb_build_object('value',app_private.document_employee_timezone(r.workspace_id,r.employee_id),'configured_value',p.document_timezone,'employee_revision',p.revision,'can_manage',not self_only and (p.is_remote or p.is_excluded_from_schedule) and app_private.document_timezone_admin(actor_user_id,r.workspace_id,r.employee_id) and not exists(select 1 from public.employee_location_assignments a join public.locations l on l.id=a.location_id and l.workspace_id=a.workspace_id and l.archived_at is null where a.workspace_id=r.workspace_id and a.employee_id=r.employee_id and a.ended_at is null and a.is_primary)) from public.employee_profiles p where p.id=r.employee_id));
end;
$$;


ALTER FUNCTION "public"."get_employee_document_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "self_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_hub_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_from" "date", "target_to" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare employee public.employee_profiles%rowtype; result jsonb;
begin
  if target_to < target_from or target_to > target_from + 62 then
    raise exception 'employee hub date range is invalid' using errcode = '22023';
  end if;
  employee := public.employee_hub_actor_service(actor_user_id, target_workspace_id);

  select jsonb_build_object(
    'workspace_id', target_workspace_id,
    'employee', jsonb_build_object(
      'id', employee.id,
      'display_name', concat_ws(' ', coalesce(nullif(employee.preferred_name,''),employee.first_name), employee.last_name)
    ),
    'time_off_timezone', app_private.time_off_timezone(target_workspace_id, employee.id),
    'settings', jsonb_build_object('time_off_lead_hours', coalesce((select s.time_off_lead_hours from public.workspace_scheduling_settings s where s.workspace_id = target_workspace_id), 24)),
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object('id',location.id,'name',location.name) order by location.sort_order,location.name)
      from public.employee_location_assignments assignment
      join public.locations location on location.id=assignment.location_id and location.archived_at is null
      where assignment.employee_id=employee.id and assignment.ended_at is null
    ),'[]'::jsonb),
    'shifts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',shift.id,'location_id',shift.location_id,'location_name',location.name,'job_name',job.name,
        'scheduled_date',shift.scheduled_date,'time_basis',shift.time_basis,'time_snapshot',shift.time_snapshot,'time_timezone',shift.time_timezone,'start_time',to_char(shift.start_time,'HH24:MI'),
        'end_time',to_char(shift.end_time,'HH24:MI'),'note',shift.note,'employee_id',shift.employee_id
      ) order by shift.scheduled_date,shift.start_time)
      from public.schedule_published_shifts shift
      join public.schedule_location_publications publication on publication.id=shift.publication_id and publication.status='current'
      join public.locations location on location.id=shift.location_id
      join public.jobs job on job.id=shift.job_id
      where shift.workspace_id=target_workspace_id and shift.employee_id=employee.id
        and shift.scheduled_date between target_from and target_to
    ),'[]'::jsonb),
    'open_shifts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',shift.id,'location_id',shift.location_id,'location_name',location.name,'job_name',job.name,
        'scheduled_date',shift.scheduled_date,'time_basis',shift.time_basis,'time_snapshot',shift.time_snapshot,'time_timezone',shift.time_timezone,'start_time',to_char(shift.start_time,'HH24:MI'),
        'end_time',to_char(shift.end_time,'HH24:MI'),'note',shift.note,'employee_id',null
      ) order by shift.scheduled_date,shift.start_time)
      from public.schedule_published_shifts shift
      join public.schedule_location_publications publication on publication.id=shift.publication_id and publication.status='current'
      join public.locations location on location.id=shift.location_id
      join public.jobs job on job.id=shift.job_id
      where shift.workspace_id=target_workspace_id and shift.employee_id is null
        and shift.scheduled_date between target_from and target_to
        and exists(select 1 from public.employee_location_assignments assignment
          where assignment.employee_id=employee.id and assignment.location_id=shift.location_id and assignment.ended_at is null)
    ),'[]'::jsonb),
    'team_shifts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',shift.id,'location_id',shift.location_id,'location_name',location.name,'job_name',job.name,
        'scheduled_date',shift.scheduled_date,'time_basis',shift.time_basis,'time_snapshot',shift.time_snapshot,'time_timezone',shift.time_timezone,'start_time',to_char(shift.start_time,'HH24:MI'),
        'end_time',to_char(shift.end_time,'HH24:MI'),'note','','employee_id',shift.employee_id,
        'employee_name',concat_ws(' ',coalesce(nullif(teammate.preferred_name,''),teammate.first_name),teammate.last_name)
      ) order by shift.scheduled_date,shift.start_time)
      from public.schedule_published_shifts shift
      join public.schedule_location_publications publication on publication.id=shift.publication_id and publication.status='current'
      join public.locations location on location.id=shift.location_id
      join public.jobs job on job.id=shift.job_id
      join public.employee_profiles teammate on teammate.id=shift.employee_id
      where shift.workspace_id=target_workspace_id and shift.employee_id<>employee.id
        and shift.scheduled_date between target_from and target_to
        and exists(select 1 from public.employee_location_assignments assignment
          where assignment.employee_id=employee.id and assignment.location_id=shift.location_id and assignment.ended_at is null)
    ),'[]'::jsonb),
    'requests', coalesce((
      select jsonb_agg(request_row order by request_row->>'created_at' desc) from (
        select jsonb_build_object(
          'id',request.id,'kind','time_off','request_type',request.request_type,'cancellation',public.time_off_cancellation_context(target_workspace_id,request.id),'periods',public.time_off_request_periods(request.id,target_workspace_id), 'decision_events',coalesce((select jsonb_agg(jsonb_build_object('id',ev.id,'action',ev.action,'note',ev.note,'created_at',ev.created_at,'revision',ev.metadata->'revision','released_assignments',public.time_off_event_released_assignments(get_employee_hub_service.actor_user_id,target_workspace_id,ev.id)) order by ev.created_at,ev.id)
  from public.schedule_time_off_events ev where ev.request_id=request.id and ev.workspace_id=target_workspace_id and ev.action in('approved','denied','revoked','expired')),'[]'), 'status',request.status::text,'display_status',app_private.time_off_display_status(target_workspace_id,request.id),'decide_by',request.decide_by,
          'title',case when request.request_type='time_off_cancellation' then 'Cancel approved leave · ' else 'Time off · ' end||to_char(min(segment.segment_date),'Mon DD')||case when min(segment.segment_date)<>max(segment.segment_date) then '–'||to_char(max(segment.segment_date),'Mon DD') else '' end,
          'detail',coalesce(nullif(request.reason,''),'No note'),'revision',request.revision,'created_at',request.created_at,
          'can_cancel',request.status='pending'
        ) request_row
        from public.schedule_time_off_requests request
        join public.schedule_time_off_segments segment on segment.request_id=request.id
        where request.workspace_id=target_workspace_id and request.employee_id=employee.id
        group by request.id
      ) requests
    ),'[]'::jsonb),
    'team', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',teammate.id,
        'display_name',concat_ws(' ',coalesce(nullif(teammate.preferred_name,''),teammate.first_name),teammate.last_name),
        'job_names',coalesce((select jsonb_agg(job.name order by lower(job.name),job.id) from public.employee_job_assignments assignment join public.jobs job on job.id=assignment.job_id where assignment.employee_id=teammate.id and assignment.ended_at is null),'[]'::jsonb),
        'location_names',coalesce((select jsonb_agg(location.name order by location.sort_order,location.name) from public.employee_location_assignments assignment join public.locations location on location.id=assignment.location_id where assignment.employee_id=teammate.id and assignment.ended_at is null),'[]'::jsonb)
      ) order by teammate.last_name,teammate.first_name)
      from public.employee_profiles teammate
      where teammate.workspace_id=target_workspace_id and teammate.archived_at is null and teammate.id<>employee.id
        and exists(select 1 from public.employee_location_assignments mine join public.employee_location_assignments theirs on theirs.location_id=mine.location_id and theirs.ended_at is null where mine.employee_id=employee.id and mine.ended_at is null and theirs.employee_id=teammate.id)
    ),'[]'::jsonb)
  ) into result;
  return result;
end; $$;


ALTER FUNCTION "public"."get_employee_hub_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_from" "date", "target_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_name_settings_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.people.read');
  return coalesce(
    (select preferred_name_approval from public.employee_name_settings
     where workspace_id = target_workspace_id),
    'auto'
  );
end;
$$;


ALTER FUNCTION "public"."get_employee_name_settings_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_onboarding_review_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare target_case public.employee_onboarding_cases%rowtype; requirement_rows jsonb; total_count integer; completed_count integer;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'onboarding.review', target_person => target_employee_id);
  select * into target_case from public.employee_onboarding_cases
  where workspace_id = target_workspace_id and employee_id = target_employee_id;
  if target_case.id is null then raise exception 'onboarding case unavailable' using errcode = 'P0002'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', requirement.id, 'kind', requirement.kind, 'title', requirement.title,
    'description', requirement.description, 'status', (app_private.document_view(actor_user_id, requirement)).status,
    'required', requirement.required, 'blocks_activation', requirement.blocks_activation,
    'requires_review', requirement.requires_review, 'sort_order', requirement.sort_order,
    'source_id', requirement.source_id,
    'accepted_formats', coalesce(requirement.source_snapshot->'accepted_formats', '[]'::jsonb),
    'content_text', null, 'content_digest', requirement.source_snapshot->>'content_digest',
    'intent_statement', null, 'rejection_reason', (app_private.document_view(actor_user_id, requirement)).rejection_reason
  ) order by requirement.sort_order), '[]'::jsonb),
  count(*) filter (where requirement.required),
  count(*) filter (where requirement.required and (app_private.document_view(actor_user_id, requirement)).status = 'completed')
  into requirement_rows, total_count, completed_count
  from public.employee_onboarding_requirements requirement
  where requirement.case_id = target_case.id and requirement.status <> 'superseded' and requirement.lifecycle_retired_at is null
    -- a row the reader may not see is not counted either (S2)
    and (requirement.kind <> 'document' or app_private.document_row_readable(actor_user_id, requirement));
  return jsonb_build_object(
    'case_id', target_case.id, 'employee_id', target_case.employee_id,
    'case_status', target_case.status, 'revision', target_case.revision,
    'submitted_at', target_case.submitted_at,
    'progress_completed', completed_count, 'progress_total', total_count,
    'ssn_present', false,
    'requirements', requirement_rows
  );
end;
$$;


ALTER FUNCTION "public"."get_employee_onboarding_review_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_onboarding_service"("target_user_id" "uuid", "target_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_case public.employee_onboarding_cases%rowtype;
  employee public.employee_profiles%rowtype;
  membership public.workspace_memberships%rowtype;
  profile jsonb;
  requirements jsonb;
  completed_count integer;
  total_count integer;
  first_path text;
begin
 perform app_private.authorize(target_user_id, app_private.onboarding_self_workspace(target_user_id, target_workspace_id, true), 'onboarding.self');
  perform app_private.initialize_employee_onboarding(target_user_id, target_workspace_id);
  select onboarding.* into target_case
  from public.employee_onboarding_cases onboarding
  where onboarding.id = app_private.employee_onboarding_case_id(target_user_id, target_workspace_id);
  if target_case.id is null then
    raise exception 'employee onboarding is unavailable' using errcode = 'P0002';
  end if;
  select * into employee from public.employee_profiles where id = target_case.employee_id;
  select * into membership from public.workspace_memberships where id = target_case.membership_id;

  select to_jsonb(private_profile) - 'created_at' - 'updated_at' - 'employee_id' - 'workspace_id'
  into profile from public.employee_private_profiles private_profile
  where private_profile.employee_id = employee.id;
  profile := coalesce(
    profile,
    jsonb_build_object(
      'legal_first_name', employee.first_name,
      'legal_last_name', employee.last_name
    )
  );


  select coalesce(jsonb_agg(jsonb_build_object(
    'id', requirement.id,
    'kind', requirement.kind,
    'title', requirement.title,
    'description', requirement.description,
    'status', requirement.status,
    'required', requirement.required,'document_mode',requirement.lifecycle_settings->>'mode', 'conditional_reason',requirement.conditional_reason,
    'blocks_activation', requirement.blocks_activation,
    'requires_review', requirement.requires_review,
    'sort_order', requirement.sort_order,
    'source_id', requirement.source_id,
    'accepted_formats', coalesce(requirement.source_snapshot->'accepted_formats', '[]'::jsonb),
    'content_text', requirement.source_snapshot->>'content_text',
    'content_digest', requirement.source_snapshot->>'content_digest',
    'intent_statement', requirement.source_snapshot->>'intent_statement',
    'rejection_reason', requirement.rejection_reason
  ) order by requirement.sort_order, requirement.id), '[]'::jsonb),
  count(*) filter (where requirement.required or (requirement.kind='document' and requirement.lifecycle_settings->>'mode'='conditional')),
  count(*) filter (where (requirement.required and requirement.status in ('completed', 'awaiting_review')) or (requirement.kind='document' and requirement.lifecycle_settings->>'mode'='conditional' and not app_private.document_initial_action_missing(requirement)))
  into requirements, total_count, completed_count
  from public.employee_onboarding_requirements requirement
  where requirement.case_id = target_case.id and requirement.status <> 'superseded' and requirement.lifecycle_retired_at is null and (requirement.kind<>'document' or (not requirement.lifecycle_exempt and requirement.lifecycle_closed_at is null));

  select case requirement.kind
    when 'profile' then '/welcome/profile'
    when 'ssn' then '/welcome/review'
    when 'document' then '/welcome/documents/' || requirement.id
    when 'acknowledgement' then '/welcome/acknowledgements/' || requirement.id
    when 'availability' then '/welcome/availability'
  end into first_path
  from public.employee_onboarding_requirements requirement
  where requirement.case_id = target_case.id
    and (requirement.required or app_private.document_initial_action_missing(requirement))
    and requirement.status in ('not_started', 'in_progress', 'rejected', 'manual_follow_up')
  order by case when requirement.status = 'rejected' then 0 else 1 end,
    requirement.sort_order, requirement.id
  limit 1;
  first_path := coalesce(first_path,
    case when target_case.status = 'approved' then '/app/employee-hub' else '/welcome/review' end);

  return jsonb_build_object(
    'case_id', target_case.id,
    'workspace_id', target_case.workspace_id,
    'workspace_name', (select name from public.workspaces where id = target_case.workspace_id),
    'employee_id', employee.id,
    'employee_name', concat_ws(' ', employee.first_name, employee.last_name),
    'membership_id', membership.id,
    'membership_status', membership.status,
    'case_status', target_case.status,
    'revision', target_case.revision,
    'progress_completed', completed_count,
    'progress_total', total_count,
    'first_actionable_path', first_path,
    'ssn_status', jsonb_build_object(
      'present', false,
      'last_four', null
    ),
    'profile', profile,
    'assignments', jsonb_build_object(
      'locations', coalesce((select jsonb_agg(location.name order by assignment.is_primary desc, location.name)
        from public.employee_location_assignments assignment join public.locations location on location.id = assignment.location_id
        where assignment.employee_id = employee.id and assignment.ended_at is null), '[]'::jsonb),
      'jobs', coalesce((select jsonb_agg(job.name order by assignment.is_primary desc, lower(job.name), job.id)
        from public.employee_job_assignments assignment join public.jobs job on job.id = assignment.job_id
        where assignment.employee_id = employee.id and assignment.ended_at is null), '[]'::jsonb)
    ),
    'requirements', requirements
  );
end;
$$;


ALTER FUNCTION "public"."get_employee_onboarding_service"("target_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_schedule_board_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor public.employee_profiles%rowtype;
  settings public.workspace_scheduling_settings%rowtype;
  resolved_week_start date;
  result jsonb;
begin
  actor := public.employee_hub_actor_service(actor_user_id, target_workspace_id);

  select * into settings
  from public.workspace_scheduling_settings
  where workspace_id = target_workspace_id;
  if settings.workspace_id is null then
    raise exception 'scheduling settings are unavailable' using errcode = 'P0002';
  end if;

  resolved_week_start := case settings.week_start_day
    when 'sunday' then target_date - extract(dow from target_date)::integer
    else target_date - (extract(isodow from target_date)::integer - 1)
  end;

  with allowed_locations as (
    select location.*
    from public.locations location
    where location.workspace_id = target_workspace_id
      and location.archived_at is null
      and exists (
        select 1
        from public.employee_location_assignments assignment
        where assignment.employee_id = actor.id
          and assignment.location_id = location.id
          and assignment.ended_at is null
      )
  ), current_publications as (
    select publication.*
    from public.schedule_location_publications publication
    join allowed_locations location on location.id = publication.location_id
    where publication.week_start = resolved_week_start
      and publication.status = 'current'
  ), visible_employees as (
    select distinct employee.*
    from public.employee_profiles employee
    where employee.workspace_id = target_workspace_id
      and employee.archived_at is null
      and exists (
        select 1
        from public.employee_location_assignments assignment
        join allowed_locations location on location.id = assignment.location_id
        where assignment.employee_id = employee.id and assignment.ended_at is null
      )
  ), current_shifts as (
    select shift.*
    from public.schedule_published_shifts shift
    join current_publications publication on publication.id = shift.publication_id
    where shift.scheduled_date between resolved_week_start and resolved_week_start + 6
  ), own_availability as materialized (
    -- The employee's own marks; the manager's private reminder never reaches here.
    select * from app_private.schedule_week_availability(
      target_workspace_id, resolved_week_start, array[actor.id],
      (select coalesce(array_agg(location.id), '{}') from allowed_locations location), false)
  )
  select jsonb_build_object(
    'workspace_id', target_workspace_id,
    'week_start', resolved_week_start,
    'week_start_day', settings.week_start_day,
    'settings', jsonb_build_object(
      'time_format', coalesce(settings.time_format, '12h')
    ),
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', location.id,
        'name', location.name,
        'timezone', location.timezone,
        'sort_order', location.sort_order,
        'publication_status', case when publication.id is null then 'unpublished' else 'published' end,
        'published_at', publication.published_at
      ) order by location.sort_order, location.name)
      from allowed_locations location
      left join current_publications publication on publication.location_id = location.id
    ), '[]'::jsonb),
    'shift_types', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', shift_type.id, 'name', shift_type.name, 'color', shift_type.color,
        'sort_order', shift_type.sort_order,
        'default_revision', shift_type.default_revision,
        'default_start_time', case when shift_type.default_start_time is null then null else to_char(shift_type.default_start_time, 'HH24:MI') end,
        'default_end_time', case when shift_type.default_end_time is null then null else to_char(shift_type.default_end_time, 'HH24:MI') end
      ) order by shift_type.sort_order, shift_type.name)
      from public.shift_types shift_type
      where shift_type.workspace_id = target_workspace_id and shift_type.archived_at is null
    ), '[]'::jsonb),
    'shift_labels', '[]'::jsonb,
    'employees', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', employee.id,
        'employee_code', employee.employee_code,
        'display_name', coalesce(nullif(employee.preferred_name, ''), employee.first_name) || ' ' || employee.last_name,
        'location_ids', coalesce((select jsonb_agg(assignment.location_id order by assignment.location_id)
          from public.employee_location_assignments assignment
          join allowed_locations location on location.id = assignment.location_id
          where assignment.employee_id = employee.id and assignment.ended_at is null), '[]'::jsonb),
        'job_ids', coalesce((select jsonb_agg(assignment.job_id order by assignment.job_id)
          from public.employee_job_assignments assignment
          where assignment.employee_id = employee.id and assignment.ended_at is null), '[]'::jsonb),
        'primary_job_id', app_private.stored_primary_job(employee.id)
      ) || case when employee.id = actor.id then jsonb_build_object('weekly_availability', coalesce((
          select jsonb_agg(own.projection order by own.location_id)
          from own_availability own
          where exists (select 1 from public.employee_location_assignments assignment
            where assignment.employee_id = actor.id and assignment.location_id = own.location_id
              and assignment.ended_at is null)), '[]'::jsonb))
        else '{}'::jsonb end
      order by employee.last_name, employee.first_name, employee.id)
      from visible_employees employee
    ), '[]'::jsonb),
    'shifts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', shift.id,
        'location_id', shift.location_id,
        'employee_id', shift.employee_id,
        'job_id', shift.job_id,
        'shift_type_id', shift.shift_type_id,
        'scheduled_date', shift.scheduled_date,
        'time_basis', shift.time_basis,
        'time_snapshot', shift.time_snapshot,
        'time_timezone', shift.time_timezone,
        'start_time', to_char(shift.start_time, 'HH24:MI'),
        'end_time', to_char(shift.end_time, 'HH24:MI'),
        'crosses_midnight', shift.crosses_midnight,
        'unpaid_break_minutes', coalesce(shift.unpaid_break_minutes, 0),
        'hide_time_on_badge', coalesce(shift.hide_time_on_badge, false),
        'note', case when shift.employee_id is null or shift.employee_id = actor.id then shift.note else '' end,
        'label_ids', to_jsonb(coalesce(shift.label_ids, '{}'::uuid[])),
        'label_names', to_jsonb(coalesce(shift.label_names, '{}'::text[])),
        'warning_codes', to_jsonb(array_remove(array[
          case when exists (
            select 1 from public.schedule_closures closure
            where closure.location_id = shift.location_id
              and closure.closed_date = shift.scheduled_date and closure.is_all_day
          ) then 'closed_location' end,
          -- Only a conflict with the employee's own marks, as accepted at publishing.
          case when shift.employee_id = actor.id
            and coalesce((shift.availability_snapshot -> 'assessment' ->> 'has_availability_conflict')::boolean, false)
            and jsonb_array_length(coalesce(shift.availability_snapshot -> 'assessment' -> 'employee_intervals', '[]'::jsonb)) > 0
          then 'availability' end,
          case when shift.employee_id is not null and exists (
            select 1 from current_shifts other
            where other.employee_id = shift.employee_id
              and other.scheduled_date = shift.scheduled_date
              and other.id <> shift.id
              and not shift.crosses_midnight and not other.crosses_midnight
              and shift.start_time < other.end_time and shift.end_time > other.start_time
          ) then 'overlap' end
        ]::text[], null))
      ) order by shift.scheduled_date, shift.start_time, shift.id)
      from current_shifts shift
    ), '[]'::jsonb),
    'closures', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', closure.id, 'location_id', closure.location_id,
        'closed_date', closure.closed_date, 'title', closure.title,
        'is_all_day', closure.is_all_day
      ) order by closure.closed_date, closure.title)
      from public.schedule_closures closure
      join allowed_locations location on location.id = closure.location_id
      where closure.closed_date between resolved_week_start and resolved_week_start + 6
    ), '[]'::jsonb),
    'important_dates', '[]'::jsonb
  ) || app_private.schedule_departments_and_jobs(target_workspace_id)
    || app_private.schedule_referenced_catalog(target_workspace_id,
      array(select shift.job_id from current_shifts shift),
      array(select shift.shift_type_id from current_shifts shift))
  into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_employee_schedule_board_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_inbox_v2_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_cursor_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "target_cursor_id" "uuid" DEFAULT NULL::"uuid", "target_limit" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  effective_limit integer := greatest(1, least(coalesce(target_limit, 30), 50));
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'notifications.read_own');
  if (target_cursor_created_at is null) <> (target_cursor_id is null) then
    raise exception 'complete notification cursor required' using errcode = '22023';
  end if;

  with candidate as (
    select
      item.id,
      item.workspace_id,
      recipient.event_id,
      event.type_key,
      event.schema_version,
      item.title,
      item.body,
      item.safe_preview,
      item.action_url,
      item.group_key,
      item.created_at,
      item.seen_at,
      item.read_at,
      item.dismissed_at,
      item.visibility_state
    from public.notification_inbox_items item
    join public.notification_recipients recipient
      on recipient.id = item.recipient_projection_id
     and recipient.workspace_id = item.workspace_id
    join public.notification_events event
      on event.id = recipient.event_id
     and event.workspace_id = recipient.workspace_id
    where item.workspace_id = target_workspace_id
      and recipient.recipient_user_id = get_notification_inbox_v2_service.actor_user_id
      and item.dismissed_at is null
      and item.visibility_state = 'visible'
      and (
        target_cursor_created_at is null
        or (item.created_at, item.id) < (target_cursor_created_at, target_cursor_id)
      )
    order by item.created_at desc, item.id desc
    limit effective_limit + 1
  ), page as (
    select * from candidate
    order by created_at desc, id desc
    limit effective_limit
  )
  select jsonb_build_object(
    'workspace_id', target_workspace_id,
    'unread_count', (
      select count(*)
      from public.notification_inbox_items unread_item
      join public.notification_recipients unread_recipient
        on unread_recipient.id = unread_item.recipient_projection_id
       and unread_recipient.workspace_id = unread_item.workspace_id
      where unread_item.workspace_id = target_workspace_id
        and unread_recipient.recipient_user_id = get_notification_inbox_v2_service.actor_user_id
        and unread_item.read_at is null
        and unread_item.dismissed_at is null
        and unread_item.visibility_state = 'visible'
    ),
    'next_cursor', case
      when (select count(*) from candidate) > effective_limit then (
        select jsonb_build_object('created_at', created_at, 'id', id)
        from page
        order by created_at asc, id asc
        limit 1
      )
      else null
    end,
    'items', coalesce((
      select jsonb_agg(to_jsonb(page_row) order by page_row.created_at desc, page_row.id desc)
      from page page_row
    ), '[]'::jsonb)
  ) into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_notification_inbox_v2_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_cursor_created_at" timestamp with time zone, "target_cursor_id" "uuid", "target_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_inbox_v2_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_category" "text", "target_severity" "text", "target_read_state" "text", "target_cursor_created_at" timestamp with time zone, "target_cursor_id" "uuid", "target_limit" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  effective_limit integer := greatest(1, least(coalesce(target_limit, 30), 50));
begin
  if target_workspace_id is not null then
    perform app_private.authorize(actor_user_id, target_workspace_id, 'notifications.read_own');
  end if;
  if (target_cursor_created_at is null) <> (target_cursor_id is null) then
    raise exception 'complete notification cursor required' using errcode = '22023';
  end if;
  if target_category is not null and target_category not in (
    'security', 'schedule', 'requests',
    'payroll', 'people', 'communications', 'system',
    'announcement', 'request'
  ) then
    raise exception 'valid notification category required' using errcode = '22023';
  end if;
  if target_severity is not null and target_severity not in ('info', 'success', 'warning', 'action_required') then
    raise exception 'valid notification severity required' using errcode = '22023';
  end if;
  if target_read_state is not null and target_read_state not in ('all', 'seen', 'unseen', 'read', 'unread') then
    raise exception 'valid notification read state required' using errcode = '22023';
  end if;

  with all_items as (
    select
      item.id,
      item.workspace_id,
      catalog.category,
      event.type_key,
      event.schema_version,
      catalog.severity,
      item.title,
      item.body,
      case when target_workspace_id is null then (select w.name from public.workspaces w where w.id=item.workspace_id)||' · A document update is available.' else item.safe_preview end as safe_preview,
      item.action_url,
      item.group_key,
      'notification_event'::text as source_type,
      event.id as source_id,
      item.created_at,
      item.seen_at,
      item.read_at,
      item.dismissed_at,
      item.visibility_state
    from public.notification_inbox_items item
    join public.notification_recipients recipient
      on recipient.id = item.recipient_projection_id
     and recipient.workspace_id = item.workspace_id
    join public.notification_events event
      on event.id = recipient.event_id
     and event.workspace_id = recipient.workspace_id
    join public.notification_catalog catalog
      on catalog.type_key = event.type_key
     and catalog.schema_version = event.schema_version
    where (item.workspace_id = target_workspace_id or (target_workspace_id is null and app_private.document_account_inbox_allowed(item.id,get_notification_inbox_v2_service.actor_user_id)))
      and recipient.recipient_user_id = get_notification_inbox_v2_service.actor_user_id
      and item.dismissed_at is null
      and item.visibility_state = 'visible'

    union all
    select a.id,null::uuid,'security',a.type_key,a.schema_version,c.severity,t.content->>'title',t.content->>'body',
     t.content->>'safe_preview','/app/account/security',null::text,'account_security',a.event_id,a.created_at,a.seen_at,a.read_at,a.dismissed_at,'visible'
    from public.account_notification_items a join public.notification_catalog c using(type_key,schema_version)
    join public.notification_template_versions t using(type_key,schema_version)
    where a.user_id=actor_user_id and a.dismissed_at is null and t.channel='in_app' and t.locale='en' and t.status='published'
  ), candidate as (
    select * from all_items item where true
      and (
        target_category is null
        or item.category = target_category
        or (target_category = 'announcement' and item.category = 'communications')
        or (target_category = 'request' and item.category = 'requests')
      )
      and (target_severity is null or item.severity = target_severity)
      and (
        target_read_state is null
        or target_read_state = 'all'
        or (target_read_state = 'seen' and item.seen_at is not null)
        or (target_read_state = 'unseen' and item.seen_at is null)
        or (target_read_state = 'read' and item.read_at is not null)
        or (target_read_state = 'unread' and item.read_at is null)
      )
      and (
        target_cursor_created_at is null
        or (item.created_at, item.id) < (target_cursor_created_at, target_cursor_id)
      )
    order by item.created_at desc, item.id desc
    limit effective_limit + 1
  ), page as (
    select * from candidate
    order by created_at desc, id desc
    limit effective_limit
  )
  select jsonb_build_object(
    'workspace_id', target_workspace_id,
    'unread_count', (select count(*) from public.account_notification_items where user_id=actor_user_id and read_at is null and dismissed_at is null) + (
      select count(*)
      from public.notification_inbox_items unread_item
      join public.notification_recipients unread_recipient
        on unread_recipient.id = unread_item.recipient_projection_id
       and unread_recipient.workspace_id = unread_item.workspace_id
      where (unread_item.workspace_id = target_workspace_id or (target_workspace_id is null and app_private.document_account_inbox_allowed(unread_item.id,get_notification_inbox_v2_service.actor_user_id)))
        and unread_recipient.recipient_user_id = get_notification_inbox_v2_service.actor_user_id
        and unread_item.read_at is null
        and unread_item.dismissed_at is null
        and unread_item.visibility_state = 'visible'
    ),
    'next_cursor', case
      when (select count(*) from candidate) > effective_limit then (
        select jsonb_build_object('created_at', created_at, 'id', id)
        from page
        order by created_at asc, id asc
        limit 1
      )
      else null
    end,
    'notifications', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', page_row.id,
        'workspace_id', page_row.workspace_id,
        'scope', case when page_row.workspace_id is null then 'account' else 'workspace' end,
        'category', page_row.category,
        'type_key', page_row.type_key,
        'severity', page_row.severity,
        'safe_preview', page_row.safe_preview,
        'title', page_row.title,
        'body', page_row.body,
        'action_url', page_row.action_url,
        'group_key', page_row.group_key,
        'source_type', page_row.source_type,
        'source_id', page_row.source_id,
        'created_at', page_row.created_at,
        'seen_at', page_row.seen_at,
        'read_at', page_row.read_at,
        'visibility_state', page_row.visibility_state
      ) order by page_row.created_at desc, page_row.id desc)
      from page page_row
    ), '[]'::jsonb)
  ) into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_notification_inbox_v2_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_category" "text", "target_severity" "text", "target_read_state" "text", "target_cursor_created_at" timestamp with time zone, "target_cursor_id" "uuid", "target_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_settings_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  can_write boolean;
  catalog_rows jsonb;
  policy_rows jsonb;
  role_rows jsonb;
  location_rows jsonb;
  audit_rows jsonb;
begin
  if not (
    public.service_actor_has_permission(actor_user_id, target_workspace_id, 'notifications.settings.read')
    or public.service_actor_has_permission(actor_user_id, target_workspace_id, 'notifications.settings.write')
  ) then
    raise exception 'notification settings read access required' using errcode = '42501';
  end if;

  can_write := public.service_actor_has_permission(
    actor_user_id,
    target_workspace_id,
    'notifications.settings.write'
  );

  select coalesce(jsonb_agg(jsonb_build_object(
    'type_key', entry.type_key,
    'schema_version', entry.schema_version,
    'category', entry.category,
    'severity', entry.severity,
    'sensitivity', entry.sensitivity,
    'supported_channels', to_jsonb(entry.supported_channels),
    'default_cadence', entry.default_cadence,
    'action_route', entry.action_route_contract->>'route',
    'mandatory_in_app', entry.mandatory_in_app,
    'policy', jsonb_build_object(
      'id', policy.id,
      'scope', jsonb_build_object('kind', 'global', 'id', null, 'name', 'Organization'),
      'enabled', coalesce(policy.enabled, true),
      'allowed_channels', coalesce(to_jsonb(policy.allowed_channels), to_jsonb(entry.supported_channels)),
      'cadence', coalesce(policy.cadence, entry.default_cadence),
      'version', policy.version,
      'updated_by', policy.updated_by,
      'updated_at', policy.updated_at,
      'source', case when policy.id is null then 'catalog_default' else 'organization_policy' end
    )
  ) order by entry.category, entry.type_key), '[]'::jsonb)
  into catalog_rows
  from public.notification_catalog entry
  left join public.notification_org_policies policy
    on policy.workspace_id = target_workspace_id
   and policy.type_key = entry.type_key
   and policy.schema_version = entry.schema_version
   and policy.role_id is null
   and policy.location_id is null
  where entry.notification_scope = 'workspace' and entry.lifecycle = 'active';

  select coalesce(jsonb_agg(jsonb_build_object(
    'type_key', policy.type_key,
    'schema_version', policy.schema_version,
    'id', policy.id,
    'scope', jsonb_build_object(
      'kind', case
        when policy.role_id is not null then 'role'
        when policy.location_id is not null then 'location'
        else 'global'
      end,
      'id', coalesce(policy.role_id, policy.location_id),
      'name', coalesce(role_row.name, location.name, 'Organization')
    ),
    'enabled', policy.enabled,
    'allowed_channels', to_jsonb(policy.allowed_channels),
    'cadence', policy.cadence,
    'version', policy.version,
    'updated_by', policy.updated_by,
    'updated_at', policy.updated_at,
    'source', 'organization_policy'
  ) order by policy.type_key, coalesce(role_row.name, location.name, 'Organization')), '[]'::jsonb)
  into policy_rows
  from public.notification_org_policies policy
  left join public.workspace_roles role_row
    on role_row.id = policy.role_id and role_row.workspace_id = policy.workspace_id
  left join public.locations location
    on location.id = policy.location_id and location.workspace_id = policy.workspace_id
  where policy.workspace_id = target_workspace_id;

  select coalesce(jsonb_agg(jsonb_build_object('id', role_row.id, 'name', role_row.name)
    order by role_row.sort_order, role_row.name), '[]'::jsonb)
  into role_rows
  from public.workspace_roles role_row
  where role_row.workspace_id = target_workspace_id;

  select coalesce(jsonb_agg(jsonb_build_object('id', location.id, 'name', location.name)
    order by location.sort_order, location.name), '[]'::jsonb)
  into location_rows
  from public.locations location
  where location.workspace_id = target_workspace_id
    and location.archived_at is null;

  select coalesce(jsonb_agg(to_jsonb(audit_item) order by audit_item.occurred_at desc, audit_item.id desc), '[]'::jsonb)
  into audit_rows
  from (
    select
      log.id,
      log.action,
      log.target_type,
      log.target_id,
      log.actor_user_id,
      log.reason,
      case when jsonb_typeof(log.metadata->'before_version') = 'number'
        then (log.metadata->>'before_version')::integer else null end as before_version,
      case when jsonb_typeof(log.metadata->'after_version') = 'number'
        then (log.metadata->>'after_version')::integer else null end as after_version,
      log.occurred_at
    from public.notification_audit_log log
    where log.workspace_id = target_workspace_id
      and log.action in ('notification.policy.saved', 'notification.policy.reset')
    order by log.occurred_at desc, log.id desc
    limit 50
  ) audit_item;

  return jsonb_build_object(
    'workspace_id', target_workspace_id,
    'can_write', can_write,
    'catalog', catalog_rows,
    'policies', policy_rows,
    'roles', role_rows,
    'locations', location_rows,
    'audit', audit_rows
  );
end;
$$;


ALTER FUNCTION "public"."get_notification_settings_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_user_preferences_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; account_catalog jsonb;
begin
 if not exists(select 1 from auth.users where id=actor_user_id and deleted_at is null) then raise exception 'account session required' using errcode='42501'; end if;
 if target_workspace_id is not null and not exists(select 1 from public.workspaces where id=target_workspace_id and lifecycle_status in ('active','closure_scheduled')) then raise exception 'notification preference access required' using errcode='42501'; end if;
 if target_workspace_id is null then
  result:=jsonb_build_object('workspace_id',null,'can_write',false,'workspaces','[]'::jsonb,'catalog','[]'::jsonb,'preferences','[]'::jsonb);
 else
  result:=public.get_notification_user_preferences_workspace_base(actor_user_id,target_workspace_id);
  result:=jsonb_set(result,'{workspaces}',coalesce((select jsonb_agg(w) from jsonb_array_elements(result->'workspaces') w where exists(select 1 from public.workspaces where id=(w->>'id')::uuid and lifecycle_status in ('active','closure_scheduled'))),'[]'::jsonb));
  result:=jsonb_set(result,'{catalog}',coalesce((select jsonb_agg(e||jsonb_build_object('default_channels',public.notification_default_channels_service(actor_user_id,e->>'type_key')))
   from jsonb_array_elements(result->'catalog') e where not exists(select 1 from public.notification_catalog c where c.type_key=e->>'type_key' and c.notification_scope='account')),'[]'::jsonb));
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('type_key',c.type_key,'scope','account','title',t.content->>'title','description',t.content->>'body','mandatory_in_app',true,'delivery','transactional_in_app') order by c.type_key),'[]'::jsonb)
 into account_catalog from public.notification_catalog c join public.notification_template_versions t using(type_key,schema_version)
 where c.notification_scope='account' and c.lifecycle='active' and t.channel='in_app' and t.locale='en' and t.status='published';
 return result||jsonb_build_object('account_catalog',account_catalog,'email_channel_reason',case when exists(select 1 from auth.users where id=actor_user_id and email_confirmed_at is not null) then 'delivery_unavailable' else 'email_unverified' end);
end; $$;


ALTER FUNCTION "public"."get_notification_user_preferences_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notification_user_preferences_workspace_base"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  actor_role_id uuid;
begin
  select membership.role_id into actor_role_id
  from public.workspace_memberships membership
  where membership.workspace_id = target_workspace_id
    and membership.user_id = actor_user_id
    and membership.status = 'active';

  if actor_role_id is null then
    raise exception 'notification preference access required' using errcode = '42501';
  end if;

  select jsonb_build_object(
    'workspace_id', target_workspace_id,
    'can_write', true,
    'workspaces', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', workspace.id,
        'name', workspace.name,
        'role', member.role,
        'isActive', workspace.id = target_workspace_id,
        'onboarding', jsonb_build_object(
          'status', coalesce(onboarding.status, 'complete'::public.onboarding_status),
          'currentStep', coalesce(onboarding.current_step, 2)
        )
      ) order by workspace.name, workspace.id)
      from public.workspace_memberships member
      join public.workspaces workspace
        on workspace.id = member.workspace_id
      left join public.workspace_onboarding onboarding
        on onboarding.workspace_id = workspace.id
      where member.user_id = actor_user_id
        and member.status = 'active'
    ), '[]'::jsonb),
    'catalog', coalesce((
      select jsonb_agg(jsonb_build_object(
        'type_key', catalog.type_key,
        'schema_version', catalog.schema_version,
        'category', catalog.category,
        'severity', catalog.severity,
        'sensitivity', catalog.sensitivity,
        'supported_channels', to_jsonb(catalog.supported_channels),
        'default_cadence', catalog.default_cadence,
        'mandatory_in_app', catalog.mandatory_in_app,
        'channel_controls', (
          select jsonb_agg(jsonb_build_object(
            'channel', channel.value,
            'locked', public.notification_user_channel_lock_reason_service(
              actor_user_id,
              target_workspace_id,
              catalog.type_key,
              channel.value
            ) <> 'available',
            'reason_code', public.notification_user_channel_lock_reason_service(
              actor_user_id,
              target_workspace_id,
              catalog.type_key,
              channel.value
            )
          ) order by channel.ordinality)
          from unnest(array['in_app', 'email', 'push']::text[])
            with ordinality as channel(value, ordinality)
        )
      ) order by catalog.category, catalog.type_key)
      from public.notification_catalog catalog
      where catalog.lifecycle = 'active'
    ), '[]'::jsonb),
    'preferences', coalesce((
      select jsonb_agg(public.notification_user_preference_to_json(preference)
        order by preference.preference_scope, preference.scope_key)
      from public.notification_user_preferences preference
      where preference.workspace_id = target_workspace_id
        and preference.user_id = actor_user_id
    ), '[]'::jsonb)
  ) into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_notification_user_preferences_workspace_base"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_notifications_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_category" "text" DEFAULT NULL::"text", "target_unread_only" boolean DEFAULT false, "target_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone, "target_limit" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'notifications.read_own');
 if target_category is not null and target_category not in('announcement','request','schedule') then raise exception 'valid notification category required' using errcode='22023'; end if;
 select jsonb_build_object(
  'workspace_id',target_workspace_id,
  'unread_count',(select count(*) from public.notifications where workspace_id=target_workspace_id and recipient_user_id=actor_user_id and dismissed_at is null and read_at is null and created_at<=now()),
  'next_cursor',(select min(page.created_at) from (select notification.created_at from public.notifications notification where notification.workspace_id=target_workspace_id and notification.recipient_user_id=actor_user_id and notification.dismissed_at is null and notification.created_at<=now() and (target_category is null or notification.category::text=target_category) and (not target_unread_only or notification.read_at is null) and (target_cursor is null or notification.created_at<target_cursor) order by notification.created_at desc,notification.id limit greatest(1,least(target_limit,50))+1) page having count(*)>greatest(1,least(target_limit,50))),
  'notifications',coalesce((select jsonb_agg(jsonb_build_object('id',page.id,'workspace_id',page.workspace_id,'category',page.category,'title',page.title,'body',page.body,'action_url',page.action_url,'source_type',page.source_type,'source_id',page.source_id,'created_at',page.created_at,'read_at',page.read_at) order by page.created_at desc,page.id) from (select notification.* from public.notifications notification where notification.workspace_id=target_workspace_id and notification.recipient_user_id=actor_user_id and notification.dismissed_at is null and notification.created_at<=now() and (target_category is null or notification.category::text=target_category) and (not target_unread_only or notification.read_at is null) and (target_cursor is null or notification.created_at<target_cursor) order by notification.created_at desc,notification.id limit greatest(1,least(target_limit,50))) page),'[]'::jsonb)
 ) into result;
 return result;
end; $$;


ALTER FUNCTION "public"."get_notifications_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_category" "text", "target_unread_only" boolean, "target_cursor" timestamp with time zone, "target_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_own_employee_avatar_path_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare avatar_path text; employee_id uuid;
begin
  if not app_private.workspace_allows_interactive_access(target_workspace_id)
    or not exists (select 1 from public.workspace_memberships m
      where m.workspace_id = target_workspace_id and m.user_id = actor_user_id and m.status = 'active') then
    raise exception 'workspace unavailable' using errcode = 'P0002';
  end if;
  select e.id, p.avatar_object_path into employee_id, avatar_path
  from public.employee_profiles e
  join public.employee_private_profiles p on p.employee_id = e.id and p.workspace_id = e.workspace_id
  where e.workspace_id = target_workspace_id and e.user_id = actor_user_id;
  if avatar_path is not null and avatar_path !~* (
    '^' || target_workspace_id::text || '/' || employee_id::text ||
    '/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp)$'
  ) then return null; end if;
  return avatar_path;
end;
$_$;


ALTER FUNCTION "public"."get_own_employee_avatar_path_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_own_legal_name_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS TABLE("legal_first_name" "text", "legal_middle_name" "text", "legal_last_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'workspace.setup');

  return query
  select private_profile.legal_first_name, private_profile.legal_middle_name,
    private_profile.legal_last_name
  from (select 1) always_one_row
  left join public.employee_profiles employee
    on employee.workspace_id = target_workspace_id
   and employee.user_id = actor_user_id
   and employee.archived_at is null
  left join public.employee_private_profiles private_profile
    on private_profile.employee_id = employee.id;
end;
$$;


ALTER FUNCTION "public"."get_own_legal_name_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_owner_setup_checklist_progress_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  progress public.owner_setup_checklist_progress%rowtype;
begin
  if actor_user_id is null then
    raise exception 'workspace management required' using errcode = '42501';
  end if;
  if not public.service_actor_has_permission(actor_user_id, target_workspace_id, 'settings.general.read') then
    raise exception 'workspace management required' using errcode = '42501';
  end if;

  select * into progress
  from public.owner_setup_checklist_progress
  where workspace_id = target_workspace_id
    and user_id = actor_user_id;

  return jsonb_build_object(
    'workspace_id', target_workspace_id,
    'user_id', actor_user_id,
    'completed_item_ids', coalesce(progress.completed_item_ids, '{}'::text[]),
    'closed_at', progress.closed_at
  );
end;
$$;


ALTER FUNCTION "public"."get_owner_setup_checklist_progress_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_schedule_edit_session_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_session public.schedule_edit_sessions%rowtype;
  result jsonb;
begin
  select * into target_session
  from public.schedule_edit_sessions session
  where session.id = target_session_id
    and session.workspace_id = target_workspace_id
    and session.holder_user_id = actor_user_id;
  if target_session.id is null then
    raise exception 'edit session not found' using errcode = 'P0002';
  end if;
  -- The edit's locations are still the person's to edit (B-3).
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit', target_locations => target_session.location_ids);

  with counterpart as materialized (
    select published.source_shift_id as edit_shift_id, published.employee_id, published.location_id,
      published.scheduled_date, published.start_time, published.end_time, published.time_timezone,
      published.availability_snapshot
    from public.schedule_location_publications publication
    join public.schedule_published_shifts published on published.publication_id = publication.id
    where publication.workspace_id = target_workspace_id and publication.status = 'current'
      and publication.week_start = target_session.week_start
      and publication.location_id = any (target_session.location_ids)
  ), week_availability as materialized (
    select * from app_private.schedule_week_availability(
      target_workspace_id, target_session.week_start,
      array(select s.employee_id from public.schedule_edit_session_shifts s
            where s.session_id = target_session.id and s.employee_id is not null
            union select c.employee_id from counterpart c where c.employee_id is not null),
      array(select s.location_id from public.schedule_edit_session_shifts s
            where s.session_id = target_session.id
            union select c.location_id from counterpart c))
  )
  select jsonb_build_object(
    'id', target_session.id,
    'workspace_id', target_session.workspace_id,
    'week_start', target_session.week_start,
    'source_kind', target_session.source_kind,
    'source_draft_id', target_session.source_draft_id,
    'source_revision', target_session.source_revision,
    'holder_user_id', target_session.holder_user_id,
    'holder_name', coalesce((
      select profile.display_name from public.user_profiles profile
      where profile.user_id = target_session.holder_user_id
    ), 'Manager'),
    'revision', target_session.revision,
    'dirty', target_session.dirty,
    -- DB-1c: how many steps Undo can take back.
    'undo_depth', (select count(*) from (select distinct step.step_at, step.step_xact
      from app_private.schedule_edit_undo_steps step where step.session_id = target_session.id) undo)::integer,
    'last_heartbeat', target_session.last_heartbeat,
    'expires_at', target_session.expires_at,
    'location_ids', to_jsonb(target_session.location_ids),
    'shifts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', shift.id,
        'location_id', shift.location_id,
        'employee_id', shift.employee_id,
        'job_id', shift.job_id,
        'shift_type_id', shift.shift_type_id,
        'scheduled_date', shift.scheduled_date,
        'time_basis',shift.time_basis,'time_snapshot',shift.time_snapshot,'time_timezone',shift.time_timezone,'start_time', to_char(shift.start_time, 'HH24:MI'),
        'end_time', to_char(shift.end_time, 'HH24:MI'),
        'crosses_midnight', shift.crosses_midnight,
        'unpaid_break_minutes', coalesce(shift.unpaid_break_minutes, 0),
        'hide_time_on_badge', coalesce(shift.hide_time_on_badge, false),
        'note', shift.note,
        'revision', shift.revision,
        'source_published_shift_id', shift.source_published_shift_id,
        'pending_op_type', shift.pending_op_type,
        'locked', shift.locked,
        'label_ids', to_jsonb(coalesce(shift.label_ids, '{}'::uuid[])),
        'label_names', to_jsonb(coalesce(shift.label_names, '{}'::text[])),
        -- K18, M11 in Edit mode (VAR-UYG-DB): read from the shift's published
        -- counterpart by the published week's own rule; a shift never
        -- published has none and says false.
        'availability_changed_after_publish', coalesce((
          -- KK-171: only while the edit keeps the published person on the card.
          select c.employee_id is not null and c.employee_id = shift.employee_id
            and exists (select 1 from week_availability week
              where week.employee_id = c.employee_id and week.location_id = c.location_id
                and week.unavailable && app_private.shift_time_range(c.scheduled_date, c.start_time, c.end_time, c.time_timezone))
            and not coalesce((c.availability_snapshot -> 'first' ->> 'has_own_mark')::boolean, true)
          from counterpart c where c.edit_shift_id = shift.id
          -- A shift moved to another location and published only there sits in
          -- two current publications; the one at its location today speaks.
          order by (c.location_id = shift.location_id) desc limit 1), false),
        'warning_codes', to_jsonb(array_remove(array[
          case when exists (
            select 1 from public.schedule_closures closure
            where closure.location_id = shift.location_id
              and closure.closed_date = shift.scheduled_date and closure.is_all_day
          ) then 'closed_location' end,
          -- Today's marks and approved leave, published or not (BL-186).
          case when shift.employee_id is not null and exists (select 1 from week_availability week
            where week.employee_id = shift.employee_id and week.location_id = shift.location_id
              and (week.unavailable + week.leave) && app_private.shift_time_range(shift.scheduled_date, shift.start_time, shift.end_time, shift.time_timezone)
          ) then 'availability' end,
          case when shift.employee_id is not null and exists (
            select 1 from public.schedule_edit_session_shifts other
            where other.session_id = target_session.id
              and other.employee_id = shift.employee_id
              and other.scheduled_date = shift.scheduled_date
              and other.id <> shift.id
              and not shift.crosses_midnight and not other.crosses_midnight
              and shift.start_time < other.end_time and shift.end_time > other.start_time
          ) then 'overlap' end
        ]::text[], null))
      ) order by shift.scheduled_date, shift.start_time, shift.id)
      from public.schedule_edit_session_shifts shift
      where shift.session_id = target_session.id
    ), '[]'::jsonb)
  ) into result;
  return result;
end;
$$;


ALTER FUNCTION "public"."get_schedule_edit_session_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_schedule_publication_history_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'workspace_id', target_workspace_id,
    'week_start', target_week_start,
    'publications', coalesce(jsonb_agg(jsonb_build_object(
      'id', publication.id,
      'location_id', publication.location_id,
      'location_name', location.name,
      'version', publication.version_number,
      'status', publication.status,
      'source_draft_id', publication.source_draft_id,
      'source_draft_revision', publication.source_draft_revision,
      'shift_count', (select count(*) from public.schedule_published_shifts shift where shift.publication_id = publication.id),
      'published_at', publication.published_at,
      'unpublished_at', publication.unpublished_at,
      'superseded_by', publication.superseded_by
    ) order by location.sort_order, publication.version_number desc) filter (where publication.id is not null), '[]'::jsonb)
  )
  from public.schedule_location_publications publication
  join public.locations location on location.id = publication.location_id
  where publication.workspace_id = target_workspace_id
    and publication.week_start = target_week_start
    and publication.location_id = any ((select app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.publish'))::uuid[]);
$$;


ALTER FUNCTION "public"."get_schedule_publication_history_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_schedule_publication_status_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'week_start', target_week_start,
    'week_end', target_week_start + 6,
    'week_start_day', coalesce(settings.week_start_day, 'monday'::public.schedule_week_start),
    'schedule_deadline_day', coalesce(settings.schedule_deadline_day, 'sunday'::public.schedule_deadline_day),
    'is_anchor_only', false,
    'locations', coalesce(jsonb_agg(jsonb_build_object(
      'id', location.id,
      'name', location.name,
      'color', null,
      'timezone', location.timezone,
      'status', case
        when publication.id is not null and published_counts.shift_count > 0 then 'published'
        else 'unpublished'
      end,
      'reason', case
        when publication.id is not null and published_counts.shift_count > 0 then 'active_publication_and_shifts'
        when publication.id is not null then 'no_published_shifts'
        else 'missing_publication'
      end,
      'publication_includes_location', publication.id is not null,
      'published_shift_count', coalesce(published_counts.shift_count, 0),
      'draft_shift_count', coalesce(draft_counts.shift_count, 0),
      'published_at', publication.published_at,
      'published_by_name', null,
      'source_draft_id', publication.source_draft_id,
      'source_draft_name', source_draft.name
    ) order by location.sort_order, location.name), '[]'::jsonb)
  )
  from public.workspace_scheduling_settings settings
  right join public.locations location
    on location.workspace_id = target_workspace_id
   and location.archived_at is null
  left join public.schedule_location_publications publication
    on publication.workspace_id = target_workspace_id
   and publication.location_id = location.id
   and publication.week_start = target_week_start
   and publication.status = 'current'
  left join public.schedule_drafts source_draft
    on source_draft.id = publication.source_draft_id
   and source_draft.workspace_id = target_workspace_id
  left join lateral (
    select count(*)::integer as shift_count
      from public.schedule_published_shifts shift
     where shift.publication_id = publication.id
  ) published_counts on true
  left join lateral (
    select count(*)::integer as shift_count
      from public.schedule_draft_shifts shift
      join public.schedule_drafts draft
        on draft.id = shift.draft_id
       and draft.workspace_id = shift.workspace_id
     where shift.workspace_id = target_workspace_id
       and shift.location_id = location.id
       and draft.week_start = target_week_start
       and draft.archived_at is null
  ) draft_counts on true
  where settings.workspace_id = target_workspace_id
    and location.id = any ((select app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.read'))::uuid[])
    and location.id = any ((select app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.edit'))::uuid[])
  group by settings.week_start_day, settings.schedule_deadline_day;
$$;


ALTER FUNCTION "public"."get_schedule_publication_status_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_schedule_read_model_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  settings public.workspace_scheduling_settings%rowtype;
  resolved_week_start date;
  -- ponytail: one mode today, live shifts elsewhere as ghosts. B4's
  -- published-plan preview (FB-6.1b) is a second way to fill ghost_shifts,
  -- not a second read.
  reach uuid[] := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.read');
  result jsonb;
begin
  -- Nowhere to read: the core says why. A workspace with no live location
  -- reads as empty to whoever would reach it, rather than refusing the owner.
  if cardinality(reach) = 0
     and (app_private.authz_reason(actor_user_id, target_workspace_id, 'schedule.read') is distinct from 'out_of_scope'
          or exists (select 1 from public.locations l where l.workspace_id = target_workspace_id and l.deleted_at is null)) then
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.read');
  end if;

  select * into settings
  from public.workspace_scheduling_settings
  where workspace_id = target_workspace_id;
  if settings.workspace_id is null then
    raise exception 'scheduling settings are unavailable' using errcode = 'P0002';
  end if;

  resolved_week_start := case settings.week_start_day
    when 'sunday' then target_date - extract(dow from target_date)::integer
    else target_date - (extract(isodow from target_date)::integer - 1)
  end;

  with allowed_locations as (
    select location.*
    from public.locations location
    where location.workspace_id = target_workspace_id
      and location.archived_at is null
      and location.id = any(reach)
  ), current_publications as (
    select publication.*
    from public.schedule_location_publications publication
    join allowed_locations location on location.id = publication.location_id
    where publication.week_start = resolved_week_start
      and publication.status = 'current'
  ), visible_employees as (
    select distinct employee.*
    from public.employee_profiles employee
    where employee.workspace_id = target_workspace_id
      and employee.archived_at is null
      and exists (
        select 1
        from public.employee_location_assignments assignment
        join allowed_locations location on location.id = assignment.location_id
        where assignment.employee_id = employee.id and assignment.ended_at is null
      )
  ), current_shifts as (
    select shift.*
    from public.schedule_published_shifts shift
    join current_publications publication on publication.id = shift.publication_id
    where shift.scheduled_date between resolved_week_start and resolved_week_start + 6
  ), ghost_shifts as (
    -- A shift somebody on this grid works at a location the actor does not
    -- reach: what the shift card says, not its note (REUSE B1, FB-6.1 T3).
    select shift.id, shift.employee_id, shift.location_id, location.name as location_name,
      shift.scheduled_date, shift.start_time, shift.end_time, shift.crosses_midnight,
      shift.job_id, job.name as job_name, shift.shift_type_id, shift_type.name as shift_type_name,
      shift.label_ids, shift.label_names
    from visible_employees employee
    join public.schedule_published_shifts shift
      on shift.employee_id = employee.id
     and shift.scheduled_date between resolved_week_start and resolved_week_start + 6
    join public.schedule_location_publications publication
      on publication.id = shift.publication_id and publication.status = 'current'
     and publication.week_start = resolved_week_start
    join public.locations location
      on location.id = shift.location_id and location.workspace_id = target_workspace_id
     and location.archived_at is null and location.deleted_at is null
    -- Names travel with the ghost, named as the grid names a real shift: the
    -- job and type, archived ones too (G8b, K8), null once deleted; the labels
    -- as the shift recorded them.
    left join public.jobs job
      on job.id = shift.job_id and job.workspace_id = target_workspace_id
     and job.deleted_at is null
    left join public.shift_types shift_type
      on shift_type.id = shift.shift_type_id and shift_type.workspace_id = target_workspace_id
     and shift_type.deleted_at is null
    where not exists (select 1 from allowed_locations allowed where allowed.id = shift.location_id)
  ), week_availability as materialized (
    select * from app_private.schedule_week_availability(
      target_workspace_id, resolved_week_start,
      (select coalesce(array_agg(employee.id), '{}') from visible_employees employee),
      (select coalesce(array_agg(location.id), '{}') from allowed_locations location))
  ), readable_notes as materialized (
    -- The note's words, by weekday from Sunday, for whoever the core lets read
    -- the note; nobody else gets them.
    -- Who last wrote it and when, named as the grid names a person (AVAIL-002).
    -- ponytail: a workspace-wide input-mode conversion also stamps the admin
    -- who changed the setting; keep the writer there if that ever misleads.
    select reminder.employee_id, to_jsonb(reminder.notes) as words,
      coalesce(nullif(author.preferred_name, ''), author.first_name) || ' ' || author.last_name as author,
      reminder.updated_at as edited_at
    from public.manager_weekly_reminders reminder
    left join public.employee_profiles author
      on author.workspace_id = reminder.workspace_id and author.user_id = reminder.updated_by
    where reminder.workspace_id = target_workspace_id and reminder.enabled
      and reminder.employee_id = any(array(select employee.id from visible_employees employee))
      and app_private.authz_reason(actor_user_id, target_workspace_id, 'availability.note_read',
        target_person => reminder.employee_id) is null
  )
  select jsonb_build_object(
    'workspace_id', target_workspace_id,
    'week_start', resolved_week_start,
    'week_start_day', settings.week_start_day,
    'settings', jsonb_build_object(
      'time_format', coalesce(settings.time_format, '12h'),
      'conflict_rules', settings.conflict_rules,
      'minimum_travel_minutes', settings.minimum_travel_minutes,
      'minimum_rest_minutes', settings.minimum_rest_minutes
    ),
    'shift_labels', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', label.id, 'name', label.name, 'color', label.color, 'sort_order', label.sort_order
      ) order by label.sort_order, label.name)
      from public.shift_labels label
      where label.workspace_id = target_workspace_id and label.archived_at is null
    ), '[]'::jsonb),
    'locations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', location.id,
        'name', location.name,
        'timezone', location.timezone,
        'sort_order', location.sort_order,
        'publication_status', case when publication.id is null then 'unpublished' else 'published' end,
        'published_at', publication.published_at
      ) order by location.sort_order, location.name)
      from allowed_locations location
      left join current_publications publication on publication.location_id = location.id
    ), '[]'::jsonb),
    'shift_types', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', shift_type.id, 'name', shift_type.name, 'color', shift_type.color,
        'sort_order', shift_type.sort_order,
        'default_revision',shift_type.default_revision,'default_start_time', case when shift_type.default_start_time is null then null else to_char(shift_type.default_start_time, 'HH24:MI') end,
        'default_end_time', case when shift_type.default_end_time is null then null else to_char(shift_type.default_end_time, 'HH24:MI') end
      ) order by shift_type.sort_order, shift_type.name)
      from public.shift_types shift_type
      where shift_type.workspace_id = target_workspace_id and shift_type.archived_at is null
    ), '[]'::jsonb),
    'employees', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', employee.id,
        'employee_code', employee.employee_code,
        'display_name', coalesce(nullif(employee.preferred_name, ''), employee.first_name) || ' ' || employee.last_name,
        'is_excluded_from_schedule', coalesce(employee.is_excluded_from_schedule, false),
        'location_ids', coalesce((select jsonb_agg(assignment.location_id order by assignment.location_id)
          from public.employee_location_assignments assignment
          join allowed_locations location on location.id = assignment.location_id
          where assignment.employee_id = employee.id and assignment.ended_at is null), '[]'::jsonb),
        'job_ids', coalesce((select jsonb_agg(assignment.job_id order by assignment.job_id)
          from public.employee_job_assignments assignment
          where assignment.employee_id = employee.id and assignment.ended_at is null), '[]'::jsonb),
        'primary_job_id', app_private.stored_primary_job(employee.id),
        -- The note's words and hours only for whoever may read the note (M12).
        'weekly_availability', coalesce((select jsonb_agg((week.projection - 'note_intervals')
            || jsonb_build_object('manager_notes', note.words,
              'note_author', note.author, 'note_edited_at', note.edited_at,
              'note_intervals', case when note.employee_id is null then '[]'::jsonb else week.projection -> 'note_intervals' end)
            order by week.location_id)
          from week_availability week
          left join readable_notes note on note.employee_id = employee.id
          where week.employee_id = employee.id
            and exists (select 1 from public.employee_location_assignments assignment
              where assignment.employee_id = employee.id and assignment.location_id = week.location_id
                and assignment.ended_at is null)), '[]'::jsonb)
      ) order by employee.last_name, employee.first_name, employee.id)
      from visible_employees employee
    ), '[]'::jsonb),
    'shifts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', shift.id,
        'location_id', shift.location_id,
        'employee_id', shift.employee_id,
        'job_id', shift.job_id,
        'shift_type_id', shift.shift_type_id,
        'scheduled_date', shift.scheduled_date,
        'time_basis',shift.time_basis,'time_snapshot',shift.time_snapshot,'time_timezone',shift.time_timezone,'start_time', to_char(shift.start_time, 'HH24:MI'),
        'end_time', to_char(shift.end_time, 'HH24:MI'),
        'crosses_midnight', shift.crosses_midnight,
        'unpaid_break_minutes', coalesce(shift.unpaid_break_minutes, 0),
        'hide_time_on_badge', coalesce(shift.hide_time_on_badge, false),
        'note', shift.note,
        'label_ids', to_jsonb(coalesce(shift.label_ids, '{}'::uuid[])),
        'label_names', to_jsonb(coalesce(shift.label_names, '{}'::text[])),
        -- K18, M11: the employee's own mark came after the shift was first
        -- published; approved time off is no change of availability.
        'availability_changed_after_publish', mark.own_mark
          and not coalesce((shift.availability_snapshot -> 'first' ->> 'has_own_mark')::boolean, true),
        'warning_codes', to_jsonb(array_remove(array[
          case when exists (
            select 1 from public.schedule_closures closure
            where closure.workspace_id = target_workspace_id and closure.location_id = shift.location_id
              and closure.closed_date = shift.scheduled_date and closure.is_all_day
          ) then 'closed_location' end,
          -- Today's marks and approved leave: a mark made after publishing shows
          -- here too (BL-186).
          case when mark.unavailable then 'availability' end,
          case when shift.employee_id is not null and exists (
            select 1 from current_shifts other
            where other.employee_id = shift.employee_id
              and other.scheduled_date = shift.scheduled_date
              and other.id <> shift.id
              and not shift.crosses_midnight and not other.crosses_midnight
              and shift.start_time < other.end_time and shift.end_time > other.start_time
          ) then 'overlap' end
        ]::text[], null))
      ) order by shift.scheduled_date, shift.start_time, shift.id)
      from current_shifts shift
      cross join lateral (
        select shift.employee_id is not null and exists (select 1 from week_availability week
          where week.employee_id = shift.employee_id and week.location_id = shift.location_id
            and (week.unavailable + week.leave) && app_private.shift_time_range(shift.scheduled_date, shift.start_time, shift.end_time, shift.time_timezone)
        ) as unavailable,
        shift.employee_id is not null and exists (select 1 from week_availability week
          where week.employee_id = shift.employee_id and week.location_id = shift.location_id
            and week.unavailable && app_private.shift_time_range(shift.scheduled_date, shift.start_time, shift.end_time, shift.time_timezone)
        ) as own_mark
      ) mark
    ), '[]'::jsonb),
    'ghost_shifts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', ghost.id,
        'employee_id', ghost.employee_id,
        'location_id', ghost.location_id,
        'location_name', ghost.location_name,
        'scheduled_date', ghost.scheduled_date,
        'start_time', to_char(ghost.start_time, 'HH24:MI'),
        'end_time', to_char(ghost.end_time, 'HH24:MI'),
        'crosses_midnight', ghost.crosses_midnight,
        'job_id', ghost.job_id,
        'job_name', ghost.job_name,
        'shift_type_id', ghost.shift_type_id,
        'shift_type_name', ghost.shift_type_name,
        'label_ids', to_jsonb(ghost.label_ids),
        'label_names', to_jsonb(ghost.label_names)
      ) order by ghost.scheduled_date, ghost.start_time, ghost.id)
      from ghost_shifts ghost
    ), '[]'::jsonb),
    'closures', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', closure.id, 'location_id', closure.location_id,
        'closed_date', closure.closed_date, 'title', closure.title,
        'is_all_day', closure.is_all_day
      ) order by closure.closed_date, closure.title)
      from public.schedule_closures closure
      join allowed_locations location on location.id = closure.location_id
      where closure.workspace_id = target_workspace_id
        and closure.closed_date between resolved_week_start and resolved_week_start + 6
    ), '[]'::jsonb)
  ) || app_private.schedule_departments_and_jobs(target_workspace_id)
    || app_private.schedule_referenced_catalog(target_workspace_id,
      array(select shift.job_id from current_shifts shift union select ghost.job_id from ghost_shifts ghost),
      array(select shift.shift_type_id from current_shifts shift
            union select ghost.shift_type_id from ghost_shifts ghost))
  into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_schedule_read_model_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_schedule_requests_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_time_off_queue" "text" DEFAULT 'needs_review'::"text", "target_location_id" "uuid" DEFAULT NULL::"uuid", "target_search" "text" DEFAULT ''::"text", "target_time_off_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone, "target_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare can_time_off boolean; can_shift boolean; time_rows jsonb; locations jsonb;
 time_count integer; time_cursor timestamptz; time_scope uuid[]; shift_scope uuid[]; reached uuid[];
begin
 if target_time_off_queue not in ('needs_review', 'closed') or target_limit not between 1 and 100 then raise exception 'invalid schedule request query' using errcode = '22023'; end if;
 time_scope := app_private.scope_set(actor_user_id, target_workspace_id, 'requests.read');
 shift_scope := app_private.scope_set(actor_user_id, target_workspace_id, 'exchange.read');
 -- The people whose time off the actor reads.
 -- ponytail: one core call per person of the workspace; ask per page if workspaces grow past a few hundred people.
 reached := coalesce((select array_agg(e.id) from public.employee_profiles e where e.workspace_id = target_workspace_id
   and app_private.time_off_reason(actor_user_id, target_workspace_id, 'requests.read', e.id) is null), '{}');
 can_time_off := cardinality(reached) > 0;
 can_shift := cardinality(shift_scope) > 0;
 -- Neither list anywhere: say why not.
 if not can_time_off and not can_shift then
  perform app_private.authorize(actor_user_id, target_workspace_id, 'requests.read', target_locations => time_scope);
 end if;
 if target_location_id is not null then
  if can_time_off and app_private.time_off_reason(actor_user_id, target_workspace_id, 'requests.read', null, target_location_id) is not null then
   raise exception 'Not allowed' using errcode = '42501', detail = 'requests.read',
     hint = 'authz.' || app_private.time_off_reason(actor_user_id, target_workspace_id, 'requests.read', null, target_location_id);
  end if;
  if can_shift then perform app_private.authorize(actor_user_id, target_workspace_id, 'exchange.read', array[target_location_id]); end if;
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name) order by l.name), '[]') into locations
 from public.locations l where l.workspace_id = target_workspace_id and l.archived_at is null and (l.id = any (time_scope) or l.id = any (shift_scope));
 select count(*) into time_count from public.schedule_time_off_requests r
 where can_time_off and r.workspace_id = target_workspace_id and r.status = 'pending' and r.employee_id = any (reached);
 -- ponytail: the queue past the cursor is read whole to find the page edge; bound it by the edge's send time if one queue grows past tens of thousands of requests.
 with filtered as (
  select r.* from public.schedule_time_off_requests r join public.employee_profiles e on e.id = r.employee_id
  where can_time_off and r.workspace_id = target_workspace_id and r.employee_id = any (reached)
   and (target_location_id is null
        or exists (select 1 from public.time_off_required_locations x where x.request_id = r.id and x.location_id = target_location_id))
   and ((target_time_off_queue = 'needs_review' and r.status = 'pending') or (target_time_off_queue = 'closed' and r.status <> 'pending'))
   and (target_time_off_cursor is null or r.created_at < target_time_off_cursor)
   and (btrim(target_search) = '' or concat_ws(' ', e.first_name, e.last_name, e.preferred_name, r.reason) ilike '%' || btrim(target_search) || '%')
 ), edge as (
  -- The send time of the page's last row.
  select f.created_at from filtered f order by f.created_at desc, f.id offset target_limit - 1 limit 1
 ), page as (
  -- A page takes every request sent at its edge's time, so "Older" starts right after it.
  select f.* from filtered f where not exists (select 1 from edge) or f.created_at >= (select edge.created_at from edge)
 )
 select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'employee_id', r.employee_id,
   'employee_name', concat_ws(' ', coalesce(nullif(e.preferred_name, ''), e.first_name), e.last_name),
   'request_type', r.request_type, 'reason', r.reason,
   'cancellation', public.time_off_cancellation_context(target_workspace_id, r.id), 'status', r.status,
   'start_date', (select min(s.segment_date) from public.schedule_time_off_segments s where s.request_id = r.id),
   'end_date', (select max(s.segment_date) from public.schedule_time_off_segments s where s.request_id = r.id),
   'revision', r.revision, 'created_at', r.created_at, 'decide_by', r.decide_by,
   'conflict_count', public.time_off_request_assignment_count(target_workspace_id, r.id),
   'segments', public.time_off_request_periods(r.id, target_workspace_id),
   'progress', case when r.status = 'pending' then app_private.time_off_progress(get_schedule_requests_service.actor_user_id, target_workspace_id, r.id) end,
   'events', coalesce((select jsonb_agg(jsonb_build_object('id', ev.id, 'action', ev.action,
       'actor_name', case when ev.actor_user_id is null then 'System' else coalesce(nullif(up.display_name, ''), 'Team member') end,
       'note', ev.note, 'created_at', ev.created_at,
       'released_assignments', public.time_off_event_released_assignments(get_schedule_requests_service.actor_user_id, target_workspace_id, ev.id)) order by ev.created_at)
     from public.schedule_time_off_events ev left join public.user_profiles up on up.user_id = ev.actor_user_id where ev.request_id = r.id), '[]'))
   order by r.created_at desc, r.id), '[]'),
   -- "Older" only while something was sent before the edge.
   (select edge.created_at from edge where exists (select 1 from filtered f where f.created_at < edge.created_at))
 into time_rows, time_cursor
 from page r join public.employee_profiles e on e.id = r.employee_id;
 return jsonb_build_object('workspace_id', target_workspace_id,
   'time_format', (select time_format from public.workspace_scheduling_settings where workspace_id = target_workspace_id),
   'locations', locations, 'time_off_pending_count', time_count, 'time_off_next_cursor', time_cursor, 'time_off_requests', time_rows);
end;
$$;


ALTER FUNCTION "public"."get_schedule_requests_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_time_off_queue" "text", "target_location_id" "uuid", "target_search" "text", "target_time_off_cursor" timestamp with time zone, "target_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_schedule_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; template_scope uuid[]; org_wide boolean;
begin
 perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.templates.read',
   target_locations => app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.templates.read'));
 template_scope := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.templates.read');
 org_wide := app_private.authz_reason(actor_user_id, target_workspace_id, 'schedule.templates.read', '{}'::uuid[]) is null;
 select jsonb_build_object('template',jsonb_build_object('id',t.id,'workspace_id',t.workspace_id,'name',t.name,'revision',t.revision,
   'shift_count',(select count(*) from public.schedule_template_shifts s where s.template_id=t.id and s.location_id=any(places.ids)),
   'open_slot_count',(select count(*) from public.schedule_template_shifts s where s.template_id=t.id and s.location_id=any(places.ids) and s.employee_id is null),
   'created_by_name',coalesce(u.display_name,'Manager'),'updated_at',t.updated_at),
   'shifts',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'location_id',s.location_id,'employee_id',s.employee_id,'job_id',s.job_id,
     'shift_type_id',s.shift_type_id,'day_offset',s.day_offset,'time_basis',s.time_basis,'time_snapshot',s.time_snapshot,'time_timezone',s.time_timezone,'start_time',to_char(s.start_time,'HH24:MI'),'end_time',to_char(s.end_time,'HH24:MI'),
     'crosses_midnight',s.crosses_midnight,'hide_time_on_badge',coalesce(s.hide_time_on_badge,false),'label_ids',to_jsonb(coalesce(s.label_ids,'{}'::uuid[])),
     'label_names',to_jsonb(coalesce(s.label_names,'{}'::text[])),'note',s.note,'unpaid_break_minutes',s.unpaid_break_minutes) order by s.day_offset,s.start_time,s.id) from public.schedule_template_shifts s where s.template_id=t.id and s.location_id=any(places.ids)),'[]'::jsonb))
 into result from public.schedule_templates t join public.user_profiles u on u.user_id=t.created_by
 cross join lateral (select public.live_location_ids(t.workspace_id, array(select distinct s.location_id from public.schedule_template_shifts s where s.template_id=t.id)) ids) places
 where t.id=target_template_id and t.workspace_id=target_workspace_id
 and (org_wide or (cardinality(places.ids)>0 and places.ids <@ template_scope));
 if result is null then raise exception 'schedule template not found' using errcode='P0002'; end if; return result;
end; $$;


ALTER FUNCTION "public"."get_schedule_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_workspace_dashboard_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me app_private.actor_state := app_private.actor(actor_user_id, target_workspace_id);
  read_rule app_private.authz_actions;
  schedule_places uuid[];
  result jsonb;
begin
  -- Workspace home is the to-do list's page: one gate (KK-32, KK-34).
  perform app_private.authorize(actor_user_id, target_workspace_id, 'workspace.todos');
  select * into read_rule from app_private.authz_actions r where r.key = 'employee.read';
  schedule_places := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.read');

  perform public.sync_expiring_document_todos_service(target_workspace_id);

  select jsonb_build_object(
    'workspace_id', target_workspace_id,
    'display_name', coalesce(profile.display_name, 'Manager'),
    'metrics', jsonb_build_object(
      'today_shift_count', (
        select count(*)
        from public.schedule_published_shifts shift
        join public.schedule_location_publications publication
          on publication.id = shift.publication_id and publication.status = 'current'
        join public.locations location on location.id = shift.location_id
        where shift.workspace_id = target_workspace_id
          -- Every zone's date is within a day of UTC's: keeps the date index range.
          and shift.scheduled_date between (now() at time zone 'UTC')::date - 1 and (now() at time zone 'UTC')::date + 1
          and shift.location_id = any(schedule_places)
          and shift.scheduled_date = (now() at time zone location.timezone)::date
      ),
      'today_open_shift_count', (
        select count(*)
        from public.schedule_published_shifts shift
        join public.schedule_location_publications publication
          on publication.id = shift.publication_id and publication.status = 'current'
        join public.locations location on location.id = shift.location_id
        where shift.workspace_id = target_workspace_id
          -- Every zone's date is within a day of UTC's: keeps the date index range.
          and shift.scheduled_date between (now() at time zone 'UTC')::date - 1 and (now() at time zone 'UTC')::date + 1
          and shift.location_id = any(schedule_places)
          and shift.employee_id is null
          and shift.scheduled_date = (now() at time zone location.timezone)::date
      ),
      'pending_time_off_count', (select count(*) from public.schedule_time_off_requests request where request.workspace_id = target_workspace_id and request.status = 'pending'
        and app_private.time_off_reason(actor_user_id, target_workspace_id, 'requests.read', request.employee_id) is null),
      'unread_notification_count', (select count(*) from public.notifications notification where notification.workspace_id = target_workspace_id and notification.recipient_user_id = actor_user_id and notification.dismissed_at is null and notification.read_at is null and notification.created_at <= now())
    ),
    'today_ends_at', (
      select min(((now() at time zone location.timezone)::date + 1)::timestamp at time zone location.timezone)
      from public.locations location
      where location.workspace_id = target_workspace_id
        and location.id = any(schedule_places)
    ),
    'announcements', coalesce((select jsonb_agg(item.value) from (select value from jsonb_array_elements((public.get_announcements_service(actor_user_id, target_workspace_id)->'announcements')) value where value->>'status' in ('published', 'scheduled') and (value->>'publish_at')::timestamptz <= now() limit 5) item), '[]'::jsonb),
    'notifications', coalesce(public.get_notifications_service(actor_user_id, target_workspace_id, null, false, null, 5)->'notifications', '[]'::jsonb),
    'todos', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', todo.id,
        'workspace_id', todo.workspace_id,
        'title', todo.title,
        'body', todo.body,
        'severity', todo.severity,
        'status', todo.status,
        'system_generated', todo.system_generated,
        'source_type', todo.source_type,
        'source_id', todo.source_id,
        'source_key', todo.source_key,
        'employee_id', todo.employee_id,
        'due_at', todo.due_at,
        'action_url', todo.action_url,
        'created_at', todo.created_at
      ) order by todo.due_at nulls last, todo.created_at, todo.id)
      from (
        select todo.*
        from public.workspace_todos todo
        where todo.workspace_id = target_workspace_id
          and todo.status = 'open'::public.workspace_todo_status
          and (
            todo.employee_id is null
            or app_private.authz_check(me, read_rule, null, todo.employee_id, null) is null
          )
        order by todo.due_at nulls last, todo.created_at, todo.id
        limit 5
      ) todo
    ), '[]'::jsonb),
    'layout', jsonb_build_object(
      'widget_order', public.normalize_workspace_widget_order(preference.widget_order),
      'hidden_widget_ids', array(
        select distinct value
        from unnest(coalesce(preference.hidden_widget_ids, '{}'::text[])) value
        where value = any(array[
          'operations',
          'pending_requests',
          'open_shifts',
          'announcements',
          'todos',
          'notifications',
          'quick_actions'
        ])
      )
    )
  ) into result
  from public.user_profiles profile
  left join public.workspace_layout_preferences preference
    on preference.workspace_id = target_workspace_id
   and preference.user_id = actor_user_id
  where profile.user_id = actor_user_id;

  return result;
end;
$$;


ALTER FUNCTION "public"."get_workspace_dashboard_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


