CREATE OR REPLACE FUNCTION "public"."guard_time_off_requested_period"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare parent public.schedule_time_off_requests%rowtype; resolved jsonb;
begin
 select * into parent from public.schedule_time_off_requests where id = coalesce(new.request_id, old.request_id);
 if tg_op in ('UPDATE', 'DELETE') then
  if tg_op = 'DELETE' or (to_jsonb(new) - 'status') is distinct from (to_jsonb(old) - 'status') then
   raise exception 'Requested time-off periods are immutable; submit a new request to change the hours' using errcode = '55000'; end if;
 end if;
 if tg_op = 'INSERT' then
  if parent.status <> 'pending' then raise exception 'Requested periods can only be added to a pending request' using errcode = '55000'; end if;
  if parent.request_type = 'time_off_cancellation' then
   if not exists (select 1 from public.time_off_cancellation_links cl
    join public.schedule_time_off_segments original on original.request_id = cl.parent_request_id and original.workspace_id = cl.workspace_id
    where cl.request_id = parent.id and cl.workspace_id = parent.workspace_id and original.time_timezone = new.time_timezone
     and public.time_off_effective_ranges(original.id) @> tstzrange(new.starts_at, new.ends_at, '[)'))
    or (new.segment_date, new.start_time, new.end_time, new.ends_next_day) is distinct from
     ((new.starts_at at time zone new.time_timezone)::date, (new.starts_at at time zone new.time_timezone)::time,
      (new.ends_at at time zone new.time_timezone)::time, (new.ends_at at time zone new.time_timezone)::date > (new.starts_at at time zone new.time_timezone)::date)
    then raise exception 'Cancellation hours must match approved leave in its original time zone' using errcode = '22023'; end if;
   return new;
  end if;
  resolved := public.time_off_resolve_period(jsonb_build_object('segment_date', new.segment_date, 'start_time', new.start_time, 'end_time', new.end_time,
   'ends_next_day', new.ends_next_day) || new.fold_choices, new.time_timezone);
  if (new.time_timezone, new.starts_at, new.ends_at) is distinct from
   (resolved ->> 'time_timezone', (resolved ->> 'starts_at')::timestamptz, (resolved ->> 'ends_at')::timestamptz) then
   raise exception 'Requested time-off clock and time-zone snapshot must agree' using errcode = '22023'; end if;
 end if;
 return case when tg_op = 'DELETE' then old else new end;
end $$;


ALTER FUNCTION "public"."guard_time_off_requested_period"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_weekly_onboarding_requirement"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare declared_at timestamptz;
begin
 if tg_op='INSERT' and new.kind='availability' and not app_private.ranks_as_employee(new.workspace_id,
  (select e.user_id from public.employee_profiles e where e.workspace_id=new.workspace_id and e.id=new.employee_id)) then
  return null;
 end if;
 if new.lifecycle_retired_at is not null or new.kind <> 'availability' or exists (
  select 1 from public.employee_onboarding_cases c where c.id=new.case_id and c.status in ('approved','cancelled')
 ) then return new; end if;
 select s.availability_onboarding_required into new.required
 from public.workspace_scheduling_settings s where s.workspace_id=new.workspace_id;
 if new.required is null then raise exception 'Scheduling settings unavailable' using errcode='P0002'; end if;
 new.blocks_activation:=new.required;
 new.requires_review:=false;
 select p.updated_at into declared_at from public.employee_weekly_preferences p
 where p.workspace_id=new.workspace_id and p.employee_id=new.employee_id;
 new.status:=case when declared_at is null then 'not_started' else 'completed' end;
 new.completed_at:=declared_at;
 new.rejection_reason:=null;
 new.reviewed_at:=null;
 new.reviewed_by:=null;
 return new;
end; $$;


ALTER FUNCTION "public"."guard_weekly_onboarding_requirement"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_weekly_preference_type_hours"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare must_have_hours boolean;
begin
 if new.archived_at is not null or new.deleted_at is not null then return new; end if;
 if tg_op='INSERT' then must_have_hours:=true;
 else must_have_hours:=old.archived_at is not null or old.deleted_at is not null
   or (new.default_start_time,new.default_end_time) is distinct from (old.default_start_time,old.default_end_time)
   or (select availability_input_mode='shift_type' from public.workspace_scheduling_settings where workspace_id=new.workspace_id);
 end if;
 if must_have_hours and (new.default_start_time is null or new.default_end_time is null
  or new.default_start_time=new.default_end_time or new.default_start_time='24:00'::time) then
  raise exception 'Set valid default start and end times for this shift type' using errcode='22023'; end if;
 return new;
end; $$;


ALTER FUNCTION "public"."guard_weekly_preference_type_hours"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."heartbeat_schedule_edit_session_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- The edit's locations are still the person's to edit (B-3).
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit', target_locations => session.location_ids)
  from public.schedule_edit_sessions session
  where session.id = target_session_id and session.workspace_id = target_workspace_id
    and session.holder_user_id = actor_user_id;
  update public.schedule_edit_sessions session
  set last_heartbeat = now(), expires_at = now() + interval '4 minutes'
  where session.id = target_session_id and session.workspace_id = target_workspace_id
    and session.holder_user_id = actor_user_id and session.status = 'active'
    and session.expires_at > now();
  if not found then
    if exists (select 1 from public.schedule_edit_sessions s
        where s.id = target_session_id and s.workspace_id = target_workspace_id
          and s.holder_user_id = actor_user_id and s.status <> 'active') then
      raise exception 'edit session closed' using errcode = 'PT409', hint = 'schedule.edit_session_closed';
    end if;
    raise exception 'edit lease expired' using errcode = 'PT409', hint = 'schedule.edit_lease_expired';
  end if;
  return public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id);
end;
$$;


ALTER FUNCTION "public"."heartbeat_schedule_edit_session_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid") OWNER TO "postgres";


