CREATE TABLE IF NOT EXISTS "public"."notification_outbox" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "event_id" "uuid" NOT NULL,
    "type_key" "text" NOT NULL,
    "schema_version" integer NOT NULL,
    "actor_user_id" "uuid",
    "subject_type" "text" NOT NULL,
    "subject_id" "text" NOT NULL,
    "payload" "jsonb" NOT NULL,
    "occurred_at" timestamp with time zone NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "lease_owner" "text",
    "lease_expires_at" timestamp with time zone,
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "notification_outbox_attempt_count_check" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "notification_outbox_check" CHECK (((("status" = 'leased'::"text") AND ("lease_owner" IS NOT NULL) AND ("lease_expires_at" IS NOT NULL)) OR ("status" <> 'leased'::"text"))),
    CONSTRAINT "notification_outbox_last_error_check" CHECK ((("last_error" IS NULL) OR ("char_length"("last_error") <= 2000))),
    CONSTRAINT "notification_outbox_payload_check" CHECK (("jsonb_typeof"("payload") = 'object'::"text")),
    CONSTRAINT "notification_outbox_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'leased'::"text", 'processed'::"text", 'retry'::"text", 'dead_letter'::"text"]))),
    CONSTRAINT "notification_outbox_subject_id_check" CHECK ((("char_length"("btrim"("subject_id")) >= 1) AND ("char_length"("btrim"("subject_id")) <= 160))),
    CONSTRAINT "notification_outbox_subject_type_check" CHECK ((("char_length"("btrim"("subject_type")) >= 1) AND ("char_length"("btrim"("subject_type")) <= 80)))
);


ALTER TABLE "public"."notification_outbox" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lease_notification_outbox_service"("target_worker_id" "text", "target_batch_size" integer DEFAULT 25, "target_lease_seconds" integer DEFAULT 60) RETURNS SETOF "public"."notification_outbox"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if char_length(btrim(coalesce(target_worker_id, ''))) not between 1 and 120 then
    raise exception 'valid notification worker id required' using errcode = '22023';
  end if;
  if target_batch_size not between 1 and 100 then
    raise exception 'notification batch size must be between 1 and 100' using errcode = '22023';
  end if;
  if target_lease_seconds not between 5 and 300 then
    raise exception 'notification lease seconds must be between 5 and 300' using errcode = '22023';
  end if;

  return query
  with candidates as (
    select outbox.id
    from public.notification_outbox outbox
    where (
        outbox.status in ('pending', 'retry')
        and outbox.available_at <= now()
      ) or (
        outbox.status = 'leased'
        and outbox.lease_expires_at <= now()
      )
    order by outbox.available_at, outbox.created_at, outbox.id
    for update skip locked
    limit target_batch_size
  )
  update public.notification_outbox outbox
  set status = 'leased',
      attempt_count = outbox.attempt_count + 1,
      lease_owner = btrim(target_worker_id),
      lease_expires_at = now() + make_interval(secs => target_lease_seconds),
      last_error = null
  from candidates
  where outbox.id = candidates.id
  returning outbox.*;
end;
$$;


ALTER FUNCTION "public"."lease_notification_outbox_service"("target_worker_id" "text", "target_batch_size" integer, "target_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leave_employee_onboarding_service"("target_user_id" "uuid", "expected_revision" integer, "target_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_case public.employee_onboarding_cases%rowtype;
  target_membership public.workspace_memberships%rowtype;
begin
  perform app_private.authorize(target_user_id, app_private.onboarding_self_workspace(target_user_id, target_workspace_id, true), 'onboarding.self');

  select onboarding.* into target_case
  from public.employee_onboarding_cases onboarding
  where onboarding.id = app_private.employee_onboarding_case_id(target_user_id, target_workspace_id)
  for update;

  if target_case.id is null then
    raise exception 'onboarding unavailable' using errcode = 'P0002';
  end if;
  if target_case.revision <> expected_revision then
    raise exception 'onboarding changed; refresh required' using errcode = 'PT409';
  end if;

  select membership.* into target_membership
  from public.workspace_memberships membership
  where membership.id = target_case.membership_id
    and membership.workspace_id = target_case.workspace_id
    and membership.user_id = target_user_id
  for update;

  if target_membership.id is null then
    raise exception 'workspace membership unavailable' using errcode = 'P0002';
  end if;
  if target_membership.status = 'active'::public.membership_status then
    raise exception 'active employees cannot leave onboarding' using errcode = '23514';
  end if;
  if target_membership.status <> 'pending_activation'::public.membership_status then
    raise exception 'pending onboarding membership required' using errcode = '23514';
  end if;
  if target_case.status = 'approved'::public.employee_onboarding_case_status then
    raise exception 'approved onboarding cannot be cancelled' using errcode = '22023';
  end if;

  perform set_config('app.workspace_closure', 'on', true);

  update public.workspace_memberships
  set status = 'suspended'::public.membership_status,
      updated_at = now()
  where id = target_membership.id
    and workspace_id = target_case.workspace_id;

  update public.employee_onboarding_cases
  set status = 'cancelled'::public.employee_onboarding_case_status,
      revision = revision + 1,
      updated_at = now()
  where id = target_case.id
  returning * into target_case;

  insert into public.onboarding_events (
    workspace_id, employee_id, case_id, actor_user_id, action, target_type, target_id
  ) values (
    target_case.workspace_id, target_case.employee_id, target_case.id, target_user_id,
    'onboarding.left', 'onboarding_case', target_case.id::text
  );

  insert into public.audit_events (
    workspace_id, actor_user_id, action, target_type, target_id, metadata
  ) values (
    target_case.workspace_id, target_user_id, 'employee_onboarding.left',
    'workspace_membership', target_membership.id::text,
    jsonb_build_object('employee_id', target_case.employee_id, 'case_id', target_case.id)
  );

  return jsonb_build_object(
    'status', 'left',
    'workspace_id', target_case.workspace_id,
    'employee_id', target_case.employee_id,
    'membership_id', target_membership.id,
    'revision', target_case.revision
  );
end;
$$;


ALTER FUNCTION "public"."leave_employee_onboarding_service"("target_user_id" "uuid", "expected_revision" integer, "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_employee_document_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "self_only" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,case when self_only then 'documents.self' else 'documents.read' end,
  target_locations=>case when self_only then null else app_private.scope_set(actor_user_id,target_workspace_id,'documents.read') end);
 if self_only is null then raise exception 'document audience required' using errcode='22023'; end if;
 return (select coalesce(jsonb_agg(app_private.document_obligation_json(app_private.document_view(actor_user_id,r)) order by r.sort_order,r.id),'[]')
 from public.employee_onboarding_requirements r where r.workspace_id=target_workspace_id and r.kind in ('document','acknowledgement')
 and (not self_only or r.lifecycle_user_id=actor_user_id)
 and app_private.document_row_readable(actor_user_id,r));
end;
$$;


ALTER FUNCTION "public"."list_employee_document_lifecycle_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "self_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_employees_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "include_archived" boolean DEFAULT false, "search_text" "text" DEFAULT ''::"text", "status_filter" "text" DEFAULT 'all'::"text", "page_limit" integer DEFAULT 100, "page_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "workspace_id" "uuid", "employee_code" "text", "first_name" "text", "last_name" "text", "preferred_name" "text", "display_name" "text", "invitation_email" "text", "start_date" "date", "primary_location_id" "uuid", "primary_location_name" "text", "location_count" bigint, "primary_job_id" "uuid", "primary_job_name" "text", "job_count" bigint, "role_name" "text", "display_status" "text", "archived_at" timestamp with time zone, "revision" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me app_private.actor_state := app_private.actor(actor_user_id, target_workspace_id);
  rule_row app_private.authz_actions;
  reason text;
begin
  select * into rule_row from app_private.authz_actions action where action.key = 'employee.list';
  if not found then
    raise exception 'core action employee.list is missing' using errcode = '22023';
  end if;
  -- May they list anybody at all; who, is answered row by row.
  reason := app_private.authz_check(me, rule_row, null, null, null);
  if reason is not null and reason <> 'out_of_scope' then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || reason, detail = 'employee.list';
  end if;

  return query
  with directory as (
    select employee.id, employee.workspace_id, employee.employee_code,
      employee.first_name, employee.last_name, employee.preferred_name,
      concat_ws(' ', coalesce(nullif(employee.preferred_name, ''), employee.first_name), employee.last_name) as display_name,
      employee.invitation_email, employee.start_date,
      primary_location.location_id as primary_location_id,
      location.name as primary_location_name,
      (select count(*) from public.employee_location_assignments a where a.employee_id = employee.id and a.ended_at is null) as location_count,
      primary_job.job_id as primary_job_id, listed_job.name as primary_job_name,
      (select count(*) from public.employee_job_assignments a where a.employee_id = employee.id and a.ended_at is null) as job_count,
      role.name as role_name,
      case
        when employee.archived_at is not null then 'archived'
        when membership.status = 'active' then 'active'
        when onboarding.status in ('submitted', 'changes_requested') then 'needs_attention'
        when membership.status = 'pending_activation' then 'onboarding'
        when invitation.status = 'pending' and invitation.expires_at > now() then 'invited'
        else 'not_invited'
      end as display_status,
      employee.archived_at, employee.revision
    from public.employee_profiles employee
    left join public.employee_location_assignments primary_location on primary_location.employee_id = employee.id and primary_location.ended_at is null and primary_location.is_primary
    left join public.locations location on location.id = primary_location.location_id
    left join public.employee_job_assignments primary_job on primary_job.employee_id = employee.id and primary_job.ended_at is null and primary_job.is_primary
    -- The job the list names: the stored primary; failing that the Owner job
    -- (the owner's, never stored as primary), then the first job in the
    -- catalog's order (A to Z, BL-475).
    left join lateral (
      select job.name
      from public.employee_job_assignments assignment
      join public.jobs job on job.id = assignment.job_id
      where assignment.employee_id = employee.id and assignment.ended_at is null
        and (assignment.is_primary or job.archived_at is null)
      order by assignment.is_primary desc, coalesce(job.system_key = 'owner', false) desc,
        lower(job.name), job.id
      limit 1
    ) listed_job on true
    left join public.workspace_memberships membership on membership.workspace_id = employee.workspace_id and membership.user_id = employee.user_id
    left join public.workspace_roles role on role.id = membership.role_id
    left join public.employee_onboarding_cases onboarding on onboarding.employee_id = employee.id
    left join lateral (
      select candidate.status, candidate.expires_at
      from public.employee_invitations candidate
      where candidate.employee_id = employee.id
      order by candidate.created_at desc limit 1
    ) invitation on true
    where employee.workspace_id = target_workspace_id
      and (include_archived = (employee.archived_at is not null))
      and app_private.authz_check(me, rule_row, null, employee.id, null) is null
  )
  select * from directory
  where (
      btrim(search_text) = ''
      or concat_ws(
        ' ',
        directory.first_name,
        directory.last_name,
        directory.preferred_name,
        directory.employee_code,
        directory.invitation_email,
        directory.primary_location_name,
        directory.primary_job_name
      ) ilike '%' || btrim(search_text) || '%'
    )
    and (status_filter = 'all' or directory.display_status = status_filter)
  order by lower(directory.display_name), directory.id
  limit least(greatest(page_limit, 1), 200)
  offset greatest(page_offset, 0);
end;
$$;


ALTER FUNCTION "public"."list_employees_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "include_archived" boolean, "search_text" "text", "status_filter" "text", "page_limit" integer, "page_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_my_workspace_identities_service"("actor_user_id" "uuid") RETURNS TABLE("workspace_id" "uuid", "workspace_name" "text", "workspace_role" "public"."workspace_role", "employee_name" "text", "employee_code" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    workspace.id,
    workspace.name,
    membership.role,
    nullif(btrim(coalesce(employee.first_name, '') || ' ' || coalesce(employee.last_name, '')), ''),
    employee.employee_code
  from public.workspace_memberships membership
  join public.workspaces workspace on workspace.id = membership.workspace_id
  left join public.employee_profiles employee
    on employee.workspace_id = membership.workspace_id
   and employee.user_id = membership.user_id
   and employee.archived_at is null
  where membership.user_id = actor_user_id
    and membership.status in (
      'active'::public.membership_status,
      'pending_activation'::public.membership_status
    )
    and workspace.lifecycle_status <> 'deleted'::public.workspace_lifecycle_status
  order by workspace.name;
$$;


ALTER FUNCTION "public"."list_my_workspace_identities_service"("actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_my_workspaces"() RETURNS TABLE("workspace_id" "uuid", "workspace_name" "text", "workspace_role" "public"."workspace_role", "membership_status" "public"."membership_status", "is_active" boolean, "onboarding_status" "public"."onboarding_status", "onboarding_current_step" smallint, "workspace_lifecycle_status" "public"."workspace_lifecycle_status", "closure_effective_at" timestamp with time zone, "last_used_at" timestamp with time zone, "access_removed" boolean, "pending_ownership_transfer_id" "uuid", "pending_ownership_transfer_role" "text", "pending_ownership_transfer_expires_at" timestamp with time zone, "other_member_count" integer, "pending_invitation_count" integer, "default_closure_effective_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    workspace.id,
    workspace.name,
    membership.role,
    membership.status,
    coalesce(workspace.id = preference.active_workspace_id, false)
      and membership.status = 'active'
      and (
        workspace.lifecycle_status = 'active'
        or (
          workspace.lifecycle_status = 'closure_scheduled'
          and workspace.closure_effective_at > now()
        )
      ),
    coalesce(onboarding.status, 'complete'::public.onboarding_status),
    coalesce(onboarding.current_step, 2::smallint),
    workspace.lifecycle_status,
    workspace.closure_effective_at,
    membership.last_used_at,
    exists (
      select 1
      from public.employee_access_snapshots snapshot
      where snapshot.membership_id = membership.id
        and snapshot.restored_at is null
    ),
    transfer.id,
    case
      when transfer.id is null then null
      when transfer.target_user_id = (select auth.uid()) then 'target'
      else 'initiator'
    end,
    transfer.expires_at,
    -- Everybody else who would lose access, and everybody who has been asked
    -- and not answered. The reader is not counted: they know about themselves,
    -- and what the closing screen has to say is what it costs other people.
    (
      select count(*)
      from public.workspace_memberships other
      where other.workspace_id = workspace.id
        and other.user_id <> membership.user_id
        and other.status in ('active', 'pending_activation')
        and not exists (
          select 1
          from public.employee_profiles employee
          where employee.workspace_id = other.workspace_id
            and employee.user_id = other.user_id
            and employee.archived_at is not null
        )
    )::integer,
    (
      select count(*)
      from public.employee_invitations invitation
      where invitation.workspace_id = workspace.id
        and invitation.status = 'pending'
        and invitation.expires_at > now()
    )::integer,
    -- What a scheduled closure would land on if nobody names a date, so the
    -- panel can say it before anybody commits to anything.
    now() + app_private.default_closure_period()
  from public.workspace_memberships membership
  join public.workspaces workspace on workspace.id = membership.workspace_id
  left join public.user_workspace_preferences preference on preference.user_id = membership.user_id
  left join public.workspace_onboarding onboarding on onboarding.workspace_id = workspace.id
  left join lateral (
    select pending_transfer.id,
           pending_transfer.target_user_id,
           pending_transfer.expires_at
    from public.workspace_ownership_transfers pending_transfer
    where pending_transfer.workspace_id = workspace.id
      and pending_transfer.status = 'pending'
      -- Keep expired requests visible to their sender so they can be cancelled.
      and (pending_transfer.expires_at > now() or pending_transfer.initiated_by = membership.user_id)
      and (
        pending_transfer.initiated_by = membership.user_id
        or pending_transfer.target_user_id = membership.user_id
      )
    order by pending_transfer.created_at desc
    limit 1
  ) transfer on true
  where membership.user_id = (select auth.uid())
    and not exists (
      select 1
      from public.employee_profiles employee
      where employee.workspace_id = membership.workspace_id
        and employee.user_id = membership.user_id
        and employee.archived_at is not null
    )
  order by
    (membership.status = 'active') desc,
    (coalesce(workspace.id = preference.active_workspace_id, false) and membership.status = 'active') desc,
    workspace.name asc;
$$;


ALTER FUNCTION "public"."list_my_workspaces"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_my_workspaces_service"("actor_user_id" "uuid") RETURNS TABLE("workspace_id" "uuid", "workspace_name" "text", "workspace_role" "public"."workspace_role", "membership_status" "public"."membership_status", "is_active" boolean, "onboarding_status" "public"."onboarding_status", "onboarding_current_step" smallint, "workspace_lifecycle_status" "public"."workspace_lifecycle_status", "closure_effective_at" timestamp with time zone, "last_used_at" timestamp with time zone, "access_removed" boolean, "pending_ownership_transfer_id" "uuid", "pending_ownership_transfer_role" "text", "pending_ownership_transfer_expires_at" timestamp with time zone, "other_member_count" integer, "pending_invitation_count" integer, "default_closure_effective_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;

  perform set_config('request.jwt.claim.sub', actor_user_id::text, true);
  return query select * from public.list_my_workspaces();
end;
$$;


ALTER FUNCTION "public"."list_my_workspaces_service"("actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_own_employment_records_service"("actor_user_id" "uuid") RETURNS TABLE("workspace_id" "uuid", "workspace_name" "text", "employee_id" "uuid", "preferred_name" "text", "phone" "text", "emergency_contact_name" "text", "emergency_contact_relationship" "text", "emergency_contact_phone" "text", "emergency_contact_email" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    employee.workspace_id,
    workspace.name,
    employee.id,
    coalesce(employee.preferred_name, ''),
    private_profile.phone,
    coalesce(private_profile.emergency_contact_name, ''),
    coalesce(private_profile.emergency_contact_relationship, ''),
    coalesce(private_profile.emergency_contact_phone, ''),
    coalesce(private_profile.emergency_contact_email, '')
  from public.employee_profiles employee
  join public.workspaces workspace on workspace.id = employee.workspace_id
  join public.workspace_memberships membership
    on membership.workspace_id = employee.workspace_id
   and membership.user_id = employee.user_id
  left join public.employee_private_profiles private_profile
    on private_profile.employee_id = employee.id
  where employee.user_id = actor_user_id
    and employee.archived_at is null
    and membership.status in (
      'active'::public.membership_status,
      'pending_activation'::public.membership_status
    )
    and workspace.lifecycle_status <> 'deleted'
  order by workspace.name;
$$;


ALTER FUNCTION "public"."list_own_employment_records_service"("actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_owner_onboarding_invitation_intents_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS TABLE("employee_id" "uuid", "email" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  onboarding_status public.onboarding_status;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'workspace.setup');

  select onboarding.status
  into onboarding_status
  from public.workspace_onboarding onboarding
  where onboarding.workspace_id = target_workspace_id;

  if onboarding_status is null then
    raise exception 'workspace onboarding was not found' using errcode = 'P0002';
  end if;
  if onboarding_status <> 'complete'::public.onboarding_status then
    raise exception 'owner onboarding must be complete' using errcode = '22023';
  end if;

  return query
  select intent.employee_id, intent.email
  from public.owner_onboarding_invitation_intents intent
  join public.employee_profiles employee
    on employee.workspace_id = intent.workspace_id
   and employee.id = intent.employee_id
  where intent.workspace_id = target_workspace_id
    and intent.dispatched_at is null
    and employee.archived_at is null
    and employee.user_id is null
    and not exists (
      select 1
      from public.employee_invitations invitation
      where invitation.workspace_id = intent.workspace_id
        and invitation.employee_id = intent.employee_id
        and invitation.status in ('pending', 'accepted')
    )
  order by intent.created_at, intent.employee_id;
end;
$$;


ALTER FUNCTION "public"."list_owner_onboarding_invitation_intents_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_pending_employee_invitations_for_account_service"("actor_user_id" "uuid") RETURNS TABLE("invitation_id" "uuid", "workspace_id" "uuid", "workspace_name" "text", "email" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_email text;
  email_confirmed boolean;
begin
  if actor_user_id is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;

  select lower(user_row.email), user_row.email_confirmed_at is not null
  into normalized_email, email_confirmed
  from auth.users user_row
  where user_row.id = actor_user_id;

  if normalized_email is null then
    raise exception 'valid actor required' using errcode = '42501';
  end if;
  if not email_confirmed then
    return;
  end if;

  return query
  select
    invitation.id,
    invitation.workspace_id,
    workspace.name,
    invitation.email,
    invitation.expires_at
  from public.employee_invitations invitation
  join public.workspaces workspace on workspace.id = invitation.workspace_id
  where invitation.email = normalized_email
    and invitation.status = 'pending'
    and invitation.expires_at > now()
    and not exists (
      select 1
      from public.workspace_memberships membership
      where membership.workspace_id = invitation.workspace_id
        and membership.user_id = actor_user_id
    )
  order by invitation.expires_at asc, workspace.name asc;
end;
$$;


ALTER FUNCTION "public"."list_pending_employee_invitations_for_account_service"("actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_pending_preferred_names_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS TABLE("request_id" "uuid", "employee_id" "uuid", "employee_name" "text", "requested_name" "text", "requested_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  me app_private.actor_state := app_private.actor(actor_user_id, target_workspace_id);
  rule_row app_private.authz_actions;
  reason text;
begin
  select * into rule_row from app_private.authz_actions action where action.key = 'employee.decide_preferred_name';
  -- May they answer anybody at all; whom, is answered row by row.
  reason := app_private.authz_check(me, rule_row, null, null, null);
  if reason is not null and reason <> 'out_of_scope' then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.' || reason, detail = 'employee.decide_preferred_name';
  end if;
  return query
  select
    request.id,
    request.employee_id,
    concat_ws(' ', employee.first_name, employee.last_name),
    request.requested_name,
    request.requested_at
  from public.employee_preferred_name_requests request
  join public.employee_profiles employee on employee.id = request.employee_id
  where request.workspace_id = target_workspace_id
    and request.status = 'pending'
    and employee.archived_at is null
    and app_private.authz_check(me, rule_row, null, request.employee_id, null) is null
  order by request.requested_at;
end;
$$;


ALTER FUNCTION "public"."list_pending_preferred_names_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_schedule_draft_document_conflicts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_draft_id" "uuid", "target_week_start" "date", "target_location_ids" "uuid"[], "target_department_ids" "uuid"[] DEFAULT NULL::"uuid"[], "include_no_department" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  draft_week date;
  conflicts jsonb := '[]'::jsonb;
  fingerprint text := 'none';
  normalized_locations uuid[];
  normalized_departments uuid[];
  effective_include_no_department boolean := coalesce(include_no_department, true);
  requested uuid;
begin
  if cardinality(coalesce(target_location_ids, '{}'::uuid[])) = 0 then
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.publish', target_locations => '{}'::uuid[]);
  end if;
  foreach requested in array target_location_ids loop
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.publish', target_locations => array[requested]);
  end loop;

  select coalesce(array_agg(distinct location.id order by location.id), '{}'::uuid[])
  into normalized_locations
  from public.locations location
  join unnest(coalesce(target_location_ids, '{}'::uuid[])) requested(location_id)
    on requested.location_id = location.id
  where location.workspace_id = target_workspace_id
    and location.archived_at is null;

  if cardinality(normalized_locations) = 0 then
    return jsonb_build_object(
      'status', 'ok',
      'conflicts', conflicts,
      'fingerprint', fingerprint
    );
  end if;

  if target_department_ids is not null then
    select coalesce(array_agg(distinct department.id order by department.id), '{}'::uuid[])
    into normalized_departments
    from public.departments department
    join unnest(target_department_ids) requested(id)
      on requested.id = department.id
    where department.workspace_id = target_workspace_id
      and department.archived_at is null;
  end if;

  select draft.week_start
  into draft_week
  from public.schedule_drafts draft
  where draft.id = target_draft_id
    and draft.workspace_id = target_workspace_id
    and draft.archived_at is null
  limit 1;

  if draft_week is null or draft_week <> target_week_start then
    return jsonb_build_object(
      'status', 'ok',
      'conflicts', conflicts,
      'fingerprint', fingerprint
    );
  end if;

  with candidate_shifts as (
    select
      shift.id,
      shift.location_id,
      location.name as location_name,
      shift.employee_id,
      trim(coalesce(nullif(employee.preferred_name, ''), employee.first_name) || ' ' || employee.last_name) as employee_name,
      shift.scheduled_date,
      to_char(shift.start_time, 'HH24:MI') as start_time,
      to_char(shift.end_time, 'HH24:MI') as end_time
    from public.schedule_draft_shifts shift
    join public.locations location
      on location.id = shift.location_id
     and location.workspace_id = shift.workspace_id
    join public.employee_profiles employee
      on employee.id = shift.employee_id
     and employee.workspace_id = shift.workspace_id
     and employee.archived_at is null
    where shift.workspace_id = target_workspace_id
      and shift.draft_id = target_draft_id
      and shift.employee_id is not null
      and shift.location_id = any(normalized_locations)
      and public.schedule_shift_in_department_scope_service(
        shift.job_id,
        normalized_departments,
        effective_include_no_department
      )
      and shift.scheduled_date >= target_week_start
      and shift.scheduled_date < target_week_start + 7
  ),
  active_document_requirements as (
    select distinct on (requirement.employee_id, requirement.source_id)
      requirement.employee_id,
      requirement.id as requirement_id,
      requirement.source_id as document_type_id,
      requirement.title as document_title
    from public.employee_onboarding_requirements requirement
    join public.document_types document_type
      on document_type.id = requirement.source_id
     and document_type.workspace_id = requirement.workspace_id
    where requirement.workspace_id = target_workspace_id
      and requirement.kind = 'document'::public.employee_onboarding_requirement_kind
      and requirement.status <> 'superseded'::public.employee_onboarding_requirement_status
      and document_type.archived_at is null
      and document_type.tracks_expiry
      and document_type.expiry_schedule_impact in ('warn', 'block')
    order by requirement.employee_id, requirement.source_id, requirement.created_at desc, requirement.id
  ),
  latest_accepted_documents as (
    select distinct on (document.workspace_id, document.requirement_id)
      document.*
    from public.employee_documents document
    where document.workspace_id = target_workspace_id
      and document.review_status = 'accepted'::public.employee_document_review_status
    order by document.workspace_id, document.requirement_id, document.version_number desc
  ),
  latest_pending_documents as (
    select distinct on (document.workspace_id, document.requirement_id)
      document.*
    from public.employee_documents document
    where document.workspace_id = target_workspace_id
      and document.review_status = 'awaiting_review'::public.employee_document_review_status
    order by document.workspace_id, document.requirement_id, document.version_number desc
  ),
  violation_rows as (
    select
      document_type.expiry_schedule_impact,
      document_type.expiry_policy_version,
      requirement.requirement_id,
      requirement.document_type_id,
      requirement.document_title,
      accepted.id as document_id,
      accepted.expiry_date,
      pending.id as pending_document_id,
      shift.id as shift_id,
      shift.location_id,
      shift.location_name,
      shift.employee_id,
      shift.employee_name,
      shift.scheduled_date,
      shift.start_time,
      shift.end_time
    from candidate_shifts shift
    join active_document_requirements requirement
      on requirement.employee_id = shift.employee_id
    join public.document_types document_type
      on document_type.id = requirement.document_type_id
     and document_type.workspace_id = target_workspace_id
    join latest_accepted_documents accepted
      on accepted.requirement_id = requirement.requirement_id
    left join latest_pending_documents pending
      on pending.requirement_id = requirement.requirement_id
    where accepted.expiry_date is not null
      and accepted.expiry_date < shift.scheduled_date
  ),
  conflict_rows as (
    select
      jsonb_build_object(
        'kind', 'document_expiry',
        'employee_id', employee_id,
        'employee_name', employee_name,
        'shift_id', shift_id,
        'location_id', location_id,
        'location_name', location_name,
        'date', scheduled_date,
        'start_time', start_time,
        'end_time', end_time,
        'document_type_id', document_type_id,
        'requirement_id', requirement_id,
        'document_id', document_id,
        'document_title', document_title,
        'expiry_date', expiry_date,
        'expiry_policy_version', expiry_policy_version,
        'pending_document_id', pending_document_id,
        'review_action', case when pending_document_id is null then null else 'review_document' end,
        'severity', case
          when expiry_schedule_impact = 'block' then 'hard'
          else 'soft'
        end,
        'overrideable', expiry_schedule_impact = 'warn',
        'warning_text', case
          when expiry_schedule_impact = 'block'
            then document_title || ' is expired and blocks scheduling.'
          else document_title || ' is expired.'
        end,
        'conflict_fingerprint', 'pending'
      ) as conflict,
      concat_ws(
        '|',
        employee_id,
        shift_id,
        document_type_id,
        requirement_id,
        document_id,
        pending_document_id,
        expiry_schedule_impact,
        expiry_policy_version,
        scheduled_date,
        expiry_date
      ) as conflict_key
    from violation_rows
    order by scheduled_date, start_time, shift_id, document_type_id
  )
  select coalesce(jsonb_agg(conflict), '[]'::jsonb),
         coalesce(
           encode(
             extensions.digest(
               convert_to(string_agg(conflict_key, E'\n' order by conflict_key), 'UTF8'),
               'sha256'
             ),
             'hex'
           ),
           'none'
         )
  into conflicts, fingerprint
  from conflict_rows;

  if fingerprint <> 'none' then
    conflicts := (
      select jsonb_agg(conflict - 'conflict_fingerprint' || jsonb_build_object(
        'conflict_fingerprint',
        fingerprint
      ))
      from jsonb_array_elements(conflicts) conflict
    );
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'conflicts', conflicts,
    'fingerprint', fingerprint
  );
end;
$$;


ALTER FUNCTION "public"."list_schedule_draft_document_conflicts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_draft_id" "uuid", "target_week_start" "date", "target_location_ids" "uuid"[], "target_department_ids" "uuid"[], "include_no_department" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_schedule_drafts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare edit_scope uuid[]; org_wide boolean;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit',
    target_locations => app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.edit'));
  edit_scope := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.edit');
  org_wide := app_private.authz_reason(actor_user_id, target_workspace_id, 'schedule.edit', '{}'::uuid[]) is null;
  return jsonb_build_object('drafts', coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', draft.id, 'workspace_id', draft.workspace_id,
      'week_start', draft.week_start, 'name', draft.name,
      'revision', draft.revision, 'created_by', draft.created_by,
      'updated_by', draft.updated_by, 'created_at', draft.created_at,
      'updated_at', draft.updated_at
    ) order by draft.updated_at desc, draft.name)
    from public.schedule_drafts draft
    where draft.workspace_id = target_workspace_id
      and draft.week_start = target_week_start and draft.archived_at is null
      and (org_wide or draft.location_ids && edit_scope)
  ), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."list_schedule_drafts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_week_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_schedule_export_cron_candidates_service"("target_now" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'schedules',
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', s.id,
          'workspace_id', s.workspace_id,
          'workspace_name', w.name,
          'created_by', s.created_by,
          'preset_id', s.preset_id,
          'preset_name', p.name,
          'settings', p.settings,
          'name', s.name,
          'recipients', s.recipients,
          'location_ids', to_jsonb(public.live_location_ids(s.workspace_id, s.location_ids)),
          'day_of_week', s.day_of_week,
          'send_hour', s.send_hour,
          'timezone', s.timezone,
          'week_start_day', coalesce(settings.week_start_day::text, 'monday'),
          'last_sent_at', s.last_sent_at,
          'consecutive_failures', s.consecutive_failures
        )
        order by s.workspace_id, s.send_hour, s.id
      ),
      '[]'::jsonb
    )
  )
  from public.scheduled_schedule_exports s
  join public.schedule_export_presets p
    on p.id = s.preset_id
   and p.workspace_id = s.workspace_id
  join public.workspaces w
    on w.id = s.workspace_id
  left join public.workspace_scheduling_settings settings
    on settings.workspace_id = s.workspace_id
  where s.enabled
    and (s.last_failed_at is null or s.last_failed_at <= target_now - interval '15 minutes')
    and s.auto_disabled_at is null
    and cardinality(s.location_ids) > 0
    and app_private.workspace_allows_interactive_access(s.workspace_id)
    and (
      s.last_sent_at is null
      or s.last_sent_at <= target_now - interval '20 hours'
    );
$$;


ALTER FUNCTION "public"."list_schedule_export_cron_candidates_service"("target_now" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_schedule_export_events_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare export_scope uuid[]; org_wide boolean;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.export',
    target_locations => app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.export'));
  export_scope := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.export');
  org_wide := app_private.authz_reason(actor_user_id, target_workspace_id, 'schedule.export', '{}'::uuid[]) is null;
  return (
    select jsonb_build_object(
      'events',
      coalesce(
        jsonb_agg(public.schedule_export_event_json(event_row) order by event_row.created_at desc, event_row.id desc),
        '[]'::jsonb
      )
    )
    from (
      select event.*
        from public.schedule_export_events event
        cross join lateral (
          -- The locations it was for; null when the list is missing or holds
          -- anything that is not a location id.
          select case
            when jsonb_typeof(event.params -> 'location_ids') = 'array'
              and not exists (
                select 1 from jsonb_array_elements(event.params -> 'location_ids') item
                where jsonb_typeof(item) <> 'string'
                   or item #>> '{}' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              )
            then array(select (item #>> '{}')::uuid from jsonb_array_elements(event.params -> 'location_ids') item)
          end as ids
        ) places
       where event.workspace_id = target_workspace_id
         and (org_wide or (cardinality(public.live_location_ids(target_workspace_id, places.ids)) > 0
           and public.live_location_ids(target_workspace_id, places.ids) <@ export_scope))
       order by event.created_at desc, event.id desc
       limit 10
    ) event_row
  );
end;
$_$;


