CREATE OR REPLACE FUNCTION "public"."load_employee_invitation_link_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  invitation_row public.employee_invitations%rowtype;
  recovered_token text;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.invite', target_person => target_employee_id);

  select * into invitation_row
  from public.employee_invitations
  where workspace_id = target_workspace_id
    and employee_id = target_employee_id
    and status = 'pending'
  order by created_at desc
  limit 1;
  -- Handing the link on is handing out its role.
  if invitation_row.id is not null
     and not app_private.can_invite_with_role(actor_user_id, target_workspace_id, invitation_row.role_id) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.rank', detail = 'employee.invite';
  end if;
  if invitation_row.id is null or invitation_row.expires_at <= now() then
    raise exception 'open invitation not found' using errcode = 'P0002';
  end if;

  select token into recovered_token
  from public.employee_invitation_delivery_secrets
  where invitation_id = invitation_row.id
    and workspace_id = invitation_row.workspace_id;
  if recovered_token is null then
    raise exception 'invitation link is unavailable; use Resend' using errcode = 'P0002';
  end if;

  insert into public.employee_events (
    workspace_id, employee_id, actor_user_id, action, summary
  ) values (
    target_workspace_id,
    target_employee_id,
    actor_user_id,
    'employee.invitation_link_copied',
    'Invitation link copied'
  );

  return jsonb_build_object(
    'token', recovered_token,
    'expires_at', invitation_row.expires_at
  );
end;
$$;


ALTER FUNCTION "public"."load_employee_invitation_link_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."load_employee_invitation_retry_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  invitation_row public.employee_invitations%rowtype;
  recovered_token text;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.invite', target_person => target_employee_id);

  select * into invitation_row
  from public.employee_invitations
  where workspace_id = target_workspace_id
    and employee_id = target_employee_id
    and status = 'pending'
  order by created_at desc
  limit 1
  for update;
  if invitation_row.id is not null
     and not app_private.can_invite_with_role(actor_user_id, target_workspace_id, invitation_row.role_id) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.rank', detail = 'employee.invite';
  end if;
  if invitation_row.id is null or invitation_row.delivery_status <> 'failed' then
    raise exception 'failed invitation not found' using errcode = 'P0002';
  end if;
  if invitation_row.expires_at <= now() then
    raise exception 'invitation expired; use Resend' using errcode = '22023';
  end if;

  select token into recovered_token
  from public.employee_invitation_delivery_secrets
  where invitation_id = invitation_row.id
    and workspace_id = invitation_row.workspace_id;
  if recovered_token is null then
    raise exception 'original invitation link is unavailable; use Resend'
      using errcode = 'P0002';
  end if;
  if invitation_row.token_hash <>
    encode(extensions.digest(recovered_token, 'sha256'), 'hex') then
    raise exception 'stored invitation token does not match'
      using errcode = '22023';
  end if;

  update public.employee_invitations
  set resend_count = resend_count + 1,
      updated_at = now()
  where id = invitation_row.id;

  insert into public.employee_events (
    workspace_id,
    employee_id,
    actor_user_id,
    action,
    summary
  ) values (
    target_workspace_id,
    target_employee_id,
    actor_user_id,
    'employee.invitation_delivery_retry_started',
    'Employee invitation delivery retry started'
  );

  return jsonb_build_object(
    'id', invitation_row.id,
    'email', invitation_row.email,
    'token', recovered_token,
    'expires_at', invitation_row.expires_at
  );
end;
$$;


ALTER FUNCTION "public"."load_employee_invitation_retry_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_account_deletion_email_sent_service"("target_request_id" "uuid", "delivery_kind" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if delivery_kind not in ('initial', 'day_7', 'last_24h', 'resend') then
    raise exception 'valid account deletion delivery kind required' using errcode = '22023';
  end if;

  update public.account_deletion_requests
  set recovery_email_sent_at = case
        when delivery_kind in ('initial', 'resend') then now()
        else recovery_email_sent_at
      end,
      reminder_7d_sent_at = case
        when delivery_kind = 'day_7' then now()
        else reminder_7d_sent_at
      end,
      reminder_24h_sent_at = case
        when delivery_kind = 'last_24h' then now()
        else reminder_24h_sent_at
      end,
      updated_at = now()
  where id = target_request_id
    and status = 'pending';

  if not found then
    raise exception 'pending account deletion request not found' using errcode = 'P0002';
  end if;
end;
$$;


ALTER FUNCTION "public"."mark_account_deletion_email_sent_service"("target_request_id" "uuid", "delivery_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_employee_invitation_delivery_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_invitation_id" "uuid", "delivery_result" "text", "delivery_failure_message" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  invitation_row public.employee_invitations%rowtype;
begin
  -- Asked before the lock (nf-guvenlik D-c); an unknown invitation has no
  -- person and gets the answer one out of reach gets.
  select * into invitation_row
  from public.employee_invitations
  where id = target_invitation_id
    and workspace_id = target_workspace_id;
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.invite', target_person => invitation_row.employee_id);
  if not app_private.can_invite_with_role(actor_user_id, target_workspace_id, invitation_row.role_id) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.rank', detail = 'employee.invite';
  end if;
  select * into invitation_row
  from public.employee_invitations
  where id = target_invitation_id
  for update;
  if delivery_result not in ('sent', 'failed') then
    raise exception 'valid invitation delivery result required' using errcode = '22023';
  end if;
  if invitation_row.status <> 'pending' then
    raise exception 'pending invitation not found' using errcode = 'P0002';
  end if;

  update public.employee_invitations
  set delivery_status = delivery_result,
      delivery_attempted_at = now(),
      delivery_failed_at = case when delivery_result = 'failed' then now() else null end,
      delivery_error = case
        when delivery_result = 'failed' then left(coalesce(delivery_failure_message, 'Invitation delivery failed'), 500)
        else null
      end,
      sent_at = case when delivery_result = 'sent' then now() else sent_at end,
      updated_at = now()
  where id = invitation_row.id;

  insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary)
  values (
    target_workspace_id,
    invitation_row.employee_id,
    actor_user_id,
    case when delivery_result = 'failed' then 'employee.invitation_delivery_failed' else 'employee.invitation_delivery_sent' end,
    case when delivery_result = 'failed' then 'Employee invitation delivery failed' else 'Employee invitation delivered' end
  );
end;
$$;


ALTER FUNCTION "public"."mark_employee_invitation_delivery_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_invitation_id" "uuid", "delivery_result" "text", "delivery_failure_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_owner_onboarding_invitation_intent_dispatched_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "dispatch_failure_message" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'workspace.setup');

  update public.owner_onboarding_invitation_intents
  set dispatched_at = now(),
      dispatch_error = nullif(left(coalesce(dispatch_failure_message, ''), 500), ''),
      updated_at = now()
  where workspace_id = target_workspace_id
    and employee_id = target_employee_id;

  if not found then
    raise exception 'owner onboarding invitation intent not found' using errcode = 'P0002';
  end if;
end;
$$;


ALTER FUNCTION "public"."mark_owner_onboarding_invitation_intent_dispatched_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "dispatch_failure_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_owner_setup_checklist_item_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_item_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_item_id text := lower(btrim(coalesce(target_item_id, '')));
begin
  if actor_user_id is null then
    raise exception 'workspace management required' using errcode = '42501';
  end if;
  if not public.service_actor_has_permission(actor_user_id, target_workspace_id, 'settings.general.manage') then
    raise exception 'workspace management required' using errcode = '42501';
  end if;
  if normalized_item_id <> all(app_private.owner_setup_checklist_item_ids()) then
    raise exception 'valid setup checklist item required' using errcode = '22023';
  end if;

  insert into public.owner_setup_checklist_progress (
    workspace_id,
    user_id,
    completed_item_ids
  )
  values (
    target_workspace_id,
    actor_user_id,
    array[normalized_item_id]
  )
  on conflict (workspace_id, user_id)
  do update set
    completed_item_ids = (
      select array_agg(distinct item order by item)
      from unnest(
        public.owner_setup_checklist_progress.completed_item_ids ||
        excluded.completed_item_ids
      ) item
    ),
    updated_at = now();

  return public.get_owner_setup_checklist_progress_service(
    actor_user_id,
    target_workspace_id
  );
end;
$$;


ALTER FUNCTION "public"."mark_owner_setup_checklist_item_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_item_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_schedule_edit_session_shift_source"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  session_source public.schedule_edit_source;
  session_week date;
begin
  select session.source_kind, session.week_start into session_source, session_week
  from public.schedule_edit_sessions session
  where session.id = new.session_id
    and session.workspace_id = new.workspace_id;

  -- D-O1: a shift added while editing a published week is new, not "Live".
  if session_source = 'published' and new.source_published_shift_id is null and exists (
    select 1 from public.schedule_location_publications publication
    join public.schedule_published_shifts published
      on published.publication_id = publication.id and published.source_shift_id = new.id
    where publication.location_id = new.location_id and publication.week_start = session_week
      and publication.status = 'current' and publication.workspace_id = new.workspace_id
  ) then
    new.source_published_shift_id := new.id;
    new.locked := true;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."mark_schedule_edit_session_shift_source"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_workspace_retention_purge_completed_service"("target_workspace_id" "uuid", "purge_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  workspace_row public.workspaces%rowtype;
  purge_job public.workspace_retention_purge_jobs%rowtype;
  tombstone public.workspace_retention_tombstones%rowtype;
begin
  if target_workspace_id is null then
    raise exception 'valid workspace required' using errcode = '22023';
  end if;
  if purge_metadata is null or jsonb_typeof(purge_metadata) <> 'object' then
    raise exception 'purge metadata must be an object' using errcode = '22023';
  end if;

  select * into tombstone
  from public.workspace_retention_tombstones existing
  where existing.workspace_id = target_workspace_id;
  if tombstone.workspace_id is not null then
    return jsonb_build_object(
      'status', 'completed',
      'workspace_id', tombstone.workspace_id,
      'purged_at', tombstone.purged_at,
      'idempotent', true
    );
  end if;

  select * into workspace_row
  from public.workspaces workspace
  where workspace.id = target_workspace_id
  for update;
  if workspace_row.id is null then
    raise exception 'workspace not found' using errcode = '02000';
  end if;
  if workspace_row.lifecycle_status <> 'deleted' then
    raise exception 'workspace must be deleted before retention purge' using errcode = '23514';
  end if;

  insert into public.workspace_retention_purge_jobs (
    workspace_id,
    due_at,
    metadata
  )
  values (
    target_workspace_id,
    coalesce(workspace_row.closed_at, now()),
    jsonb_build_object('source', 'manual_service_enqueue')
  )
  on conflict (workspace_id) do nothing;

  select * into purge_job
  from public.workspace_retention_purge_jobs job
  where job.workspace_id = target_workspace_id
  for update;

  if purge_job.status = 'completed' then
    return jsonb_build_object(
      'status', 'completed',
      'workspace_id', target_workspace_id,
      'purged_at', purge_job.completed_at,
      'idempotent', true
    );
  end if;
  if purge_job.due_at > now() then
    raise exception 'workspace retention purge is not due' using errcode = '23514';
  end if;

  insert into public.workspace_retention_tombstones (
    workspace_id,
    workspace_name,
    closed_at,
    closed_by,
    purge_job_id,
    metadata
  )
  values (
    target_workspace_id,
    workspace_row.name,
    coalesce(workspace_row.closed_at, now()),
    workspace_row.closed_by,
    purge_job.id,
    purge_metadata
  )
  returning * into tombstone;

  update public.workspace_retention_purge_jobs
  set status = 'completed',
      completed_at = tombstone.purged_at,
      metadata = public.workspace_retention_purge_jobs.metadata || purge_metadata,
      updated_at = now()
  where id = purge_job.id;

  insert into public.audit_events (
    workspace_id,
    actor_user_id,
    action,
    target_type,
    target_id,
    metadata
  )
  values (
    target_workspace_id,
    workspace_row.closed_by,
    'workspace.retention_purge.completed',
    'workspace',
    target_workspace_id::text,
    purge_metadata || jsonb_build_object('purge_job_id', purge_job.id)
  );

  return jsonb_build_object(
    'status', 'completed',
    'workspace_id', target_workspace_id,
    'purged_at', tombstone.purged_at,
    'idempotent', false
  );
end;
$$;


ALTER FUNCTION "public"."mark_workspace_retention_purge_completed_service"("target_workspace_id" "uuid", "purge_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mutate_schedule_edit_shift_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "expected_session_revision" integer, "operation" "text", "target_shift_id" "uuid", "expected_shift_revision" integer DEFAULT NULL::integer, "shift_payload" "jsonb" DEFAULT NULL::"jsonb", "request_idempotency_key" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  reach uuid[];
  write_row boolean := false;
  target_session public.schedule_edit_sessions%rowtype;
  target_shift public.schedule_edit_session_shifts%rowtype;
  mutated_shift record;
  override_note text;
  audited_shift_id uuid;
begin
  perform public.availability_lock_workspace(target_workspace_id);
  if operation not in ('create', 'update', 'delete', 'restore') then
    raise exception 'invalid shift operation' using errcode = '22023';
  end if;
  reach := app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.edit');

  -- a. Delete and restore: a published shift is marked, an unpublished one goes.
  if operation in ('create', 'update') then
    write_row := true;
  else
    select * into target_session
    from public.schedule_edit_sessions session
    where session.id = target_session_id
      and session.workspace_id = target_workspace_id
    for update;

    if target_session.id is null or target_session.holder_user_id <> actor_user_id then
      raise exception 'edit session not found' using errcode = 'P0002';
    end if;
    if target_session.status <> 'active' then
      raise exception 'edit session closed' using errcode = 'PT409', hint = 'schedule.edit_session_closed';
    elsif target_session.expires_at <= now() then
      raise exception 'edit lease expired' using errcode = 'PT409', hint = 'schedule.edit_lease_expired';
    end if;
    if target_session.revision <> expected_session_revision then
      raise exception 'session revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
    end if;

    select * into target_shift
    from public.schedule_edit_session_shifts shift
    where shift.session_id = target_session_id
      and shift.id = target_shift_id
      and shift.revision = expected_shift_revision
      and shift.location_id = any(reach)
    for update;

    if target_shift.id is null then
      raise exception 'shift revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
    end if;

    if operation = 'restore' then
      if target_shift.source_published_shift_id is null
        or target_shift.pending_op_type is distinct from 'delete' then
        raise exception 'shift restore unavailable' using errcode = '22023';
      end if;

      update public.schedule_edit_session_shifts shift
      set pending_op_type = null,
          locked = true,
          revision = revision + 1,
          updated_at = now()
      where shift.session_id = target_session_id
        and shift.id = target_shift_id;

      update public.schedule_edit_sessions
      set revision = revision + 1,
          dirty = true,
          last_heartbeat = now(),
          expires_at = now() + interval '4 minutes'
      where id = target_session_id;

      result := public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id);
    elsif target_shift.source_published_shift_id is null and not target_shift.locked then
      write_row := true;
    else
      update public.schedule_edit_session_shifts shift
      set pending_op_type = 'delete',
          locked = true,
          revision = revision + 1,
          updated_at = now()
      where shift.session_id = target_session_id
        and shift.id = target_shift_id;

      update public.schedule_edit_sessions
      set revision = revision + 1,
          dirty = true,
          last_heartbeat = now(),
          expires_at = now() + interval '4 minutes'
      where id = target_session_id;

      result := public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id);
    end if;
  end if;

  -- b. Write the row: create, update, or delete an unpublished shift. The
  -- block keeps its own copy of the id and payload, as the old inner layer did.
  if write_row then
    <<write_shift>>
    declare
      row_shift_id uuid := target_shift_id;
      row_payload jsonb := shift_payload;
      target_location_id uuid;
      target_employee_id uuid;
      target_job_id uuid;
      target_shift_type_id uuid;
      target_scheduled_date date;
      target_start_time time;
      target_end_time time;
      target_unpaid_break_minutes integer;
      target_hide_time_on_badge boolean;
      target_note text;
      kept public.schedule_edit_session_shifts%rowtype;
    begin
      select * into target_session from public.schedule_edit_sessions session
      where session.id = target_session_id and session.workspace_id = target_workspace_id
      for update;
      if target_session.id is null or target_session.holder_user_id <> actor_user_id then
        raise exception 'edit session not found' using errcode = 'P0002';
      end if;
      if target_session.status <> 'active' then
        raise exception 'edit session closed' using errcode = 'PT409', hint = 'schedule.edit_session_closed';
      elsif target_session.expires_at <= now() then
        raise exception 'edit lease expired' using errcode = 'PT409', hint = 'schedule.edit_lease_expired';
      end if;
      if target_session.revision <> expected_session_revision then
        raise exception 'session revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
      end if;

      if operation in ('create', 'update') then
        row_payload := public.normalize_schedule_time_source(target_workspace_id,row_payload,(select to_jsonb(s) from public.schedule_edit_session_shifts s where s.session_id=target_session_id and s.id=row_shift_id));
        target_location_id := (row_payload->>'location_id')::uuid;
        target_employee_id := nullif(row_payload->>'employee_id', '')::uuid;
        target_job_id := (row_payload->>'job_id')::uuid;
        target_shift_type_id := nullif(row_payload->>'shift_type_id', '')::uuid;
        target_scheduled_date := (row_payload->>'scheduled_date')::date;
        target_start_time := nullif(row_payload->>'start_time','')::time;
        target_end_time := nullif(row_payload->>'end_time','')::time;
        -- A field the payload leaves out keeps the shift's own value; a new
        -- shift starts from the default (BL-292, EKRAN-01 #11).
        select * into kept from public.schedule_edit_session_shifts s
        where s.session_id = target_session_id and s.id = row_shift_id;
        target_unpaid_break_minutes := case when row_payload ? 'unpaid_break_minutes'
          then coalesce((row_payload->>'unpaid_break_minutes')::integer, 0)
          else coalesce(kept.unpaid_break_minutes, 0) end;
        target_hide_time_on_badge := case when row_payload ? 'hide_time_on_badge'
          then coalesce((row_payload->>'hide_time_on_badge')::boolean, false)
          else coalesce(kept.hide_time_on_badge, false) end;
        target_note := case when row_payload ? 'note' then coalesce(row_payload->>'note', '')
          else coalesce(kept.note, '') end;
        if target_start_time = target_end_time then
          raise exception 'Start and end time cannot be the same.' using errcode = '22023';
        end if;
        if char_length(target_note) > 500
          or target_unpaid_break_minutes not in (0, 15, 30, 45, 60)
          or target_scheduled_date not between target_session.week_start and target_session.week_start + 6 then
          raise exception 'invalid shift values' using errcode = '22023';
        end if;
        perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit', target_locations => array[target_location_id]);
        if not exists (select 1 from public.jobs job where job.id = target_job_id and job.workspace_id = target_workspace_id and job.archived_at is null)
          or not exists (select 1 from public.locations location where location.id = target_location_id and location.workspace_id = target_workspace_id and location.archived_at is null)
          or (target_shift_type_id is not null and not exists (select 1 from public.shift_types shift_type where shift_type.id = target_shift_type_id and shift_type.workspace_id = target_workspace_id and shift_type.archived_at is null))
          or (target_employee_id is not null and not exists (
            select 1 from public.employee_profiles employee
            join public.employee_location_assignments location_assignment
              on location_assignment.employee_id = employee.id and location_assignment.location_id = target_location_id and location_assignment.ended_at is null
            join public.employee_job_assignments job_assignment
              on job_assignment.employee_id = employee.id and job_assignment.job_id = target_job_id and job_assignment.ended_at is null
            where employee.id = target_employee_id and employee.workspace_id = target_workspace_id and employee.archived_at is null
          )) then
          raise exception 'invalid shift reference' using errcode = '23503';
        end if;
      end if;

      if operation = 'create' then
        if request_idempotency_key is not null and exists (
          select 1 from public.schedule_edit_session_shifts shift
          where shift.session_id = target_session_id and shift.idempotency_key = request_idempotency_key
        ) then
          result := public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id);
          exit write_shift;
        end if;
        row_shift_id:=coalesce(row_shift_id,gen_random_uuid());
        perform public.schedule_prepare_availability_assignment(actor_user_id,target_workspace_id,row_payload||jsonb_build_object('id',row_shift_id,'session_id',target_session_id),null);
        insert into public.schedule_edit_session_shifts (id, workspace_id, session_id, location_id, employee_id, job_id, shift_type_id, scheduled_date, start_time, end_time, time_basis, time_snapshot, time_timezone, unpaid_break_minutes, hide_time_on_badge, note, idempotency_key) values (row_shift_id, target_workspace_id, target_session_id, target_location_id, target_employee_id, target_job_id, target_shift_type_id, target_scheduled_date, target_start_time, target_end_time, row_payload->>'time_basis', row_payload->'time_snapshot', row_payload->>'time_timezone', target_unpaid_break_minutes, target_hide_time_on_badge, target_note, request_idempotency_key);
      elsif operation = 'update' then
        perform public.schedule_prepare_availability_assignment(actor_user_id,target_workspace_id,row_payload||jsonb_build_object('id',row_shift_id,'session_id',target_session_id),(select to_jsonb(s) from public.schedule_edit_session_shifts s where s.workspace_id=target_workspace_id and s.session_id=target_session_id and s.id=row_shift_id));
        update public.schedule_edit_session_shifts shift
        set location_id = target_location_id, employee_id = target_employee_id,
          job_id = target_job_id, shift_type_id = target_shift_type_id,
          scheduled_date = target_scheduled_date, start_time = target_start_time,
          end_time = target_end_time, time_basis=row_payload->>'time_basis', time_snapshot=row_payload->'time_snapshot', time_timezone=row_payload->>'time_timezone', unpaid_break_minutes = target_unpaid_break_minutes, hide_time_on_badge = target_hide_time_on_badge, note = target_note,
          revision = revision + 1, updated_at = now()
        where shift.session_id = target_session_id and shift.id = row_shift_id
          and shift.revision = expected_shift_revision
          and shift.location_id = any(reach);
        if not found then
          raise exception 'shift revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
        end if;
      else
        update public.schedule_availability_overrides set revoked_at=now() where workspace_id=target_workspace_id and shift_id=row_shift_id and revoked_at is null;
        delete from public.schedule_edit_session_shifts shift
        where shift.session_id = target_session_id and shift.id = row_shift_id
          and shift.revision = expected_shift_revision
          and shift.location_id = any(reach);
        if not found then
          raise exception 'shift revision stale' using errcode = 'PT409', hint = 'schedule.edit_session_stale';
        end if;
      end if;

      update public.schedule_edit_sessions
      set revision = revision + 1, dirty = true,
        last_heartbeat = now(), expires_at = now() + interval '4 minutes'
      where id = target_session_id;
      result := public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id);
    end write_shift;

    -- An updated published shift becomes a pending update and unlocks.
    if operation = 'update' then
      update public.schedule_edit_session_shifts shift
      set pending_op_type = case
            when shift.source_published_shift_id is not null
             and shift.pending_op_type is distinct from 'delete'
            then 'update'
            else shift.pending_op_type
          end,
          locked = case
            when shift.source_published_shift_id is not null then false
            else shift.locked
          end
      where shift.session_id = target_session_id
        and shift.id = target_shift_id;

      result := public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id);
    end if;
  end if;

  -- c. Labels: the catalog's name for an active label of this workspace, the
  -- shift's own copy for a label it already carries; anything else is refused.
  -- A payload without label_ids keeps the shift's labels; an empty list clears
  -- them (EKRAN-01 B7, as for the note).
  if operation in ('create', 'update') and shift_payload ? 'label_ids' then
    <<labels>>
    declare
      tag_ids uuid[];
      tag_names text[];
    begin
      select * into target_shift from public.schedule_edit_session_shifts shift
      where shift.session_id = target_session_id
        and shift.id = target_shift_id
        and shift.workspace_id = target_workspace_id;
      if target_shift.id is null then
        exit labels;
      end if;

      select coalesce(array_agg(requested.id order by requested.ord), '{}'::uuid[]),
             coalesce(array_agg(coalesce(catalog.name, kept.name) order by requested.ord), '{}'::text[])
      into tag_ids, tag_names
      from (
        select tag.value::uuid as id, min(tag.ord) as ord
        from jsonb_array_elements_text(coalesce(shift_payload->'label_ids', '[]'::jsonb)) with ordinality as tag(value, ord)
        group by tag.value::uuid
      ) requested
      left join public.shift_labels catalog
        on catalog.id = requested.id
       and catalog.workspace_id = target_workspace_id
       and catalog.archived_at is null
      left join lateral (
        select copy.name from unnest(target_shift.label_ids, target_shift.label_names) as copy(id, name)
        where copy.id = requested.id limit 1
      ) kept on true;

      if array_position(tag_names, null) is not null then
        raise exception 'invalid shift reference' using errcode = '23503';
      end if;

      update public.schedule_edit_session_shifts shift
         set label_ids = tag_ids, label_names = tag_names
       where shift.session_id = target_session_id
         and shift.id = target_shift_id
         and shift.workspace_id = target_workspace_id;
      result := public.get_schedule_edit_session_service(actor_user_id, target_workspace_id, target_session_id);
    end labels;
  end if;

  -- d. A person missing a required document is never on a shift that day.
  if operation in ('create', 'update') then
    select shift.employee_id, shift.scheduled_date
    into mutated_shift
    from public.schedule_edit_session_shifts shift
    where shift.workspace_id = target_workspace_id
      and shift.session_id = target_session_id
      and shift.id = target_shift_id
    limit 1;

    if mutated_shift.employee_id is not null
      and public.employee_has_hard_document_schedule_conflict_service(
        target_workspace_id,
        mutated_shift.employee_id,
        mutated_shift.scheduled_date
      ) then
      raise exception 'employee document hard conflict' using errcode = '23514';
    end if;
  end if;

  -- e. An overridden soft conflict is audited once per request.
  override_note := btrim(coalesce(shift_payload->>'conflict_override_note', ''));

  if operation in ('create', 'update') and char_length(override_note) >= 10 then
    select shift.id
    into audited_shift_id
    from public.schedule_edit_session_shifts shift
    where shift.workspace_id = target_workspace_id
      and shift.session_id = target_session_id
      and (
        shift.id = target_shift_id
        or (
          operation = 'create'
          and request_idempotency_key is not null
          and shift.idempotency_key = request_idempotency_key
        )
      )
    order by (shift.id = target_shift_id) desc
    limit 1;

    if audited_shift_id is not null
      and not exists (
        select 1
        from public.audit_events event
        where event.workspace_id = target_workspace_id
          and event.action = 'schedule.soft_conflict_overridden'
          and event.target_type = 'schedule_edit_session_shift'
          and event.target_id = audited_shift_id::text
          and request_idempotency_key is not null
          and event.metadata->>'idempotency_key' = request_idempotency_key::text
      ) then
      insert into public.audit_events (
        workspace_id,
        actor_user_id,
        action,
        target_type,
        target_id,
        metadata
      ) values (
        target_workspace_id,
        actor_user_id,
        'schedule.soft_conflict_overridden',
        'schedule_edit_session_shift',
        audited_shift_id::text,
        jsonb_build_object(
          'session_id', target_session_id,
          'operation', operation,
          'idempotency_key', request_idempotency_key,
          'note', override_note
        )
      );
    end if;
  end if;

  return result;
end;
$$;


ALTER FUNCTION "public"."mutate_schedule_edit_shift_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_session_id" "uuid", "expected_session_revision" integer, "operation" "text", "target_shift_id" "uuid", "expected_shift_revision" integer, "shift_payload" "jsonb", "request_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_schedule_time_source"("w" "uuid", "payload" "jsonb", "previous" "jsonb" DEFAULT NULL::"jsonb", "preserve_saved_timezone" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare basis text; snap jsonb; tz text; source_type uuid; source_revision integer; ver public.shift_type_time_versions%rowtype;
begin
  select timezone into tz from public.locations where id=(payload->>'location_id')::uuid and workspace_id=w;
  if tz is null then raise exception 'invalid shift location' using errcode='23503'; end if;
  if previous is not null and payload->>'location_id'=previous->>'location_id' then
    tz:=coalesce(nullif(previous->>'time_timezone',''),tz);
  elsif preserve_saved_timezone then
    tz:=coalesce(nullif(payload->>'time_timezone',''),tz);
  end if;
  if not app_private.timezone_name_valid(tz) then
    raise exception 'Invalid shift timezone' using errcode='22023';
  end if;
  basis:=payload->>'time_basis';
  if basis is null and previous is not null then
    if previous->>'time_basis'='type_default' and
      (nullif(payload->>'start_time','')::time,nullif(payload->>'end_time','')::time) is distinct from
      (nullif(previous->>'start_time','')::time,nullif(previous->>'end_time','')::time) then
      raise exception 'Refresh the schedule before changing reference hours' using errcode = 'PT409';
    end if;
    basis:=previous->>'time_basis'; snap:=previous->'time_snapshot';
  else snap:=payload->'time_snapshot'; end if;
  basis:=coalesce(basis,'explicit');
  if basis not in ('explicit','type_default') then raise exception 'invalid shift time source' using errcode='22023'; end if;
  if basis='type_default' then
    if snap is null or snap='null'::jsonb then
      source_type:=(payload->>'shift_type_id')::uuid;
      select default_revision into source_revision from public.shift_types where id=source_type and workspace_id=w;
    else
      source_type:=(snap->>'shift_type_id')::uuid; source_revision:=(snap->>'default_revision')::integer;
    end if;
    select * into ver from public.shift_type_time_versions where workspace_id=w and shift_type_id=source_type and revision=source_revision;
    if ver.shift_type_id is null or ver.start_time is null or ver.end_time is null then
      raise exception 'This shift type has no default hours. Enter start and end time.' using errcode='23514';
    end if;
    if snap is not null and snap<>'null'::jsonb and
      ((snap->>'start_time')::time,(snap->>'end_time')::time) is distinct from (ver.start_time,ver.end_time) then
      raise exception 'Shift default hours changed; refresh the reference before saving' using errcode = 'PT409';
    end if;
    if previous is not null and payload->>'location_id'=previous->>'location_id' then
      tz:=coalesce(nullif(previous->>'time_timezone',''),tz);
    end if;
    snap:=jsonb_build_object('shift_type_id',source_type,'default_revision',source_revision,
      'start_time',to_char(ver.start_time,'HH24:MI'),'end_time',to_char(ver.end_time,'HH24:MI'),'timezone',tz);
    payload:=payload||jsonb_build_object('start_time',to_char(ver.start_time,'HH24:MI'),'end_time',to_char(ver.end_time,'HH24:MI'));
  else
    if nullif(payload->>'start_time','') is null or nullif(payload->>'end_time','') is null then
      raise exception 'Enter start and end time.' using errcode='22023'; end if;
    if (payload->>'start_time')::time=(payload->>'end_time')::time then
      raise exception 'Start and end time cannot be the same.' using errcode='22023'; end if;
    snap:=null;
    if previous is not null and payload->>'location_id'=previous->>'location_id' then tz:=coalesce(nullif(previous->>'time_timezone',''),tz); end if;
  end if;
  return payload||jsonb_build_object('time_basis',basis,'time_snapshot',snap,'time_timezone',tz);
end; $$;


ALTER FUNCTION "public"."normalize_schedule_time_source"("w" "uuid", "payload" "jsonb", "previous" "jsonb", "preserve_saved_timezone" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_workspace_widget_order"("target_widget_order" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with allowed(value, position) as (
    values
      ('operations', 1),
      ('pending_requests', 2),
      ('open_shifts', 3),
      ('announcements', 4),
      ('todos', 5),
      ('notifications', 6),
      ('quick_actions', 7)
  ),
  input_order as (
    select input.value, min(input.ordinality) as ordinality
    from unnest(coalesce(target_widget_order, '{}'::text[])) with ordinality input(value, ordinality)
    join allowed on allowed.value = input.value
    group by input.value
  )
  select array_agg(allowed.value order by coalesce(input_order.ordinality, 1000 + allowed.position), allowed.position)
  from allowed
  left join input_order on input_order.value = allowed.value;
$$;


ALTER FUNCTION "public"."normalize_workspace_widget_order"("target_widget_order" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_actor_is_active_member_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select actor_user_id is not null and exists (
    select 1
    from public.workspace_memberships membership
    where membership.workspace_id = target_workspace_id
      and membership.user_id = actor_user_id
      and membership.status = 'active'
  );
$$;


ALTER FUNCTION "public"."notification_actor_is_active_member_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_default_channels_service"("actor_user_id" "uuid", "target_type_key" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select jsonb_build_object('in_app','enabled','email',case when c.severity='action_required'
  or exists(select 1 from app_private.notification_legacy_default_accounts a where a.user_id=actor_user_id)
  then 'enabled' else 'disabled' end)
 from public.notification_catalog c where c.type_key=target_type_key order by c.schema_version desc limit 1;
$$;


ALTER FUNCTION "public"."notification_default_channels_service"("actor_user_id" "uuid", "target_type_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_user_channel_lock_reason_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_type_key" "text", "target_channel" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if exists(select 1 from public.notification_catalog where type_key=target_type_key and notification_scope='account') then return 'mandatory_account_security'; end if;
 if target_channel='email' then
  if not exists(select 1 from auth.users where id=actor_user_id and email_confirmed_at is not null) then return 'email_unverified'; end if;
  -- There is currently no workspace email sender. Catalog support is not delivery capability.
  return 'delivery_unavailable';
 end if;
 return public.notification_user_channel_lock_reason_workspace_base(actor_user_id,target_workspace_id,target_type_key,target_channel);
end; $$;


ALTER FUNCTION "public"."notification_user_channel_lock_reason_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_type_key" "text", "target_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_user_channel_lock_reason_workspace_base"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_type_key" "text", "target_channel" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  catalog public.notification_catalog%rowtype;
  actor_role_id uuid;
  global_policy public.notification_org_policies%rowtype;
  role_policy public.notification_org_policies%rowtype;
begin
  if target_channel not in ('in_app', 'email', 'push') then
    return 'channel_unknown';
  end if;

  select * into catalog
  from public.notification_catalog entry
  where entry.type_key = target_type_key
    and entry.lifecycle = 'active'
  order by entry.schema_version desc
  limit 1;
  if catalog.type_key is null then
    return 'catalog_type_inactive';
  end if;
  if not (target_channel = any(catalog.supported_channels)) then
    return 'catalog_channel_unsupported';
  end if;

  select membership.role_id into actor_role_id
  from public.workspace_memberships membership
  where membership.workspace_id = target_workspace_id
    and membership.user_id = actor_user_id
    and membership.status = 'active';
  if actor_role_id is null then
    return 'workspace_membership_required';
  end if;

  select * into global_policy
  from public.notification_org_policies policy
  where policy.workspace_id = target_workspace_id
    and policy.type_key = target_type_key
    and policy.role_id is null
    and policy.location_id is null
  order by policy.version desc
  limit 1;
  if global_policy.id is not null and
    (not global_policy.enabled or not (target_channel = any(global_policy.allowed_channels))) then
    return 'organization_policy_denied';
  end if;

  select * into role_policy
  from public.notification_org_policies policy
  where policy.workspace_id = target_workspace_id
    and policy.type_key = target_type_key
    and policy.role_id = actor_role_id
    and policy.location_id is null
  order by policy.version desc
  limit 1;
  if role_policy.id is not null and
    (not role_policy.enabled or not (target_channel = any(role_policy.allowed_channels))) then
    return 'role_policy_denied';
  end if;

  return 'available';
end;
$$;


ALTER FUNCTION "public"."notification_user_channel_lock_reason_workspace_base"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_type_key" "text", "target_channel" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."notification_user_preferences" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "preference_scope" "text" NOT NULL,
    "scope_key" "text" NOT NULL,
    "channel_preferences" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "cadence" "text",
    "timezone" "text",
    "quiet_hours" "jsonb",
    "safe_preview_enabled" boolean DEFAULT true NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "notification_user_preferences_cadence_check" CHECK ((("cadence" IS NULL) OR ("cadence" = ANY (ARRAY['immediate'::"text", 'daily_digest'::"text", 'weekly_digest'::"text"])))),
    CONSTRAINT "notification_user_preferences_channel_preferences_check" CHECK (("jsonb_typeof"("channel_preferences") = 'object'::"text")),
    CONSTRAINT "notification_user_preferences_preference_scope_check" CHECK (("preference_scope" = ANY (ARRAY['category'::"text", 'type'::"text"]))),
    CONSTRAINT "notification_user_preferences_quiet_hours_check" CHECK ((("quiet_hours" IS NULL) OR ("jsonb_typeof"("quiet_hours") = 'object'::"text"))),
    CONSTRAINT "notification_user_preferences_scope_key_check" CHECK ((("char_length"("btrim"("scope_key")) >= 1) AND ("char_length"("btrim"("scope_key")) <= 160))),
    CONSTRAINT "notification_user_preferences_timezone_check" CHECK ((("timezone" IS NULL) OR (("char_length"("timezone") >= 1) AND ("char_length"("timezone") <= 80)))),
    CONSTRAINT "notification_user_preferences_version_check" CHECK (("version" > 0))
);


ALTER TABLE "public"."notification_user_preferences" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notification_user_preference_to_json"("preference" "public"."notification_user_preferences") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', preference.id,
    'preference_scope', preference.preference_scope,
    'scope_key', preference.scope_key,
    'channel_preferences', preference.channel_preferences,
    'cadence', preference.cadence,
    'timezone', preference.timezone,
