CREATE OR REPLACE FUNCTION "public"."notify_schedule_request_event_service"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r public.schedule_time_off_requests%rowtype;
  requester uuid;
  recipients uuid[];
  is_cancel boolean;
  title text;
  body text;
  preview text;
  url text;
begin
  select * into r from public.schedule_time_off_requests where id = new.request_id and workspace_id = new.workspace_id;
  if r.id is null then
    return new;
  end if;
  -- BL-182/BL-127: a shortening tells its own people (requests.time_off.shortened).
  if public.time_off_event_is_shortening(new.workspace_id, new.request_id, new.metadata) then
    return new;
  end if;
  is_cancel := r.request_type = 'time_off_cancellation';
  select e.user_id into requester from public.employee_profiles e where e.id = r.employee_id and e.workspace_id = r.workspace_id;

  if new.action = 'submitted' then
    -- The owner's own time off is recorded without review (BL-183).
    if public.time_off_is_the_owners_own(new.actor_user_id, new.workspace_id, new.request_id) then
      return new;
    end if;
    select coalesce(array_agg(u order by u), '{}') into recipients
    from unnest(app_private.time_off_deciders(new.workspace_id, r.id)) u where u is distinct from new.actor_user_id;
    perform public.enqueue_notification_outbox_service(new.workspace_id, new.id, 'requests.time_off.submitted', 1, new.actor_user_id,
      tg_table_name, new.request_id::text,
      jsonb_build_object('correlation_id', new.id, 'request_id', new.request_id, 'request_event_id', new.id, 'request_action', new.action,
        'recipient_user_ids', to_jsonb(recipients), 'audience_contract', 'schedule_request_reviewers', 'category', 'request',
        'title', case when is_cancel then 'Leave cancellation requested' else 'New time-off request' end,
        'body', case when is_cancel then 'Review the proposed cancellation. Approved leave stays in effect until accepted.'
          else 'A time-off request needs your decision.' end,
        'safe_preview', case when is_cancel then 'A leave cancellation needs review.' else 'A schedule request needs review.' end,
        'action_url', '/app/schedule/requests?tab=time-off&request=' || new.request_id::text,
        'group_key', tg_table_name || ':' || new.request_id::text),
      new.created_at);
    return new;
  end if;

  -- The person who asked, unless they did it themselves.
  title := case when is_cancel then 'Leave cancellation updated' else 'Time-off request updated' end;
  body := case
    when new.action = 'expired' then 'Your request was not decided in time and was declined.'
    when is_cancel and new.action = 'denied' then 'Your cancellation was declined. The approved leave remains in effect.'
    when is_cancel and new.action = 'revoked' then 'Your cancellation request was closed. Review the original leave for its current status.'
    when is_cancel then 'Your leave cancellation was reviewed. Shifts opened earlier stay open.'
    else 'Your time-off request status changed.' end;
  preview := case when is_cancel then 'A leave cancellation was updated.' else 'A schedule request was updated.' end;
  url := case when is_cancel then '/app/employee-hub/my-availability#request-' || new.request_id::text else '/app/employee-hub/my-availability' end;
  perform public.enqueue_notification_outbox_service(new.workspace_id, new.id, 'requests.time_off.status_changed', 1, new.actor_user_id,
    tg_table_name, new.request_id::text,
    jsonb_build_object('correlation_id', new.id, 'request_id', new.request_id, 'request_event_id', new.id, 'request_action', new.action,
      'recipient_user_ids', to_jsonb(case when requester is not null and requester is distinct from new.actor_user_id then array[requester] else '{}'::uuid[] end),
      'audience_contract', 'time_off_requester', 'category', 'request',
      'title', title, 'body', body, 'safe_preview', preview, 'action_url', url,
      'group_key', tg_table_name || ':' || new.request_id::text),
    new.created_at);

  -- The managers who could have decided it, but not who closed it; never for
  -- the owner's own time off.
  -- No actor (the system's own decline) is never the owner's own.
  if new.action in ('approved', 'denied', 'revoked', 'expired')
     and not coalesce(public.time_off_is_the_owners_own(new.actor_user_id, new.workspace_id, new.request_id), false) then
    select coalesce(array_agg(u order by u), '{}') into recipients
    from unnest(app_private.time_off_deciders(new.workspace_id, r.id, false)) u where u is distinct from new.actor_user_id;
    if cardinality(recipients) > 0 then
      perform public.enqueue_notification_outbox_service(new.workspace_id, gen_random_uuid(), 'requests.time_off.decided', 1, new.actor_user_id,
        tg_table_name, new.request_id::text,
        jsonb_build_object('correlation_id', new.id, 'request_id', new.request_id, 'request_event_id', new.id, 'request_action', new.action,
          'recipient_user_ids', to_jsonb(recipients), 'audience_contract', 'time_off_deciders', 'category', 'request',
          'title', case new.action when 'approved' then 'Time off approved' when 'denied' then 'Time off declined'
            when 'expired' then 'Time off not decided in time' else 'Time off withdrawn or revoked' end,
          'body', case when is_cancel then 'A leave cancellation you could decide was closed.' else 'A time-off request you could decide was closed.' end,
          'safe_preview', 'A time-off request was closed.',
          'action_url', '/app/schedule/requests?tab=time-off&request=' || new.request_id::text,
          'group_key', tg_table_name || ':' || new.request_id::text),
        new.created_at);
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."notify_schedule_request_event_service"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_time_off_shortened"("actor" "uuid", "w" "uuid", "parent_id" "uuid", "cut" "tstzmultirange", "zone_name" "text", "source" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare fmt text; employee_user uuid; employee_name text; lines text; deciders uuid[];
 by_manager boolean:=coalesce(source->>'source','')='manager';
begin
 fmt := case when (select s.time_format from public.workspace_scheduling_settings s where s.workspace_id = w) = '24h'
  then 'HH24:MI' else 'FMHH12:MI AM' end;
 select e.user_id, coalesce(nullif(e.preferred_name, ''), e.first_name) into employee_user, employee_name
  from public.schedule_time_off_requests r join public.employee_profiles e on e.id = r.employee_id and e.workspace_id = r.workspace_id
  where r.id = parent_id and r.workspace_id = w;
 -- "Wed, Oct 1, 10:00 AM–2:00 PM", in the leave's own time zone.
 select string_agg(to_char(lower(p) at time zone zone_name, 'Dy, Mon FMDD') || ', ' || to_char(lower(p) at time zone zone_name, fmt)
   || '–' || to_char(upper(p) at time zone zone_name, fmt), '; ' order by lower(p))
  into lines from unnest(cut) p;
 -- Whoever approved the leave (its decisions), but not the one shortening it
 -- and not the employee: the owner's own leave is approved by themselves.
 select coalesce(array_agg(distinct ev.actor_user_id order by ev.actor_user_id), '{}') into deciders
  from public.schedule_time_off_events ev
  join public.workspace_memberships m on m.workspace_id = w and m.user_id = ev.actor_user_id and m.status = 'active'
  where ev.workspace_id = w and ev.request_id = parent_id and ev.action = 'approved'
   and ev.metadata ? 'segments' and ev.actor_user_id <> actor and ev.actor_user_id is distinct from employee_user;
 if cardinality(deciders) > 0 then
  perform public.enqueue_notification_outbox_service(w, gen_random_uuid(), 'requests.time_off.shortened', 1, actor,
   'schedule_time_off_requests', parent_id::text,
   jsonb_build_object('request_id', parent_id, 'recipient_user_ids', to_jsonb(deciders),
    'audience_contract', 'time_off_deciders', 'category', 'requests',
    'title', left(coalesce(employee_name, 'An employee') || '''s time off was shortened', 160),
    'body', left(lines || case when by_manager then ' is back on the schedule.' else ' — they took a shift in these hours.' end, 500),
    'safe_preview', 'Approved time off was shortened.',
    'action_url', '/app/schedule/requests?tab=time-off&request=' || parent_id::text,
    'group_key', 'schedule_time_off_requests:' || parent_id::text),
   now());
 end if;
 -- The employee agreed in Shift Hub themselves; a manager's shortening is news to them.
 if by_manager and employee_user is not null and employee_user <> actor
  and exists (select 1 from public.workspace_memberships m where m.workspace_id = w and m.user_id = employee_user and m.status = 'active') then
  perform public.enqueue_notification_outbox_service(w, gen_random_uuid(), 'requests.time_off.shortened', 1, actor,
   'schedule_time_off_requests', parent_id::text,
   jsonb_build_object('request_id', parent_id, 'recipient_user_ids', jsonb_build_array(employee_user),
    'audience_contract', 'time_off_requester', 'category', 'requests',
    'title', 'Your time off was shortened',
    'body', left(lines || ' is no longer time off. Your manager can put you on the schedule then.', 500),
    'safe_preview', 'Approved time off was shortened.',
    'action_url', '/app/employee-hub/my-availability#request-' || parent_id::text,
    'group_key', 'schedule_time_off_requests:' || parent_id::text),
   now());
 end if;
end;
$$;


ALTER FUNCTION "public"."notify_time_off_shortened"("actor" "uuid", "w" "uuid", "parent_id" "uuid", "cut" "tstzmultirange", "zone_name" "text", "source" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organization_job_counts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result jsonb;
  me app_private.actor_state := app_private.actor(actor_user_id, target_workspace_id);
  read_rule app_private.authz_actions;
begin
  perform app_private.authorize_employee_list(actor_user_id, target_workspace_id);
  select * into read_rule from app_private.authz_actions r where r.key = 'employee.list';
  with memberships as materialized (
    select a.employee_id,a.job_id,j.department_id,j.archived_at
    from public.employee_job_assignments a
    join public.jobs j on j.id=a.job_id and j.workspace_id=a.workspace_id
    join public.employee_profiles e on e.id=a.employee_id and e.workspace_id=a.workspace_id
    where a.workspace_id=target_workspace_id and a.ended_at is null and e.archived_at is null
      and app_private.authz_check(me, read_rule, null, e.id, null) is null
  )
  select jsonb_build_object(
    'jobs',coalesce((select jsonb_agg(to_jsonb(c)) from (
      select job_id as id,count(distinct employee_id) as employee_count from memberships group by job_id)c),'[]'),
    'departments',coalesce((select jsonb_agg(to_jsonb(c)) from (
      select department_id as id,count(distinct employee_id) as employee_count from memberships
      where department_id is not null group by department_id)c),'[]')
  ) into result;
  return result;
end; $$;


ALTER FUNCTION "public"."organization_job_counts_service"("actor_user_id" "uuid", "target_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_account_deletion_delivery_service"("target_request_id" "uuid", "target_lease_id" "uuid", "delivery_kind" "text", "recovery_token_digest" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare request public.account_deletion_requests%rowtype;
begin
  select * into request from public.account_deletion_requests
  where id = target_request_id and status = 'pending'
    and work_lease_id = target_lease_id and work_lease_until > now()
    and restore_until > now() for update;
  if request.id is null then raise exception 'account deletion lease unavailable'; end if;
  insert into public.account_deletion_deliveries(request_id, delivery_kind, token_digest)
  values (request.id, delivery_kind, recovery_token_digest)
  on conflict on constraint account_deletion_deliveries_pkey do nothing;
  if not exists (select 1 from public.account_deletion_deliveries d
    where d.request_id = request.id and d.delivery_kind = prepare_account_deletion_delivery_service.delivery_kind
      and d.token_digest = recovery_token_digest) then
    raise exception 'account deletion delivery token changed';
  end if;
  return jsonb_build_object('email', request.typed_email, 'restore_until', request.restore_until);
end;
$$;


ALTER FUNCTION "public"."prepare_account_deletion_delivery_service"("target_request_id" "uuid", "target_lease_id" "uuid", "delivery_kind" "text", "recovery_token_digest" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_account_deletion_recovery_resend_service"("account_email" "text", "recovery_token_digest" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  target_request public.account_deletion_requests%rowtype;
  normalized_email text := lower(btrim(coalesce(account_email, '')));
begin
  if recovery_token_digest is null
    or recovery_token_digest !~ '^[a-f0-9]{64}$' then
    raise exception 'valid recovery token digest required' using errcode = '22023';
  end if;

  select request.* into target_request
  from public.account_deletion_requests request
  join auth.users auth_user on auth_user.id = request.user_id
  where request.status = 'pending'
    and request.restore_until > now()
    and lower(btrim(auth_user.email)) = normalized_email
  order by request.requested_at desc
  limit 1
  for update of request;

  if target_request.id is null then
    return null;
  end if;

  -- KK-11: at most one new link per fifteen minutes; the link already in the
  -- inbox stays valid until then.
  if target_request.recovery_token_rotated_at > now() - interval '15 minutes' then
    return null;
  end if;

  update public.account_deletion_requests
  set recovery_token_digest = prepare_account_deletion_recovery_resend_service.recovery_token_digest,
      recovery_token_rotated_at = now(),
      updated_at = now()
  where id = target_request.id;

  return jsonb_build_object(
    'request_id', target_request.id,
    'user_id', target_request.user_id,
    'email', normalized_email,
    'restore_until', target_request.restore_until
  );
end;
$_$;


ALTER FUNCTION "public"."prepare_account_deletion_recovery_resend_service"("account_email" "text", "recovery_token_digest" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_employee_invitation_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "employee_email" "text", "target_role_id" "uuid", "invitation_token_hash" "text", "invitation_expires_at" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  invitation_id uuid;
  invite_role public.workspace_roles%rowtype;
  assigned_location_ids uuid[];
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.invite', target_person => target_employee_id);
  if employee_email <> lower(btrim(employee_email)) or employee_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'valid normalized invitation email required' using errcode = '22023';
  end if;
  if invitation_token_hash !~ '^[0-9a-f]{64}$' or invitation_expires_at <= now() then
    raise exception 'valid invitation token and expiry required' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.employee_profiles employee
    where employee.id = target_employee_id
      and employee.workspace_id = target_workspace_id
      and employee.archived_at is null
      and employee.user_id is null
  ) then
    raise exception 'invitable employee not found' using errcode = 'P0002';
  end if;

  if target_role_id is null then
    select * into invite_role from public.workspace_roles
    where workspace_id = target_workspace_id and system_key = 'employee';
  else
    select * into invite_role from public.workspace_roles
    where workspace_id = target_workspace_id and id = target_role_id;
  end if;
  if invite_role.id is null then
    raise exception 'invitation role is unavailable' using errcode = '22023';
  end if;
  if not app_private.can_invite_with_role(actor_user_id, target_workspace_id, invite_role.id) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.rank', detail = 'employee.invite';
  end if;

  -- K4: nobody without a location is invited as a manager, unless Remote.
  perform app_private.keep_manager_at_a_location(target_workspace_id, target_employee_id, invite_role.access_class);

  select coalesce(array_agg(location_id order by location_id), '{}') into assigned_location_ids
  from public.employee_location_assignments
  where employee_id = target_employee_id and ended_at is null;
  if cardinality(assigned_location_ids) = 0 and not exists (
    select 1 from public.employee_profiles where id = target_employee_id
      and workspace_id = target_workspace_id and (is_remote or is_excluded_from_schedule)
  ) then
    raise exception 'employee requires a location before invitation' using errcode = '22023';
  end if;

  -- Inviting again takes back what was waiting: only an invitation the actor
  -- could take back themselves (nf-guvenlik O-2).
  if exists (
    select 1 from public.employee_invitations pending
    where pending.employee_id = target_employee_id and pending.status = 'pending'
      and not app_private.can_invite_with_role(actor_user_id, target_workspace_id, pending.role_id)
  ) then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.rank', detail = 'employee.invite';
  end if;
  update public.employee_invitations
  set status = 'revoked', revoked_at = now(), updated_at = now()
  where employee_id = target_employee_id and status = 'pending';
  insert into public.employee_invitations (
    workspace_id, employee_id, email, role_id, all_locations, location_ids,
    token_hash, expires_at, created_by, delivery_status
  ) values (
    target_workspace_id, target_employee_id, employee_email, invite_role.id,
    invite_role.access_class in ('admin', 'employee'),
    case when invite_role.access_class in ('admin', 'employee') then '{}'::uuid[] else assigned_location_ids end, invitation_token_hash, invitation_expires_at,
    actor_user_id, 'pending'
  ) returning id into invitation_id;
  update public.employee_profiles
  set invitation_email = employee_email, revision = revision + 1, updated_at = now()
  where id = target_employee_id;
  insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary)
  values (target_workspace_id, target_employee_id, actor_user_id, 'employee.invited', 'Employee invitation prepared');
  return invitation_id;
end;
$_$;


ALTER FUNCTION "public"."prepare_employee_invitation_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "employee_email" "text", "target_role_id" "uuid", "invitation_token_hash" "text", "invitation_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_weekly_schedule_assignment"("actor" "uuid", "w" "uuid", "s" "jsonb", "previous" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a jsonb; preview jsonb; evidence jsonb; logical_id uuid:=coalesce(s->>'source_shift_id',s->>'id')::uuid;
 loc uuid:=(s->>'location_id')::uuid; emp uuid:=(s->>'employee_id')::uuid;
begin
 perform public.availability_lock_workspace(w);
 if logical_id is null then
  raise exception 'Schedule location access denied' using errcode='42501'; end if;
 perform app_private.authorize(actor, w, 'schedule.edit', target_locations => array[loc]);
 if emp is not null and not exists(select 1 from public.employee_location_assignments
  where workspace_id=w and employee_id=emp and location_id=loc and ended_at is null) then
  raise exception 'Employee is not assigned to this location' using errcode='42501'; end if;
 
 
 s:=s||jsonb_build_object('_exclude_shift_id',logical_id);
 a:=public.assess_weekly_shift_availability(w,emp,s);
 if a->>'operation' in ('blocked','verification_required') then
  raise exception '%',coalesce((select string_agg(r->>'message',' ') from jsonb_array_elements(a->'reasons') r where r->>'severity'='block'),'Scheduling rules block this assignment') using errcode='23514',detail=a::text;
 end if;
 if emp is null then
   if a->>'operation'='warning_requires_override' and s->>'availability_assessment_fingerprint' is distinct from
    public.assess_weekly_shift_availability(w,emp,s-'id'-'source_shift_id')->>'fingerprint' then
    raise exception 'Review the current availability assessment before saving' using errcode='PT409';
   end if;
   if a->>'operation'='warning_requires_override' then
    insert into public.audit_events(workspace_id,actor_user_id,action,target_type,target_id,metadata)
    values(w,actor,'schedule.conflict_accepted','shift',logical_id::text,jsonb_build_object('assessment',a));
   end if;
   return;
  end if;
  evidence:=public.schedule_availability_override(w,s,a);
 -- Only an existing same-identity assignment can reuse its acceptance.
 if evidence is not null and previous is not null
  and coalesce(previous->>'source_shift_id',previous->>'id')=logical_id::text
  and previous->>'employee_id'=emp::text then return; end if;
 if a->>'operation'='warning_requires_override' then
  preview:=public.assess_weekly_shift_availability(w,emp,s-'id'-'source_shift_id');
  if s->>'availability_assessment_fingerprint' is distinct from preview->>'fingerprint' then
   raise exception 'Review the current availability assessment before saving' using errcode='PT409'; end if;
 end if;
 update public.schedule_availability_overrides set revoked_at=now() where workspace_id=w and shift_id=logical_id and revoked_at is null;
 if a->>'operation'='warning_requires_override' then
  insert into public.schedule_availability_overrides(workspace_id,shift_id,employee_id,location_id,assessment_fingerprint,assessment,reason,actor_user_id)
  values(w,logical_id,emp,loc,a->>'fingerprint',a,
   case when a->>'warning_policy'='confirm' then 'Schedule conflict confirmed by manager.' else 'Schedule warning acknowledged (warn policy).' end,actor);
 end if;
end; $$;


ALTER FUNCTION "public"."prepare_weekly_schedule_assignment"("actor" "uuid", "w" "uuid", "s" "jsonb", "previous" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_department_archive_with_active_jobs"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if old.archived_at is null and new.archived_at is not null and exists (
    select 1 from public.jobs job
    where job.workspace_id = new.workspace_id
      and job.department_id = new.id
      and job.archived_at is null
  ) then
    raise exception 'archive active jobs before archiving their department' using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_department_archive_with_active_jobs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_last_workspace_owner_removal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  workspace_state public.workspace_lifecycle_status;
  transfer_bypass boolean := coalesce(current_setting('app.owner_transfer', true), '') = 'on';
begin
  if old.role <> 'owner' or old.status <> 'active' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  select lifecycle_status into workspace_state
  from public.workspaces
  where id = old.workspace_id;

  if workspace_state = 'deleted' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_op = 'UPDATE' and new.role = 'owner' and new.status = 'active' then
    return new;
  end if;

  if not exists (
    select 1
    from public.workspace_memberships other
    where other.workspace_id = old.workspace_id
      and other.id <> old.id
      and other.role = 'owner'
      and other.status = 'active'
  ) then
    raise exception 'workspace must retain an active owner' using errcode = '23514';
  end if;

  if not transfer_bypass then
    raise exception 'owner role can only be changed through ownership transfer'
      using errcode = '23514';
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION "public"."prevent_last_workspace_owner_removal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_owner_employee_archive"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.archived_at is not null
    and old.archived_at is distinct from new.archived_at
    and old.user_id is not null
    and exists (
      select 1
      from public.workspace_memberships membership
      where membership.workspace_id = old.workspace_id
        and membership.user_id = old.user_id
        and membership.role = 'owner'::public.workspace_role
    ) then
    raise exception 'owner employee record cannot be archived through ordinary lifecycle'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_owner_employee_archive"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_document_publication_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d public.document_types%rowtype; result jsonb; effects jsonb; scope_options jsonb; pair text[]; identities jsonb; token text;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'settings.documents.write');
 select * into d from public.document_types where id=target_document_type_id and workspace_id=target_workspace_id;
 if d.id is null then raise exception 'document type not found' using errcode='P0002'; end if;
 if d.archived_at is not null then raise exception 'Archived documents cannot be published; restore first' using errcode='PT409'; end if;
 perform app_private.assert_document_definition_target(actor_user_id,target_workspace_id,d.lifecycle_settings->'target');
 result:=app_private.preview_lifecycle_definition(actor_user_id,target_workspace_id,d.id,'document');
 if d.publication_status='published' then
  select coalesce(jsonb_agg(jsonb_build_object('employee_id',r.employee_id,'employee_name',concat_ws(' ',e.first_name,e.last_name),'employee_revision',e.revision,
    'requirement_id',r.id,'revision',r.lifecycle_revision,'action','pause','deadline_action','pause') order by r.id),'[]') into effects
  from public.employee_onboarding_requirements r join public.employee_profiles e on e.id=r.employee_id and e.workspace_id=r.workspace_id
  where r.workspace_id=target_workspace_id and r.source_id=d.id and r.kind='document' and r.lifecycle_retired_at is null and r.lifecycle_closed_at is null and not r.lifecycle_exempt and not r.lifecycle_assignment_disabled;
  result:=jsonb_set(result,'{employees}',effects);
 end if;
 scope_options:=public.document_definition_target_options_service(actor_user_id,target_workspace_id);
 -- Include selected identities and the actual locations/jobs/departments of affected employees.
 foreach pair slice 1 in array array[['location_ids','locations'],['department_ids','departments'],['job_ids','jobs'],['employee_ids','named_people']] loop
  select coalesce(jsonb_agg(o order by o->>'name',o->>'id'),'[]') into identities
  from jsonb_array_elements(scope_options->case when pair[2]='named_people' then 'employees' else pair[2] end) o
  where (pair[2]<>'named_people' and jsonb_array_length(coalesce(d.lifecycle_settings->'target'->pair[1],'[]'))=0) or (d.lifecycle_settings->'target'->pair[1]) ? (o->>'id') or (pair[2]<>'named_people' and exists(
   select 1 from jsonb_array_elements(result->'employees') effect
   where effect->>'action' not in ('unchanged','exempt') and (
    (pair[2]='locations' and exists(select 1 from public.employee_location_assignments a where a.workspace_id=target_workspace_id and a.employee_id=(effect->>'employee_id')::uuid and a.ended_at is null and a.location_id=(o->>'id')::uuid)) or
    (pair[2] in ('jobs','departments') and exists(select 1 from public.employee_job_assignments a join public.jobs j on j.id=a.job_id and j.workspace_id=a.workspace_id where a.workspace_id=target_workspace_id and a.employee_id=(effect->>'employee_id')::uuid and a.ended_at is null and (case when pair[2]='jobs' then j.id else j.department_id end)=(o->>'id')::uuid))
   )));
  result:=result||jsonb_build_object(pair[2],identities);
 end loop;
 -- Return exact matcher membership even for unchanged/exempt rows; bind it to the confirmation token.
 select coalesce(jsonb_agg(effect || jsonb_build_object('matches_target',
   exists(select 1 from public.employee_profiles e join public.workspace_memberships m on m.workspace_id=e.workspace_id and m.user_id=e.user_id
    where e.id=(effect->>'employee_id')::uuid and e.workspace_id=target_workspace_id and e.archived_at is null and m.status in ('active','pending_activation')
      and app_private.document_target_matches(e.workspace_id,e.id,d.lifecycle_settings->'target')))
   order by position),'[]') into effects
 from jsonb_array_elements(result->'employees') with ordinality as entries(effect,position);
 result:=jsonb_set(result,'{employees}',effects);
 result:=(result-'preview_token')||jsonb_build_object('publication_revision',d.publication_revision,'target',d.lifecycle_settings->'target','assignment_scope',d.lifecycle_settings->>'assignment_scope','transition',case when d.publication_status='draft' then 'publish' else 'unpublish' end);
 token:=encode(extensions.digest(convert_to(jsonb_build_object('actor',actor_user_id,'definition',to_jsonb(d),'impact',result)::text,'UTF8'),'sha256'),'hex');
 return result||jsonb_build_object('preview_token',token);
end;
$$;


ALTER FUNCTION "public"."preview_document_publication_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_document_type_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_employee_document_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "proposed_location_ids" "uuid"[], "proposed_job_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype; d app_private.lifecycle_definition%rowtype; p public.employee_profiles%rowtype; m public.workspace_memberships%rowtype;
 result jsonb:='[]'; matching boolean; action text; readable boolean; approved boolean; next_deadline timestamptz;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'employee.save',target_person=>target_employee_id);
 select * into p from public.employee_profiles where id=target_employee_id and workspace_id=target_workspace_id;
 if p.id is null then raise exception 'employee unavailable' using errcode='P0002'; end if;
 if proposed_location_ids is null or proposed_job_ids is null or cardinality(proposed_location_ids)>100 or cardinality(proposed_job_ids)>100
  or exists(select 1 from unnest(proposed_location_ids) proposed(id) where proposed.id is null or not exists(select 1 from public.locations l where l.id=proposed.id and l.workspace_id=target_workspace_id and l.archived_at is null) or not proposed.id = any (app_private.scope_set(actor_user_id,target_workspace_id,'employee.save')))
  or exists(select 1 from unnest(proposed_job_ids) proposed(id) where proposed.id is null or not exists(select 1 from public.jobs j where j.id=proposed.id and j.workspace_id=target_workspace_id and j.archived_at is null))
 then raise exception 'Not allowed' using errcode='42501', hint='authz.out_of_scope', detail='employee.save'; end if;
 select * into m from public.workspace_memberships where workspace_id=target_workspace_id and user_id=p.user_id;
 if p.archived_at is not null or m.id is null or m.status not in ('active','pending_activation') then return result; end if;
 readable:=app_private.authz_reason(actor_user_id,target_workspace_id,'documents.read',null,target_employee_id) is null;
 for r in select * from public.employee_onboarding_requirements where workspace_id=target_workspace_id and employee_id=target_employee_id and kind in ('document','acknowledgement') and lifecycle_retired_at is null and source_id is not null and not lifecycle_exempt and not lifecycle_assignment_disabled loop
  matching:=app_private.document_target_matches_assignments(target_workspace_id,target_employee_id,r.lifecycle_settings->'target',proposed_location_ids,proposed_job_ids);
  action:=case when not matching and r.lifecycle_closed_at is null then 'remove' when matching and (r.lifecycle_closed_at is not null or r.status='superseded') then 'reopen' end;
  if action is null then continue; end if;
  next_deadline:=null;
  if action='reopen' then
   r.lifecycle_closed_at:=null; if r.status='superseded' then r.status:='not_started'; end if;
   approved:=app_private.document_obligation_state(r,now())='completed';
   if not approved and m.status='active' and r.lifecycle_settings->>'mode'<>'optional' then next_deadline:=now()+(r.lifecycle_settings->>'period_days')::integer*interval '24 hours'; end if;
  end if;
  result:=result||jsonb_build_array(jsonb_build_object('title',case when readable then r.title else 'Document requirement' end,'action',action,'deadline_at',next_deadline,'period_days',(r.lifecycle_settings->>'period_days')::integer,'clears_block',action='remove' and app_private.document_obligation_blocked(r,now())));
 end loop;
 for d in select * from app_private.lifecycle_definition q where q.workspace_id=target_workspace_id and q.archived_at is null and q.current_version
  and (m.status='pending_activation' or q.lifecycle_settings->>'assignment_scope'='all_active')
  and app_private.document_target_matches_assignments(target_workspace_id,target_employee_id,q.lifecycle_settings->'target',proposed_location_ids,proposed_job_ids)
  and not exists(select 1 from public.employee_onboarding_requirements existing_req where existing_req.workspace_id=target_workspace_id and existing_req.employee_id=target_employee_id and existing_req.kind::text=q.kind and existing_req.source_id=q.id and existing_req.lifecycle_retired_at is null) loop
  next_deadline:=case when m.status='active' and d.lifecycle_settings->>'mode'<>'optional' then now()+(d.lifecycle_settings->>'period_days')::integer*interval '24 hours' end;
  result:=result||jsonb_build_array(jsonb_build_object('title',case when readable then d.title else 'Document requirement' end,'action','assign','deadline_at',next_deadline,'period_days',(d.lifecycle_settings->>'period_days')::integer,'clears_block',false));
 end loop;
 return result;
end;
$$;


ALTER FUNCTION "public"."preview_employee_document_assignments_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "proposed_location_ids" "uuid"[], "proposed_job_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_employee_invitation_service"("invitation_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (
      select jsonb_build_object(
        'state', case
          when invitation.status = 'pending'::public.employee_invitation_status
               and invitation.expires_at <= now()
            then 'expired'
          when invitation.status <> 'pending'::public.employee_invitation_status
            then invitation.status::text
          when workspace.lifecycle_status <> 'active'::public.workspace_lifecycle_status
               and not (
                 workspace.lifecycle_status = 'closure_scheduled'::public.workspace_lifecycle_status
                 and workspace.closure_effective_at > now()
               )
            then 'workspace_unavailable'
          else 'valid'
        end,
        'workspace_name', workspace.name,
        'email', invitation.email,
        'expires_at', invitation.expires_at
      )
      from public.employee_invitations invitation
      join public.workspaces workspace on workspace.id = invitation.workspace_id
      where invitation.token_hash = invitation_token_hash
      limit 1
    ),
    jsonb_build_object('state', 'not_found')
  );
$$;


ALTER FUNCTION "public"."preview_employee_invitation_service"("invitation_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_important_date_closure_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_important_date_id" "uuid", "target_type" "text", "target_starts_on" "date", "target_ends_on" "date", "target_recurrence" "text", "target_location_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  stored public.important_dates;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.important_dates.read');
  target_location_ids := array(select distinct id from unnest(coalesce(target_location_ids, '{}')) id order by id);
  if target_important_date_id is null then
    perform app_private.communication_authorize(actor_user_id, target_workspace_id, 'important_date', target_location_ids, actor_user_id);
  else
    select * into stored from public.important_dates
    where id = target_important_date_id and workspace_id = target_workspace_id;
    if stored.id is null or not app_private.important_date_visible(actor_user_id, stored) then
      raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope', detail = 'important_date.write';
    end if;
    perform app_private.communication_authorize(actor_user_id, target_workspace_id, 'important_date', stored.location_ids, stored.created_by, stored.location_ids);
    perform app_private.communication_authorize(actor_user_id, target_workspace_id, 'important_date', target_location_ids, stored.created_by, stored.location_ids);
  end if;
  if target_type not in ('holiday', 'event', 'blackout', 'closed_day') or target_recurrence not in ('none', 'annual')
     or target_starts_on is null or target_ends_on is null or target_ends_on < target_starts_on then
    raise exception 'valid important date required' using errcode = '22023';
  end if;
  return (
    select jsonb_build_object(
      'fingerprint', impact ->> 'fingerprint',
      'shifts', coalesce((select jsonb_agg(x order by ord) from jsonb_array_elements(impact -> 'shifts') with ordinality listed(x, ord)
                          where (x ->> 'location_id')::uuid = any (reach)), '[]'::jsonb),
      'hidden_shift_count', (select count(*) from jsonb_array_elements(impact -> 'shifts') x
                             where not (x ->> 'location_id')::uuid = any (reach)),
      'draft_shift_count', jsonb_array_length(impact -> 'draft_shift_ids'))
    from app_private.important_date_closure_impact(target_workspace_id, stored, target_type, target_starts_on,
      target_ends_on, target_recurrence, target_location_ids) impact,
      lateral (select app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.read') reach) scope);
end;
$$;


ALTER FUNCTION "public"."preview_important_date_closure_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_important_date_id" "uuid", "target_type" "text", "target_starts_on" "date", "target_ends_on" "date", "target_recurrence" "text", "target_location_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."preview_notification_policy_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_type_key" "text", "target_channel" "text", "target_recipient_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  catalog_row public.notification_catalog%rowtype;
  decision jsonb;
  requested_actor_user_id uuid := actor_user_id;
begin
  if not public.service_actor_has_permission(actor_user_id, target_workspace_id, 'notifications.test_send') then
    raise exception 'notification test-send access required' using errcode = '42501';
  end if;
  if target_recipient_user_id is not null and target_recipient_user_id <> actor_user_id then
    raise exception 'notification preview recipient must be current actor' using errcode = '42501';
  end if;
  select * into catalog_row
  from public.notification_catalog entry
  where entry.type_key = target_type_key
    and entry.schema_version = 1
    and entry.lifecycle = 'active';
  if catalog_row.type_key is null then
    raise exception 'active notification type not found' using errcode = 'P0002';
  end if;
  if not (target_channel = any(catalog_row.supported_channels)) then
    raise exception 'notification channel is not supported' using errcode = '22023';
  end if;
  if (
    select count(*)
    from public.notification_audit_log log
    where log.workspace_id = target_workspace_id
      and log.actor_user_id = requested_actor_user_id
      and log.action = 'notification.policy.previewed'
      and log.occurred_at >= now() - interval '1 minute'
  ) >= 5 then
    raise exception 'notification preview rate limit exceeded' using errcode = '54000';
  end if;

  decision := public.resolve_notification_policy_v1_service(
    target_workspace_id,
    actor_user_id,
    target_type_key,
    target_channel,
    null,
    null,
    '{}'::jsonb
  );

  insert into public.notification_audit_log (
    workspace_id, actor_user_id, action, target_type, target_id, reason, metadata
  ) values (
    target_workspace_id, actor_user_id, 'notification.policy.previewed',
    'notification_catalog', target_type_key, 'Safe preview only',
    jsonb_build_object(
      'channel', target_channel,
      'redirected_to_user_id', actor_user_id,
      'decision', decision->>'decision',
      'delivery_mode', 'preview_only'
    )
  );

  return jsonb_build_object(
    'status', 'previewed',
    'delivery_mode', 'preview_only',
    'redirected_to_user_id', actor_user_id,
    'decision', decision->>'decision',
    'reason_code', coalesce(decision->'reason_chain'->>-1, 'policy_evaluated')
  );
end;
$$;


ALTER FUNCTION "public"."preview_notification_policy_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_type_key" "text", "target_channel" "text", "target_recipient_user_id" "uuid") OWNER TO "postgres";


