CREATE OR REPLACE FUNCTION "public"."record_weekly_exchange_acceptance"("w" "uuid", "cid" "uuid", "aid" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.shift_exchange_cases%rowtype; app public.shift_exchange_applications%rowtype;
 s jsonb; t jsonb; item record; a jsonb; actor uuid; normalized jsonb;
begin
 select * into c from public.shift_exchange_cases where workspace_id=w and id=cid;
 select * into app from public.shift_exchange_applications where workspace_id=w and case_id=cid and id=aid;
 s:=public.shift_exchange_shift(w,c.offered_source_id); t:=public.shift_exchange_shift(w,c.requested_source_id);
 if c.id is null or app.id is null or c.status<>'open' or app.status<>'pending_manager'
  or public.shift_exchange_fingerprint(w,s,t) is distinct from c.consent_fingerprint
  or app.consent_fingerprint is distinct from c.consent_fingerprint then
  raise exception 'Current employee acceptance is required' using errcode='PT409'; end if;
 for item in select s target,app.employee_id emp union all select t,c.owner_id where c.kind='swap' loop
  normalized:=item.target||jsonb_build_object('id',item.target->>'source_id','employee_id',item.emp,
   '_exclude_shift_ids',to_jsonb(array_remove(array[(s->>'source_id')::uuid,(t->>'source_id')::uuid],null)));
  a:=public.assess_weekly_shift_availability(w,item.emp,normalized);
  if a->>'operation' in ('blocked','verification_required') then
   raise exception 'Resolve shift hours or approved time off before transfer' using errcode='23514'; end if;
  select user_id into actor from public.employee_profiles where workspace_id=w and id=item.emp;
  if actor is null then raise exception 'Employee acceptance identity unavailable' using errcode='42501'; end if;
  if a->>'operation'='warning_requires_override' then
   update public.schedule_availability_overrides set revoked_at=now()
    where workspace_id=w and shift_id=(item.target->>'source_id')::uuid and revoked_at is null;
   insert into public.schedule_availability_overrides(workspace_id,shift_id,employee_id,location_id,assessment_fingerprint,assessment,reason,actor_user_id)
   values(w,(item.target->>'source_id')::uuid,item.emp,(item.target->>'location_id')::uuid,a->>'fingerprint',
    a||jsonb_build_object('consent_source','shift_exchange','consent_case_id',cid,'consent_application_id',aid),
    'Employee voluntarily accepted this shift through Shift Hub.',actor);
  end if;
 end loop;
end; $$;


ALTER FUNCTION "public"."record_weekly_exchange_acceptance"("w" "uuid", "cid" "uuid", "aid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_weekly_exchange_terms"("w" "uuid", "cid" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.shift_exchange_cases%rowtype; s jsonb; t jsonb; fp text; deadline timestamptz;
 event_action text; message text; prior_details jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(w::text,921));
 select * into c from public.shift_exchange_cases where workspace_id=w and id=cid for update;
 -- Expired, invalidated and completed requests must never be revived.
 if c.id is null or c.status<>'open' or c.expires_at<=clock_timestamp() then return; end if;
 s:=public.shift_exchange_shift(w,c.offered_source_id); t:=public.shift_exchange_shift(w,c.requested_source_id);
 if not public.weekly_exchange_same_responsibility(c.offered_snapshot,s)
  or not public.weekly_exchange_same_responsibility(c.requested_snapshot,t) then return; end if;
 if public.shift_exchange_terms(c.offered_snapshot)=public.shift_exchange_terms(s)
  and public.shift_exchange_terms(c.requested_snapshot)=public.shift_exchange_terms(t) then return; end if;
 fp:=public.shift_exchange_fingerprint(w,s,t);
 if fp=c.consent_fingerprint then return; end if;
 deadline:=coalesce(least((s->>'starts_at')::timestamptz,(t->>'starts_at')::timestamptz),c.expires_at);
 event_action:=case when deadline<=clock_timestamp() then 'expired' else 'terms_changed' end;
 prior_details:=jsonb_build_object('before',jsonb_build_object('offered',c.offered_snapshot,'requested',c.requested_snapshot,
  'consent_fingerprint',c.consent_fingerprint,'revision',c.revision),
  'after',jsonb_build_object('offered',s,'requested',t,'consent_fingerprint',fp,'revision',c.revision+1),
  'acceptance_retained',event_action='terms_changed','cause','published_assignment_changed');
 update public.shift_exchange_cases set offered_snapshot=s,requested_snapshot=t,consent_fingerprint=fp,
  expires_at=deadline,status=case when event_action='expired' then 'expired' else status end,
  revision=revision+1,updated_at=now() where id=cid;
 update public.shift_exchange_applications set consent_fingerprint=fp,
  status=case when event_action='expired' then 'expired' else status end,updated_at=now()
  where case_id=cid and workspace_id=w and status in ('invited','pending_manager');
 -- Employee consent survives; a manager's old scoped review does not.
 delete from public.shift_exchange_votes where workspace_id=w and case_id=cid;
 message:=case when event_action='expired' then
  'The updated shift has already started. This request closed without a transfer. Check your current schedule.'
 else format('Shift details changed: %s, %s, %s-%s (%s).%s Existing acceptances remain valid; pending invitations still need a response. Final manager approval is required.',
  s->>'location_name',s->>'date',s->>'start_time',s->>'end_time',coalesce(s->>'time_timezone',s->>'timezone'),
  case when t is null then '' else format(' Swap shift: %s, %s, %s-%s (%s).',t->>'location_name',t->>'date',t->>'start_time',t->>'end_time',coalesce(t->>'time_timezone',t->>'timezone')) end) end;
 perform public.shift_exchange_emit(null,w,cid,null,event_action,message);
 -- emit is synchronous under the workspace lock; its newest event is ours.
 update public.shift_exchange_events set details=prior_details where id=(select id from public.shift_exchange_events
  where workspace_id=w and case_id=cid and action=event_action order by notification_sequence desc limit 1);
 perform realtime.send(jsonb_build_object('workspace_id',w,'case_id',cid,'revision',c.revision+1),
  'changed','shift-exchanges:'||w::text,true);
end; $$;


ALTER FUNCTION "public"."refresh_weekly_exchange_terms"("w" "uuid", "cid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_weekly_exchange_terms_after_publication"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare w uuid; source_ids uuid[]; item record;
begin
 w:=case when tg_op='DELETE' then old.workspace_id else new.workspace_id end;
 if tg_table_name='schedule_published_shifts' then
  source_ids:=case when tg_op='DELETE' then array[old.source_shift_id]
   when tg_op='INSERT' then array[new.source_shift_id] else array[old.source_shift_id,new.source_shift_id] end;
 else
  select array_agg(source_shift_id) into source_ids from public.schedule_published_shifts
   where workspace_id=w and publication_id=case when tg_op='DELETE' then old.id else new.id end;
 end if;
 for item in select id from public.shift_exchange_cases where workspace_id=w and status='open'
  and (offered_source_id=any(source_ids) or requested_source_id=any(source_ids)) order by id loop
  perform public.refresh_weekly_exchange_terms(w,item.id);
 end loop;
 return null;
end; $$;


ALTER FUNCTION "public"."refresh_weekly_exchange_terms_after_publication"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_employee_access_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  employee public.employee_profiles%rowtype;
  membership public.workspace_memberships%rowtype;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.remove_access', target_person => target_employee_id);

  select * into employee
  from public.employee_profiles
  where id = target_employee_id and workspace_id = target_workspace_id and archived_at is null
  for update;
  if employee.id is null then
    raise exception 'employee not found' using errcode = 'P0002';
  end if;
  if employee.user_id is null then
    return;
  end if;

  select * into membership
  from public.workspace_memberships
  where workspace_id = target_workspace_id and user_id = employee.user_id
  for update;
  if membership.id is null then
    raise exception 'linked workspace membership not found' using errcode = 'P0002';
  end if;

  update public.workspace_memberships
  set status = 'suspended'::public.membership_status, updated_at = now()
  where id = membership.id;

  update public.employee_profiles
  set user_id = null, revision = revision + 1, updated_at = now()
  where id = employee.id;

  update public.employee_invitations
  set status = 'revoked'::public.employee_invitation_status, revoked_at = now(), updated_at = now()
  where employee_id = employee.id and status = 'pending'::public.employee_invitation_status;

  update public.employee_onboarding_cases
  set status = 'cancelled'::public.employee_onboarding_case_status,
      submitted_at = null,
      approved_at = null,
      approved_by = null,
      revision = revision + 1,
      updated_at = now()
  where employee_id = employee.id
    and status <> 'cancelled'::public.employee_onboarding_case_status;

  insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary)
  values (target_workspace_id, target_employee_id, actor_user_id, 'employee.access_removed',
    'Workspace access removed and employee account unlinked');
end;
$$;


ALTER FUNCTION "public"."remove_employee_access_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_employee_avatar_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  avatar_path text;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.save', target_person => target_employee_id);

  select private_profile.avatar_object_path into avatar_path
  from public.employee_private_profiles private_profile
  where private_profile.workspace_id = target_workspace_id
    and private_profile.employee_id = target_employee_id
  for update;

  if avatar_path is null then
    return null;
  end if;

  update public.employee_private_profiles
  set avatar_object_path = null, updated_at = now()
  where workspace_id = target_workspace_id and employee_id = target_employee_id;

  insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary)
  values (target_workspace_id, target_employee_id, actor_user_id, 'employee.avatar_removed', 'Workspace profile photo removed');

  return avatar_path;
end;
$$;


ALTER FUNCTION "public"."remove_employee_avatar_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_employee_document_draft_file_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "target_submission_id" "uuid", "target_file_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'documents.self',target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id and q.workspace_id=target_workspace_id));
 select * into r from public.employee_onboarding_requirements where id=target_requirement_id and workspace_id=target_workspace_id and kind='document' for update;
 if r.id is null or r.lifecycle_user_id is distinct from actor_user_id or not app_private.document_actor_can_read(actor_user_id,r.workspace_id,r.employee_id,r.lifecycle_user_id)
 then raise exception 'document unavailable' using errcode='P0002'; end if;
 perform app_private.assert_document_published(r);
 if r.lifecycle_revision<>expected_revision then raise exception 'document changed; refresh required' using errcode='PT409'; end if;
 if r.lifecycle_closed_at is not null or r.lifecycle_exempt or r.lifecycle_retired_at is not null then raise exception 'document request is closed' using errcode='22023'; end if;
 if not exists(select 1 from public.employee_document_submissions where id=target_submission_id and requirement_id=r.id and user_id=actor_user_id and state='draft') then raise exception 'draft unavailable' using errcode='PT409'; end if;
 delete from public.employee_document_submission_files where submission_id=target_submission_id and file_id=target_file_id and requirement_id=r.id;
 if not found then raise exception 'draft file unavailable' using errcode='P0002'; end if;
 update public.employee_onboarding_requirements set lifecycle_revision=lifecycle_revision+1,updated_at=now() where id=r.id returning lifecycle_revision into expected_revision;
 perform app_private.document_audit(r,actor_user_id,'document.draft_file_removed',jsonb_build_object('submission_id',target_submission_id,'file_id',target_file_id,'revision',expected_revision));
 return expected_revision;
end;
$$;


ALTER FUNCTION "public"."remove_employee_document_draft_file_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer, "target_submission_id" "uuid", "target_file_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_employee_from_location_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "target_location_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  assignment public.employee_location_assignments%rowtype;
  employee public.employee_profiles%rowtype;
  released uuid[];
  locations_left integer;
  told uuid[];
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'employee.remove_from_location',
    array[target_location_id], target_employee_id);

  select * into assignment
  from public.employee_location_assignments candidate
  where candidate.workspace_id = target_workspace_id
    and candidate.employee_id = target_employee_id
    and candidate.location_id = target_location_id
    and candidate.ended_at is null
  for update;
  -- Not working there is answered as a target out of reach: the refusal does
  -- not tell what the record holds.
  if assignment.id is null then
    raise exception 'Not allowed' using errcode = '42501', hint = 'authz.out_of_scope',
      detail = 'employee.remove_from_location';
  end if;

  select * into employee from public.employee_profiles where id = target_employee_id for update;

  update public.employee_location_assignments set ended_at = now(), is_primary = false
  where id = assignment.id;
  -- Another location they still work at becomes the primary one.
  if assignment.is_primary then
    update public.employee_location_assignments set is_primary = true
    where id = (
      select other.id from public.employee_location_assignments other
      where other.employee_id = target_employee_id and other.ended_at is null
      order by other.assigned_at, other.id
      limit 1
    );
  end if;

  -- K4: a manager's last location is not taken; the record of anybody else
  -- stays, with no location if this was the only one.
  perform app_private.keep_manager_at_a_location(target_workspace_id, target_employee_id);

  -- Their published shifts there from now on are left open, as when
  -- employment ends; their shifts elsewhere stay.
  with open_up as (
    update public.schedule_published_shifts shift
    set employee_id = null
    from public.schedule_location_publications publication, public.locations location
    where publication.id = shift.publication_id
      and publication.workspace_id = shift.workspace_id
      and publication.location_id = shift.location_id
      and publication.status = 'current'
      and location.id = shift.location_id
      and location.workspace_id = shift.workspace_id
      and shift.workspace_id = target_workspace_id
      and shift.employee_id = target_employee_id
      and shift.location_id = target_location_id
      and (shift.scheduled_date + shift.start_time) at time zone location.timezone >= now()
    returning shift.id
  )
  select coalesce(array_agg(id), '{}') into released from open_up;

  update public.employee_profiles
  set revision = revision + 1, updated_at = now()
  where id = target_employee_id;

  select count(*) into locations_left
  from public.employee_location_assignments other
  where other.employee_id = target_employee_id and other.ended_at is null;

  insert into public.employee_events (workspace_id, employee_id, actor_user_id, action, summary, occurred_at)
  values (target_workspace_id, target_employee_id, actor_user_id, 'employee.location_removed',
    format('Removed from a location; %s published shift(s) left open', cardinality(released)), now());

  insert into public.audit_events (workspace_id, actor_user_id, action, target_type, target_id, metadata)
  values (target_workspace_id, actor_user_id, 'employee.location_removed', 'employee', target_employee_id::text,
    jsonb_build_object('location_id', target_location_id, 'released_shift_ids', to_jsonb(released),
      'locations_left', locations_left));

  -- No location left: whoever may end their employment or give them another
  -- location decides (the owner and admins; S1). The record stays.
  if locations_left = 0 then
    select coalesce(array_agg(member.user_id order by member.user_id), '{}') into told
    from public.workspace_memberships member
    where member.workspace_id = target_workspace_id
      and member.status = 'active'
      and member.user_id is distinct from actor_user_id
      and app_private.authz_reason(member.user_id, target_workspace_id, 'employee.terminate', null, target_employee_id) is null;
    if cardinality(told) > 0 then
      perform public.enqueue_notification_outbox_service(
        target_workspace_id,
        gen_random_uuid(),
        'people.employee.no_location',
        1,
        actor_user_id,
        'employee',
        target_employee_id::text,
        jsonb_build_object(
          'employee_id', target_employee_id,
          'recipient_user_ids', to_jsonb(told),
          'audience_contract', 'workspace_employee_access_managers',
          'category', 'people',
          'title', 'No location left',
          'body', left(concat_ws(' ', employee.first_name, employee.last_name)
            || ' has no location left. End their employment or give them a new location.', 2000),
          'safe_preview', 'Somebody on your team has no location left.',
          'action_url', '/app/employees?employeeId=' || target_employee_id::text,
          'group_key', 'employee:' || target_employee_id::text
        ),
        now()
      );
    end if;
  end if;

  return jsonb_build_object(
    'employee_id', target_employee_id,
    'location_id', target_location_id,
    'released_shift_count', cardinality(released),
    'locations_left', locations_left
  );
end;
$$;


ALTER FUNCTION "public"."remove_employee_from_location_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_employee_id" "uuid", "target_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_schedule_pending_op_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_op_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_session public.schedule_edit_sessions%rowtype;
  target_shift public.schedule_edit_session_shifts%rowtype;
begin
 perform public.availability_lock_workspace(target_workspace_id);
  select session.* into target_session
    from public.schedule_edit_sessions session
    join public.schedule_edit_session_shifts shift on shift.session_id = session.id
   where session.workspace_id = target_workspace_id
     and shift.id = target_op_id
     and session.status = 'active'
   for update of session;

  select shift.* into target_shift
    from public.schedule_edit_session_shifts shift
   where shift.session_id = target_session.id
     and shift.id = target_op_id
   for update;

  if target_session.id is null or target_session.holder_user_id <> actor_user_id then
    raise exception 'pending op not found' using errcode='P0002';
  end if;
  -- The edit's locations are still the person's to edit (B-3).
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit', target_locations => target_session.location_ids);
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.edit', target_locations => array[target_shift.location_id]);

  if target_shift.pending_op_type = 'create' then
    delete from public.schedule_edit_session_shifts
     where session_id = target_session.id
       and id = target_op_id;
  else
    update public.schedule_edit_session_shifts
       set pending_op_type = null,
           locked = target_shift.source_published_shift_id is not null,
           revision = revision + 1,
           updated_at = now()
     where session_id = target_session.id
       and id = target_op_id;
  end if;

  update public.schedule_edit_sessions
     set revision = revision + 1,
         dirty = true,
         last_heartbeat = now(),
         expires_at = now() + interval '4 minutes'
   where id = target_session.id;

  return jsonb_build_object('status', 'ok', 'op_id', target_op_id);
end;
$$;


ALTER FUNCTION "public"."remove_schedule_pending_op_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_op_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rename_schedule_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid", "target_name" "text", "expected_revision" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare old_name text;
begin
 select name into old_name from public.schedule_templates where id=target_template_id and workspace_id=target_workspace_id;
 perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.templates', target_locations => case
   when old_name is null then null
   else public.live_location_ids(target_workspace_id, array(select distinct s.location_id from public.schedule_template_shifts s
     where s.template_id = target_template_id and s.workspace_id = target_workspace_id))
 end);
 update public.schedule_templates set name=btrim(target_name),revision=revision+1,updated_by=actor_user_id,updated_at=now()
 where id=target_template_id and workspace_id=target_workspace_id and revision=expected_revision;
 if not found then raise exception 'schedule template revision stale' using errcode = 'PT409'; end if;
 insert into public.schedule_template_events(workspace_id,template_id,template_name,action,actor_user_id,detail)
 values(target_workspace_id,target_template_id,btrim(target_name),'renamed',actor_user_id,jsonb_build_object('previous_name',old_name));
 return public.get_schedule_template_service(actor_user_id,target_workspace_id,target_template_id);
exception when unique_violation then raise exception 'schedule template name conflict' using errcode='23505'; end;
$$;


ALTER FUNCTION "public"."rename_schedule_template_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_template_id" "uuid", "target_name" "text", "expected_revision" integer) OWNER TO "postgres";


