CREATE TABLE IF NOT EXISTS "public"."schedule_edit_session_shifts" (
    "id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "session_id" "uuid" NOT NULL,
    "location_id" "uuid" NOT NULL,
    "employee_id" "uuid",
    "job_id" "uuid" NOT NULL,
    "shift_type_id" "uuid",
    "scheduled_date" "date" NOT NULL,
    "start_time" time without time zone,
    "end_time" time without time zone,
    "crosses_midnight" boolean GENERATED ALWAYS AS (("end_time" <= "start_time")) STORED,
    "note" "text" DEFAULT ''::"text" NOT NULL,
    "revision" integer DEFAULT 1 NOT NULL,
    "idempotency_key" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "source_published_shift_id" "uuid",
    "pending_op_type" "text",
    "locked" boolean DEFAULT false NOT NULL,
    "unpaid_break_minutes" integer DEFAULT 0 NOT NULL,
    "hide_time_on_badge" boolean DEFAULT false NOT NULL,
    "label_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "label_names" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "time_basis" "text" NOT NULL,
    "time_snapshot" "jsonb",
    "time_timezone" "text" NOT NULL,
    CONSTRAINT "schedule_edit_session_shifts_check" CHECK (("start_time" <> "end_time")),
    CONSTRAINT "schedule_edit_session_shifts_note_check" CHECK (("char_length"("note") <= 500)),
    CONSTRAINT "schedule_edit_session_shifts_pending_op_type_check" CHECK ((("pending_op_type" IS NULL) OR ("pending_op_type" = ANY (ARRAY['create'::"text", 'update'::"text", 'delete'::"text"])))),
    CONSTRAINT "schedule_edit_session_shifts_revision_check" CHECK (("revision" > 0)),
    CONSTRAINT "schedule_edit_session_shifts_time_basis_check" CHECK (("time_basis" = ANY (ARRAY['explicit'::"text", 'type_default'::"text"]))),
    CONSTRAINT "schedule_edit_session_shifts_time_source_range" CHECK ((("start_time" IS NOT NULL) AND ("end_time" IS NOT NULL) AND ("start_time" <> "end_time"))),
    CONSTRAINT "schedule_edit_session_shifts_unpaid_break_minutes_check" CHECK (("unpaid_break_minutes" = ANY (ARRAY[0, 15, 30, 45, 60])))
);


