CREATE OR REPLACE FUNCTION "public"."update_schedule_export_preset_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_preset_id" "uuid", "target_name" "text", "target_settings" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  p public.schedule_export_presets%rowtype;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.export',
    target_locations => app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.export'));

  update public.schedule_export_presets
     set name = btrim(target_name),
         settings = target_settings,
         updated_by = actor_user_id,
         updated_at = now()
   where id = target_preset_id
     and workspace_id = target_workspace_id
     and created_by = actor_user_id
   returning * into p;

  if not found then
    raise exception 'schedule export preset not found' using errcode='P0002';
  end if;

  return jsonb_build_object(
    'id', p.id,
    'workspace_id', p.workspace_id,
    'name', p.name,
    'settings', p.settings,
    'created_by', p.created_by,
    'updated_at', p.updated_at
  );
exception
  when unique_violation then
    raise exception 'schedule export preset name conflict' using errcode='23505';
end;
$$;


ALTER FUNCTION "public"."update_schedule_export_preset_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_preset_id" "uuid", "target_name" "text", "target_settings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_schedule_export_schedule_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_schedule_id" "uuid", "target_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  existing public.scheduled_schedule_exports%rowtype;
  updated public.scheduled_schedule_exports%rowtype;
  next_location_ids uuid[];
  added_location_ids uuid[];
  next_preset_id uuid;
  preset_name text;
  reset_failure_state boolean := false;
begin
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.export',
    target_locations => app_private.scope_set(actor_user_id, target_workspace_id, 'schedule.export'));

  select * into existing
    from public.scheduled_schedule_exports s
   where s.id = target_schedule_id
     and s.workspace_id = target_workspace_id
   for update;

  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.export',
    target_locations => public.live_location_ids(target_workspace_id, existing.location_ids));

  if existing.id is null then
    raise exception 'scheduled export not found' using errcode='P0002';
  end if;

  -- The locations it will export once saved.
  next_location_ids := case
    when target_payload ? 'location_ids' then
      array(select jsonb_array_elements_text(target_payload->'location_ids')::uuid)
    else existing.location_ids
  end;
  perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.export',
    -- A location already on the rule and no longer live is not asked about;
    -- every location added is, so an archived one cannot be slipped in.
    target_locations => array(
      select distinct requested.id from unnest(next_location_ids) requested(id)
      where requested.id = any (public.live_location_ids(target_workspace_id, next_location_ids))
         or not requested.id = any (coalesce(existing.location_ids, '{}'::uuid[]))));
  -- The rule sends as the person who set it up (the cron exports as them): a
  -- location they cannot export would switch the rule off at its first send.
  -- Whoever edits the rule may not reach past its owner with it.
  added_location_ids := array(
    select distinct requested.id from unnest(next_location_ids) requested(id)
    where not requested.id = any (coalesce(existing.location_ids, '{}'::uuid[])));
  if actor_user_id is distinct from existing.created_by
     and cardinality(added_location_ids) > 0
     and app_private.authz_reason(existing.created_by, target_workspace_id, 'schedule.export',
       target_locations => added_location_ids) is not null then
    raise exception 'The person who set up this export cannot export a location you added.'
      using errcode = '22023', hint = 'schedule.export_rule_beyond_its_owner';
  end if;

  -- The address list and the name: its maker, the owner and admins (KK-224).
  if actor_user_id is distinct from existing.created_by
     and ((target_payload ? 'recipients' and target_payload->'recipients' is distinct from existing.recipients)
       or (target_payload ? 'name' and btrim(target_payload->>'name') is distinct from existing.name)) then
    perform app_private.authorize(actor_user_id, target_workspace_id, 'schedule.export',
      target_locations => '{}'::uuid[]);
  end if;

  next_preset_id := coalesce((target_payload->>'preset_id')::uuid, existing.preset_id);
  if not exists (
    select 1
      from public.schedule_export_presets p
     where p.id = next_preset_id
       and p.workspace_id = target_workspace_id
       and (p.id = existing.preset_id
         or (actor_user_id = existing.created_by and p.created_by = actor_user_id))
  ) then
    raise exception 'schedule export preset not found' using errcode='P0002';
  end if;

  reset_failure_state :=
    target_payload ? 'enabled' and (target_payload->>'enabled')::boolean = true;

  update public.scheduled_schedule_exports
     set preset_id = next_preset_id,
         name = coalesce(btrim(target_payload->>'name'), existing.name),
         recipients = coalesce(target_payload->'recipients', existing.recipients),
         location_ids = next_location_ids,
         day_of_week = coalesce((target_payload->>'day_of_week')::smallint, existing.day_of_week),
         send_hour = coalesce((target_payload->>'send_hour')::smallint, existing.send_hour),
         timezone = coalesce(btrim(target_payload->>'timezone'), existing.timezone),
         enabled = coalesce((target_payload->>'enabled')::boolean, existing.enabled),
         updated_by = actor_user_id,
         updated_at = now(),
         consecutive_failures = case when reset_failure_state then 0 else consecutive_failures end,
         last_error = case when reset_failure_state then null else last_error end,
         auto_disabled_at = case when reset_failure_state then null else auto_disabled_at end
   where id = target_schedule_id
     and workspace_id = target_workspace_id
   returning * into updated;

  select p.name into preset_name
    from public.schedule_export_presets p
   where p.id = updated.preset_id;

  return public.schedule_export_schedule_json(updated, preset_name);
exception
  when unique_violation then
    raise exception 'scheduled export name conflict' using errcode='23505';
end;
$$;


ALTER FUNCTION "public"."update_schedule_export_schedule_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_schedule_id" "uuid", "target_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_schedule_pending_op_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_op_id" "uuid", "target_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_session public.schedule_edit_sessions%rowtype;
  target_shift public.schedule_edit_session_shifts%rowtype;
begin
  select session.* into target_session
    from public.schedule_edit_sessions session
    join public.schedule_edit_session_shifts shift on shift.session_id = session.id
   where session.workspace_id = target_workspace_id
     and shift.id = target_op_id
     and session.status = 'active'
   for update of session;

  select shift.* into target_shift
    from public.schedule_edit_session_shifts shift
   where shift.session_id = target_session.id
     and shift.id = target_op_id
   for update;

  if target_session.id is null or target_session.holder_user_id <> actor_user_id then
    raise exception 'pending op not found' using errcode='P0002';
  end if;
  if target_shift.pending_op_type is null then
    raise exception 'pending op not found' using errcode='P0002';
  end if;

  perform public.add_schedule_pending_op_service(
    actor_user_id,
    target_workspace_id,
    target_session.id,
    target_shift.pending_op_type,
    target_op_id,
    public.schedule_pending_op_payload_json(target_shift) || target_payload
  );
  return jsonb_build_object('status', 'ok', 'op_id', target_op_id);
end;
$$;


ALTER FUNCTION "public"."update_schedule_pending_op_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_op_id" "uuid", "target_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_scheduling_settings_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "settings" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare previous public.workspace_scheduling_settings; proposed public.workspace_scheduling_settings; saved public.workspace_scheduling_settings;
 conflict_keys text[]:=array['conflict_rules','conflict_rules_revision','minimum_travel_minutes','minimum_rest_minutes'];
 touches_conflicts boolean:=jsonb_typeof(settings)='object' and settings ?| conflict_keys;
begin
 perform app_private.authorize(actor_user_id, target_workspace_id,
   case when touches_conflicts then 'settings.conflict_rules.write' else 'settings.scheduling.write' end);
 if touches_conflicts then
  if settings-conflict_keys<>'{}'::jsonb then
   perform app_private.authorize(actor_user_id, target_workspace_id, 'settings.scheduling.write');
  end if;
 end if;
 if jsonb_typeof(settings) is distinct from 'object' then raise exception 'Valid settings required' using errcode='22023'; end if;
 if settings='{}'::jsonb then raise exception 'Settings are required' using errcode='22023'; end if;
 -- BL-186: availability is a preference; there is no rule to set.
 if settings->'conflict_rules' ? 'availability' then
  raise exception 'Availability is a preference and has no conflict rule' using errcode='22023'; end if;
 if settings ? 'time_off_lead_hours' and (jsonb_typeof(settings->'time_off_lead_hours') is distinct from 'number'
  or (settings->>'time_off_lead_hours')::numeric not between 0 and 720 or (settings->>'time_off_lead_hours')::numeric % 1 <> 0) then
  raise exception 'The time-off decision lead time is 0 to 720 whole hours' using errcode='22023'; end if;
 perform public.availability_lock_workspace(target_workspace_id);
 perform pg_advisory_xact_lock(hashtextextended(target_workspace_id::text,921));
 select * into previous from public.workspace_scheduling_settings where workspace_id=target_workspace_id for update;
 if not found then raise exception 'Scheduling settings not found'; end if;
 if settings ?| conflict_keys and (settings->>'conflict_rules_revision')::integer is distinct from previous.conflict_rules_revision then
  raise exception 'Conflict rules changed. Reload the current rules before saving.' using errcode='PT409';
 end if;
 -- Partial calls preserve every omitted field. Revision is stamped by trigger.
 select * into proposed from jsonb_populate_record(previous,settings);
 update public.workspace_scheduling_settings set
  week_start_day=proposed.week_start_day,schedule_deadline_day=proposed.schedule_deadline_day,
  time_format=proposed.time_format,minimum_travel_minutes=proposed.minimum_travel_minutes,
  minimum_rest_minutes=proposed.minimum_rest_minutes,conflict_rules=proposed.conflict_rules,time_off_lead_hours=proposed.time_off_lead_hours,updated_at=now()
 where workspace_id=target_workspace_id returning * into saved;
 if (to_jsonb(previous)-'updated_at') is distinct from (to_jsonb(saved)-'updated_at') then
  insert into public.audit_events(workspace_id,actor_user_id,action,target_type,target_id,metadata)
  values(target_workspace_id,actor_user_id,'scheduling.settings_updated','scheduling_settings',target_workspace_id::text,
   jsonb_build_object('before',to_jsonb(previous),'after',to_jsonb(saved)));
 end if;
 return to_jsonb(saved);
end;
$$;


ALTER FUNCTION "public"."update_scheduling_settings_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "settings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_weekly_preference_command"("actor" "uuid", "w" "uuid", "command" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare model jsonb; prior jsonb; pref jsonb:=command->'preference'; source text:=command->>'source'; copied boolean:=false;
 rule jsonb; type_id uuid; old_rule jsonb; notes jsonb:=command->'notes';
begin
 model:=public.weekly_preferences_read_service(actor,w,(command->>'employee_id')::uuid);
 perform app_private.weekly_preference_may_write(actor,w,source,model);
 if not public.weekly_preference_valid(pref) then raise exception 'Check the weekly unavailable hours' using errcode='22023'; end if;
 perform 1 from public.workspace_scheduling_settings where workspace_id=w for share;
 model:=public.weekly_preferences_read_service(actor,w,(command->>'employee_id')::uuid);
 prior:=model->source;
 if (command->>'expected_revision')::integer is distinct from (prior->>'revision')::integer then raise exception 'Availability changed. Reload before saving; your draft has not been saved.' using errcode='PT409'; end if;
 if (command->>'settings_revision')::integer is distinct from (model->'settings'->>'revision')::integer then raise exception 'Availability settings changed. Reload before saving.' using errcode='PT409'; end if;
 if source='employee' and (command ? 'notes' or command ? 'enabled' or command ? 'copy_employee_revision') then raise exception 'Manager fields cannot be saved with employee preferences' using errcode='42501'; end if;
 if source='manager' then
  if jsonb_typeof(command->'enabled') is distinct from 'boolean' or jsonb_typeof(notes) is distinct from 'array' or jsonb_array_length(notes)<>7
   or exists(select 1 from jsonb_array_elements(notes) n where jsonb_typeof(n)<>'string' or length(n#>>'{}')>1000) then raise exception 'Include reminder state and seven valid notes' using errcode='22023'; end if;
  if command ? 'copy_employee_revision' then
   if not (model->'employee'->>'submitted')::boolean or (command->>'copy_employee_revision')::integer is distinct from (model->'employee'->>'revision')::integer
    or pref is distinct from model->'employee'->'preference' then raise exception 'Employee preferences changed. Copy the latest saved week again.' using errcode='PT409'; end if;
   copied:=true;
  end if;
  if not (prior->>'enabled')::boolean and not (command->>'enabled')::boolean and (pref<>prior->'preference' or notes<>prior->'notes' or copied) then
   raise exception 'Turn reminders on before editing or copying' using errcode='22023'; end if;
 end if;
 if pref->>'input_mode'<>model->'settings'->>'input_mode' then
  raise exception 'Use the current organization entry mode' using errcode='PT409'; end if;
 perform 1 from public.shift_types where workspace_id=w order by id for share;
 for rule in select value from jsonb_array_elements(pref->'days') loop
  select value into old_rule from jsonb_array_elements((case when copied then model->'employee' else prior end)->'preference'->'days') where value->'day'=rule->'day';
  for type_id in select value::uuid from jsonb_array_elements_text(rule->'shift_type_ids') loop
   if not exists(select 1 from public.shift_types t where t.workspace_id=w and t.id=type_id and t.archived_at is null and t.deleted_at is null
    and t.default_start_time is not null and t.default_end_time is not null and t.default_start_time<>t.default_end_time)
    and not (coalesce(old_rule->'shift_type_ids','[]') @> jsonb_build_array(type_id) and exists(select 1 from public.weekly_preference_type_defaults d where d.workspace_id=w and d.shift_type_id=type_id)) then
     raise exception 'A selected shift type is no longer available. Reload before saving.' using errcode='PT409'; end if;
  end loop;
 end loop;
 return model;
end; $$;


ALTER FUNCTION "public"."validate_weekly_preference_command"("actor" "uuid", "w" "uuid", "command" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_account_password_service"("target_user_id" "uuid", "candidate_password" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  window_start timestamptz := now() - interval '15 minutes';
  failures integer;
  oldest timestamptz;
  stored text;
begin
  -- One check at a time per account, so parallel guesses cannot all slip
  -- under the limit.
  perform pg_advisory_xact_lock(hashtextextended('password_failure:' || target_user_id::text, 0));
  delete from app_private.account_throttle_events e where e.at < now() - interval '1 day';

  select count(*), min(e.at) into failures, oldest
  from app_private.account_throttle_events e
  where e.kind = 'password_failure'
    and e.key_digest = target_user_id::text
    and e.at > window_start;
  if failures >= 5 then
    return jsonb_build_object(
      'result', 'locked',
      'retry_after_seconds', greatest(1, ceil(extract(epoch from (oldest + interval '15 minutes' - now()))))::integer
    );
  end if;

  select u.encrypted_password into stored from auth.users u where u.id = target_user_id;
  if coalesce(stored, '') <> ''
    and extensions.crypt(coalesce(candidate_password, ''), stored) = stored then
    delete from app_private.account_throttle_events e
    where e.kind = 'password_failure' and e.key_digest = target_user_id::text;
    return jsonb_build_object('result', 'ok');
  end if;

  insert into app_private.account_throttle_events (kind, key_digest)
  values ('password_failure', target_user_id::text);
  return jsonb_build_object('result', 'incorrect');
end;
$$;


ALTER FUNCTION "public"."verify_account_password_service"("target_user_id" "uuid", "candidate_password" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."version_shift_type_times"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op='INSERT' then new.default_revision:=1;
  elsif (new.default_start_time,new.default_end_time) is distinct from (old.default_start_time,old.default_end_time) then
    new.default_revision:=old.default_revision+1;
  else new.default_revision:=old.default_revision; end if;
  return new;
end; $$;


ALTER FUNCTION "public"."version_shift_type_times"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."version_weekly_preference_settings"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if (new.availability_input_mode,new.availability_onboarding_required)
  is distinct from (old.availability_input_mode,old.availability_onboarding_required) then
  if auth.uid() is not null then raise exception 'Use Availability settings to save these changes' using errcode='42501'; end if;
  new.availability_preferences_revision:=old.availability_preferences_revision+1;
 else new.availability_preferences_revision:=old.availability_preferences_revision; end if;
 return new;
end; $$;


ALTER FUNCTION "public"."version_weekly_preference_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_assignment_candidate_base"("w" "uuid", "emp" "uuid", "target" "jsonb", "excluded" "uuid"[] DEFAULT '{}'::"uuid"[], "travel_minutes" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare loc uuid:=(target->>'location_id')::uuid; job uuid:=(target->>'job_id')::uuid;
  d date:=(target->>'date')::date; tz text; span tstzrange; assessment jsonb;
  available tstzmultirange; overlap tstzmultirange; free tstzmultirange; reasons text[]:=array[]::text[]; state text:='eligible';
  consent jsonb:=target->'_time_off_consent'; leave tstzmultirange; waived boolean:=false; op text;
begin
  travel_minutes:=greatest(coalesce(travel_minutes,0),coalesce((select minimum_travel_minutes
    from public.workspace_scheduling_settings where workspace_id=w),0));
  select coalesce(nullif(target->>'time_timezone',''),nullif(target->'time_snapshot'->>'timezone',''),timezone) into tz from public.locations where id=loc and workspace_id=w and archived_at is null;
  if tz is null then raise exception 'location not found'; end if;
  span:=app_private.shift_time_range(d,(target->>'start_time')::time,(target->>'end_time')::time,tz);
  if not exists(select 1 from public.employee_profiles p where p.id=emp and p.workspace_id=w and p.archived_at is null and not p.is_excluded_from_schedule
    and (p.start_date is null or p.start_date<=d)) then reasons:=array_append(reasons,'Employee is not active in Schedule'); end if;
  if not exists(select 1 from public.employee_location_assignments where employee_id=emp and workspace_id=w and location_id=loc and assigned_at<=lower(span) and (ended_at is null or ended_at>=upper(span))) then reasons:=array_append(reasons,'Not assigned to this location'); end if;
  if not exists(select 1 from public.employee_job_assignments where employee_id=emp and workspace_id=w and job_id=job and assigned_at<=lower(span) and (ended_at is null or ended_at>=upper(span))) then reasons:=array_append(reasons,'Not eligible for this position'); end if;
  if exists(select 1 from public.schedule_closures c where c.workspace_id=w and c.location_id=loc and c.closed_date=d and (c.is_all_day or (target->>'shift_type_id')::uuid=any(c.shift_type_ids))) then reasons:=array_append(reasons,'Location or service is closed'); end if;
  if public.employee_has_hard_document_schedule_conflict_service(w,emp,d) then reasons:=array_append(reasons,'Required document is expired'); end if;


  if exists(select 1 from public.employee_profiles where workspace_id=w and id=emp) then
    -- A candidate target names its day as date; the assessment reads scheduled_date.
    assessment:=public.assess_weekly_shift_availability(w,emp,target||jsonb_build_object('scheduled_date',d,'_exclude_shift_ids',to_jsonb(excluded)));
    -- BL-182: approved time off is the one blocker its own employee may set
    -- aside, and only for hours they agreed to: consent is true while they act
    -- themselves, else the intervals kept with their application. Nobody else
    -- (a cover search, a manager's Schedule) passes consent.
    leave:=public.availability_json_ranges(public.time_off_leave_intervals(assessment));
    waived:=coalesce(assessment->>'operation'='blocked' and not isempty(leave)
      and not exists(select 1 from jsonb_array_elements(assessment->'reasons') r
        where r->>'severity'='block' and r->>'code'<>'approved_time_off')
      and (consent='true'::jsonb or (jsonb_typeof(consent)='array' and public.availability_json_ranges(consent) @> leave)),false);
    op:=case when waived then 'warning_requires_override' else assessment->>'operation' end;
    -- Preferences never shorten the requested assignment. Hard blockers remain
    -- in status/reasons; the private assessment carries the separate warning.
    if op in ('allowed','warning_requires_override') then
      select coalesce(range_agg(tstzrange((r->>'start_at')::timestamptz,(r->>'end_at')::timestamptz,'[)')),'{}'::tstzmultirange)
        into free from jsonb_array_elements(assessment->'intervals') r;
    end if;
    state:=case op
      when 'blocked' then 'ineligible'
      when 'verification_required' then 'verification_required'
      else 'eligible' end;
    reasons:=reasons||array(select r->>'message' from jsonb_array_elements(assessment->'reasons') r
      where r->>'code' not in ('availability','note') and not (waived and r->>'code'='approved_time_off'));
  end if;
  select coalesce(range_agg(r),'{}'::tstzmultirange) into overlap from (
    select app_private.shift_time_range(s.scheduled_date,s.start_time,s.end_time,coalesce(s.time_timezone,l.timezone)) r
    from public.schedule_published_shifts s join public.schedule_location_publications p on p.id=s.publication_id and p.status='current'
    join public.locations l on l.id=s.location_id
    where s.workspace_id=w and s.employee_id=emp and not s.id=any(excluded)
      and s.scheduled_date between d-2 and d+2
  ) busy where r && span;
  if overlap && span then state:='ineligible'; reasons:=array_append(reasons,'Overlaps a published shift or approved time off'); end if;
  if travel_minutes>0 and exists(select 1 from (
    select app_private.shift_time_range(s.scheduled_date,s.start_time,s.end_time,coalesce(s.time_timezone,l.timezone)) r
    from public.schedule_published_shifts s
    join public.schedule_location_publications p on p.id=s.publication_id and p.status='current'
    join public.locations l on l.id=s.location_id
    where s.workspace_id=w and s.employee_id=emp and s.location_id<>loc
      and not s.id=any(excluded) and s.scheduled_date between d-2 and d+2
   ) busy where tstzrange(lower(r)-make_interval(mins=>travel_minutes),upper(r)+make_interval(mins=>travel_minutes),'[)') && span) then
    state:='ineligible';reasons:=array_append(reasons,format('At least %s minutes are required between locations',travel_minutes));
  end if;
  if cardinality(reasons)>0 and state='eligible' then state:='ineligible'; end if;
  if exists(select 1 from unnest(reasons) r where r in('Employee is not active in Schedule','Not assigned to this location','Not eligible for this position','Required document is expired','Location or service is closed')) then state:='ineligible'; end if;

  if cardinality(reasons)=0 then
    reasons:=case when coalesce((assessment->>'has_availability_conflict')::boolean,false)
      then array['Position and location match','No assignment blockers']
      else array['Position and location match','Available for the full interval','No conflicts'] end;
  end if;

  return jsonb_build_object('employee_id',emp,'status',state,'shortens_time_off',waived,'reasons',to_jsonb(reasons),'availability',assessment,
    'available_start',case when free is not null and not isempty(free) then (select lower(r)::text from unnest(free) r order by lower(r) limit 1) end,
    'available_end',case when free is not null and not isempty(free) then (select upper(r)::text from unnest(free) r order by lower(r) limit 1) end);
end; $$;


ALTER FUNCTION "public"."weekly_assignment_candidate_base"("w" "uuid", "emp" "uuid", "target" "jsonb", "excluded" "uuid"[], "travel_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_assignment_candidate_check"("w" "uuid", "emp" "uuid", "target" "jsonb", "excluded" "uuid"[] DEFAULT '{}'::"uuid"[], "travel_minutes" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; starts timestamptz; ends timestamptz; problems jsonb:='[]';
begin
 if nullif(target->>'start_time','') is null or nullif(target->>'end_time','') is null then
  return jsonb_build_object('employee_id',emp,'status','verification_required','reasons',jsonb_build_array('A manager must confirm the shift hours before a full-shift exchange'));
 end if;
 result:=public.weekly_assignment_candidate_base(w,emp,target,excluded,travel_minutes);
 select lower(r),upper(r) into starts,ends from (select app_private.shift_time_range((target->>'date')::date,(target->>'start_time')::time,(target->>'end_time')::time,coalesce(nullif(target->>'time_timezone',''),nullif(target->'time_snapshot'->>'timezone',''),l.timezone)) r from public.locations l where l.id=(target->>'location_id')::uuid and l.workspace_id=w) q;
 if coalesce((target->>'requires_employee_access')::boolean,false) and not exists(select 1 from public.employee_profiles e join public.workspace_memberships m on m.workspace_id=e.workspace_id and m.user_id=e.user_id and m.status='active' where e.workspace_id=w and e.id=emp) then problems:=problems||'"Active workspace access is required"'::jsonb; end if;
 if not exists(select 1 from public.employee_location_assignments a where a.workspace_id=w and a.employee_id=emp and a.location_id=(target->>'location_id')::uuid and a.assigned_at<=starts and (a.ended_at is null or a.ended_at>=ends)) then problems:=problems||'"Location assignment must cover the full shift"'::jsonb; end if;
 if not exists(select 1 from public.employee_job_assignments a where a.workspace_id=w and a.employee_id=emp and a.job_id=(target->>'job_id')::uuid and a.assigned_at<=starts and (a.ended_at is null or a.ended_at>=ends)) then problems:=problems||'"Position assignment must cover the full shift"'::jsonb; end if;
 if jsonb_array_length(problems)>0 then result:=result||jsonb_build_object('status','ineligible','reasons',case when result->>'status'='eligible' then problems else result->'reasons'||problems end); end if;
 return result;
end; $$;


ALTER FUNCTION "public"."weekly_assignment_candidate_check"("w" "uuid", "emp" "uuid", "target" "jsonb", "excluded" "uuid"[], "travel_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_exchange_candidate_check"("w" "uuid", "emp" "uuid", "target" "jsonb", "excluded" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select jsonb_build_object('status',r->>'status','reasons',case when r->>'status'='eligible'
  then '["Position and location match","No assignment blockers"]'::jsonb else r->'reasons' end,
  'shortens_time_off',coalesce((r->>'shortens_time_off')::boolean,false))
 from (select public.weekly_assignment_candidate_check(w,emp,target,excluded) r) q;
$$;


ALTER FUNCTION "public"."weekly_exchange_candidate_check"("w" "uuid", "emp" "uuid", "target" "jsonb", "excluded" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_exchange_employee_warning"("w" "uuid", "emp" "uuid", "target" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a jsonb; leave jsonb;
begin
 a:=public.assess_weekly_shift_availability(w,emp,target||jsonb_build_object('scheduled_date',target->>'date'));
 leave:=public.time_off_leave_intervals(a);
 -- Their own approved time off is asked about only when it is the one thing
 -- in the way (BL-182); anything else that blocks is not theirs to set aside.
 if a->>'operation'='verification_required' or (a->>'operation'='blocked' and (jsonb_array_length(leave)=0
  or exists(select 1 from jsonb_array_elements(a->'reasons') r where r->>'severity'='block' and r->>'code'<>'approved_time_off'))) then
  return null; end if;
 if jsonb_array_length(a->'employee_intervals')=0 and jsonb_array_length(leave)=0 then return null; end if;
 return jsonb_build_object('fingerprint',encode(extensions.digest(convert_to(jsonb_build_object(
  'workspace',w,'employee',emp,'source',target->>'source_id','location',target->>'location_id',
  'intervals',a->'intervals','conflicts',a->'employee_intervals','time_off',leave)::text,'UTF8'),'sha256'),'hex'),
  'time_off_intervals',leave);
end; $$;


ALTER FUNCTION "public"."weekly_exchange_employee_warning"("w" "uuid", "emp" "uuid", "target" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_exchange_same_responsibility"("before_shift" "jsonb", "current_shift" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
 select case when before_shift is null and current_shift is null then true
  when before_shift is null or current_shift is null or nullif(before_shift->>'source_id','') is null then false
  else (public.shift_exchange_terms(before_shift)-array['date','start','end','location','time_basis','time_snapshot','time_timezone'])
   = (public.shift_exchange_terms(current_shift)-array['date','start','end','location','time_basis','time_snapshot','time_timezone']) end;
$$;


ALTER FUNCTION "public"."weekly_exchange_same_responsibility"("before_shift" "jsonb", "current_shift" "jsonb") OWNER TO "postgres";


