    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
 select coalesce(public.weekly_exchange_employee_warning(w,emp,target)->'time_off_intervals','[]'::jsonb);
$$;


ALTER FUNCTION "public"."weekly_exchange_time_off_consent"("w" "uuid", "emp" "uuid", "target" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_preference_capacity"("w" "uuid", "emp" "uuid", "target_span" "tstzrange", "zone_name" "text", "proposed" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare employee_week jsonb; manager_week jsonb; employee_ranges tstzmultirange:='{}'; manager_ranges tstzmultirange:='{}';
begin
 if not exists(select 1 from public.employee_profiles where workspace_id=w and id=emp) then raise exception 'Employee not found' using errcode='42501'; end if;
 if target_span is null or isempty(target_span) then raise exception 'A valid assignment span is required' using errcode='22023'; end if;
 select preference into employee_week from public.employee_weekly_preferences where workspace_id=w and employee_id=emp;
 employee_week:=coalesce(proposed,employee_week,public.empty_weekly_preference('time_range'));
 employee_ranges:=public.weekly_preference_intersections(w,employee_week,target_span,zone_name);
 select preference into manager_week from public.manager_weekly_reminders where workspace_id=w and employee_id=emp and enabled;
 if manager_week is not null then manager_ranges:=public.weekly_preference_intersections(w,manager_week,target_span,zone_name); end if;
 return jsonb_build_object('employee_intervals',public.availability_ranges_json(employee_ranges),
  'manager_intervals',public.availability_ranges_json(manager_ranges));
end; $$;


ALTER FUNCTION "public"."weekly_preference_capacity"("w" "uuid", "emp" "uuid", "target_span" "tstzrange", "zone_name" "text", "proposed" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_preference_convert"("w" "uuid", "preference" "jsonb", "target_mode" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare days jsonb:='[]'; d integer; week int4multirange; day_set int4multirange; whole int4multirange;
 source_rule jsonb; marked jsonb; ranges jsonb; unresolved integer;
begin
 if preference->>'input_mode'=target_mode then return preference; end if;
 -- A picked type means the hours weekly_preference_intersections reads for it:
 -- the live type while it is active, its last saved hours once archived.
 select count(*) into unresolved
 from jsonb_array_elements(preference->'days') r
 cross join lateral jsonb_array_elements_text(r->'shift_type_ids') picked(id)
 left join public.shift_types t on t.workspace_id=w and t.id=picked.id::uuid and t.archived_at is null and t.deleted_at is null
 left join public.weekly_preference_type_defaults dft on dft.workspace_id=w and dft.shift_type_id=picked.id::uuid
 where coalesce(case when t.id is not null then t.default_start_time else dft.start_time end,'00:00')
  =coalesce(case when t.id is not null then t.default_end_time else dft.end_time end,'00:00');
 if unresolved>0 then raise exception 'A saved week names a shift type with no valid default hours' using errcode='22023'; end if;
 -- The week's unavailable minutes, Sunday 00:00 = 0, wrapping past Saturday.
 with clock as (
  select (r->>'day')::integer as day, 0 as s, 1440 as e
  from jsonb_array_elements(preference->'days') r where (r->>'all_day')::boolean
  union all
  select (r->>'day')::integer, split_part(x->>'start',':',1)::integer*60+split_part(x->>'start',':',2)::integer,
   split_part(x->>'end',':',1)::integer*60+split_part(x->>'end',':',2)::integer
  from jsonb_array_elements(preference->'days') r cross join lateral jsonb_array_elements(r->'ranges') x
  where not (r->>'all_day')::boolean
  union all
  select (r->>'day')::integer, h.s, case when h.e<=h.s then h.e+1440 else h.e end
  from jsonb_array_elements(preference->'days') r
  cross join lateral jsonb_array_elements_text(r->'shift_type_ids') picked(id)
  left join public.shift_types t on t.workspace_id=w and t.id=picked.id::uuid and t.archived_at is null and t.deleted_at is null
  left join public.weekly_preference_type_defaults dft on dft.workspace_id=w and dft.shift_type_id=picked.id::uuid
  cross join lateral (select
   (extract(hour from case when t.id is not null then t.default_start_time else dft.start_time end)*60
    +extract(minute from case when t.id is not null then t.default_start_time else dft.start_time end))::integer s,
   (extract(hour from case when t.id is not null then t.default_end_time else dft.end_time end)*60
    +extract(minute from case when t.id is not null then t.default_end_time else dft.end_time end))::integer e) h
  where not (r->>'all_day')::boolean
 ), piece as (
  select int4range(c.day*1440+c.s, least(c.day*1440+c.e,10080)) span from clock c
  union all
  select int4range(0, c.day*1440+c.e-10080) from clock c where c.day*1440+c.e>10080
 )
 select coalesce(range_agg(span),'{}') into week from piece where not isempty(span);
 for d in 0..6 loop
  whole:=int4multirange(int4range(d*1440,(d+1)*1440));
  select value into source_rule from jsonb_array_elements(preference->'days') where (value->>'day')::integer=d;
  if target_mode='time_range' then
   day_set:=week*whole;
   if day_set=whole then
    days:=days||jsonb_build_array(jsonb_build_object('day',d,'all_day',true,'shift_type_ids','[]'::jsonb,'ranges','[]'::jsonb));
   else
    select coalesce(jsonb_agg(jsonb_build_object(
      'start',lpad(((lower(x)-d*1440)/60)::text,2,'0')||':'||lpad(((lower(x)-d*1440)%60)::text,2,'0'),
      'end',lpad(((upper(x)-d*1440)/60)::text,2,'0')||':'||lpad(((upper(x)-d*1440)%60)::text,2,'0')) order by lower(x)),'[]')
     into ranges from unnest(day_set) x;
    days:=days||jsonb_build_array(jsonb_build_object('day',d,'all_day',false,'shift_type_ids','[]'::jsonb,'ranges',ranges));
   end if;
  elsif coalesce((source_rule->>'all_day')::boolean,false) then
   days:=days||jsonb_build_array(jsonb_build_object('day',d,'all_day',true,'shift_type_ids','[]'::jsonb,'ranges','[]'::jsonb));
  else
   -- ponytail: a range reaching more than 64 active types fails the week's check; cap it when a workspace has that many.
   select coalesce(jsonb_agg(t.id order by t.sort_order,t.name,t.id),'[]') into marked from public.shift_types t
   cross join lateral (select (extract(hour from t.default_start_time)*60+extract(minute from t.default_start_time))::integer s,
    (extract(hour from t.default_end_time)*60+extract(minute from t.default_end_time))::integer e) h
   cross join lateral (select d*1440+h.s lo, d*1440+case when h.e<=h.s then h.e+1440 else h.e end hi) span
   where t.workspace_id=w and t.archived_at is null and t.deleted_at is null
    and t.default_start_time is not null and t.default_end_time is not null and t.default_start_time<>t.default_end_time
    and week && (int4multirange(int4range(span.lo,least(span.hi,10080)))
     +case when span.hi>10080 then int4multirange(int4range(0,span.hi-10080)) else '{}'::int4multirange end);
   days:=days||jsonb_build_array(jsonb_build_object('day',d,'all_day',false,'shift_type_ids',marked,'ranges','[]'::jsonb));
  end if;
 end loop;
 return app_private.weekly_preference_whole_days(w,jsonb_build_object('input_mode',target_mode,'days',days));
end; $$;


ALTER FUNCTION "public"."weekly_preference_convert"("w" "uuid", "preference" "jsonb", "target_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_preference_intersections"("w" "uuid", "preference" "jsonb", "target_span" "tstzrange", "zone_name" "text") RETURNS "tstzmultirange"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result tstzmultirange:='{}'; piece record; local_day date; last_day date; rule jsonb; type_id uuid;
 clocks jsonb; clock jsonb; start_clock time; end_clock time; candidate tstzrange; local_start timestamp; local_end timestamp;
begin
 if not public.weekly_preference_valid(preference) then raise exception 'Invalid weekly preferences' using errcode='22023'; end if;
 if zone_name is null or not app_private.timezone_name_valid(zone_name) then raise exception 'Valid location timezone required' using errcode='22023'; end if;
 if target_span is null or isempty(target_span) then return result; end if;
 for piece in select * from public.availability_offset_segments(target_span,zone_name) loop
  local_day:=((lower(piece.utc_span) at time zone 'UTC')+make_interval(secs=>piece.offset_seconds))::date-1;
  last_day:=((upper(piece.utc_span) at time zone 'UTC')+make_interval(secs=>piece.offset_seconds))::date;
  while local_day<=last_day loop
   select value into rule from jsonb_array_elements(preference->'days') where (value->>'day')::integer=extract(dow from local_day)::integer;
   clocks:='[]';
   if (rule->>'all_day')::boolean then clocks:='[{"start":"00:00","end":"24:00"}]';
   elsif preference->>'input_mode'='time_range' then clocks:=rule->'ranges';
   elsif preference->>'input_mode'='shift_type' then
    for type_id in select value::uuid from jsonb_array_elements_text(rule->'shift_type_ids') loop
     select case when t.id is not null and t.archived_at is null and t.deleted_at is null then t.default_start_time else d.start_time end,
      case when t.id is not null and t.archived_at is null and t.deleted_at is null then t.default_end_time else d.end_time end
      into start_clock,end_clock
     from (select type_id id) selected left join public.shift_types t on t.workspace_id=w and t.id=selected.id
      left join public.weekly_preference_type_defaults d on d.workspace_id=w and d.shift_type_id=selected.id;
     if start_clock is null or end_clock is null or start_clock=end_clock then raise exception 'Selected shift type has no valid default hours' using errcode='22023'; end if;
     clocks:=clocks||jsonb_build_array(jsonb_build_object('start',start_clock,'end',end_clock));
    end loop;
   end if;
   for clock in select value from jsonb_array_elements(clocks) loop
    start_clock:=(clock->>'start')::time; end_clock:=(clock->>'end')::time;
    local_start:=local_day+start_clock;
    local_end:=local_day+end_clock+case when end_clock<start_clock then interval '1 day' else interval '0' end;
    candidate:=tstzrange((local_start at time zone 'UTC')-make_interval(secs=>piece.offset_seconds),
     (local_end at time zone 'UTC')-make_interval(secs=>piece.offset_seconds),'[)');
    if candidate && piece.utc_span then result:=result+tstzmultirange(candidate*piece.utc_span); end if;
   end loop;
   local_day:=local_day+1;
  end loop;
 end loop;
 return result;
end; $$;


ALTER FUNCTION "public"."weekly_preference_intersections"("w" "uuid", "preference" "jsonb", "target_span" "tstzrange", "zone_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_preference_manager_scope"("actor" "uuid", "w" "uuid", "emp" "uuid", "capability" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
 select case when capability in ('availability.read','availability.note','availability.manage') then
  app_private.authz_reason(actor,w,case capability
   when 'availability.read' then 'availability.team_read'
   when 'availability.note' then 'availability.note_read'
   else 'availability.team_write' end,target_person=>emp) is null
  -- Any other capability is nobody's: no, never an error the caller could skip.
  else false end;
$$;


ALTER FUNCTION "public"."weekly_preference_manager_scope"("actor" "uuid", "w" "uuid", "emp" "uuid", "capability" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_preference_settings_read_service"("actor" "uuid", "w" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare settings public.workspace_scheduling_settings%rowtype; can_edit boolean; missing jsonb;
begin
 perform app_private.authorize(actor,w,'settings.availability.read');
 can_edit:=app_private.authz_reason(actor,w,'settings.availability.write') is null;
 select * into settings from public.workspace_scheduling_settings where workspace_id=w;
 if not found then raise exception 'Availability settings not found' using errcode='P0002'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name) order by sort_order,name,id),'[]') into missing
  from public.shift_types where workspace_id=w and archived_at is null and deleted_at is null
   and (default_start_time is null or default_end_time is null or default_start_time=default_end_time or default_start_time='24:00'::time);
 return jsonb_build_object('settings',jsonb_build_object('input_mode',settings.availability_input_mode,
  'onboarding_required',settings.availability_onboarding_required,'revision',settings.availability_preferences_revision),
  'can_edit',can_edit,'missing_shift_types',missing);
end; $$;


ALTER FUNCTION "public"."weekly_preference_settings_read_service"("actor" "uuid", "w" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_preference_settings_save_service"("actor" "uuid", "w" "uuid", "command" "jsonb", "request_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare model jsonb; prior jsonb; stored public.weekly_preference_commands%rowtype;
 envelope jsonb:=jsonb_build_object('kind','settings','value',command); event uuid:=gen_random_uuid(); recipients uuid[];
begin
 perform public.availability_lock_workspace(w);
 perform app_private.authorize(actor,w,'settings.availability.write');
 model:=public.weekly_preference_settings_read_service(actor,w);
 if request_key is null then raise exception 'A save key is required' using errcode='22023'; end if;
 select * into stored from public.weekly_preference_commands q where q.workspace_id=w and q.actor_user_id=actor and q.request_key=weekly_preference_settings_save_service.request_key;
 if found then
  if stored.command<>envelope then raise exception 'Idempotency key was used for another save' using errcode='22023'; end if;
  return model;
 end if;
 if jsonb_typeof(command) is distinct from 'object' or command->>'input_mode' is null or command->>'input_mode' not in ('time_range','shift_type')
  or jsonb_typeof(command->'onboarding_required') is distinct from 'boolean'
  or jsonb_typeof(command->'expected_revision') is distinct from 'number' or (command->>'expected_revision') !~ '^[0-9]+$' then
  raise exception 'Choose valid availability settings' using errcode='22023'; end if;
 perform 1 from public.workspace_scheduling_settings where workspace_id=w for update;
 model:=public.weekly_preference_settings_read_service(actor,w); prior:=model->'settings';
 if (command->>'expected_revision')::integer is distinct from (prior->>'revision')::integer then
  raise exception 'Availability settings changed. Reload the latest settings before saving.' using errcode = 'PT409'; end if;
 if command->>'input_mode'='shift_type' and jsonb_array_length(model->'missing_shift_types')>0 then
  raise exception 'Complete default hours for all active shift types before using shift type availability' using errcode='22023',detail=(model->'missing_shift_types')::text; end if;
 if (command-'expected_revision') is distinct from (prior-'revision') then
  update public.workspace_scheduling_settings set availability_input_mode=command->>'input_mode',
   availability_onboarding_required=(command->>'onboarding_required')::boolean,updated_at=now() where workspace_id=w;
  model:=public.weekly_preference_settings_read_service(actor,w);
  insert into public.audit_events(workspace_id,actor_user_id,action,target_type,target_id,metadata)
   values(w,actor,'availability.settings_updated','scheduling_settings',w::text,jsonb_build_object('before',prior,'after',model->'settings'));
  if prior->>'input_mode' is distinct from command->>'input_mode' then
   -- Every employee is told, active or still onboarding, whether or not they
   -- had saved a week (M4, D4); a manager whose note was converted is not.
   select coalesce(array_agg(distinct e.user_id),'{}') into recipients from public.employee_profiles e
    join public.workspace_memberships m on m.workspace_id=e.workspace_id and m.user_id=e.user_id and m.status in ('active','pending_activation')
    where e.workspace_id=w and e.archived_at is null and app_private.ranks_as_employee(w,e.user_id);
   with history as (
    insert into public.weekly_preference_events(workspace_id,employee_id,source,actor_user_id,before_record,after_record)
    select w,p.employee_id,'employee',actor,jsonb_build_object('revision',p.revision,'preference',p.preference),
     jsonb_build_object('revision',p.revision+1,'preference',public.weekly_preference_convert(w,p.preference,command->>'input_mode'))
    from public.employee_weekly_preferences p where p.workspace_id=w and p.preference->>'input_mode'<>command->>'input_mode'
    returning employee_id,after_record)
   update public.employee_weekly_preferences p set preference=h.after_record->'preference',revision=p.revision+1,updated_by=actor,updated_at=now()
    from history h where p.workspace_id=w and p.employee_id=h.employee_id;
   with history as (
    insert into public.weekly_preference_events(workspace_id,employee_id,source,actor_user_id,before_record,after_record)
    select w,p.employee_id,'manager',actor,jsonb_build_object('revision',p.revision,'preference',p.preference),
     jsonb_build_object('revision',p.revision+1,'preference',public.weekly_preference_convert(w,p.preference,command->>'input_mode'))
    from public.manager_weekly_reminders p where p.workspace_id=w and p.preference->>'input_mode'<>command->>'input_mode'
    returning employee_id,after_record)
   update public.manager_weekly_reminders p set preference=h.after_record->'preference',revision=p.revision+1,updated_by=actor,updated_at=now()
    from history h where p.workspace_id=w and p.employee_id=h.employee_id;
   perform public.enqueue_notification_outbox_service(w,event,'availability.status_changed',1,actor,'availability_settings',w::text,
    jsonb_build_object('recipient_user_ids',to_jsonb(recipients),'audience_contract','availability_scoped_recipients','category','request',
     'title','Check your availability','body','Your organization changed how availability is entered. Your saved week was converted; check that it is still right.',
     'safe_preview','Availability entry settings changed.','action_url','/app/employee-hub/my-availability',
     'input_mode',command->>'input_mode','group_key','availability-settings:'||w::text),now());
  end if;
 end if;
 insert into public.weekly_preference_commands(workspace_id,actor_user_id,request_key,command,result) values(w,actor,request_key,envelope,'{}');
 return model;
end; $_$;


ALTER FUNCTION "public"."weekly_preference_settings_save_service"("actor" "uuid", "w" "uuid", "command" "jsonb", "request_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_preference_valid"("preference" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare rule jsonb; mode text; seen integer[]:='{}'; weekday integer; ids uuid[]; piece jsonb; previous_end text;
begin
 if jsonb_typeof(preference) is distinct from 'object' then return false; end if;
 mode:=preference->>'input_mode';
 if mode is null or mode not in ('shift_type','time_range') or jsonb_typeof(preference->'days') is distinct from 'array'
  or jsonb_array_length(preference->'days')<>7 then return false; end if;
 for rule in select value from jsonb_array_elements(preference->'days') loop
  if jsonb_typeof(rule) is distinct from 'object' or jsonb_typeof(rule->'day') is distinct from 'number'
   or (rule->>'day') !~ '^[0-6]$' or jsonb_typeof(rule->'all_day') is distinct from 'boolean'
   or jsonb_typeof(rule->'shift_type_ids') is distinct from 'array' or jsonb_typeof(rule->'ranges') is distinct from 'array'
   or rule ? 'range' or jsonb_array_length(rule->'ranges')>12 then return false; end if;
  weekday:=(rule->>'day')::integer;
  if weekday=any(seen) then return false; end if;
  seen:=array_append(seen,weekday);
  if jsonb_array_length(rule->'shift_type_ids')>64 or exists(select 1 from jsonb_array_elements(rule->'shift_type_ids') x where jsonb_typeof(x)<>'string') then return false; end if;
  select coalesce(array_agg(value::uuid),'{}') into ids from jsonb_array_elements_text(rule->'shift_type_ids');
  if cardinality(ids)<>(select count(distinct id) from unnest(ids) id) then return false; end if;
  if (rule->>'all_day')::boolean and (cardinality(ids)>0 or jsonb_array_length(rule->'ranges')>0) then return false; end if;
  if mode='time_range' and cardinality(ids)>0 then return false; end if;
  if mode='shift_type' and jsonb_array_length(rule->'ranges')>0 then return false; end if;
  -- Several hours a day (M4, S2 a), each within the day, in order and apart.
  previous_end:=null;
  for piece in select value from jsonb_array_elements(rule->'ranges') loop
   if jsonb_typeof(piece) is distinct from 'object'
    or jsonb_typeof(piece->'start') is distinct from 'string' or jsonb_typeof(piece->'end') is distinct from 'string'
    or (piece->>'start') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    or (piece->>'end') !~ '^(([01][0-9]|2[0-3]):[0-5][0-9]|24:00)$'
    or (piece->>'end')<=(piece->>'start') or (piece->>'start')<=previous_end then return false; end if;
   previous_end:=piece->>'end';
  end loop;
 end loop;
 return true;
exception when invalid_text_representation or invalid_parameter_value then return false;
end; $_$;


ALTER FUNCTION "public"."weekly_preference_valid"("preference" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_preferences_read_service"("actor" "uuid", "w" "uuid", "emp" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare employee public.employee_profiles%rowtype; settings public.workspace_scheduling_settings%rowtype;
 own_record boolean; can_manage boolean; can_read boolean; can_view_manager boolean; employee_record jsonb; manager_record jsonb; types jsonb; selected_ids uuid[];
begin
 select * into employee from public.employee_profiles e where e.workspace_id=w and (e.id=emp or (emp is null and e.user_id=actor)) and e.archived_at is null;
 if employee.id is null then
  -- Nobody there: the same no as somebody out of reach (a non-member hears that first).
  perform app_private.authorize(actor,w,'availability.own',target_person=>emp);
  raise exception 'Not allowed' using errcode='42501',hint='authz.out_of_scope',detail='availability.own';
 end if;
 -- One's own week is an employee's own action (M13), asked of the core.
 own_record:=app_private.authz_reason(actor,w,'availability.own',target_person=>employee.id) is null;
 can_manage:=public.weekly_preference_manager_scope(actor,w,employee.id,'availability.manage');
 can_read:=public.weekly_preference_manager_scope(actor,w,employee.id,'availability.read');
 -- The Manager note exists for employees only (availability.note_read).
 can_view_manager:=can_manage or public.weekly_preference_manager_scope(actor,w,employee.id,'availability.note');
 if not own_record and not can_read and not can_view_manager then
  -- The core says why: their own week, or somebody else's.
  perform app_private.authorize(actor,w,case when employee.user_id=actor then 'availability.own' else 'availability.team_read' end,target_person=>employee.id);
  raise exception 'Not allowed' using errcode='42501',hint='authz.out_of_scope',detail='availability.team_read';
 end if;
 select * into settings from public.workspace_scheduling_settings where workspace_id=w;
 if settings.workspace_id is null then raise exception 'Scheduling settings unavailable' using errcode='P0002'; end if;
 select jsonb_build_object('revision',p.revision,'submitted',true,'updated_at',p.updated_at,'preference',p.preference) into employee_record
  from public.employee_weekly_preferences p where p.workspace_id=w and p.employee_id=employee.id;
 employee_record:=coalesce(employee_record,jsonb_build_object('revision',0,'submitted',false,'updated_at',null,'preference',public.empty_weekly_preference(settings.availability_input_mode)));
 if can_view_manager then
  select jsonb_build_object('revision',p.revision,'submitted',true,'updated_at',p.updated_at,'preference',p.preference,'enabled',p.enabled,'notes',to_jsonb(p.notes)) into manager_record
   from public.manager_weekly_reminders p where p.workspace_id=w and p.employee_id=employee.id;
  manager_record:=coalesce(manager_record,jsonb_build_object('revision',0,'submitted',false,'updated_at',null,'preference',public.empty_weekly_preference(settings.availability_input_mode),'enabled',true,'notes',jsonb_build_array('','','','','','','')));
 end if;
 -- Include fallback names only for records this actor can read. Reminder-only
 -- selections must not be inferred from the employee's catalog response.
 select coalesce(array_agg(distinct id::uuid),'{}') into selected_ids
 from jsonb_array_elements((employee_record->'preference'->'days')||coalesce(manager_record->'preference'->'days','[]')) day
 cross join lateral jsonb_array_elements_text(day->'shift_type_ids') id;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'start_time',to_char(start_time,'HH24:MI'),'end_time',to_char(end_time,'HH24:MI'),
  'archived',archived,'selectable',selectable) order by sort_order,name,id),'[]') into types from (
  select t.id,t.name,t.default_start_time start_time,t.default_end_time end_time,false archived,
   (t.default_start_time is not null and t.default_end_time is not null and t.default_start_time<>t.default_end_time) selectable,t.sort_order
  from public.shift_types t where t.workspace_id=w and t.archived_at is null and t.deleted_at is null
  union all
  select d.shift_type_id,d.name,d.start_time,d.end_time,true,false,2147483647 from public.weekly_preference_type_defaults d
  where d.workspace_id=w and d.shift_type_id=any(selected_ids) and not exists(select 1 from public.shift_types t where t.workspace_id=w and t.id=d.shift_type_id and t.archived_at is null and t.deleted_at is null)
 ) catalog;
 return jsonb_build_object('employee_id',employee.id,'employee_name',concat_ws(' ',coalesce(nullif(employee.preferred_name,''),employee.first_name),employee.last_name),
  'can_edit_employee',own_record,'can_manage',can_manage,
  'settings',jsonb_build_object('input_mode',settings.availability_input_mode,
   'onboarding_required',settings.availability_onboarding_required,'revision',settings.availability_preferences_revision),
  'employee',employee_record,'shift_types',types,'time_format',settings.time_format)
  -- The manager part: the note when it is this reader's to see; null for an
  -- employee's note they may not see; left out when there is no note at all
  -- (the person is not an employee).
  || case when can_view_manager then jsonb_build_object('manager',manager_record)
     when app_private.ranks_as_employee(w,employee.user_id) then jsonb_build_object('manager',null)
     else '{}'::jsonb end;
end; $$;


ALTER FUNCTION "public"."weekly_preferences_read_service"("actor" "uuid", "w" "uuid", "emp" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_preferences_save_service"("actor" "uuid", "w" "uuid", "command" "jsonb", "request_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare emp uuid:=(command->>'employee_id')::uuid; source text:=command->>'source'; model jsonb; prior jsonb; preference jsonb;
 old_command public.weekly_preference_commands%rowtype; event uuid:=gen_random_uuid(); result jsonb:='{}';
 recipients uuid[]; summary text; changed_days text;
begin
 if request_key is null then raise exception 'Idempotency key required' using errcode='22023'; end if;
 perform public.availability_lock_workspace(w);
 -- Authorize again before idempotent replay; never return a stored private read model.
 model:=public.weekly_preferences_read_service(actor,w,emp);
 perform app_private.weekly_preference_may_write(actor,w,source,model);
 select * into old_command from public.weekly_preference_commands q where q.workspace_id=w and q.actor_user_id=actor and q.request_key=weekly_preferences_save_service.request_key;
 if old_command.request_key is not null then
  if old_command.command<>command then raise exception 'Idempotency key was used for another save' using errcode='22023'; end if;
  return old_command.result||jsonb_build_object('model',model);
 end if;
 model:=public.validate_weekly_preference_command(actor,w,command); prior:=model->source;
 emp:=(model->>'employee_id')::uuid;
 -- A pending swap, cover or pickup is never asked about and never changed:
 -- the employee withdraws one in Shift Hub if they want to (M5).
 preference:=app_private.weekly_preference_whole_days(w,command->'preference');
 insert into public.weekly_preference_events(id,workspace_id,employee_id,source,actor_user_id,before_record,after_record)
  values(event,w,emp,source,actor,prior,'{}');
 if source='employee' then
  insert into public.employee_weekly_preferences(workspace_id,employee_id,preference,revision,updated_by)
   values(w,emp,preference,1,actor) on conflict(workspace_id,employee_id) do update set preference=excluded.preference,revision=employee_weekly_preferences.revision+1,updated_by=actor,updated_at=now();
  update public.employee_onboarding_requirements set status='completed',completed_at=now(),rejection_reason=null,updated_at=now() where workspace_id=w and employee_id=emp and kind='availability';
  update public.employee_onboarding_cases set revision=revision+1,updated_at=now() where workspace_id=w and employee_id=emp;
 else
  insert into public.manager_weekly_reminders(workspace_id,employee_id,preference,enabled,notes,revision,updated_by)
   values(w,emp,preference,(command->>'enabled')::boolean,array(select jsonb_array_elements_text(command->'notes')),1,actor)
   on conflict(workspace_id,employee_id) do update set preference=excluded.preference,enabled=excluded.enabled,notes=excluded.notes,revision=manager_weekly_reminders.revision+1,updated_by=actor,updated_at=now();
 end if;
 model:=public.weekly_preferences_read_service(actor,w,emp);
 update public.weekly_preference_events set after_record=model->(command->>'source') where id=event;
 select string_agg((array['Sun','Mon','Tue','Wed','Thu','Fri','Sat'])[(d->>'day')::integer+1],', ' order by (d->>'day')::integer) into changed_days
 from jsonb_array_elements(preference->'days') d
 where d is distinct from (select value from jsonb_array_elements(prior->'preference'->'days') where value->'day'=d->'day');
 summary:=case when source='manager' then 'Manager reminders updated.' else 'Weekly availability updated. '||case when changed_days is null then 'Week confirmed.' else 'Changed days: '||changed_days||'.' end end;
 insert into public.employee_events(workspace_id,employee_id,actor_user_id,action,summary) values(w,emp,actor,case when source='manager' then 'manager_reminders_updated' else 'weekly_availability_updated' end,summary);
 if source='employee' then
  select coalesce(array_agg(m.user_id),'{}') into recipients from public.workspace_memberships m where m.workspace_id=w and m.status='active' and m.user_id<>actor
   and public.weekly_preference_manager_scope(m.user_id,w,emp,'availability.read');
  perform public.enqueue_notification_outbox_service(w,event,'availability.weekly_updated',1,actor,'weekly_availability',emp::text,
   jsonb_build_object('recipient_user_ids',to_jsonb(recipients),'audience_contract','availability_scoped_recipients','category','request',
    'title','Availability updated','body',(model->>'employee_name')||': '||summary,'safe_preview','An employee updated weekly availability.',
    'action_url','/app/employees?employeeId='||emp::text||'&section=availability','employee_id',emp,'changed_days',changed_days,'group_key','weekly-availability:'||emp::text),now());
 end if;
 insert into public.weekly_preference_commands(workspace_id,actor_user_id,request_key,command,result) values(w,actor,request_key,command,result);
 return result||jsonb_build_object('model',model);
end; $$;


ALTER FUNCTION "public"."weekly_preferences_save_service"("actor" "uuid", "w" "uuid", "command" "jsonb", "request_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_publication_decisions"("preview" "jsonb", "decisions" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare result jsonb:='[]'; f jsonb; decision jsonb;
begin
 if jsonb_typeof(coalesce(decisions,'[]')) is distinct from 'array' then raise exception 'publication overrides must be an array' using errcode='22023'; end if;
 for f in select value from jsonb_array_elements(preview->'findings') where value->>'severity'='soft' loop
  -- A note (the availability list among them, M9) asks nothing and records nothing.
  if not coalesce((f->>'overrideable')::boolean,true) and f->>'tier'='note' then continue; end if;
  select d into decision from jsonb_array_elements(coalesce(decisions,'[]')) d where d->>'finding_id'=f->>'id' limit 1;
  if f->>'availability_state'='new' and f->>'warning_policy'='confirm' and decision is null then
   raise exception 'Confirm the current schedule conflicts before publishing' using errcode='22023'; end if;
  if f->>'availability_state' is null and coalesce(f->>'tier','blocker')<>'note' and decision is null then
   raise exception 'Review the current schedule conflicts before publishing' using errcode='22023'; end if;
  result:=result||jsonb_build_array(jsonb_build_object('finding_id',f->>'id','reason',case
   when f->>'availability_state'='accepted' then 'Previously accepted schedule conflict retained.'
   when f->>'warning_policy'='warn' then 'Schedule warning acknowledged (warn policy).'
   else 'Schedule conflict confirmed by manager.' end));
 end loop;
 return result;
end; $$;


ALTER FUNCTION "public"."weekly_publication_decisions"("preview" "jsonb", "decisions" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_schedule_publication_preflight"("payload" "jsonb", "actor" "uuid", "departments" "uuid"[] DEFAULT NULL::"uuid"[], "include_no_department" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare findings jsonb; signatures jsonb:='[]'; s record; a jsonb; prior jsonb; evidence jsonb; scope jsonb;
 unsigned jsonb; w uuid:=(payload->>'workspace_id')::uuid; message text; state text; tier text; warning boolean;
 pending jsonb:='[]'; shift_span tstzrange; asking uuid[];
begin
 if payload->>'status'='past_week_closed' then return payload; end if;
 -- Who has time off waiting for a decision, read once for the whole draft.
 asking:=array(select distinct q.employee_id from public.schedule_time_off_requests q
  where q.workspace_id=w and q.status='pending' and q.request_type='time_off');
 select coalesce(jsonb_agg(f),'[]') into findings from jsonb_array_elements(payload->'findings') f
  where f->>'code' not in ('availability','availability_unknown','availability_review_pending','time_source_unresolved','overlap','double_booking','time_off','closed_location','closed_day');
 -- Publishing is asked at each location the preview is for, once.
 perform app_private.authorize(actor,w,'schedule.publish',array[(x->>'location_id')::uuid])
  from jsonb_array_elements(coalesce(payload->'locations','[]'::jsonb)) x;
 scope:=jsonb_build_object('_publish_locations',(select jsonb_agg(x->'location_id') from jsonb_array_elements(payload->'locations') x),
  '_publish_departments',to_jsonb(departments),'_publish_no_department',coalesce(include_no_department,true));
 for s in select d.*,concat_ws(' ',coalesce(nullif(e.preferred_name,''),e.first_name),e.last_name) employee_name,l.name location_name
  from public.schedule_draft_shifts d left join public.employee_profiles e on e.id=d.employee_id and e.workspace_id=d.workspace_id
  join public.locations l on l.id=d.location_id and l.workspace_id=d.workspace_id
  where d.workspace_id=w and d.draft_id=(payload->>'draft_id')::uuid
   and d.location_id in (select (x->>'location_id')::uuid from jsonb_array_elements(payload->'locations') x)
   and public.schedule_shift_in_department_scope_service(d.job_id,departments,coalesce(include_no_department,true)) order by d.id loop
  state:=null; prior:=null;
  a:=public.assess_weekly_shift_availability(w,s.employee_id,to_jsonb(s)||scope);
  evidence:=public.schedule_availability_override(w,to_jsonb(s),a);
  -- A conflict accepted when this shift was last published stays accepted
  -- (BL-174). Availability is no conflict and is not part of it (BL-186).
  if a->>'operation'='warning_requires_override' then
   prior:=public.schedule_availability_prior_publication(w,to_jsonb(s));
   state:=case when evidence is not null or prior->'availability_snapshot'->'assessment'->>'fingerprint'=a->>'fingerprint'
    or exists(select 1 from public.schedule_publication_overrides o where o.workspace_id=w
     and o.publication_id=(prior->>'publication_id')::uuid and o.finding_id=a->>'fingerprint' and s.id=any(o.source_shift_ids)) then 'accepted' else 'new' end;
   if s.employee_id is null and exists(select 1 from public.audit_events ev where ev.workspace_id=w and ev.action='schedule.conflict_accepted'
     and ev.target_id=s.id::text and ev.metadata->'assessment'->>'fingerprint'=a->>'fingerprint') then state:='accepted'; end if;
  end if;
  signatures:=signatures||jsonb_build_array(jsonb_build_object('shift_id',s.id,'fingerprint',a->>'fingerprint',
   'availability_fingerprint',a->>'availability_fingerprint','override_id',evidence->>'id','retained_publication_id',prior->>'publication_id'));
  if a->>'operation'<>'allowed' then
   warning:=state is not null;
   select string_agg(r->>'message',' ' order by ord) into message from jsonb_array_elements(a->'reasons') with ordinality r(r,ord) where r->>'code' not in ('availability','note');
   tier:=case when not warning then 'blocker' when state='new' and a->>'warning_policy'='confirm' then 'risk' else 'note' end;
   findings:=findings||jsonb_build_array(jsonb_build_object('id',a->>'fingerprint','code','schedule_conflict',
    'conflict_severity',coalesce(a->>'conflict_severity',case when a->>'warning_policy'='confirm' then 'confirm' else 'warn' end),
    'severity',case when warning then 'soft' else 'hard' end,'overrideable',warning,'tier',tier,'introduced',state is distinct from 'accepted',
    'location_id',s.location_id,'location_name',s.location_name,'employee_id',s.employee_id,'employee_name',nullif(s.employee_name,''),
    'scheduled_date',s.scheduled_date,'shift_ids',jsonb_build_array(s.id),'message',left(coalesce(message,'Review this assignment before publishing.'),500))
    ||case when warning then jsonb_build_object('availability_state',state,'warning_policy',a->>'warning_policy') else '{}'::jsonb end);
  end if;
  -- The employee's own mark: listed for a last look, never asked (M9); a
  -- manager's note never reaches Publish (M12).
  if coalesce((a->>'has_availability_conflict')::boolean,false) then
   findings:=findings||jsonb_build_array(jsonb_build_object('id',a->>'availability_fingerprint','code','availability',
    'conflict_severity','warn','severity','soft','overrideable',false,'tier','note',
    'location_id',s.location_id,'location_name',s.location_name,'employee_id',s.employee_id,'employee_name',nullif(s.employee_name,''),
    'scheduled_date',s.scheduled_date,'shift_ids',jsonb_build_array(s.id),
    'message',left(coalesce(nullif(s.employee_name,''),'This person')||' shows as unavailable for this shift.',500)));
  end if;
  -- Time off waiting for a decision over a shift that has not started (FB-6.3).
  if s.employee_id=any(asking) then
   select tstzrange((i->>'start_at')::timestamptz,(i->>'end_at')::timestamptz,'[)') into shift_span
    from jsonb_array_elements(case when a->>'assessment_scope'='shift_interval' then a->'intervals' else a->'unknown_intervals' end) i limit 1;
   if lower(shift_span)>now() then
    pending:=pending||coalesce((select jsonb_agg(jsonb_build_object('employee_id',s.employee_id,'employee_name',nullif(s.employee_name,''),
      'scheduled_date',s.scheduled_date,'location_id',s.location_id,'location_name',s.location_name,'shift_id',s.id,'request_id',r.id))
     from (select distinct req.id from public.schedule_time_off_requests req
      join public.schedule_time_off_segments seg on seg.request_id=req.id and seg.workspace_id=req.workspace_id
      where req.workspace_id=w and req.employee_id=s.employee_id and req.request_type='time_off' and req.status='pending'
       and seg.segment_date between s.scheduled_date-3 and s.scheduled_date+3
       and public.time_off_effective_ranges(seg.id)&&shift_span) r),'[]');
   end if;
  end if;
 end loop;
 findings:=findings||coalesce((select jsonb_agg(jsonb_build_object(
   'id',encode(extensions.digest(convert_to('time_off_pending|'||g.employee_id||'|'||g.scheduled_date||'|'||g.location_id||'|'||g.request_id,'UTF8'),'sha256'),'hex'),
   'code','time_off_pending','severity','soft','overrideable',false,'tier','note',
   'location_id',g.location_id,'location_name',g.location_name,'employee_id',g.employee_id,'employee_name',g.employee_name,
   'scheduled_date',g.scheduled_date,'shift_ids',g.shift_ids,'time_off_request_id',g.request_id,
   'message',left(coalesce(g.employee_name,'This person')||' has time off waiting for a decision on '||to_char(g.scheduled_date,'Mon FMDD'),500))
  order by g.scheduled_date,g.employee_id,g.location_id,g.request_id)
  from (select h->>'employee_id' employee_id,h->>'employee_name' employee_name,(h->>'scheduled_date')::date scheduled_date,
    h->>'location_id' location_id,h->>'location_name' location_name,h->>'request_id' request_id,
    jsonb_agg(h->'shift_id' order by h->>'shift_id') shift_ids
   from jsonb_array_elements(pending) h group by 1,2,3,4,5,6) g),'[]');
 -- BL-198: a draft that would undo an approved shift change is a blocker.
 findings:=findings||public.shift_exchange_draft_undoes(w,(payload->>'draft_id')::uuid,
  array(select (x->>'location_id')::uuid from jsonb_array_elements(coalesce(payload->'locations','[]'::jsonb)) x),departments,include_no_department);
 unsigned:=(payload-'fingerprint'-'status')||jsonb_build_object('findings',findings,'availability_assessments',signatures,'department_ids',to_jsonb(departments),'include_no_department',coalesce(include_no_department,true));
 return unsigned||jsonb_build_object('status',case
  when exists(select 1 from jsonb_array_elements(findings) f where f->>'severity'='hard' and coalesce(f->>'tier','blocker')<>'note') then 'hard_blocked'
  when exists(select 1 from jsonb_array_elements(findings) f where coalesce(f->>'tier','blocker')<>'note' and (coalesce((f->>'introduced')::boolean,true) or not (f->>'overrideable')::boolean)) then 'override_required'
  else 'publish_ready' end,'fingerprint',encode(extensions.digest(convert_to(unsigned::text,'UTF8'),'sha256'),'hex'));
end; $$;


ALTER FUNCTION "public"."weekly_schedule_publication_preflight"("payload" "jsonb", "actor" "uuid", "departments" "uuid"[], "include_no_department" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."weekly_team_read_service"("actor" "uuid", "w" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb; read_scope uuid[]; org_wide boolean;
begin
 read_scope:=app_private.scope_set(actor,w,'availability.team_read');
 -- Nowhere to read the team's availability: asked with nobody named, the core says
 -- why; with no live location in the workspace, only the people with none show.
 if cardinality(read_scope)=0 and (app_private.authz_reason(actor,w,'availability.team_read') is distinct from 'out_of_scope'
  or exists(select 1 from public.locations l where l.workspace_id=w and l.deleted_at is null)) then
  perform app_private.authorize(actor,w,'availability.team_read');
 end if;
 org_wide:=app_private.authz_reason(actor,w,'availability.team_read','{}'::uuid[]) is null;
 with scope as materialized (
  select l.id,l.name,l.sort_order from public.locations l where l.workspace_id=w and l.archived_at is null
   and l.id=any(read_scope)
 ), people as materialized (
  select e.id,e.employee_code,coalesce(nullif(e.preferred_name,''),e.first_name)||' '||e.last_name display_name,
   coalesce((select jsonb_agg(a.location_id order by a.location_id) from public.employee_location_assignments a
    join scope s on s.id=a.location_id where a.workspace_id=w and a.employee_id=e.id and a.ended_at is null),'[]') location_ids,
   p.employee_id is not null submitted,coalesce(p.preference,public.empty_weekly_preference(s.availability_input_mode)) preference,
   (public.weekly_preference_manager_scope(actor,w,e.id,'availability.read')
    or public.weekly_preference_manager_scope(actor,w,e.id,'availability.manage')) can_open
  from public.employee_profiles e
  join public.workspace_scheduling_settings s on s.workspace_id=e.workspace_id
  left join public.employee_weekly_preferences p on p.workspace_id=e.workspace_id and p.employee_id=e.id
  where e.workspace_id=w and e.archived_at is null and (
   exists(select 1 from public.employee_location_assignments a join scope l on l.id=a.location_id
    where a.workspace_id=w and a.employee_id=e.id and a.ended_at is null)
   or (not exists(select 1 from public.employee_location_assignments a where a.workspace_id=w and a.employee_id=e.id and a.ended_at is null)
    and org_wide)
  )
 ), selected_types as (
  select distinct type_id::uuid id from people p cross join lateral jsonb_array_elements(p.preference->'days') day
   cross join lateral jsonb_array_elements_text(day->'shift_type_ids') type_id
 ), types as (
  select x.id,coalesce(t.name,d.name,'Unavailable shift type') name,
   to_char(case when t.id is not null and t.archived_at is null and t.deleted_at is null then t.default_start_time else d.start_time end,'HH24:MI') start_time,
   to_char(case when t.id is not null and t.archived_at is null and t.deleted_at is null then t.default_end_time else d.end_time end,'HH24:MI') end_time,
   (t.id is null or t.archived_at is not null or t.deleted_at is not null) archived,false selectable
  from selected_types x left join public.shift_types t on t.workspace_id=w and t.id=x.id
   left join public.weekly_preference_type_defaults d on d.workspace_id=w and d.shift_type_id=x.id
 )
 select jsonb_build_object(
  'locations',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name) order by sort_order,name,id) from scope),'[]'),
  'time_format',(select time_format from public.workspace_scheduling_settings where workspace_id=w),
  'employees',coalesce((select jsonb_agg(to_jsonb(p) order by display_name,employee_code,id) from people p),'[]'),
  'shift_types',coalesce((select jsonb_agg(to_jsonb(t) order by name,id) from types t),'[]')
 ) into result;
 return result;
end; $$;


ALTER FUNCTION "public"."weekly_team_read_service"("actor" "uuid", "w" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."withdraw_document_acknowledgement_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.employee_onboarding_requirements%rowtype; c public.employee_onboarding_cases%rowtype; evidence_id uuid;
begin
 perform app_private.authorize(actor_user_id,target_workspace_id,'documents.self',target_person=>(select q.employee_id from public.employee_onboarding_requirements q where q.id=target_requirement_id and q.workspace_id=target_workspace_id));
 select c0.* into c from public.employee_onboarding_cases c0 join public.employee_onboarding_requirements q on q.case_id=c0.id
 where q.id=target_requirement_id and q.workspace_id=target_workspace_id and q.lifecycle_user_id=actor_user_id for update of c0;
 select * into r from public.employee_onboarding_requirements where id=target_requirement_id and workspace_id=target_workspace_id for update;
 if c.id is null or r.kind<>'acknowledgement' or r.lifecycle_user_id is distinct from actor_user_id
  or not app_private.document_actor_can_read(actor_user_id,r.workspace_id,r.employee_id,r.lifecycle_user_id)
 then raise exception 'policy unavailable' using errcode='P0002'; end if;
 if r.lifecycle_revision<>expected_revision then raise exception 'policy changed; refresh required' using errcode='PT409'; end if;
 if c.submitted_at is not null or c.status<>'in_progress' or r.lifecycle_retired_at is not null
  or not exists(select 1 from public.workspace_memberships where id=c.membership_id and user_id=actor_user_id and status='pending_activation')
 then raise exception 'acknowledgement can only be withdrawn before first onboarding Submit' using errcode='22023'; end if;
 update public.employee_acknowledgement_envelopes set withdrawn_at=now() where requirement_id=r.id and user_id=actor_user_id and withdrawn_at is null returning id into evidence_id;
 if evidence_id is null then raise exception 'current acknowledgement unavailable' using errcode='PT409'; end if;
 update public.employee_onboarding_requirements set status='not_started',completed_at=null,lifecycle_revision=lifecycle_revision+1,updated_at=now() where id=r.id returning lifecycle_revision into expected_revision;
 perform app_private.document_audit(r,actor_user_id,'document.policy_withdrawn',jsonb_build_object('evidence_id',evidence_id,'revision',expected_revision));
 perform app_private.document_sync_onboarding(r.id,actor_user_id);
 return expected_revision;
end;
$$;


ALTER FUNCTION "public"."withdraw_document_acknowledgement_service"("actor_user_id" "uuid", "target_workspace_id" "uuid", "target_requirement_id" "uuid", "expected_revision" integer) OWNER TO "postgres";


