CREATE OR REPLACE VIEW "app_private"."lifecycle_definition" AS
 SELECT "d"."id",
    "d"."workspace_id",
    'document'::"text" AS "kind",
    "d"."title",
    "d"."description",
    "d"."requires_review",
    "d"."sort_order",
    "d"."archived_at",
    "d"."lifecycle_revision",
    "d"."lifecycle_settings",
    "app_private"."document_definition_snapshot"("d".*) AS "snapshot",
    ("d"."publication_status" = 'published'::"text") AS "current_version"
   FROM "public"."document_types" "d"
UNION ALL
 SELECT "v"."id",
    "v"."workspace_id",
    'acknowledgement'::"text" AS "kind",
    "v"."title",
    "v"."summary" AS "description",
    false AS "requires_review",
    (200 + "v"."version_number") AS "sort_order",
    "t"."archived_at",
    "v"."lifecycle_revision",
    "app_private"."policy_lifecycle_settings"("v".*) AS "lifecycle_settings",
    "jsonb_build_object"('template_version_id', "v"."id", 'content_text', "v"."content_text", 'content_digest', "v"."content_digest", 'intent_statement', "v"."intent_statement", 'locale', "v"."locale", 'effective_date', "v"."effective_date", 'retention_policy_id', "v"."retention_policy_id") AS "snapshot",
    (NOT (EXISTS ( SELECT 1
           FROM "public"."signature_template_versions" "newer"
          WHERE (("newer"."template_id" = "v"."template_id") AND ("newer"."status" = 'published'::"public"."signature_version_status") AND ("newer"."version_number" > "v"."version_number"))))) AS "current_version"
   FROM ("public"."signature_template_versions" "v"
     JOIN "public"."signature_templates" "t" ON ((("t"."id" = "v"."template_id") AND ("t"."workspace_id" = "v"."workspace_id"))))
  WHERE ("v"."status" = 'published'::"public"."signature_version_status");


