COMMENT ON COLUMN "public"."workspace_memberships"."last_used_at" IS 'When this membership was last opened. The landing decision picks the most recent one.';



COMMENT ON COLUMN "public"."workspace_memberships"."employee_id" IS 'The employee record this membership is. Null while the workspace has no record for the account.';



CREATE OR REPLACE VIEW "public"."membership_location_scopes" WITH ("security_invoker"='true') AS
 SELECT "membership"."id" AS "membership_id",
    "membership"."workspace_id",
    "assignment"."location_id",
    "min"("assignment"."assigned_at") AS "created_at"
   FROM (("public"."workspace_memberships" "membership"
     JOIN "public"."employee_profiles" "profile" ON ((("profile"."workspace_id" = "membership"."workspace_id") AND ("profile"."user_id" = "membership"."user_id") AND ("profile"."archived_at" IS NULL))))
     JOIN "public"."employee_location_assignments" "assignment" ON ((("assignment"."employee_id" = "profile"."id") AND ("assignment"."workspace_id" = "profile"."workspace_id") AND ("assignment"."ended_at" IS NULL))))
  GROUP BY "membership"."id", "membership"."workspace_id", "assignment"."location_id";


ALTER VIEW "public"."membership_location_scopes" OWNER TO "postgres";


COMMENT ON VIEW "public"."membership_location_scopes" IS 'Where each member works: their active location assignments. Derived, never written; readers move to app_private.scope_set() in stage 6.';



