    CONSTRAINT "notification_catalog_category_check" CHECK (("category" = ANY (ARRAY['security'::"text", 'schedule'::"text", 'requests'::"text", 'payroll'::"text", 'people'::"text", 'communications'::"text", 'system'::"text"]))),
