CREATE TABLE IF NOT EXISTS "public"."workspace_scheduling_settings" (
    "workspace_id" "uuid" NOT NULL,
    "week_start_day" "public"."schedule_week_start" DEFAULT 'monday'::"public"."schedule_week_start" NOT NULL,
    "schedule_deadline_day" "public"."schedule_deadline_day" DEFAULT 'sunday'::"public"."schedule_deadline_day" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "time_format" "text" DEFAULT '12h'::"text" NOT NULL,
    "minimum_travel_minutes" integer DEFAULT 0 NOT NULL,
    "availability_input_mode" "text" DEFAULT 'time_range'::"text" NOT NULL,
    "availability_onboarding_required" boolean DEFAULT false NOT NULL,
    "availability_preferences_revision" integer DEFAULT 0 NOT NULL,
    "conflict_rules" "jsonb" DEFAULT '{"minimum_rest": "confirm", "minimum_travel": "confirm", "closed_location": "confirm", "approved_time_off": "block", "document_required": "confirm", "document_conditional_grace": "warn", "document_conditional_overdue": "confirm"}'::"jsonb" NOT NULL,
    "conflict_rules_revision" integer DEFAULT 1 NOT NULL,
    "minimum_rest_minutes" integer DEFAULT 0 NOT NULL,
    "time_off_lead_hours" integer DEFAULT 24 NOT NULL,
    CONSTRAINT "scheduling_conflict_rules_valid" CHECK ((("jsonb_typeof"("conflict_rules") = 'object'::"text") AND ("conflict_rules" ?& ARRAY['approved_time_off'::"text", 'closed_location'::"text", 'minimum_travel'::"text", 'minimum_rest'::"text", 'document_required'::"text", 'document_conditional_grace'::"text", 'document_conditional_overdue'::"text"]) AND (("conflict_rules" - ARRAY['approved_time_off'::"text", 'closed_location'::"text", 'minimum_travel'::"text", 'minimum_rest'::"text", 'document_required'::"text", 'document_conditional_grace'::"text", 'document_conditional_overdue'::"text"]) = '{}'::"jsonb") AND (("conflict_rules" ->> 'approved_time_off'::"text") = 'block'::"text") AND (("conflict_rules" ->> 'closed_location'::"text") = ANY (ARRAY['confirm'::"text", 'confirm_once'::"text", 'block'::"text"])) AND (("conflict_rules" ->> 'minimum_travel'::"text") = ANY (ARRAY['warn'::"text", 'confirm'::"text", 'block'::"text"])) AND (("conflict_rules" ->> 'minimum_rest'::"text") = ANY (ARRAY['warn'::"text", 'confirm'::"text", 'block'::"text"])) AND (("conflict_rules" ->> 'document_required'::"text") = ANY (ARRAY['warn'::"text", 'confirm'::"text", 'block'::"text"])) AND (("conflict_rules" ->> 'document_conditional_grace'::"text") = ANY (ARRAY['warn'::"text", 'confirm'::"text", 'block'::"text"])) AND (("conflict_rules" ->> 'document_conditional_overdue'::"text") = ANY (ARRAY['confirm'::"text", 'block'::"text"])) AND ("array_position"(ARRAY['warn'::"text", 'confirm'::"text", 'block'::"text"], ("conflict_rules" ->> 'document_conditional_overdue'::"text")) >= "array_position"(ARRAY['warn'::"text", 'confirm'::"text", 'block'::"text"], ("conflict_rules" ->> 'document_conditional_grace'::"text"))))),
    CONSTRAINT "workspace_scheduling_setting_availability_preferences_rev_check" CHECK (("availability_preferences_revision" >= 0)),
    CONSTRAINT "workspace_scheduling_settings_availability_input_mode_check" CHECK (("availability_input_mode" = ANY (ARRAY['time_range'::"text", 'shift_type'::"text"]))),
    CONSTRAINT "workspace_scheduling_settings_conflict_rules_revision_check" CHECK (("conflict_rules_revision" > 0)),
    CONSTRAINT "workspace_scheduling_settings_minimum_rest_minutes_check" CHECK ((("minimum_rest_minutes" >= 0) AND ("minimum_rest_minutes" <= 1440))),
    CONSTRAINT "workspace_scheduling_settings_minimum_travel_minutes_check" CHECK ((("minimum_travel_minutes" >= 0) AND ("minimum_travel_minutes" <= 240))),
    CONSTRAINT "workspace_scheduling_settings_time_format_check" CHECK (("time_format" = ANY (ARRAY['12h'::"text", '24h'::"text"]))),
    CONSTRAINT "workspace_scheduling_settings_time_off_lead_hours_check" CHECK ((("time_off_lead_hours" >= 0) AND ("time_off_lead_hours" <= 720)))
);


ALTER TABLE "public"."workspace_scheduling_settings" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."workspaces" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "name" "text" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "logo_storage_path" "text",
    "logo_file_name" "text",
    "logo_updated_at" timestamp with time zone,
    "schedule_logo_scale" numeric(4,2) DEFAULT 1 NOT NULL,
    "schedule_logo_offset_x" numeric(5,2) DEFAULT 0 NOT NULL,
    "schedule_logo_offset_y" numeric(5,2) DEFAULT 0 NOT NULL,
    "lifecycle_status" "public"."workspace_lifecycle_status" DEFAULT 'active'::"public"."workspace_lifecycle_status" NOT NULL,
    "closure_scheduled_at" timestamp with time zone,
    "closure_effective_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "closed_by" "uuid",
    CONSTRAINT "workspaces_closure_lifecycle_consistency" CHECK (((("lifecycle_status" = ANY (ARRAY['draft'::"public"."workspace_lifecycle_status", 'active'::"public"."workspace_lifecycle_status", 'suspended'::"public"."workspace_lifecycle_status"])) AND ("closure_scheduled_at" IS NULL) AND ("closure_effective_at" IS NULL) AND ("closed_at" IS NULL) AND ("closed_by" IS NULL)) OR (("lifecycle_status" = 'closure_scheduled'::"public"."workspace_lifecycle_status") AND ("closure_scheduled_at" IS NOT NULL) AND ("closure_effective_at" IS NOT NULL) AND ("closed_at" IS NULL) AND ("closed_by" IS NULL)) OR (("lifecycle_status" = 'deleted'::"public"."workspace_lifecycle_status") AND ("closed_at" IS NOT NULL) AND ("closed_by" IS NOT NULL)))),
    CONSTRAINT "workspaces_logo_file_name_check" CHECK ((("logo_file_name" IS NULL) OR (("char_length"("btrim"("logo_file_name")) >= 1) AND ("char_length"("btrim"("logo_file_name")) <= 255)))),
    CONSTRAINT "workspaces_logo_metadata_check" CHECK (((("logo_storage_path" IS NULL) AND ("logo_file_name" IS NULL) AND ("logo_updated_at" IS NULL)) OR (("logo_storage_path" IS NOT NULL) AND ("logo_file_name" IS NOT NULL) AND ("logo_updated_at" IS NOT NULL)))),
    CONSTRAINT "workspaces_logo_storage_path_check" CHECK ((("logo_storage_path" IS NULL) OR ("logo_storage_path" ~* '^[a-f0-9-]+/logo/[a-f0-9-]+\.(jpg|png|webp|svg)$'::"text"))),
    CONSTRAINT "workspaces_name_check" CHECK ((("char_length"("btrim"("name")) >= 1) AND ("char_length"("btrim"("name")) <= 120))),
    CONSTRAINT "workspaces_schedule_logo_offset_x_check" CHECK ((("schedule_logo_offset_x" >= ('-100'::integer)::numeric) AND ("schedule_logo_offset_x" <= (100)::numeric))),
    CONSTRAINT "workspaces_schedule_logo_offset_y_check" CHECK ((("schedule_logo_offset_y" >= ('-100'::integer)::numeric) AND ("schedule_logo_offset_y" <= (100)::numeric))),
    CONSTRAINT "workspaces_schedule_logo_scale_check" CHECK ((("schedule_logo_scale" >= 0.25) AND ("schedule_logo_scale" <= (4)::numeric)))
);


ALTER TABLE "public"."workspaces" OWNER TO "postgres";


